englishA2Plans[80]={"title": "Visitando um apartamento para alugar", "file": "", "grammar": "Present simple vs present continuous (rotina e agora)", "goal": "Descreva o que acontece agora e o que sempre acontece.", "words": [["landlord", "senhorio"], ["lease", "contrato de aluguel"], ["tenant", "inquilino"], ["move in", "mudar-se para"], ["balcony", "varanda"], ["rent", "aluguel"], ["view", "vista"], ["heating", "aquecimento"]]};
englishA2Content[80]=[[["Ana is visiting an apartment with the landlord today.", "Ana está visitando um apartamento com o senhorio hoje."], ["He usually shows apartments on Saturdays.", "Ele costuma mostrar apartamentos aos sábados."], ["Right now, the tenant is packing boxes, and Mr. Cole is changing a bulb.", "Agora, o inquilino está arrumando caixas, e o Sr. Cole está trocando uma lâmpada."], ["Ana likes the balcony and the view.", "Ana gosta da varanda e da vista."], ["The rent is nine hundred dollars a month.", "O aluguel é de novecentos dólares por mês."], ["She wants to sign the lease and move in next month.", "Ela quer assinar o contrato e se mudar no mês que vem."]], [["Hi, Mr. Cole. I'm looking for a small apartment near my job.", "Oi, Sr. Cole. Estou procurando um apartamento pequeno perto do meu trabalho."], ["Come in. The tenant is packing right now, but you can look around.", "Entre. O inquilino está arrumando as coisas agora, mas você pode olhar tudo."], ["Thanks. Does the heating work well in the winter?", "Obrigada. O aquecimento funciona bem no inverno?"], ["Yes, it works very well. Only one screw in the door is loose.", "Sim, funciona muito bem. Só um parafuso da porta está solto."], ["Is there parking? I drive to work every day.", "Tem estacionamento? Eu vou de carro para o trabalho todo dia."], ["Yes, every tenant gets a spot. Look at the view from the balcony!", "Sim, cada inquilino tem uma vaga. Olhe a vista da varanda!"], ["Wow, I love it. There's a plug by the bed, so I'm ready to sign today.", "Uau, eu adorei. Tem uma tomada ao lado da cama, então estou pronta para assinar hoje."], ["Great. The lease is in my office, and you can move in on the first.", "Ótimo. O contrato está no meu escritório, e você pode se mudar no dia primeiro."]], ["/l/ em landlord e lease", "Encoste a ponta da língua na gengiva, logo atrás dos dentes de cima. No fim de palavras como landlord, não deixe o L virar U, como no português do Brasil.", ["landlord", "lease"]], ["Ana ___ for an apartment right now.", "is looking", "looks", "Ana está procurando um apartamento agora.", "Right now indica algo que acontece neste momento, então usamos is + verbo com -ing."], [["Ana is visiting an apartment with the landlord today.", "Ana está visitando um apartamento com o senhorio hoje."], ["He usually shows apartments on Saturdays.", "Ele costuma mostrar apartamentos aos sábados."]], [{"t": "c", "q": "Mr. Cole usually ___ apartments on Saturdays.", "o": ["shows", "is showing", "show"], "pt": "O Sr. Cole costuma mostrar apartamentos aos sábados.", "why": "Usually fala de rotina, então usamos o presente simples; com he, o verbo leva -s."}, {"t": "l", "say": "The tenant is packing boxes right now.", "o": ["The tenant is packing boxes right now.", "The tenant packs boxes every day.", "The landlord is packing boxes right now."], "why": "Right now e is packing mostram uma ação em andamento, e quem arruma é o inquilino."}, {"t": "b", "pt": "Eu estou procurando um apartamento.", "w": ["I'm", "looking", "for", "an", "apartment"]}, {"t": "b", "pt": "Ela sempre paga o aluguel no dia primeiro.", "w": ["She", "always", "pays", "the", "rent", "on", "the", "first"]}]];
