englishA2Plans[84]={"title": "Consulta marcada na clínica", "file": "", "grammar": "Present perfect negativo (haven't / hasn't)", "goal": "Diga o que você ainda não fez usando haven't.", "words": [["checkup", "check-up"], ["receptionist", "recepcionista"], ["insurance card", "carteirinha do seguro"], ["fill out a form", "preencher um formulário"], ["prescription", "receita médica"], ["dizzy", "tonto"], ["allergy", "alergia"], ["height", "altura"], ["temperature", "temperatura"]]};
englishA2Content[84]=[[["Rosa is an exchange student, and today she has a checkup at the clinic.", "Rosa é intercambista, e hoje ela tem um check-up na clínica."], ["She hasn't filled out the form yet.", "Ela ainda não preencheu o formulário."], ["The receptionist asks for her insurance card.", "A recepcionista pede a carteirinha do seguro dela."], ["Rosa feels a little dizzy because she hasn't eaten breakfast.", "Rosa se sente um pouco tonta porque não tomou café da manhã."], ["The nurse checks her temperature and her height.", "A enfermeira mede a temperatura e a altura dela."], ["Then the doctor writes a prescription for her allergy.", "Depois a médica escreve uma receita para a alergia dela."]], [["Good morning. I have a checkup at nine. My host family made the appointment.", "Bom dia. Tenho um check-up às nove. Minha família anfitriã marcou a consulta."], ["Good morning. What's your name? Do you have your insurance card?", "Bom dia. Qual é o seu nome? Você está com a carteirinha do seguro?"], ["Yes, here it is. I haven't had time to fill out a form yet.", "Sim, aqui está. Ainda não tive tempo de preencher um formulário."], ["No problem. Do you live on campus? We have a short form for students.", "Sem problema. Você mora no campus? Temos um formulário curto para estudantes."], ["Yes. Also, I haven't eaten today, and I feel dizzy.", "Moro. Além disso, não comi hoje e estou tonta."], ["Oh no. Please sit down. The nurse is coming to check your temperature.", "Ah, não. Por favor, sente-se. A enfermeira está vindo medir a sua temperatura."], ["Thanks. Also, I haven't renewed my prescription. Is there any allergy medicine today?", "Obrigada. Além disso, não renovei minha receita. Tem algum remédio para alergia hoje?"], ["Sure. Write it on the form, and the doctor can help you.", "Claro. Escreva no formulário, e a médica pode ajudar você."]], ["/ʃ/ em insurance e receptionist", "Para o sh de insurance e receptionist, arredonde os lábios e solte o ar como quem pede silêncio, shhh. É parecido com o ch de chave em português.", ["insurance", "receptionist"]], ["Rosa ___ eaten breakfast.", "hasn't", "haven't", "A Rosa não tomou café da manhã.", "Rosa é she, então a negativa é hasn't + particípio."], [["She hasn't filled out the form yet.", "Ela ainda não preencheu o formulário."], ["Rosa feels a little dizzy because she hasn't eaten breakfast.", "Rosa se sente um pouco tonta porque não tomou café da manhã."]], [{"t": "c", "q": "I ___ filled out the form yet.", "o": ["haven't", "hasn't", "don't"], "pt": "Eu ainda não preenchi o formulário.", "why": "Com I usamos haven't + particípio para dizer o que ainda não aconteceu."}, {"t": "l", "say": "She hasn't filled out the form.", "o": ["She hasn't filled out the form.", "She has filled out the form.", "He hasn't filled out the form."], "why": "A frase é negativa (hasn't) e o sujeito é she."}, {"t": "b", "pt": "Eu ainda não comi hoje.", "w": ["I", "haven't", "eaten", "today"]}, {"t": "b", "pt": "Ela ainda não preencheu o formulário.", "w": ["She", "hasn't", "filled", "out", "the", "form"]}]];
