englishA2Plans[86]={"title": "Abrindo conta no banco", "file": "", "grammar": "Present perfect com never", "goal": "Diga o que você nunca fez usando never.", "words": [["account", "conta bancária"], ["teller", "caixa de banco"], ["overdraft", "cheque especial"], ["savings", "poupança"], ["withdraw", "sacar"], ["signature", "assinatura"], ["loan", "empréstimo"], ["bank card", "cartão do banco"]]};
englishA2Content[86]=[[["Mia is an exchange student, and she is at the bank to open an account.", "Mia é intercambista e está no banco para abrir uma conta."], ["She has never had a bank account before.", "Ela nunca teve uma conta bancária."], ["The teller shows her a savings account with good interest.", "O caixa mostra a ela uma poupança com bons juros."], ["Mia has never had an overdraft, and she doesn't want one.", "Mia nunca teve cheque especial, e não quer um."], ["She needs to give her signature on the form.", "Ela precisa dar a assinatura no formulário."], ["She doesn't need to withdraw any money today.", "Ela não precisa sacar dinheiro hoje."]], [["Good morning! How can I help you today?", "Bom dia! Como posso ajudar você hoje?"], ["I'd like to open a bank account. I have never had one before.", "Eu gostaria de abrir uma conta. Eu nunca tive uma antes."], ["No problem. Do you want a savings account or a regular account?", "Sem problema. Você quer uma poupança ou uma conta comum?"], ["A savings account, please. Is the interest good?", "Uma poupança, por favor. Os juros são bons?"], ["It's two percent. And you can't have an overdraft with this account.", "São dois por cento. E você não pode ter cheque especial com esta conta."], ["Good, because I have never borrowed money from a bank. I don't want a loan.", "Ótimo, porque eu nunca peguei dinheiro emprestado de um banco. Não quero um empréstimo."], ["That's smart. Please fill out a form, and then give me your signature here.", "Isso é esperto. Por favor, preencha um formulário e depois dê aqui a sua assinatura."], ["Done. I've never signed so many papers!", "Pronto. Nunca assinei tantos papéis!"], ["Congratulations! Your account is open, and you can withdraw money today. The card is coming by courier, and you must sign for it.", "Parabéns! Sua conta está aberta, e você pode sacar dinheiro hoje. O cartão vai por entregador, e você precisa assinar o recebimento."], ["Perfect. I'm glad my account is open.", "Perfeito. Fico feliz que minha conta esteja aberta."]], ["/t/ em teller e account", "Em teller, encoste a ponta da língua na gengiva e solte o ar com força, um T bem firme. Em account, o T fica no fim e é mais leve.", ["teller", "account"]], ["She has ___ had a bank account.", "never", "ever", "Ela nunca teve uma conta bancária.", "Never já tem sentido negativo, por isso usamos has never + particípio."], [["She has never had a bank account before.", "Ela nunca teve uma conta bancária."], ["Mia has never had an overdraft, and she doesn't want one.", "Mia nunca teve cheque especial, e não quer um."]], [{"t": "c", "q": "I have never ___ an overdraft.", "o": ["had", "have", "has"], "pt": "Eu nunca tive cheque especial.", "why": "Depois de have never usamos o particípio: had."}, {"t": "l", "say": "I have never had a loan.", "o": ["I have never had a loan.", "I have never had a lawn.", "I had never a loan."], "why": "A frase certa tem have never had e a palavra loan (empréstimo)."}, {"t": "b", "pt": "Eu nunca tive um cheque especial.", "w": ["I", "have", "never", "had", "an", "overdraft"]}, {"t": "b", "pt": "Nós nunca abrimos uma conta aqui.", "w": ["We", "have", "never", "opened", "an", "account"]}]];
