englishA2ExtraWordExamples[86]={"bank card": ["I've never lost my bank card.", "Eu nunca perdi meu cartão do banco."]};
englishA2Plans[87]={"title": "Cartão de crédito perdido", "file": "", "grammar": "Present perfect com just", "goal": "Diga o que acabou de acontecer usando just.", "words": [["pickpocket", "batedor de carteira"], ["cancel", "cancelar"], ["statement", "extrato"], ["hold the line", "aguarde na linha"], ["fraud", "fraude"], ["purchase", "compra"], ["police", "polícia"], ["replace", "substituir"]]};
englishA2Content[87]=[[["Noah's wallet is gone.", "A carteira do Noah sumiu."], ["A pickpocket has just taken it on the bus.", "Um batedor de carteira acabou de levá-la no ônibus."], ["He has just called the bank to cancel his card.", "Ele acabou de ligar para o banco para cancelar o cartão."], ["The bank has just found a strange purchase on his statement.", "O banco acabou de achar uma compra estranha no extrato dele."], ["The agent says it is fraud and asks him to wait.", "A atendente diz que é fraude e pede que ele espere."], ["Later, he goes to the police, and the bank sends a new card.", "Depois, ele vai à polícia, e o banco manda um cartão novo."]], [["Thank you for calling. How can I help you?", "Obrigada por ligar. Como posso ajudar?"], ["Hi. A pickpocket has just taken my wallet, and I need to cancel my card.", "Oi. Um batedor de carteira acabou de levar minha carteira, e preciso cancelar meu cartão."], ["I'm sorry to hear that. Please hold the line while I check your account.", "Sinto muito por isso. Por favor, aguarde na linha enquanto eu verifico sua conta."], ["Sure, I can wait. Take your time.", "Claro, eu posso esperar. Sem pressa."], ["Thanks for waiting. Your statement shows a purchase in a store ten minutes ago.", "Obrigada por esperar. Seu extrato mostra uma compra em uma loja há dez minutos."], ["What? I've just left the bus, and I haven't bought anything!", "O quê? Acabei de sair do ônibus e não comprei nada!"], ["I think it's fraud. We've just blocked the card, and we can replace it.", "Acho que é fraude. Acabamos de bloquear o cartão, e podemos substituí-lo."], ["Good. Should I call the police?", "Ótimo. Devo chamar a polícia?"], ["Yes, you should. Your new card is coming by courier, and you must sign for it.", "Sim, deve. Seu novo cartão vai por entregador, e você precisa assinar o recebimento."], ["Okay, thanks. I'm calling the police now.", "Certo, obrigado. Estou ligando para a polícia agora."]], ["/w/ em wallet e wait", "Em wallet e wait, arredonde bem os lábios, como para dizer u, e abra rápido para a vogal seguinte. Não coloque um g ou um v no começo.", ["wallet", "wait"]], ["Noah has ___ called the bank.", "just", "yesterday", "Noah acabou de ligar para o banco.", "Just com has + particípio mostra que a ação acabou de acontecer; yesterday não combina com has."], [["A pickpocket has just taken it on the bus.", "Um batedor de carteira acabou de levá-la no ônibus."], ["He has just called the bank to cancel his card.", "Ele acabou de ligar para o banco para cancelar o cartão."]], [{"t": "c", "q": "A pickpocket has just ___ my wallet.", "o": ["taken", "took", "take"], "pt": "Um batedor de carteira acabou de pegar minha carteira.", "why": "Depois de has just usamos o particípio, e o particípio de take é taken."}, {"t": "l", "say": "We've just blocked the card.", "o": ["We've just blocked the card.", "We've just locked the card.", "We have just blocked the cart."], "why": "A frase certa tem blocked (bloqueamos) e card (cartão)."}, {"t": "b", "pt": "Eu acabei de cancelar meu cartão.", "w": ["I", "have", "just", "canceled", "my", "card"]}, {"t": "b", "pt": "Ela acabou de chamar a polícia.", "w": ["She", "has", "just", "called", "the", "police"]}]];
