englishA2Plans[88]={"title": "Um dia no coworking", "file": "", "grammar": "Present perfect com already", "goal": "Diga o que já está pronto usando already.", "words": [["cubicle", "baia"], ["photocopier", "fotocopiadora"], ["membership", "assinatura mensal"], ["hot desk", "mesa compartilhada"], ["wifi", "wi-fi"], ["staff", "equipe"], ["whiteboard", "quadro branco"], ["monitor", "monitor"], ["startup", "empresa iniciante"]]};
englishA2Content[88]=[[["Lia works for a startup in a coworking space.", "Lia trabalha para uma startup em um espaço de coworking."], ["She has a membership, and today she has a hot desk.", "Ela tem uma assinatura mensal, e hoje tem uma mesa compartilhada."], ["She has already connected to the wifi.", "Ela já se conectou ao wifi."], ["The staff has already fixed the photocopier, and the machine works well.", "A equipe já consertou a fotocopiadora, e a máquina funciona bem."], ["Her friend Tom has a cubicle with a big monitor.", "O amigo dela, Tom, tem uma baia com um monitor grande."], ["Lia has already finished her first report, so she takes a break.", "Lia já terminou o primeiro relatório, então faz uma pausa."]], [["Hi Ben, are you the receptionist today? Do I have a hot desk or a cubicle?", "Oi Ben, você é o recepcionista hoje? Eu tenho uma mesa compartilhada ou uma baia?"], ["I am, and you have a hot desk by the window. Make yourself at home.", "Sou, e você tem uma mesa compartilhada perto da janela. Fique à vontade."], ["Great. Is the wifi working? I have a meeting with my startup team.", "Ótimo. O wifi está funcionando? Tenho uma reunião com a equipe da minha startup."], ["Yes, it is. I've already checked it, and the password is on the whiteboard.", "Está. Eu já verifiquei, e a senha está no quadro branco."], ["Thanks. Where is the photocopier? I need ten copies before the courier comes.", "Obrigada. Onde fica a fotocopiadora? Preciso de dez cópias antes de o entregador chegar."], ["It's near the kitchen. The staff has already put paper in the machine.", "Fica perto da cozinha. A equipe já colocou papel na máquina."], ["Perfect. Can I use the monitor in the meeting room?", "Perfeito. Posso usar o monitor da sala de reunião?"], ["Of course. Tom has already booked the room, but you can join him.", "Claro. O Tom já reservou a sala, mas você pode se juntar a ele."], ["Good idea. Then we can work together on the report.", "Boa ideia. Assim podemos trabalhar juntos no relatório."], ["Exactly. Have a nice day, Lia!", "Exatamente. Tenha um bom dia, Lia!"]], ["/ʃ/ em membership e ship", "O sh de membership e machine é como o x de xícara: lábios um pouco projetados e a língua sem tocar o céu da boca. Cuidado para não dizer matchine.", ["membership", "machine"]], ["Lia has ___ connected to the wifi.", "already", "yet", "A Lia já se conectou ao wifi.", "Em frases afirmativas usamos already para dizer que algo já está pronto; yet não combina."], [["She has already connected to the wifi.", "Ela já se conectou ao wifi."], ["The staff has already fixed the photocopier, and the machine works well.", "A equipe já consertou a fotocopiadora, e a máquina funciona bem."]], [{"t": "c", "q": "The staff has already ___ the photocopier.", "o": ["fixed", "fix", "fixes"], "pt": "A equipe já consertou a fotocopiadora.", "why": "Depois de has already usamos o particípio: fixed."}, {"t": "l", "say": "I've already checked the wifi.", "o": ["I've already checked the wifi.", "I haven't checked the wifi.", "I've already checked the whiteboard."], "why": "A frase é afirmativa com already e fala do wifi."}, {"t": "b", "pt": "Eu já verifiquei o wifi.", "w": ["I've", "already", "checked", "the", "wifi"]}, {"t": "b", "pt": "Ela já terminou o relatório.", "w": ["She", "has", "already", "finished", "the", "report"]}]];
