englishA2Plans[89]={"title": "Revisão: Feira de empregos", "file": "", "grammar": "Revisão: present perfect e passado simples em contextos mistos", "goal": "Fale de experiências e do que já fez na feira de empregos.", "words": [["kiosk", "quiosque"], ["brochure", "folheto"], ["recruiter", "recrutador"], ["drop by", "dar uma passada"], ["handshake", "aperto de mão"], ["hire", "contratar"], ["position", "vaga"], ["offer", "oferecer"], ["part-time", "meio período"]]};
englishA2Content[89]=[[["Tom is at a job fair downtown.", "Tom está em uma feira de empregos no centro."], ["He has visited three booths, and he has taken many brochures.", "Ele visitou três estandes e pegou muitos folhetos."], ["Yesterday, he used the photocopier at the library to copy his resume.", "Ontem, ele usou a fotocopiadora da biblioteca para copiar o currículo."], ["At the kiosk, a recruiter asks him some questions.", "No quiosque, um recrutador faz algumas perguntas a ele."], ["Tom has never had a job interview, but he smiles and gives a firm handshake.", "Tom nunca fez uma entrevista de emprego, mas sorri e dá um aperto de mão firme."], ["The recruiter wants him to drop by the office on Monday.", "O recrutador quer que ele dê uma passada no escritório na segunda."]], [["Hello! Welcome to our booth. Are you looking for a job?", "Olá! Bem-vindo ao nosso estande. Você está procurando emprego?"], ["Yes. I'm looking for a part-time position. I've already talked to two recruiters today.", "Sim. Estou procurando uma vaga de meio período. Já falei com dois recrutadores hoje."], ["Great. What did you do last summer?", "Ótimo. O que você fez no verão passado?"], ["I worked in a bookstore for three months. I used my savings to pay for school.", "Trabalhei em uma livraria por três meses. Usei minhas economias para pagar a escola."], ["Good experience. Have you ever worked with children?", "Boa experiência. Você já trabalhou com crianças?"], ["No, I haven't, but I learn fast. I've never missed a day of work.", "Não, mas aprendo rápido. Nunca faltei um dia de trabalho."], ["Nice. Did you take our brochure? It has a list of every position.", "Legal. Você pegou o nosso folheto? Ele tem uma lista de todas as vagas."], ["Yes, I did. I saw it at the first kiosk, and I like the position in the store.", "Peguei. Vi no primeiro quiosque, e gostei da vaga na loja."], ["Wonderful. Please fill out a form here. We hire new workers every month, and we want to offer you an interview.", "Ótimo. Por favor, preencha um formulário aqui. Contratamos novos funcionários todo mês, e queremos oferecer uma entrevista a você."], ["Yes, I'm free on Friday. I can drop by in the morning. Thank you!", "Sim, estou livre na sexta. Posso dar uma passada de manhã. Obrigado!"]], ["/b/ em booth e brochure", "Em booth e brochure, feche bem os lábios e solte com um estouro, como o B de bola. No fim de booth, o th é só um sopro com a língua entre os dentes.", ["booth", "brochure"]], ["Yesterday, Tom ___ ten copies.", "made", "has made", "Ontem, Tom fez dez cópias.", "Yesterday marca um momento passado e terminado, então usamos o passado simples, não have + particípio."], [["He has visited three booths, and he has taken many brochures.", "Ele visitou três estandes e pegou muitos folhetos."], ["Yesterday, he used the photocopier at the library to copy his resume.", "Ontem, ele usou a fotocopiadora da biblioteca para copiar o currículo."]], [{"t": "c", "q": "Tom has ___ three booths today.", "o": ["visited", "visit", "visits"], "pt": "Tom visitou três estandes hoje.", "why": "Depois de has usamos o particípio: visited."}, {"t": "l", "say": "He has taken many brochures.", "o": ["He has taken many brochures.", "He has taken many brothers.", "She has taken many brochures."], "why": "A frase fala de he e de brochures (folhetos)."}, {"t": "b", "pt": "Ontem eu fui à feira de empregos.", "w": ["Yesterday", "I", "went", "to", "the", "job", "fair"]}, {"t": "b", "pt": "Eu nunca tive uma entrevista.", "w": ["I", "have", "never", "had", "an", "interview"]}]];
englishA2PhotoThemes[89]="flag";
englishA2MiniStories[89]=["O dia de sorte do Tom", "Tom wakes up early on Saturday.~Tom acorda cedo no sábado.|Today there is a job fair at the city hall.~Hoje há uma feira de empregos na prefeitura.|He wears his best shirt and takes ten copies of his resume.~Ele veste a melhor camisa e leva dez cópias do currículo.|At the first booth, nobody talks to him.~No primeiro estande, ninguém fala com ele.|He feels nervous, so he drinks some water.~Ele fica nervoso, então bebe um pouco de água.|Then he drops his brochures on the floor.~Aí ele derruba os folhetos no chão.|A woman helps him pick them up.~Uma mulher o ajuda a juntá-los.|She is a recruiter, and she likes his smile.~Ela é recrutadora e gosta do sorriso dele.|She asks about his last job, and Tom answers well.~Ela pergunta sobre o último emprego, e Tom responde bem.|On Monday, she calls him with a job offer, and Tom is very happy.~Na segunda, ela liga para ele com uma oferta de emprego, e Tom fica muito feliz."];
englishA2Plans[90]={"title": "Montando um currículo", "file": "", "grammar": "Present perfect com yet", "goal": "Pergunte e responda com yet.", "words": [["résumé", "currículo"], ["bilingual", "bilíngue"], ["reference", "referência"], ["work experience", "experiência profissional"], ["typo", "erro de digitação"], ["proofread", "revisar o texto"], ["template", "modelo"], ["fluent", "fluente"], ["vacancy", "vaga"]]};
englishA2Content[90]=[[["Ana is writing her résumé tonight.", "Ana está escrevendo o currículo dela hoje à noite."], ["She is bilingual, and that is a big plus.", "Ela é bilíngue, e isso é uma grande vantagem."], ["Her work experience is short, but she has a good reference.", "A experiência profissional dela é curta, mas ela tem uma boa referência."], ["She has chosen a simple template.", "Ela escolheu um modelo simples."], ["Her brother Ben has read the first page.", "O irmão dela, Ben, leu a primeira página."], ["He hasn't finished the second page yet.", "Ele ainda não terminou a segunda página."]], [["Hi, Ana. Have you sent your résumé to the recruiter yet?", "Oi, Ana. Você já enviou seu currículo para o recrutador?"], ["Not yet. The reason is a typo on page two.", "Ainda não. O motivo é um erro de digitação na página dois."], ["Really? Show me. I have proofread it twice already.", "Sério? Me mostre. Eu já revisei duas vezes."], ["Look, here. I spelled \"experience\" wrong in my work experience.", "Olha, aqui. Escrevi \"experience\" errado na minha experiência profissional."], ["Oh, you're right. Fix it, and add your languages.", "Ah, você tem razão. Corrija e acrescente seus idiomas."], ["Okay. I'm bilingual, but I'm not fluent in French yet.", "Certo. Sou bilíngue, mas ainda não sou fluente em francês."], ["That's fine. There's a vacancy at the language school. Drop by and pick up a brochure.", "Tudo bem. Tem uma vaga na escola de idiomas. Dê uma passada lá e pegue um folheto."], ["Good idea. I'm going to print three copies tonight.", "Boa ideia. Vou imprimir três cópias hoje à noite."]], ["/z/ em résumé e skill", "Em résumé e reason, o \"s\" soa como /z/, um zumbido com a voz ligada, igual ao \"z\" de \"zebra\". Ponha a mão na garganta: ela deve vibrar.", ["résumé", "reason"]], ["Ana hasn't sent her résumé ___.", "yet", "already", "Ana ainda não enviou o currículo.", "Em frases negativas, yet vai no fim da frase e significa \"ainda\"."], [["He hasn't finished the second page yet.", "Ele ainda não terminou a segunda página."], ["Hi, Ana. Have you sent your résumé to the recruiter yet?", "Oi, Ana. Você já enviou seu currículo para o recrutador?"]], [{"t": "c", "q": "Have you finished your résumé ___?", "o": ["yet", "never", "ago"], "pt": "Você já terminou o currículo?", "why": "Em perguntas, yet no fim significa \"já\" e pergunta se algo aconteceu até agora."}, {"t": "l", "say": "I haven't called the recruiter yet.", "o": ["I haven't called the recruiter yet.", "I have called the recruiter yet.", "I haven't called the reference yet."], "why": "A frase negativa com yet diz que ainda não ligou; reference é outra palavra."}, {"t": "b", "pt": "Eu ainda não terminei meu currículo.", "w": ["I", "haven't", "finished", "my", "résumé", "yet"]}, {"t": "b", "pt": "Ela já enviou o currículo?", "w": ["Has", "she", "sent", "the", "résumé", "yet"]}]];
englishA2PhotoThemes[90]="notebook";
englishA2Plans[91]={"title": "Entrevista por vídeo", "file": "", "grammar": "Present perfect com for", "goal": "Diga há quanto tempo algo dura usando for.", "words": [["candidate", "candidato"], ["paycheck", "contracheque"], ["headhunter", "caçador de talentos"], ["get back to you", "retornar o contato"], ["freeze", "travar (a imagem)"], ["mute", "mudo (sem som)"], ["background", "fundo"], ["connection", "conexão"], ["confident", "confiante"]]};
englishA2Content[91]=[[["Lia has a video interview this morning.", "Lia tem uma entrevista por vídeo esta manhã."], ["She has lived in this city for ten years.", "Ela mora nesta cidade há dez anos."], ["A headhunter found her résumé online.", "Um caçador de talentos achou o currículo dela na internet."], ["A good candidate sits in front of a plain background.", "Um bom candidato fica na frente de um fundo simples."], ["Lia's connection is strong.", "A conexão da Lia está forte."], ["She feels confident, and she has practiced for an hour.", "Ela se sente confiante e treinou por uma hora."]], [["Good morning, Lia. Can you hear me? I think I'm on mute.", "Bom dia, Lia. Você me ouve? Acho que estou no mudo."], ["Now I can, Tom. Your screen can freeze, but the sound is fine.", "Agora ouço, Tom. Sua tela pode travar, mas o som está bom."], ["Thanks. Tell me about your work experience.", "Obrigado. Fale sobre sua experiência profissional."], ["I've worked at a bank for six years. I've been a teller for four of them.", "Trabalho em um banco há seis anos. Sou caixa há quatro deles."], ["Great. Is your salary good at the bank?", "Ótimo. O seu salário é bom no banco?"], ["It's okay, but my paycheck hasn't changed for a year.", "É razoável, mas meu contracheque não muda há um ano."], ["Good. The recruiter has your résumé and your reference. We're going to get back to you on Friday.", "Bom. O recrutador tem seu currículo e sua referência. Vamos retornar o contato na sexta."], ["Perfect. I'm waiting for your email, Tom.", "Perfeito. Estou esperando o seu e-mail, Tom."]], ["/s/ em salary e candidate", "Em salary e city, o \"s\" e o \"c\" soam como /s/, sem vibrar a garganta, como o \"s\" de \"sapo\". Cuidado para não transformar em /z/.", ["salary", "city"]], ["Lia has worked at the bank ___ six years.", "for", "since", "Lia trabalha no banco há seis anos.", "Usamos for com um período de tempo, como six years."], [["She has lived in this city for ten years.", "Ela mora nesta cidade há dez anos."], ["I've worked at a bank for six years. I've been a teller for four of them.", "Trabalho em um banco há seis anos. Sou caixa há quatro deles."]], [{"t": "c", "q": "We have lived in this city ___ ten years.", "o": ["for", "since", "ago"], "pt": "Moramos nesta cidade há dez anos.", "why": "Ten years é um período de tempo, então usamos for."}, {"t": "l", "say": "She has worked here for a year.", "o": ["She has worked here for a year.", "She has worked here since a year.", "She has worked here from a year."], "why": "Com um período (a year) usamos for, nunca since."}, {"t": "b", "pt": "Eu moro aqui há dez anos.", "w": ["I've", "lived", "here", "for", "ten", "years"]}, {"t": "b", "pt": "Nós esperamos há uma hora.", "w": ["We", "have", "waited", "for", "an", "hour"]}]];
