englishA2Plans[93]={"title": "Voluntariado no abrigo", "file": "", "grammar": "Present perfect: been e gone", "goal": "Diferencie been e gone ao falar de lugares.", "words": [["hairnet", "touca"], ["cot", "catre"], ["donation", "doação"], ["lend a hand", "dar uma mão"], ["sweep", "varrer"], ["sort", "separar"], ["unload", "descarregar"], ["scoop", "servir com concha"], ["tidy", "arrumar"]]};
englishA2Content[93]=[[["Mia is a volunteer at the shelter.", "Mia é voluntária no abrigo."], ["She has been there since seven this morning.", "Ela está lá desde as sete da manhã."], ["Ben has gone to the kiosk for more tea.", "Ben foi ao quiosque buscar mais chá."], ["Mia puts on her hairnet and scoops rice for lunch.", "Mia coloca a touca e serve arroz no almoço."], ["Every cot has a clean blanket.", "Cada catre tem um cobertor limpo."], ["Many people drop by to give a donation.", "Muita gente dá uma passada para dar uma doação."]], [["Hi, Leo. Where have you been? We need someone to lend a hand.", "Oi, Leo. Por onde você andou? Precisamos de alguém para dar uma mão."], ["Sorry, Mia. I've been at the gate. A driver brought a big donation and a brochure.", "Desculpe, Mia. Estive no portão. Um motorista trouxe uma grande doação e um folheto."], ["Wow! Is the driver still there?", "Uau! O motorista ainda está lá?"], ["No, he drove off. But he left ten boxes, and I can unload them now.", "Não, ele foi embora. Mas deixou dez caixas, e posso descarregá-las agora."], ["Thanks. Sort the cans by size, then sweep the floor.", "Obrigada. Separe as latas por tamanho e depois varra o chão."], ["Okay. Where is Ben, by the way?", "Certo. Aliás, onde está o Ben?"], ["He has gone to the kiosk for tea. After lunch, we're going to tidy the cots.", "Ele foi ao quiosque buscar chá. Depois do almoço, vamos arrumar os catres."], ["Sounds good. I'm putting on my hairnet first.", "Combinado. Vou colocar minha touca primeiro."]], ["/v/ em volunteer e shelter", "Em volunteer e give, o /v/ nasce quando os dentes de cima tocam o lábio de baixo, com voz. Não troque por /f/: sinta a garganta vibrar.", ["volunteer", "give"]], ["Ben isn't here now. He has ___ to the kiosk.", "gone", "been", "Ben não está aqui agora. Ele foi ao quiosque.", "Gone quer dizer que a pessoa foi e ainda não voltou; been quer dizer que foi e já voltou."], [["She has been there since seven this morning.", "Ela está lá desde as sete da manhã."], ["Ben has gone to the kiosk for more tea.", "Ben foi ao quiosque buscar mais chá."]], [{"t": "c", "q": "I'm back now. I've ___ to the store.", "o": ["been", "gone", "going"], "pt": "Já voltei. Eu fui à loja.", "why": "Been indica que a pessoa foi e já voltou; gone indicaria que ainda está lá."}, {"t": "l", "say": "She has been to the shelter.", "o": ["She has been to the shelter.", "She is been to the shelter.", "She has be to the shelter."], "why": "A forma correta é have/has + been."}, {"t": "b", "pt": "Ele foi ao quiosque e ainda não voltou.", "w": ["He", "has", "gone", "to", "the", "kiosk"]}, {"t": "b", "pt": "Eu estive no abrigo hoje.", "w": ["I've", "been", "to", "the", "shelter", "today"]}]];
