englishA2Plans[95]={"title": "Maratona de rua", "file": "", "grammar": "Present perfect vs passado simples", "goal": "Compare algo recente com algo em hora marcada.", "words": [["marathon", "maratona"], ["finish line", "linha de chegada"], ["blister", "bolha no pé"], ["give it your all", "dar o seu melhor"], ["jersey", "camisa de corrida"], ["thirsty", "com sede"], ["breath", "fôlego"], ["sweat", "suor"], ["cramp", "câimbra"]]};
englishA2Content[95]=[[["Today is the city marathon, and Ivan is at the finish line.", "Hoje é a maratona da cidade, e Ivan está na linha de chegada."], ["He has just crossed it after four hours.", "Ele acabou de cruzá-la depois de quatro horas."], ["He started at nine o'clock this morning.", "Ele começou às nove horas desta manhã."], ["He has a blister, a cramp, and a lot of sweat on his jersey.", "Ele está com uma bolha, uma câimbra e muito suor na camisa."], ["His coworker Jo hands him some water.", "A colega de trabalho dele, Jo, lhe passa um pouco de água."], ["He is thirsty and out of breath, but he ran for a charity.", "Ele está com sede e sem fôlego, mas correu por uma entidade beneficente."]], [["Ivan, you did it! When did you cross the finish line?", "Ivan, você conseguiu! Quando você cruzou a linha de chegada?"], ["At one o'clock. I have just sat down, and my legs hurt.", "À uma hora. Acabei de sentar, e minhas pernas doem."], ["Have you had any water yet? Let me give you mine.", "Você já tomou água? Deixe eu te dar a minha."], ["Thanks! I drank three cups on the road, but I'm still thirsty.", "Obrigado! Bebi três copos no caminho, mas ainda estou com sede."], ["How are your feet? Did you get a blister?", "Como estão seus pés? Você teve uma bolha?"], ["Yes, I did. I've had one since the tenth mile.", "Tive, sim. Estou com uma desde a milha dez."], ["I'm proud of you. You gave it your all, and the charity gets a donation!", "Estou orgulhosa de você. Você deu o seu melhor, e a entidade ganha uma doação!"], ["That's the best part. Next year, you're going to run with me, Jo!", "Essa é a melhor parte. No ano que vem, você vai correr comigo, Jo!"]], ["/ɪ/ em finish e give", "Em finish e give, o /ɪ/ é um \"i\" curto e relaxado, mais aberto que o \"i\" de \"vida\". Não alongue como em \"feel\": o som é rápido.", ["finish", "give"]], ["I ___ my first marathon last year.", "ran", "have run", "Eu corri minha primeira maratona no ano passado.", "Last year é uma hora marcada no passado, então usamos o passado simples."], [["He has just crossed it after four hours.", "Ele acabou de cruzá-la depois de quatro horas."], ["He started at nine o'clock this morning.", "Ele começou às nove horas desta manhã."]], [{"t": "c", "q": "Rosa is very tired. She ___ just finished the race.", "o": ["has", "did", "was"], "pt": "Rosa está muito cansada. Ela acabou de terminar a corrida.", "why": "Para algo que acabou de acontecer, usamos has/have + just + particípio."}, {"t": "l", "say": "I have just crossed the finish line.", "o": ["I have just crossed the finish line.", "I have just cross the finish line.", "I has just crossed the finish line."], "why": "Present perfect: have + particípio (crossed); com I usamos have."}, {"t": "b", "pt": "Eu terminei a maratona às duas horas.", "w": ["I", "finished", "the", "marathon", "at", "two"]}, {"t": "b", "pt": "Ela acabou de chegar à linha de chegada.", "w": ["She", "has", "just", "reached", "the", "finish", "line"]}]];
