englishA2Plans[101]={"title": "Histórias dos avós na varanda", "file": "", "grammar": "Used to afirmativo", "goal": "Fale de hábitos que você tinha no passado.", "words": [["grandparents", "avós"], ["wrinkle", "ruga"], ["generation", "geração"], ["grow up", "crescer"], ["porch", "varanda"], ["quilt", "colcha de retalhos"], ["cane", "bengala"], ["diary", "diário"], ["tradition", "tradição"]]};
englishA2Content[101]=[[["My grandparents live in a small house with a big porch.", "Meus avós moram numa casa pequena com uma varanda grande."], ["My grandmother used to make a quilt every winter.", "Minha avó costumava fazer uma colcha de retalhos todo inverno."], ["She has many wrinkles, but her smile is young.", "Ela tem muitas rugas, mas o sorriso dela é jovem."], ["My grandfather used to walk to school by the old railway.", "Meu avô costumava ir a pé para a escola pela velha ferrovia."], ["He needs a cane now, but he still tells funny stories.", "Agora ele precisa de uma bengala, mas ainda conta histórias engraçadas."], ["Every generation has a tradition, and ours is storytime on the porch.", "Toda geração tem uma tradição, e a nossa é a hora das histórias na varanda."]], [["Tom, did your grandparents grow up in this town?", "Tom, seus avós cresceram nesta cidade?"], ["Yes, they did. My grandfather used to work at the railway station.", "Sim, cresceram. Meu avô costumava trabalhar na estação de trem."], ["Really? What did he do there?", "Sério? O que ele fazia lá?"], ["He checked the timetable every morning and waved to each carriage.", "Ele conferia o quadro de horários toda manhã e acenava para cada vagão."], ["That sounds great. My grandma used to be afraid of thunder and lightning.", "Que legal. Minha avó tinha medo de trovão e de raio."], ["Lots of kids are afraid of that. Did she hide under the bed?", "Muitas crianças têm medo disso. Ela se escondia debaixo da cama?"], ["Yes! She used to sit on the porch with a candle until the storm ended.", "Sim! Ela costumava ficar na varanda com uma vela até a tempestade acabar."], ["I love old stories. Now my grandfather writes everything in his diary.", "Adoro histórias antigas. Agora meu avô escreve tudo no diário dele."], ["Can I visit on Sunday and listen to his stories?", "Posso visitar no domingo e ouvir as histórias dele?"], ["Sure, you can. He loves new listeners!", "Claro que pode. Ele adora ouvintes novos!"]], ["/ɡr/ em grow e grandparents", "Junte o 'g' e o 'r' sem vogal no meio (não diga 'guerou'). O 'r' americano é feito com a língua curvada para trás, sem vibrar, como em grow e grandparents.", ["grow", "grandparents"]], ["My grandfather ___ walk to school every day.", "used to", "use to", "Meu avô costumava ir a pé para a escola todo dia.", "Para um hábito do passado, usamos 'used to' + verbo; no afirmativo é 'used', com d."], [["My grandmother used to make a quilt every winter.", "Minha avó costumava fazer uma colcha de retalhos todo inverno."], ["My grandfather used to walk to school by the old railway.", "Meu avô costumava ir a pé para a escola pela velha ferrovia."]], [{"t": "c", "q": "My grandparents ___ live on a farm.", "o": ["used to", "use to", "using to"], "pt": "Meus avós costumavam morar numa fazenda.", "why": "Hábito ou situação do passado: used to + verbo."}, {"t": "l", "say": "She used to make a quilt every winter.", "o": ["She used to make a quilt every winter.", "She uses to make a quilt every winter.", "She is used to make a quilt every winter."], "why": "Hábito do passado se diz 'used to', não 'uses to' nem 'is used to'."}, {"t": "b", "pt": "Eu costumava morar perto da ferrovia.", "w": ["I", "used", "to", "live", "near", "the", "railway"]}, {"t": "b", "pt": "Meu avô costumava escrever num diário.", "w": ["My", "grandfather", "used", "to", "write", "in", "a", "diary"]}]];
englishA2PhotoThemes[101]="map";
englishA2Plans[102]={"title": "Como era a vida sem celular", "file": "", "grammar": "Used to negativo e perguntas", "goal": "Pergunte e responda sobre hábitos antigos.", "words": [["landline", "telefone fixo"], ["typewriter", "máquina de escrever"], ["cassette", "fita cassete"], ["back in the day", "antigamente"], ["film", "filme fotográfico"], ["earphones", "fones de ouvido"], ["pay phone", "telefone público"], ["text", "mensagem de texto"], ["mail", "correspondência"]]};
englishA2Content[102]=[[["Back in the day, people didn't use cell phones every minute.", "Antigamente, as pessoas não usavam o celular o tempo todo."], ["My dad used to call his friends on a landline.", "Meu pai costumava ligar para os amigos num telefone fixo."], ["He didn't use to send a text, so he went to a pay phone.", "Ele não costumava mandar mensagem, então ia a um telefone público."], ["My mom used to listen to music on a cassette.", "Minha mãe costumava ouvir música em fita cassete."], ["Her earphones were big and heavy.", "Os fones de ouvido dela eram grandes e pesados."], ["My grandparents used to write on a typewriter, and they sent mail every week.", "Meus avós costumavam escrever numa máquina de escrever e mandavam cartas toda semana."]], [["Leo, did you use to have a cell phone when you were ten?", "Leo, você tinha celular quando tinha dez anos?"], ["No, I didn't. We only had a landline in the kitchen.", "Não, eu não tinha. Só tínhamos um telefone fixo na cozinha."], ["Wow. How did you talk to your friends?", "Uau. Como você falava com seus amigos?"], ["We used a pay phone near school, and we sent a lot of mail.", "Usávamos um telefone público perto da escola e mandávamos muitas cartas."], ["That sounds hard. Did people use to take photos with film?", "Parece difícil. As pessoas costumavam tirar fotos com filme?"], ["Yes, they did. We waited a week to see the pictures.", "Sim, costumavam. Esperávamos uma semana para ver as fotos."], ["A week? My grandparents say the same, but my generation gets everything in one second.", "Uma semana? Meus avós dizem o mesmo, mas minha geração recebe tudo em um segundo."], ["True. I didn't use to listen to music on my phone. I had a big cassette player.", "Verdade. Eu não ouvia música no celular. Eu tinha um toca-fitas grande."], ["I love that. Back in the day, life was slower, right?", "Adoro isso. Antigamente, a vida era mais lenta, né?"], ["Yes, it was. I'm glad I got to grow up that way.", "Sim, era. Fico feliz de ter crescido assim."]], ["/k/ em cassette e back", "O som /k/ é seco: a parte de trás da língua toca o céu da boca e solta o ar de uma vez, como o 'c' de 'casa'. Em cassette e back não coloque uma vogal depois do /k/ final.", ["cassette", "back"]], ["I ___ use to have a cell phone.", "didn't", "don't", "Eu não costumava ter um celular.", "No negativo de 'used to' usamos didn't + use to, sem o d em 'use', porque didn't já marca o passado."], [["My dad used to call his friends on a landline.", "Meu pai costumava ligar para os amigos num telefone fixo."], ["That sounds hard. Did people use to take photos with film?", "Parece difícil. As pessoas costumavam tirar fotos com filme?"]], [{"t": "c", "q": "Did you ___ to have a landline?", "o": ["use", "used", "using"], "pt": "Você costumava ter um telefone fixo?", "why": "Depois de did, o verbo volta ao normal: use to, sem d."}, {"t": "l", "say": "She didn't use to send texts.", "o": ["She didn't use to send texts.", "She didn't used to send texts.", "She doesn't use to send texts."], "why": "No negativo, didn't + use to; 'doesn't' não serve para o passado."}, {"t": "b", "pt": "Nós não costumávamos usar celular.", "w": ["We", "didn't", "use", "to", "use", "cell", "phones"]}, {"t": "b", "pt": "Você costumava ouvir fita cassete?", "w": ["Did", "you", "use", "to", "listen", "to", "cassettes"]}]];
englishA2PhotoThemes[102]="map";
englishA2Plans[103]={"title": "Escolhendo um tablet na loja", "file": "", "grammar": "Will para decisões na hora", "goal": "Decida na hora usando I'll.", "words": [["tablet", "tablet"], ["stylus", "caneta de tela"], ["warranty", "garantia"], ["store assistant", "atendente"], ["gadget", "aparelhinho eletrônico"], ["deal", "bom negócio"], ["brand", "marca"], ["model", "modelo"], ["in stock", "em estoque"]]};
englishA2Content[103]=[[["Mia is in a store, and she needs a new tablet.", "Mia está numa loja e precisa de um tablet novo."], ["The store assistant shows her three different models.", "O atendente mostra a ela três modelos diferentes."], ["This brand is cheap, but the screen is small.", "Esta marca é barata, mas a tela é pequena."], ["The other tablet is a good deal, and it comes with a stylus and a charger.", "O outro tablet é um bom negócio e vem com uma caneta de tela e um carregador."], ["Mia asks, \"Is it in stock?\" and the assistant says yes.", "Mia pergunta: \"Está em estoque?\" e o atendente diz que sim."], ["The warranty is two years, so Mia smiles and says, \"I'll take it.\"", "A garantia é de dois anos, então Mia sorri e diz: \"Eu levo.\""]], [["Mia, are you buying a new gadget today, or just looking?", "Mia, você vai comprar um aparelho novo hoje ou só olhar?"], ["I'm buying a tablet. My grandparents gave me my old one, and it's broken.", "Vou comprar um tablet. Meus avós me deram o antigo, e ele quebrou."], ["Look at this one. It's lighter than a typewriter, and the price is only 200 dollars.", "Olhe este. É mais leve que uma máquina de escrever, e o preço é só 200 dólares."], ["Hmm, the screen is nice. Does it have a warranty?", "Hum, a tela é boa. Tem garantia?"], ["Let me ask the store assistant. Excuse me, does this tablet come with a charger?", "Vou perguntar ao atendente. Com licença, este tablet vem com carregador?"], ["The assistant says yes. Okay, I'll take this one.", "O atendente diz que sim. Certo, eu levo este."], ["Great! Buy a case too. Back in the day, people had no cases, and phones broke all the time.", "Ótimo! Compre uma capa também. Antigamente não havia capas, e os telefones quebravam o tempo todo."], ["True. I'll get a blue case, and I'll pay with my card.", "Verdade. Vou pegar uma capa azul e pagar com meu cartão."], ["And I'll carry the bag, because I'm your best friend, right?", "E eu levo a sacola, porque sou seu melhor amigo, não é?"], ["Yes, you are, Dan. Thanks for the help.", "Sim, você é, Dan. Obrigada pela ajuda."]], ["/tʃ/ em charger e cashier", "O /tʃ/ de charger e cheap é o 'tch' de 'tchau', mas em inglês sai com os lábios um pouco arredondados e o ar mais forte. Não troque por 'sh'.", ["charger", "cheap"]], ["Okay, I ___ take this one.", "will", "am", "Certo, eu levo este.", "Uma decisão tomada na hora usa will + verbo, sem to."], [["The assistant says yes. Okay, I'll take this one.", "O atendente diz que sim. Certo, eu levo este."], ["True. I'll get a blue case, and I'll pay with my card.", "Verdade. Vou pegar uma capa azul e pagar com meu cartão."]], [{"t": "c", "q": "The phone is ringing. I ___ answer it.", "o": ["will", "am", "did"], "pt": "O telefone está tocando. Eu atendo.", "why": "Decisão tomada na hora: will + verbo."}, {"t": "l", "say": "I'll take the blue tablet.", "o": ["I'll take the blue tablet.", "I'll make the blue tablet.", "I take the blue tablet."], "why": "Você ouviu I'll (will) + take, uma decisão na hora."}, {"t": "b", "pt": "Eu vou comprar este tablet.", "w": ["I'll", "buy", "this", "tablet"]}, {"t": "b", "pt": "Eu vou levar o modelo azul.", "w": ["I'll", "take", "the", "blue", "model"]}]];
englishA2PhotoThemes[103]="city";
englishA2Plans[104]={"title": "Previsões do tempo", "file": "", "grammar": "Will para previsões", "goal": "Faça previsões sobre o tempo com will.", "words": [["humidity", "umidade"], ["breeze", "brisa"], ["drizzle", "garoa"], ["clear up", "abrir o tempo"], ["cloudy", "nublado"], ["hail", "granizo"], ["chilly", "frio, fresco"], ["freezing", "congelante"]]};
englishA2Content[104]=[[["The weather forecast says tomorrow will be cloudy.", "A previsão do tempo diz que amanhã vai estar nublado."], ["In the morning, there will be fog and a light drizzle.", "De manhã, vai ter neblina e uma garoa leve."], ["The humidity will be high, and the temperature will be chilly.", "A umidade vai estar alta, e a temperatura vai estar fresca."], ["A cool breeze will come from the sea in the afternoon.", "Uma brisa fresca vai vir do mar à tarde."], ["At night, hail will fall in the north, and it will be freezing.", "À noite, vai cair granizo no norte, e vai estar congelante."], ["By Sunday, the sky will clear up, and the sun will shine.", "Até domingo, o céu vai abrir, e o sol vai brilhar."]], [["Ben, did you see the forecast on your tablet?", "Ben, você viu a previsão no seu tablet?"], ["Yes, I did. It will rain all day tomorrow, and there will be thunder.", "Vi, sim. Vai chover o dia todo amanhã, e vai ter trovão."], ["Oh no! I was going to wash my car.", "Ah, não! Eu ia lavar meu carro."], ["Don't worry. Sunday will be sunny.", "Não se preocupe. O domingo vai ser ensolarado."], ["Really? The last forecast was wrong. It said lightning on Friday, and we had only a drizzle.", "É mesmo? A última previsão estava errada. Disse que teria raios na sexta, e só tivemos garoa."], ["I remember. Everybody ran to take cover under the bus stop.", "Eu me lembro. Todo mundo correu para se abrigar no ponto de ônibus."], ["Ha! This time I'll bring an umbrella just in case.", "Ha! Desta vez eu levo um guarda-chuva, por precaução."], ["Smart. Keep it near the umbrella stand, and don't forget it.", "Esperta. Deixe perto do porta-guarda-chuva e não esqueça."], ["Thanks! By the way, is the temperature going to drop tonight?", "Obrigada! A propósito, a temperatura vai cair hoje à noite?"], ["Yes, it is. It's going to be freezing, so wear a jacket.", "Vai, sim. Vai estar congelante, então use uma jaqueta."]], ["/f/ em forecast e fog", "Em forecast e fog, o /f/ sai com os dentes de cima tocando o lábio de baixo e o ar passando entre eles, sem vibrar a voz. É o mesmo 'f' de 'faca'.", ["forecast", "fog"]], ["Tomorrow ___ be sunny.", "will", "is", "Amanhã vai fazer sol.", "Para previsões usamos will + verbo na forma base."], [["In the morning, there will be fog and a light drizzle.", "De manhã, vai ter neblina e uma garoa leve."], ["Don't worry. Sunday will be sunny.", "Não se preocupe. O domingo vai ser ensolarado."]], [{"t": "c", "q": "The temperature ___ drop tonight.", "o": ["will", "wills", "is"], "pt": "A temperatura vai cair hoje à noite.", "why": "Previsão: will + verbo base, sem -s."}, {"t": "l", "say": "It will clear up on Sunday.", "o": ["It will clear up on Sunday.", "It will clear up on Monday.", "It was clear up on Sunday."], "why": "Você ouviu will clear up (previsão) e o dia Sunday."}, {"t": "b", "pt": "Amanhã vai ter neblina.", "w": ["Tomorrow", "there", "will", "be", "fog"]}, {"t": "b", "pt": "A garoa vai parar à noite.", "w": ["The", "drizzle", "will", "stop", "at", "night"]}]];
