englishA2Plans[134]={"title": "Preparando o jantar para muitos", "file": "", "grammar": "Enough e not enough", "goal": "Avalie se algo é suficiente usando enough.", "words": [["measuring cup", "copo medidor"], ["ingredient", "ingrediente"], ["colander", "escorredor"], ["ladle", "concha de sopa"], ["skillet", "frigideira"], ["spatula", "espátula"], ["mix", "misturar"], ["mixing bowl", "tigela de mistura"]]};
englishA2Content[134]=[[["Noah and Rosa are cooking dinner for twelve people.", "Noah e Rosa estão preparando o jantar para doze pessoas."], ["They have organic peaches, but they don't have enough for everyone.", "Eles têm pêssegos orgânicos, mas não têm o bastante para todos."], ["Rosa counts every ingredient on the counter.", "Rosa conta cada ingrediente em cima do balcão."], ["Noah pours water into the pot and uses a whisk to mix the sauce.", "Noah despeja água na panela e usa um batedor para misturar o molho."], ["The colander is big enough, but the skillet isn't big enough for all the vegetables.", "O escorredor é grande o bastante, mas a frigideira não é grande o bastante para todos os legumes."], ["Noah scoops the soup with a ladle, and the spatula turns the fish.", "Noah serve a sopa com a concha, e a espátula vira o peixe."]], [["Do we have enough rice for twelve people?", "Temos arroz suficiente para doze pessoas?"], ["I think so. The big bag is full, but we need a measuring cup.", "Acho que sim. O saco grande está cheio, mas precisamos de um copo medidor."], ["Here it is. Now, where is the skillet for the chicken?", "Aqui está. Agora, onde está a frigideira para o frango?"], ["It's small. We don't have enough space, so let's cook in two pans.", "É pequena. Não temos espaço suficiente, então vamos cozinhar em duas panelas."], ["Okay. Hand me the spatula, please. I'll mix the vegetables.", "Certo. Me passe a espátula, por favor. Eu vou misturar os legumes."], ["Sure. Did you buy the peaches? They're in season now.", "Claro. Você comprou os pêssegos? Estão na estação agora."], ["Yes, but only six. That's not enough for dessert.", "Sim, mas só seis. Isso não é suficiente para a sobremesa."], ["No problem. Six peaches and some ice cream. I'll be back soon.", "Sem problema. Seis pêssegos e um pouco de sorvete. Volto logo."]], ["/ɛ/ em recipe e ingredient", "O som /ɛ/ em ingredient e whisk é como o e aberto de 'pé', com a boca meio aberta e a língua baixa. Em whisk, comece com um w arredondado e termine com sk.", ["ingredient", "whisk"]], ["We don't have ___ chairs for twelve people.", "enough", "too", "Não temos cadeiras suficientes para doze pessoas.", "Com substantivo, enough vem antes dele: enough chairs."], [["Do we have enough rice for twelve people?", "Temos arroz suficiente para doze pessoas?"], ["Yes, but only six. That's not enough for dessert.", "Sim, mas só seis. Isso não é suficiente para a sobremesa."]], [{"t": "c", "q": "We have ___ rice for everyone.", "o": ["enough", "too", "many"], "pt": "Temos arroz suficiente para todos.", "why": "Enough rice quer dizer arroz suficiente; too e many não servem aqui."}, {"t": "l", "say": "We don't have enough rice.", "o": ["We don't have enough rice.", "We have enough rice.", "We don't have much rice."], "why": "Ouça don't have enough: falta arroz."}, {"t": "b", "pt": "Não temos pêssegos suficientes", "w": ["We", "don't", "have", "enough", "peaches"]}, {"t": "b", "pt": "Temos ingredientes suficientes para o jantar", "w": ["We", "have", "enough", "ingredients", "for", "dinner"]}]];
englishA2PhotoThemes[134]="cup";
englishA2ExtraWordExamples[134]={"mixing bowl": ["This mixing bowl is not big enough for everyone.", "Esta tigela não é grande o bastante para todo mundo."]};
englishA2Plans[135]={"title": "Barraca de limonada", "file": "", "grammar": "Too + adjetivo e adjetivo + enough", "goal": "Diga se algo é demais ou suficiente com too e enough.", "words": [["squeeze", "espremer"], ["pitcher", "jarra"], ["ice cube", "cubo de gelo"], ["sour", "azedo"], ["mint", "hortelã"], ["sticky", "grudento"], ["sprinkle", "polvilhar"], ["lime", "limão"], ["berry", "frutinha vermelha"]]};
englishA2Content[135]=[[["Lia and Tom have a lemonade stand in front of their house.", "Lia e Tom têm uma barraca de limonada na frente da casa deles."], ["Lia squeezes ten lemons into a big pitcher.", "Lia espreme dez limões em uma jarra grande."], ["The lemonade is too sour, so Tom adds sugar from the measuring cup.", "A limonada está azeda demais, então Tom põe açúcar do copo medidor."], ["Then he puts in some ice cubes, some mint, and one berry in each glass.", "Depois ele coloca cubos de gelo, hortelã e uma frutinha em cada copo."], ["A long queue forms, and the lemonade is cold enough now.", "Forma-se uma longa fila, e a limonada está gelada o bastante agora."], ["Lia sprinkles sugar on top and slices a lime for each cup.", "Lia polvilha açúcar por cima e corta uma fatia de limão para cada copo."]], [["Taste this. Is it sweet enough, or is it too sour?", "Prove isto. Está doce o bastante, ou está azedo demais?"], ["It's too sour! Our best ingredient is sugar, so add more.", "Está azedo demais! Nosso melhor ingrediente é o açúcar, então coloque mais."], ["Okay, but the pitcher is too heavy for me. Can you help?", "Certo, mas a jarra é pesada demais para mim. Você pode ajudar?"], ["Sure. Wait, my hands are sticky from the flour.", "Claro. Espere, minhas mãos estão grudentas de farinha."], ["Wash them, then squeeze two more limes. We need a bigger batch.", "Lave-as, depois esprema mais dois limões. Precisamos de uma quantidade maior."], ["Done! Now it's sweet enough. Customers are in the queue already.", "Pronto! Agora está doce o bastante. Já tem clientes na fila."], ["Great! Add some ice cubes, and the drink will be cold enough.", "Ótimo! Coloque cubos de gelo, e a bebida vai ficar gelada o bastante."], ["Okay, ice cubes in now. We're ready to open!", "Certo, cubos de gelo colocados. Estamos prontos para abrir!"]], ["/aʊ/ em sour e flour", "O som /aʊ/ em sour e flour começa com a boca aberta e termina com os lábios arredondados, como o 'au' de 'pau'. As duas palavras são pronunciadas quase como uma sílaba só, com um r leve no fim.", ["sour", "flour"]], ["The lemonade is ___ sour for me.", "too", "enough", "A limonada está azeda demais para mim.", "Too vem antes do adjetivo e mostra excesso: too sour."], [["Taste this. Is it sweet enough, or is it too sour?", "Prove isto. Está doce o bastante, ou está azedo demais?"], ["Okay, but the pitcher is too heavy for me. Can you help?", "Certo, mas a jarra é pesada demais para mim. Você pode ajudar?"]], [{"t": "c", "q": "Add sugar. The drink isn't sweet ___.", "o": ["enough", "too", "much"], "pt": "Coloque açúcar. A bebida não está doce o bastante.", "why": "Com adjetivo, enough vem depois dele: sweet enough."}, {"t": "l", "say": "The pitcher is too heavy for me.", "o": ["The pitcher is too heavy for me.", "The pitcher is heavy enough for me.", "The pitchers are too heavy for me."], "why": "Ouça too heavy: pesada demais."}, {"t": "b", "pt": "A limonada está fria o bastante", "w": ["The", "lemonade", "is", "cold", "enough"]}, {"t": "b", "pt": "Esta jarra é pesada demais para mim", "w": ["This", "pitcher", "is", "too", "heavy", "for", "me"]}]];
