englishA2Plans[136]={"title": "Um pouco de leite no café", "file": "", "grammar": "A few e a little", "goal": "Diferencie contáveis e incontáveis com a few e a little.", "words": [["spoonful", "colherada"], ["teaspoon", "colher de chá"], ["crumb", "migalha"], ["a pinch of", "uma pitada de"], ["cinnamon", "canela"], ["bagel", "rosca de pão (bagel)"], ["carton", "caixa de leite"], ["oats", "aveia"], ["nutmeg", "noz-moscada"]]};
englishA2Content[136]=[[["Ana makes breakfast for Noah on Sunday morning.", "Ana prepara o café da manhã para Noah no domingo de manhã."], ["She pours a little milk from the carton into his coffee.", "Ela despeja um pouco de leite da caixa no café dele."], ["Then she adds a teaspoon of sugar and a pinch of cinnamon.", "Depois ela põe uma colher de chá de açúcar e uma pitada de canela."], ["On the table there are a few bagels, and a crumb falls on the floor.", "Na mesa há alguns bagels, e uma migalha cai no chão."], ["Noah eats a bowl of oats with a spoonful of honey.", "Noah come uma tigela de aveia com uma colherada de mel."], ["Ana squeezes a little orange juice into a pitcher with a few ice cubes.", "Ana espreme um pouco de suco de laranja em uma jarra com alguns cubos de gelo."]], [["Do you want some milk in your coffee, Noah?", "Você quer leite no café, Noah?"], ["Yes, just a little, please. I don't like it too white.", "Sim, só um pouco, por favor. Não gosto dele muito branco."], ["Okay. Do you want sugar? I only have a little left.", "Certo. Você quer açúcar? Só tenho um pouco sobrando."], ["Just a teaspoon, and add a pinch of nutmeg if you have it.", "Só uma colher de chá, e coloque uma pitada de noz-moscada se tiver."], ["Sure. I have a few bagels with cheese. Do you want one?", "Claro. Tenho alguns bagels com queijo. Você quer um?"], ["Yes, please. Oh no, there are a few crumbs on your shirt!", "Sim, por favor. Ah, não, tem algumas migalhas na sua camisa!"], ["Ha! Come here and help me clean the table, please.", "Ha! Venha aqui e me ajude a limpar a mesa, por favor."], ["Of course, I'm coming right now.", "Claro, estou indo agora mesmo."]], ["/ʌ/ em crumb e come", "O som /ʌ/ em crumb e come é curto e relaxado, entre o a e o ê do português, com a boca meio aberta. Não diga 'cromb' com o: pense em 'crâmb'.", ["crumb", "come"]], ["I have ___ apples, but only a little milk.", "a few", "a little", "Tenho algumas maçãs, mas só um pouco de leite.", "Apples é contável (a few); milk é incontável (a little)."], [["Okay. Do you want sugar? I only have a little left.", "Certo. Você quer açúcar? Só tenho um pouco sobrando."], ["Sure. I have a few bagels with cheese. Do you want one?", "Claro. Tenho alguns bagels com queijo. Você quer um?"]], [{"t": "c", "q": "Please add ___ sugar to my tea.", "o": ["a little", "a few", "many"], "pt": "Por favor, coloque um pouco de açúcar no meu chá.", "why": "Sugar é incontável, então usamos a little."}, {"t": "l", "say": "I have a few bagels left.", "o": ["I have a few bagels left.", "I have a little bagels left.", "I have a few bagel left."], "why": "Bagels é contável no plural: a few bagels."}, {"t": "b", "pt": "Só tenho um pouco de leite", "w": ["I", "only", "have", "a", "little", "milk"]}, {"t": "b", "pt": "Tem algumas migalhas na mesa", "w": ["There", "are", "a", "few", "crumbs", "on", "the", "table"]}]];
