englishA2Plans[138]={"title": "Quem é o vizinho barulhento", "file": "", "grammar": "Oração relativa com who", "goal": "Identifique pessoas usando who.", "words": [["doormat", "capacho"], ["landlady", "senhoria"], ["janitor", "zelador"], ["keep it down", "fazer menos barulho"], ["corridor", "corredor"], ["stomp", "pisar forte"], ["thump", "fazer um baque surdo"], ["upstairs neighbor", "vizinho de cima"]]};
englishA2Content[138]=[[["Ben lives in an apartment with a small balcony and a long corridor.", "Ben mora em um apartamento com uma varanda pequena e um corredor longo."], ["He has a neighbor who stomps and thumps all night.", "Ele tem um vizinho que pisa forte e faz baques a noite toda."], ["The noise level is high, and Ben's room is stuffy because the window is closed.", "O nível de ruído é alto, e o quarto do Ben é abafado porque a janela está fechada."], ["He talks to the landlady, a woman who lives on the first floor.", "Ele fala com a senhoria, uma mulher que mora no primeiro andar."], ["She asks the janitor, the man who fixes the lights, to talk to the neighbor.", "Ela pede ao zelador, o homem que conserta as luzes, para falar com o vizinho."], ["Tomorrow the neighbor must keep it down, or Ben will leave a note on his doormat.", "Amanhã o vizinho deve fazer menos barulho, ou Ben vai deixar um bilhete no capacho dele."]], [["Rosa, I can't sleep. The man who lives upstairs stomps at night.", "Rosa, não consigo dormir. O homem que mora no andar de cima pisa forte à noite."], ["That's terrible. Is he the neighbor who has a dog?", "Que horror. Ele é o vizinho que tem um cachorro?"], ["No, that's the woman who lives next door. This man just thumps around.", "Não, essa é a mulher que mora ao lado. Este homem só faz baques por aí."], ["Did you tell the landlady or the janitor about it?", "Você falou com a senhoria ou com o zelador sobre isso?"], ["Yes. I even heard him snore through the wall last night!", "Sim. Eu até ouvi ele roncar pela parede ontem à noite!"], ["Oh no. Come to my place tonight, and we can stock up on tea.", "Ah, não. Venha para minha casa hoje à noite, e vamos fazer estoque de chá."], ["Thanks, but first I'll leave a note on his doormat: please keep it down.", "Obrigado, mas primeiro vou deixar um bilhete no capacho dele: por favor, faça menos barulho."], ["Good idea. I'll call you tomorrow morning.", "Boa ideia. Eu ligo para você amanhã de manhã."]], ["/eɪ/ em neighbor e landlady", "O som /eɪ/ em neighbor e landlady começa em um é e desliza para um i curto, como o 'ei' de 'lei'. Não pare no é: termine com o i.", ["neighbor", "landlady"]], ["He is the man ___ lives upstairs.", "who", "which", "Ele é o homem que mora no andar de cima.", "Para pessoas usamos who ligando as duas partes."], [["Rosa, I can't sleep. The man who lives upstairs stomps at night.", "Rosa, não consigo dormir. O homem que mora no andar de cima pisa forte à noite."], ["No, that's the woman who lives next door. This man just thumps around.", "Não, essa é a mulher que mora ao lado. Este homem só faz baques por aí."]], [{"t": "c", "q": "She is the woman ___ fixes the lights.", "o": ["who", "what", "where"], "pt": "Ela é a mulher que conserta as luzes.", "why": "Who liga uma pessoa à ação que ela faz."}, {"t": "l", "say": "He's the man who lives upstairs.", "o": ["He's the man who lives upstairs.", "He's the man who live upstairs.", "She's the man who lives upstairs."], "why": "Ouça who lives, com o s do verbo no singular."}, {"t": "b", "pt": "A senhoria é a mulher que mora aqui", "w": ["The", "landlady", "is", "the", "woman", "who", "lives", "here"]}, {"t": "b", "pt": "Ele é o vizinho que ronca", "w": ["He", "is", "the", "neighbor", "who", "snores"]}]];
