englishA2Plans[142]={"title": "A cidade onde nasci", "file": "", "grammar": "Oração relativa com where", "goal": "Descreva lugares usando where.", "words": [["hometown", "cidade natal"], ["suburb", "subúrbio"], ["skyline", "linha do horizonte da cidade"], ["fit in", "se encaixar"], ["rooftop", "terraço"], ["church", "igreja"], ["fisherman", "pescador"], ["miss", "sentir falta de"]]};
englishA2Content[142]=[[["Tom was born in a small town by the sea.", "Tom nasceu numa cidade pequena à beira-mar."], ["His hometown is a place where everybody knows everybody.", "A cidade natal dele é um lugar onde todo mundo conhece todo mundo."], ["Every morning, a fisherman watches the sunrise next to the old church.", "Toda manhã, um pescador assiste ao nascer do sol ao lado da igreja velha."], ["Now Tom lives in a suburb, and from his rooftop he sees the skyline.", "Agora o Tom mora num subúrbio e, do terraço, ele vê a linha do horizonte da cidade."], ["Downtown is a place where the traffic never stops.", "O centro é um lugar onde o trânsito nunca para."], ["It is hard to fit in, but he likes his new life.", "É difícil se encaixar, mas ele gosta da vida nova."]], [["Tom, where are you from originally?", "Tom, de onde você é originalmente?"], ["I'm from Ouro Preto, a town where everybody knows your name.", "Sou de Ouro Preto, uma cidade onde todo mundo sabe o seu nome."], ["That sounds nice! Was it hard to move here?", "Que legal! Foi difícil se mudar para cá?"], ["At first, yes. The suburb was too different, and I didn't fit in.", "No começo, foi. O subúrbio era diferente demais, e eu não me encaixei."], ["Really? What do you miss most about your hometown?", "Sério? Do que você mais sente falta na sua cidade natal?"], ["I miss the quiet streets and the old bridge. Here I have to keep it down at night, because of my landlady.", "Sinto falta das ruas quietas e da ponte velha. Aqui preciso fazer pouco barulho à noite, por causa da minha senhoria."], ["I know a café downtown where you can see the whole skyline.", "Conheço um café no centro onde dá para ver todo o horizonte da cidade."], ["Sure, let's go on Saturday. I'll wait for you on the doormat!", "Claro, vamos no sábado. Vou te esperar no capacho!"]], ["/aʊ/ em downtown e town", "O som /aʊ/ começa com a boca bem aberta, como em 'a', e termina fechando para 'u', parecido com o 'aú' de 'pau'. Town soa como 'taun' e downtown como 'dauntaun'.", ["downtown", "town"]], ["Downtown is the place ___ I work.", "where", "who", "O centro é o lugar onde eu trabalho.", "Where liga um lugar à descrição dele; who é para pessoas."], [["His hometown is a place where everybody knows everybody.", "A cidade natal dele é um lugar onde todo mundo conhece todo mundo."], ["I know a café downtown where you can see the whole skyline.", "Conheço um café no centro onde dá para ver todo o horizonte da cidade."]], [{"t": "c", "q": "This is the town ___ I was born.", "o": ["where", "who", "what"], "pt": "Esta é a cidade onde eu nasci.", "why": "Town é um lugar, então usamos where; who é para pessoas e what não liga a descrição."}, {"t": "l", "say": "My hometown is a place where everyone knows everyone.", "o": ["My hometown is a place where everyone knows everyone.", "My hometown is a place where everyone knows nobody.", "My hometown is a place where no one knows anyone."], "why": "A frase diz que todos conhecem todos (everyone knows everyone)."}, {"t": "b", "pt": "Esta é a cidade onde eu nasci.", "w": ["This", "is", "the", "town", "where", "I", "was", "born"]}, {"t": "b", "pt": "O centro é onde eu trabalho.", "w": ["Downtown", "is", "where", "I", "work"]}]];
