englishA2Plans[143]={"title": "Achados e perdidos", "file": "", "grammar": "Whose para posse", "goal": "Pergunte de quem é algo usando whose.", "words": [["lost property", "achados e perdidos"], ["claim ticket", "comprovante de retirada"], ["earring", "brinco"], ["hand in", "entregar"], ["describe", "descrever"], ["gold ring", "anel de ouro"], ["house keys", "chaves de casa"], ["leather bag", "bolsa de couro"]]};
englishA2Content[143]=[[["Rosa works at the lost property office at the mall.", "A Rosa trabalha no setor de achados e perdidos do shopping."], ["Today the janitor comes to hand in a blue glove and a small mitten.", "Hoje o zelador vem entregar uma luva azul e uma luva de lã pequena."], ["Rosa puts a tag on each thing and writes the date on a claim ticket.", "A Rosa coloca uma etiqueta em cada coisa e escreve a data num comprovante de retirada."], ["She also finds a wallet, a handbag, and a gold earring.", "Ela também acha uma carteira, uma bolsa e um brinco dourado."], ["She puts them in a shopping bag.", "Ela coloca tudo numa sacola de compras."], ["Everybody who loses something hopes to see it again.", "Todo mundo que perde alguma coisa espera ver de novo."]], [["Good morning. Can I help you?", "Bom dia. Posso ajudar?"], ["Yes, I lost a red scarf in a fitting room yesterday.", "Sim, perdi um cachecol vermelho num provador ontem."], ["Let me check the shelf. Whose scarf is this one?", "Deixe-me olhar a prateleira. De quem é este cachecol?"], ["It's mine! I love it. My aunt made it. I also lost a thermos.", "É meu! Eu adoro. Minha tia fez. Também perdi uma garrafa térmica."], ["Great! Can you describe your thermos? We have three.", "Ótimo! Você pode descrever sua garrafa térmica? Temos três."], ["It's silver, with a tag on the lid. Whose gloves are those on your desk?", "É prateada, com uma etiqueta na tampa. De quem são aquelas luvas na sua mesa?"], ["I don't know. A man handed them in this morning.", "Não sei. Um homem entregou hoje de manhã."], ["They look like my brother's. They have a small hole.", "Parecem as do meu irmão. Elas têm um furinho."], ["Then bring him here with this claim ticket.", "Então traga ele aqui com este comprovante."], ["Okay. I'll come back tomorrow with him.", "Certo. Volto amanhã com ele."]], ["/ʌ/ em glove e love", "O /ʌ/ de glove e love é um 'a' curto e relaxado, com a boca quase fechada e os lábios soltos: soa como 'glãv' e 'lãv'. Não diga 'glôv'.", ["glove", "love"]], ["___ gloves are these? They're on my desk.", "Whose", "Who's", "De quem são essas luvas? Estão na minha mesa.", "Whose pergunta de quem é algo; who's quer dizer who is."], [["Let me check the shelf. Whose scarf is this one?", "Deixe-me olhar a prateleira. De quem é este cachecol?"], ["It's silver, with a tag on the lid. Whose gloves are those on your desk?", "É prateada, com uma etiqueta na tampa. De quem são aquelas luvas na sua mesa?"]], [{"t": "c", "q": "___ umbrella is this? It's mine.", "o": ["Whose", "Who's", "Who"], "pt": "De quem é este guarda-chuva? É meu.", "why": "Para perguntar de quem é um objeto, usamos whose + substantivo."}, {"t": "l", "say": "Whose scarf is this?", "o": ["Whose scarf is this?", "Who found this scarf?", "Whose shoes are these?"], "why": "A pergunta é 'De quem é este cachecol?'."}, {"t": "b", "pt": "De quem é esta carteira?", "w": ["Whose", "wallet", "is", "this"]}, {"t": "b", "pt": "De quem são aquelas luvas?", "w": ["Whose", "gloves", "are", "those"]}]];
