englishA2Plans[152]={"title": "Fim de semana de lazer", "file": "", "grammar": "Enjoy, mind e finish + -ing", "goal": "Fale de gostos usando enjoy + -ing.", "words": [["kayak", "caiaque"], ["canoe", "canoa"], ["campground", "área de camping"], ["cast off", "soltar as amarras"], ["lifejacket", "colete salva-vidas"], ["firewood", "lenha"], ["raft", "bote inflável"], ["fishing rod", "vara de pesca"]]};
englishA2Content[152]=[[["Noah and Lia spend the weekend at a campground by the lake.", "Noah e Lia passam o fim de semana em uma área de camping perto do lago."], ["Noah enjoys paddling his canoe, but Lia likes her red kayak more.", "Noah gosta de remar a canoa, mas Lia gosta mais do caiaque vermelho dela."], ["Before they cast off, they put on their lifejackets.", "Antes de soltar as amarras, eles vestem os coletes salva-vidas."], ["Noah doesn't mind carrying the firewood to the camp.", "Noah não se importa de carregar a lenha até o acampamento."], ["After they finish eating lunch, they go on a short hike.", "Depois que terminam de almoçar, eles fazem uma caminhada curta."], ["At night they roast marshmallows, and Noah has a small sunburn on his nose.", "À noite eles assam marshmallows, e Noah tem uma pequena queimadura de sol no nariz."]], [["Lia, are you ready to cast off? The lake looks calm today.", "Lia, você está pronta para soltar as amarras? O lago parece calmo hoje."], ["Almost. I'm putting on my lifejacket. Do you mind carrying my paddle?", "Quase. Estou vestindo meu colete. Você se importa de carregar meu remo?"], ["Not at all. Which boat do you want, the kayak or the canoe?", "Imagina. Qual barco você quer, o caiaque ou a canoa?"], ["The kayak, please. I enjoy paddling alone, and you can take the canoe.", "O caiaque, por favor. Eu gosto de remar sozinha, e você pode pegar a canoa."], ["OK. We have to finish paddling before dark, though.", "Certo. Mas temos que terminar de remar antes de escurecer."], ["Don't worry. At camp we still have leftovers from last night.", "Sem preocupação. No acampamento ainda temos sobras da noite passada."], ["Great. Did you bring enough firewood for the campfire?", "Ótimo. Você trouxe lenha suficiente para a fogueira?"], ["Yes, I did. It's in the car, next to my safety vest.", "Sim, trouxe. Está no carro, ao lado do meu colete de segurança."]], ["/k/ em kayak e camp", "O /k/ de kayak e camp é feito com o fundo da língua tocando o céu da boca e soltando um sopro forte, como o c de casa, só que mais forte no começo da palavra. Em camp, o a abre bastante a boca, diferente de campo.", ["kayak", "camp"]], ["Noah enjoys ___ his canoe.", "paddling", "to paddle", "Noah gosta de remar a canoa dele.", "Depois de enjoy, o verbo vai na forma -ing."], [["Almost. I'm putting on my lifejacket. Do you mind carrying my paddle?", "Quase. Estou vestindo meu colete. Você se importa de carregar meu remo?"], ["The kayak, please. I enjoy paddling alone, and you can take the canoe.", "O caiaque, por favor. Eu gosto de remar sozinha, e você pode pegar a canoa."]], [{"t": "c", "q": "We have to finish ___ before dark.", "o": ["paddling", "to paddle", "paddle"], "pt": "Temos que terminar de remar antes de escurecer.", "why": "Depois de finish, o verbo vai na forma -ing."}, {"t": "l", "say": "Do you mind carrying my paddle?", "o": ["Do you mind carrying my paddle?", "Do you mind to carry my paddle?", "Do you mind carry my paddle?"], "why": "Depois de mind usamos o verbo com -ing (carrying)."}, {"t": "b", "pt": "Eu gosto de remar no lago.", "w": ["I", "enjoy", "paddling", "on", "the", "lake"]}, {"t": "b", "pt": "Você se importa de carregar a lenha?", "w": ["Do", "you", "mind", "carrying", "the", "firewood"]}]];
