englishA2ExtraWordExamples[152]={"raft": ["The kids built a small raft near the lake.", "As crianças construíram um pequeno bote perto do lago."], "fishing rod": ["I don't mind carrying the fishing rod.", "Não me importo de carregar a vara de pesca."]};
englishA2Plans[153]={"title": "Planejando uma festa de formatura", "file": "", "grammar": "Decide, plan e hope + to", "goal": "Fale de planos com decide to e plan to.", "words": [["podium", "pódio"], ["tassel", "borla"], ["graduate", "formando"], ["walk across the stage", "receber o diploma"], ["prom", "baile de formatura"], ["senior", "aluno do último ano"], ["fundraiser", "evento para arrecadar dinheiro"], ["donate", "doar"], ["cheerleader", "líder de torcida"]]};
englishA2Content[153]=[[["Ben is a senior, and his graduation is on June tenth.", "Ben está no último ano, e a formatura dele é no dia dez de junho."], ["Every graduate wears a gold tassel on a blue cap.", "Todo formando usa uma borla dourada em um capelo azul."], ["Ben plans to walk across the stage and shake his teacher's hand.", "Ben planeja receber o diploma no palco e apertar a mão do professor."], ["His friends hope to take a photo at the podium after the ceremony.", "Os amigos dele esperam tirar uma foto no pódio depois da cerimônia."], ["The cheerleaders decided to hold a fundraiser for the prom.", "As líderes de torcida decidiram fazer um evento para arrecadar dinheiro para o baile."], ["Ben's sister, a painter, decided to make a banner, and it will be on display in the hall.", "A irmã de Ben, que é pintora, decidiu fazer um banner, e ele ficará em exibição no salão."]], [["Ben, are you ready for graduation next week?", "Ben, você está pronto para a formatura da semana que vem?"], ["Almost. I plan to walk slowly, and I hope to smile.", "Quase. Eu planejo andar devagar e espero sorrir."], ["Ha! Don't worry. The line moves gradually, so you'll have time.", "Ha! Não se preocupe. A fila anda aos poucos, então você vai ter tempo."], ["True. My parents hope to arrive early.", "Verdade. Meus pais esperam chegar cedo."], ["Are the cheerleaders still having the fundraiser? Their cake last year was a masterpiece.", "As líderes de torcida ainda vão fazer o evento? O bolo delas no ano passado foi uma obra-prima."], ["Yes, they sell it on Friday, and I'll donate ten dollars.", "Sim, elas vendem na sexta, e eu vou doar dez dólares."], ["Great. I'll bring my camera and take your picture with the tassel.", "Ótimo. Vou trazer minha câmera e tirar sua foto com a borla."], ["Perfect, see you on Saturday!", "Perfeito, a gente se vê no sábado!"]], ["/dʒ/ em graduation e gym", "O /dʒ/ de graduation e gradual é como o dj de djalma: a língua encosta no céu da boca e solta o ar com som de voz. Não é o g de gato; é um som mais mole, parecido com o j de jeans.", ["graduation", "gradual"]], ["Ben decided ___ wear a blue tie.", "to", "wearing", "Ben decidiu usar uma gravata azul.", "Depois de decide, usamos to + verbo."], [["Ben plans to walk across the stage and shake his teacher's hand.", "Ben planeja receber o diploma no palco e apertar a mão do professor."], ["True. My parents hope to arrive early.", "Verdade. Meus pais esperam chegar cedo."]], [{"t": "c", "q": "The cheerleaders plan ___ sell cake.", "o": ["to", "selling", "for"], "pt": "As líderes de torcida planejam vender bolo.", "why": "Depois de plan, usamos to + verbo."}, {"t": "l", "say": "I plan to walk across the stage.", "o": ["I plan to walk across the stage.", "I plan walking across the stage.", "I plan to walking across the stage."], "why": "Plan pede to + verbo na forma base (to walk)."}, {"t": "b", "pt": "Eu espero chegar cedo.", "w": ["I", "hope", "to", "arrive", "early"]}, {"t": "b", "pt": "Ela decidiu doar dez dólares.", "w": ["She", "decided", "to", "donate", "ten", "dollars"]}]];
