englishA2Plans[156]={"title": "Vida de um fotógrafo", "file": "", "grammar": "Like, love, hate + -ing ou to", "goal": "Fale do que você ama ou odeia usando -ing.", "words": [["photographer", "fotógrafo"], ["zoom lens", "lente zoom"], ["shutter", "obturador"], ["shoot", "fotografar"], ["focus", "foco"], ["snapshot", "foto rápida"], ["angle", "ângulo"], ["blur", "borrão"]]};
englishA2Content[156]=[[["Mia is a photographer, and she loves shooting weddings.", "Mia é fotógrafa, e ela adora fotografar casamentos."], ["Her camera has a zoom lens and a very fast shutter.", "A câmera dela tem uma lente zoom e um obturador muito rápido."], ["She hates getting a blur in her photos, so she checks the focus.", "Ela odeia ter borrão nas fotos, então confere o foco."], ["Today she shoots photos of a graduate at the podium.", "Hoje ela fotografa uma formanda no pódio."], ["Between jobs, she likes to take snapshots of her friends on her phone.", "Entre os trabalhos, ela gosta de tirar fotos rápidas dos amigos com o celular."], ["Her friend Ana is a model, and she loves to pose in the hallway.", "A amiga dela, Ana, é modelo e adora posar no corredor."]], [["Mia, I'm ready. Where do you want me?", "Mia, estou pronta. Onde você me quer?"], ["Stand by the window. I like to shoot with natural light.", "Fique perto da janela. Gosto de fotografar com luz natural."], ["Do you like shooting weddings, or just snapshots like this?", "Você gosta de fotografar casamentos, ou só fotos rápidas como esta?"], ["I love shooting weddings, but I hate waking up at five in the morning.", "Adoro fotografar casamentos, mas odeio acordar às cinco da manhã."], ["Ha! Is your phone good for photos too?", "Ha! O seu celular também é bom para fotos?"], ["It's okay, but my zoom lens gives me better focus and less blur.", "É razoável, mas minha lente zoom me dá mais foco e menos borrão."], ["Do you want me to smile, or look serious?", "Quer que eu sorria ou fique séria?"], ["Smile a little and turn left. Perfect, that's the angle!", "Sorria um pouco e vire para a esquerda. Perfeito, é esse o ângulo!"]], ["/f/ em photographer e phone", "O /f/ de photographer e phone é igual ao f do português: o lábio de baixo toca os dentes de cima e o ar passa. Atenção: ph em inglês também soa como f, nunca como p.", ["photographer", "phone"]], ["Mia hates ___ a blur in her photos.", "getting", "get", "Mia odeia ter borrão nas fotos.", "Depois de hate, usamos o verbo com -ing ou to + verbo, nunca a forma base."], [["Mia is a photographer, and she loves shooting weddings.", "Mia é fotógrafa, e ela adora fotografar casamentos."], ["Between jobs, she likes to take snapshots of her friends on her phone.", "Entre os trabalhos, ela gosta de tirar fotos rápidas dos amigos com o celular."]], [{"t": "c", "q": "I like ___ with natural light.", "o": ["to shoot", "shoot", "shot"], "pt": "Eu gosto de fotografar com luz natural.", "why": "Depois de like usamos to + verbo ou verbo + -ing, nunca a forma base."}, {"t": "l", "say": "I love shooting weddings, but I hate waking up early.", "o": ["I love shooting weddings, but I hate waking up early.", "I love shoot weddings, but I hate wake up early.", "I love shooting weddings, but I hate wakes up early."], "why": "Love e hate pedem -ing (shooting, waking) ou to + verbo."}, {"t": "b", "pt": "Eu adoro fotografar casamentos.", "w": ["I", "love", "shooting", "weddings"]}, {"t": "b", "pt": "Ela gosta de tirar fotos com o celular.", "w": ["She", "likes", "taking", "photos", "with", "her", "phone"]}]];
