englishA2Plans[157]={"title": "Dormir bem", "file": "", "grammar": "Gerúndio como sujeito (Sleeping is...)", "goal": "Use um verbo -ing como sujeito da frase.", "words": [["duvet", "edredom"], ["mattress", "colchão"], ["insomnia", "insônia"], ["toss and turn", "virar na cama"], ["bedtime", "hora de dormir"], ["pillowcase", "fronha"], ["drowsy", "sonolento"], ["sleep mask", "máscara de dormir"]]};
englishA2Content[157]=[[["Ben has insomnia, and he is always tired during the day.", "Ben tem insônia e vive cansado durante o dia."], ["He doesn't want to toss and turn on his old mattress tonight.", "Ele não quer virar na cama no colchão velho esta noite."], ["Drinking coffee after dinner is a bad idea.", "Tomar café depois do jantar é uma péssima ideia."], ["Jogging in the park is good for him, and he can work out in the afternoon.", "Correr no parque faz bem para ele, e ele pode malhar à tarde."], ["Now he changes the pillowcase, puts a warm duvet on the bed, and uses earplugs because his dog snores.", "Agora ele troca a fronha, põe um edredom quente na cama e usa tampões porque o cachorro ronca."], ["Going to bed at the same time every night helps a lot.", "Ir para a cama no mesmo horário toda noite ajuda muito."]], [["You look drowsy, Ben. Did you sleep well last night?", "Você parece sonolento, Ben. Dormiu bem ontem à noite?"], ["Not really. Having insomnia is terrible.", "Nem tanto. Ter insônia é terrível."], ["Sorry to hear that. Maybe your mattress is too old.", "Sinto muito. Talvez seu colchão seja velho demais."], ["Maybe. Sleeping on it feels like sleeping on the floor.", "Talvez. Dormir nele parece dormir no chão."], ["Drinking warm milk before bedtime always helps me.", "Tomar leite morno antes da hora de dormir sempre me ajuda."], ["Thanks. I'll try it tonight, and I'll hydrate more during the day.", "Obrigado. Vou tentar hoje, e vou me hidratar mais durante o dia."], ["Good idea. Does your dog still snore at night?", "Boa ideia. Seu cachorro ainda ronca à noite?"], ["Yes, he does! That's why I need earplugs.", "Sim, ronca! É por isso que preciso de tampões de ouvido."]], ["/aɪ/ em insomnia e night", "O /aɪ/ de insomnia e night começa com a boca bem aberta, como o a de pá, e fecha para o i, como o ai de pai. Em night, o gh não se pronuncia: soa só /naɪt/.", ["insomnia", "night"]], ["___ coffee at night is a bad idea.", "Drinking", "Drink", "Tomar café à noite é uma péssima ideia.", "Quando um verbo é o sujeito da frase, ele usa -ing."], [["Drinking coffee after dinner is a bad idea.", "Tomar café depois do jantar é uma péssima ideia."], ["Drinking warm milk before bedtime always helps me.", "Tomar leite morno antes da hora de dormir sempre me ajuda."]], [{"t": "c", "q": "___ to bed early helps me sleep.", "o": ["Going", "Go", "Went"], "pt": "Ir para a cama cedo me ajuda a dormir.", "why": "O verbo no começo da frase como sujeito usa -ing."}, {"t": "l", "say": "Sleeping on this mattress is great.", "o": ["Sleeping on this mattress is great.", "Sleep on this mattress is great.", "Sleeping on this mattress are great."], "why": "Sujeito com -ing (Sleeping) leva is, no singular."}, {"t": "b", "pt": "Dormir bem é importante.", "w": ["Sleeping", "well", "is", "important"]}, {"t": "b", "pt": "Beber água me ajuda a dormir.", "w": ["Drinking", "water", "helps", "me", "sleep"]}]];
englishA2PhotoThemes[157]="health";
englishA2ExtraWordExamples[157]={"sleep mask": ["Wearing a sleep mask is helpful at night.", "Usar uma máscara de dormir ajuda à noite."]};
englishA2Plans[158]={"title": "Alugando equipamento de esqui", "file": "", "grammar": "Infinitivo de finalidade (to + verbo) e for + -ing", "goal": "Explique para que serve algo usando to e for.", "words": [["goggles case", "estojo de óculos"], ["ski pole", "bastão de esqui"], ["lift ticket", "passe do teleférico"], ["hit the slopes", "ir esquiar"], ["chairlift", "teleférico"], ["snowboard", "snowboard"], ["sled", "trenó"], ["buckle", "fivela"]]};
englishA2Content[158]=[[["Lia and Tom are at a ski lodge, and there is fresh snow on every slope.", "Lia e Tom estão em uma pousada de esqui, e há neve fresca em todas as pistas."], ["They go to the rental shop to get their gear.", "Eles vão à loja de aluguel para pegar o equipamento."], ["A tall man gives Lia boots, but the buckle on one boot is broken.", "Um homem alto dá botas a Lia, mas a fivela de uma bota está quebrada."], ["Tom takes a ski pole and a goggles case to keep his goggles safe.", "Tom pega um bastão de esqui e um estojo de óculos para manter os óculos seguros."], ["They buy a lift ticket and ride the chairlift to the top.", "Eles compram um passe do teleférico e sobem de teleférico até o topo."], ["Tom is a photographer, but today he just wants to hit the slopes.", "Tom é fotógrafo, mas hoje ele só quer ir esquiar."]], [["Good morning! What can I get you today?", "Bom dia! O que posso trazer para vocês hoje?"], ["We'd like to rent skis and boots. I'm in good shape from jogging.", "Queremos alugar esquis e botas. Estou em boa forma por causa das corridas."], ["A lift ticket is sixty dollars. It's for using the chairlift all day.", "O passe do teleférico custa sessenta dólares. É para usar o teleférico o dia todo."], ["OK. And what's that? Is it a snowboard?", "Certo. E o que é aquilo? É um snowboard?"], ["No, that's a sled. Kids use it to play on the hill.", "Não, é um trenó. As crianças usam para brincar na colina."], ["I see. Can I have a case for my goggles? I don't want to lose them.", "Entendi. Posso levar um estojo para os meus óculos? Não quero perdê-los."], ["Sure. People use a goggles case to keep goggles dry.", "Claro. As pessoas usam um estojo de óculos para mantê-los secos."], ["Perfect. Then we can hit the slopes, and I'll hydrate first.", "Perfeito. Então podemos ir esquiar, e eu me hidrato primeiro."]], ["/oʊ/ em slope e snow", "O /oʊ/ de slope e snow começa com os lábios meio arredondados, como o o de bola, e termina fechando para um u curto. É um movimento só, como ôu.", ["slope", "snow"]], ["People use a lift ticket ___ ride the chairlift.", "to", "for", "As pessoas usam um passe para subir no teleférico.", "Para explicar a finalidade com um verbo, usamos to + verbo."], [["A lift ticket is sixty dollars. It's for using the chairlift all day.", "O passe do teleférico custa sessenta dólares. É para usar o teleférico o dia todo."], ["Sure. People use a goggles case to keep goggles dry.", "Claro. As pessoas usam um estojo de óculos para mantê-los secos."]], [{"t": "c", "q": "A goggles case is ___ keeping goggles dry.", "o": ["for", "to", "at"], "pt": "Um estojo de óculos serve para manter os óculos secos.", "why": "Antes de um verbo com -ing, usamos for para dizer a utilidade."}, {"t": "l", "say": "We use the sled to play on the hill.", "o": ["We use the sled to play on the hill.", "We use the sled for play on the hill.", "We use the sled to playing on the hill."], "why": "Para dizer o objetivo com um verbo, usamos to + verbo."}, {"t": "b", "pt": "Eu uso um estojo para guardar meus óculos.", "w": ["I", "use", "a", "case", "to", "keep", "my", "goggles"]}, {"t": "b", "pt": "O passe serve para usar o teleférico.", "w": ["The", "ticket", "is", "for", "using", "the", "chairlift"]}]];
