englishA2ExtraWordExamples[160]={"throw away": ["Don't throw away your keys.", "Não jogue fora suas chaves."], "trash can": ["The trash can is under my desk.", "A lata de lixo fica embaixo da minha mesa."]};
englishA2Plans[161]={"title": "Rotina de manhã bem cedo", "file": "", "grammar": "Verbos frasais sem objeto (get up, wake up)", "goal": "Descreva uma rotina usando get up e wake up.", "words": [["alarm clock", "despertador"], ["snooze", "soneca do despertador"], ["bedside table", "criado-mudo"], ["oversleep", "dormir demais"], ["robe", "roupão"], ["rooster", "galo"], ["sleepyhead", "dorminhoco"], ["stretch out", "esticar-se"]]};
englishA2Content[161]=[[["Noah's alarm clock rings before sunrise every morning.", "O despertador do Noah toca antes do nascer do sol toda manhã."], ["He wakes up, but he hits the snooze button twice.", "Ele acorda, mas aperta o botão de soneca duas vezes."], ["Then he gets up, wears his robe and opens the curtains.", "Então ele levanta, veste o roupão e abre as cortinas."], ["Last Monday he overslept, so he got up late.", "Na segunda passada ele dormiu demais, então levantou tarde."], ["His friend Lia, a photographer, waited for him at the park.", "A amiga dele, a Lia, fotógrafa, esperou por ele no parque."], ["Now Noah puts the alarm clock far from his bed.", "Agora o Noah deixa o despertador longe da cama."]], [["Noah, you're late again, sleepyhead! What happened this time?", "Noah, você está atrasado de novo, dorminhoco! O que houve desta vez?"], ["I woke up at seven, but I hit snooze three times.", "Eu acordei às sete, mas apertei a soneca três vezes."], ["Three times? I always get up at six, even on Sunday. I'm like a rooster!", "Três vezes? Eu sempre levanto às seis, até no domingo. Sou como um galo!"], ["Really? My alarm clock is on the bedside table, so I can reach it.", "Sério? Meu despertador fica no criado-mudo, então consigo alcançar."], ["Put it on the other side of the room. Then you have to get up to turn it off.", "Coloque do outro lado do quarto. Aí você tem que levantar para desligar."], ["Good idea. Is the whole group already at the park for the shoot?", "Boa ideia. O grupo todo já está no parque para a sessão de fotos?"], ["Yes, everybody is here, and we have your zoom lens.", "Sim, todo mundo está aqui, e nós temos a sua lente zoom."], ["Great! I'm sorry, Lia. Tomorrow I won't oversleep, I promise.", "Ótimo! Desculpe, Lia. Amanhã eu não vou dormir demais, prometo."]], ["/uː/ em snooze e group", "Em snooze e group, o \"oo\" é um \"u\" longo: arredonde bem os lábios, leve-os para a frente e segure o som um pouco mais que no português \"tu\".", ["snooze", "group"]], ["Noah wakes ___ at six every morning.", "up", "on", "O Noah acorda às seis toda manhã.", "O verbo frasal é wake up: acordar."], [["He wakes up, but he hits the snooze button twice.", "Ele acorda, mas aperta o botão de soneca duas vezes."], ["Then he gets up, wears his robe and opens the curtains.", "Então ele levanta, veste o roupão e abre as cortinas."]], [{"t": "c", "q": "Please don't ___ tomorrow!", "o": ["oversleep", "overslept", "oversleeps"], "pt": "Por favor, não durma demais amanhã!", "why": "Depois de don't usamos o verbo na forma básica: oversleep."}, {"t": "l", "say": "He gets up at six.", "o": ["He gets up at six.", "He gives up at six.", "He gets up at seven."], "why": "Ouça gets up (levanta) e six (seis)."}, {"t": "b", "pt": "Eu acordo às seis.", "w": ["I", "wake", "up", "at", "six"]}, {"t": "b", "pt": "Ele apertou o botão de soneca duas vezes.", "w": ["He", "hit", "the", "snooze", "button", "twice"]}]];
