englishA2Plans[164]={"title": "Desistindo de um hábito ruim", "file": "", "grammar": "Give up, come back, carry on", "goal": "Use give up e come back em frases.", "words": [["nicotine", "nicotina"], ["patch", "adesivo"], ["willpower", "força de vontade"], ["cold turkey", "parar de uma vez"], ["cigarette", "cigarro"], ["gum", "chiclete"], ["craving", "vontade forte"], ["smoker", "fumante"], ["chew", "mastigar"]]};
englishA2Content[164]=[[["Luis is a smoker, but he wants to stop.", "O Luis é fumante, mas quer parar."], ["This week he is giving up, and he wears a nicotine patch.", "Esta semana ele está parando e usa um adesivo de nicotina."], ["Some people quit cold turkey, but Luis needs help.", "Algumas pessoas param de uma vez, mas o Luis precisa de ajuda."], ["When he wants a cigarette, he chews gum and carries on with his work.", "Quando ele quer um cigarro, mastiga chiclete e continua o trabalho."], ["A sticky note on his desk says, \"Don't give up!\"", "Um post-it na mesa dele diz: \"Não desista!\""], ["He threw all his cigarettes away, and he feels proud.", "Ele jogou todos os cigarros fora e se sente orgulhoso."]], [["Luis, you look better today. How's the patch?", "Luis, você está melhor hoje. Como está o adesivo?"], ["It helps a lot. I didn't smoke at all this week.", "Ajuda muito. Eu não fumei nada esta semana."], ["Wow! Did you stop cold turkey, or do you use the patch?", "Uau! Você parou de uma vez ou usa o adesivo?"], ["I use the patch, but I need a lot of willpower too.", "Uso o adesivo, mas preciso de muita força de vontade também."], ["I know. My dad gave up smoking last year, and he never came back to it.", "Eu sei. Meu pai parou de fumar no ano passado e nunca voltou."], ["That's great. Was it hard for him? Some days my craving is so strong that I almost give up.", "Que ótimo. Foi difícil para ele? Alguns dias minha vontade é tão forte que eu quase desisto."], ["Don't give up! Just carry on, and call me when you feel bad.", "Não desista! Continue e me ligue quando se sentir mal."], ["Thanks, Nora. Tomorrow I'll set my alarm clock and throw away my last cigarettes.", "Obrigado, Nora. Amanhã vou programar o despertador e jogar fora meus últimos cigarros."]], ["/t/ em patch e turkey", "Em turkey, o \"t\" inicial leva um sopro de ar, mais forte que o \"t\" do português. Em patch, o final \"tch\" é um som só, como em \"tchau\"; não acrescente \"i\" no fim.", ["patch", "turkey"]], ["My dad gave ___ smoking last year.", "up", "out", "Meu pai parou de fumar no ano passado.", "Give up significa desistir ou parar de fazer algo."], [["Some people quit cold turkey, but Luis needs help.", "Algumas pessoas param de uma vez, mas o Luis precisa de ajuda."], ["A sticky note on his desk says, \"Don't give up!\"", "Um post-it na mesa dele diz: \"Não desista!\""]], [{"t": "c", "q": "Don't stop now. Carry ___ with your work!", "o": ["on", "off", "in"], "pt": "Não pare agora. Continue com seu trabalho!", "why": "Carry on significa continuar."}, {"t": "l", "say": "Don't give up!", "o": ["Don't give up!", "Don't get up!", "Don't give out!"], "why": "Give up significa desistir."}, {"t": "b", "pt": "Ele voltou para casa tarde.", "w": ["He", "came", "back", "home", "late"]}, {"t": "b", "pt": "Eu uso um adesivo de nicotina.", "w": ["I", "use", "a", "nicotine", "patch"]}]];
