englishA2Plans[167]={"title": "Descrevendo onde ficam as lojas da praça", "file": "", "grammar": "Preposições de lugar: between, opposite, next to, behind", "goal": "Dê a posição de lugares usando preposições.", "words": [["plaza", "praça"], ["gazebo", "coreto"], ["flagpole", "mastro"], ["across from", "em frente a"], ["street lamp", "poste de luz"], ["ice cream stand", "barraquinha de sorvete"], ["bulletin board", "mural de avisos"], ["corner store", "mercadinho da esquina"]]};
englishA2Content[167]=[[["The plaza in Jack's town is small but fun.", "A praça da cidade do Jack é pequena, mas divertida."], ["In the middle there is a fountain, and the gazebo is next to it.", "No meio há uma fonte, e o coreto fica ao lado dela."], ["The flagpole is behind the gazebo, and a street lamp stands next to it.", "O mastro fica atrás do coreto, e um poste de luz fica ao lado dele."], ["The bakery is across from the plaza, between the bank and the pharmacy.", "A padaria fica em frente à praça, entre o banco e a farmácia."], ["The ice cream stand is opposite the bakery, near the crosswalk.", "A barraquinha de sorvete fica na frente da padaria, perto da faixa de pedestres."], ["Jack reads the bulletin board, and then he eats ice cream by the fountain.", "O Jack lê o mural de avisos e depois toma sorvete perto da fonte."]], [["Excuse me, is there a bakery near the plaza?", "Com licença, tem uma padaria perto da praça?"], ["Yes! It's across from the plaza, between the bank and the pharmacy.", "Tem! Fica em frente à praça, entre o banco e a farmácia."], ["Thanks. And where can I buy a thesaurus? I also need a bookmark.", "Obrigada. E onde posso comprar um dicionário de sinônimos? Também preciso de um marcador de página."], ["The bookstore is next to the pharmacy. You can't miss it.", "A livraria fica ao lado da farmácia. Você não vai errar."], ["Great. Is the gazebo in the middle of the plaza only for concerts?", "Ótimo. O coreto no meio da praça é só para shows?"], ["Yes, on Sundays. The band plays behind the fountain, next to the flagpole.", "É, aos domingos. A banda toca atrás da fonte, ao lado do mastro."], ["Sounds fun! I'll look it up online. Is the ice cream stand near the crosswalk at the intersection?", "Parece divertido! Vou procurar online. A barraquinha de sorvete fica perto da faixa de pedestres no cruzamento?"], ["Yes, it is. Come at six, and I'll buy you an ice cream.", "Fica, sim. Venha às seis, e eu pago um sorvete para você."]], ["/f/ em fountain e fun", "Em fountain e fun, morda de leve o lábio inferior com os dentes de cima e sopre o ar, como no \"f\" de \"faca\". Em fountain, o \"ou\" soa como \"au\" (FAUN-tin).", ["fountain", "fun"]], ["The bank is ___ the bakery and the pharmacy.", "between", "opposite", "O banco fica entre a padaria e a farmácia.", "Between é usado com duas coisas: between A and B."], [["The flagpole is behind the gazebo, and a street lamp stands next to it.", "O mastro fica atrás do coreto, e um poste de luz fica ao lado dele."], ["The bakery is across from the plaza, between the bank and the pharmacy.", "A padaria fica em frente à praça, entre o banco e a farmácia."]], [{"t": "c", "q": "The bakery is ___ from the plaza.", "o": ["across", "between", "behind"], "pt": "A padaria fica em frente à praça.", "why": "Across from significa do outro lado, em frente."}, {"t": "l", "say": "The flagpole is behind the gazebo.", "o": ["The flagpole is behind the gazebo.", "The flagpole is next to the gazebo.", "The flagpole is opposite the gazebo."], "why": "Behind significa atrás de."}, {"t": "b", "pt": "A padaria fica ao lado do banco.", "w": ["The", "bakery", "is", "next", "to", "the", "bank"]}, {"t": "b", "pt": "O coreto fica atrás da fonte.", "w": ["The", "gazebo", "is", "behind", "the", "fountain"]}]];
