englishA2ExtraWordExamples[167]={"corner store": ["The corner store is next to the bakery.", "O mercadinho da esquina fica ao lado da padaria."]};
englishA2Plans[168]={"title": "Passeio de bicicleta pela ciclovia", "file": "", "grammar": "Preposições de movimento: through, along, across, past", "goal": "Descreva trajetos usando preposições de movimento.", "words": [["cycle path", "ciclovia"], ["underpass", "passagem subterrânea"], ["handlebar", "guidão"], ["ride along", "pedalar ao longo"], ["cyclist", "ciclista"], ["reflector", "refletor"], ["water bottle", "garrafa de água"], ["flat tire", "pneu furado"], ["bike lane", "faixa de bicicleta"]]};
englishA2Content[168]=[[["Zoe is a cyclist, and she rides along the cycle path every Sunday.", "A Zoe é ciclista e pedala pela ciclovia todo domingo."], ["First she goes through the park, and then she goes across a small bridge.", "Primeiro ela passa pelo parque e depois atravessa uma pequena ponte."], ["After the bridge, she takes the underpass under the road.", "Depois da ponte, ela pega a passagem subterrânea sob a rua."], ["She holds the handlebar tight and rides past the old market.", "Ela segura firme o guidão e passa pela feira antiga."], ["It's hot, so she drinks from her water bottle and takes off her jacket.", "Está quente, então ela bebe da garrafa de água e tira a jaqueta."], ["On the last hill she needs a lot of willpower, but she doesn't stop.", "Na última ladeira ela precisa de muita força de vontade, mas não para."]], [["Zoe, do you want to ride along the river with me? It's on my agenda today.", "Zoe, você quer pedalar comigo ao longo do rio? Está na minha agenda hoje."], ["Sure! Which way do we go? Through the park or along the street?", "Claro! Por onde vamos? Pelo parque ou ao longo da rua?"], ["Through the park. Then we go across the bridge and past the school.", "Pelo parque. Depois atravessamos a ponte e passamos pela escola."], ["Is there a tunnel? I don't like the underpass at the end of the cycle path.", "Tem túnel? Não gosto da passagem subterrânea no fim da ciclovia."], ["Yes, but it's well lit. Don't worry, there's a bike lane, and it's really short.", "Tem, mas é bem iluminado. Não se preocupe, tem faixa de bicicleta, e é bem curto."], ["Okay. One more thing: I had a flat tire last week, so I have a patch on it. The reflector is loose too.", "Certo. Mais uma coisa: tive um pneu furado semana passada, então tem um remendo. O refletor também está solto."], ["Let me see. I have a small tool, so I can fix the pedal in two minutes.", "Deixe-me ver. Tenho uma ferramenta pequena, então posso consertar o pedal em dois minutos."], ["Thanks, Max! Then we can start. I'm really excited.", "Valeu, Max! Então podemos começar. Estou muito animada."]], ["/l/ em tunnel e pedal", "Em tunnel e pedal, o \"l\" final é escuro: encoste a ponta da língua atrás dos dentes de cima e segure. Não termine em \"u\" como no português \"Brasil\".", ["tunnel", "pedal"]], ["Zoe rides ___ the tunnel and comes out near the lake.", "through", "across", "A Zoe passa pelo túnel e sai perto do lago.", "Through significa atravessar por dentro de algo, como um túnel."], [["Zoe is a cyclist, and she rides along the cycle path every Sunday.", "A Zoe é ciclista e pedala pela ciclovia todo domingo."], ["She holds the handlebar tight and rides past the old market.", "Ela segura firme o guidão e passa pela feira antiga."]], [{"t": "c", "q": "She goes ___ the bridge to the other side.", "o": ["across", "through", "past"], "pt": "Ela atravessa a ponte para o outro lado.", "why": "Across significa de um lado ao outro."}, {"t": "l", "say": "She rides past the school.", "o": ["She rides past the school.", "She rides along the school.", "She rides across the school."], "why": "Past significa passar por perto sem parar."}, {"t": "b", "pt": "Nós passamos pelo túnel.", "w": ["We", "go", "through", "the", "tunnel"]}, {"t": "b", "pt": "Ela passa de bicicleta pela escola.", "w": ["She", "rides", "past", "the", "school"]}]];
englishA2PhotoThemes[168]="map";
englishA2Plans[169]={"title": "Revisão: Notícias do dia", "file": "", "grammar": "Revisão: passiva, present perfect e past continuous", "goal": "Resuma notícias usando passiva e tempos anteriores.", "words": [["editor", "editor"], ["journalist", "jornalista"], ["newsstand", "banca de jornal"], ["press conference", "coletiva de imprensa"], ["article", "reportagem"], ["mayor", "prefeito"], ["front page", "primeira página"], ["publish", "publicar"]]};
englishA2Content[169]=[[["Every morning, Kate buys a newspaper at the newsstand.", "Toda manhã, a Kate compra um jornal na banca."], ["Today the headline says, \"New park is opened by the mayor.\"", "Hoje a manchete diz: \"Novo parque é inaugurado pelo prefeito.\""], ["The article was written by a young journalist.", "A reportagem foi escrita por uma jovem jornalista."], ["The editor has chosen a big photo for the front page.", "O editor escolheu uma foto grande para a primeira página."], ["While the mayor was speaking, a dog put its head on his shoe.", "Enquanto o prefeito falava, um cachorro pôs a cabeça no sapato dele."], ["Many people have already shared the funny photo.", "Muita gente já compartilhou a foto engraçada."]], [["Kate, have you seen today's headline? It's about our park.", "Kate, você viu a manchete de hoje? É sobre o nosso parque."], ["Yes! The new park was opened by the mayor yesterday.", "Vi! O novo parque foi inaugurado pelo prefeito ontem."], ["I was working, so I didn't go. My lecture was at the same time.", "Eu estava trabalhando, então não fui. Minha aula era no mesmo horário."], ["I met the journalist at the press conference. It had to wrap up early because of the dog.", "Conheci a jornalista na coletiva. Ela teve que acabar cedo por causa do cachorro."], ["The dog? Was it really on the stage?", "O cachorro? Ele estava mesmo no palco?"], ["Yes! The mayor was giving his speech when the dog sat on his shoe. It wasn't on the agenda!", "Sim! O prefeito estava fazendo o discurso quando o cachorro sentou no sapato dele. Não estava na pauta!"], ["Ha! The editor has chosen that photo for the front page, right?", "Ha! O editor escolheu essa foto para a primeira página, certo?"], ["Yes, he has. They will publish it online too, but go to the newsstand and see it!", "Escolheu, sim. Eles vão publicar online também, mas vá à banca e veja!"]], ["/hɛd/ em headline e head", "Em headline e head, o \"h\" é um sopro de ar na garganta, como o \"r\" inicial de \"rato\" no Rio. O \"ea\" soa como \"é\" aberto, de \"pé\", e não como \"i\".", ["headline", "head"]], ["The article ___ by a young journalist.", "was written", "wrote", "A reportagem foi escrita por uma jovem jornalista.", "Na passiva usamos was/were + particípio: was written."], [["The article was written by a young journalist.", "A reportagem foi escrita por uma jovem jornalista."], ["The editor has chosen a big photo for the front page.", "O editor escolheu uma foto grande para a primeira página."]], [{"t": "c", "q": "While the mayor ___ , a dog came to the stage.", "o": ["was speaking", "spoke", "has spoken"], "pt": "Enquanto o prefeito falava, um cachorro subiu ao palco.", "why": "Uma ação em andamento no passado usa was speaking."}, {"t": "l", "say": "The park was opened by the mayor.", "o": ["The park was opened by the mayor.", "The park opened by the mayor.", "The park was open by the mayor."], "why": "Na passiva: was + opened + by."}, {"t": "b", "pt": "O editor escolheu a manchete.", "w": ["The", "editor", "has", "chosen", "the", "headline"]}, {"t": "b", "pt": "A foto foi tirada por uma jornalista.", "w": ["The", "photo", "was", "taken", "by", "a", "journalist"]}]];
englishA2PhotoThemes[169]="chat";
englishA2MiniStories[169]=["A banca sem jornais", "Kate works at a small newsstand near the station.~A Kate trabalha numa pequena banca perto da estação.|One morning, the delivery truck didn't come.~Numa manhã, o caminhão de entrega não veio.|People were waiting in line, and they weren't happy.~As pessoas esperavam na fila e não estavam felizes.|Kate called the editor. \"The truck broke down,\" he said.~A Kate ligou para o editor. \"O caminhão quebrou\", ele disse.|Kate had an idea: a young journalist could read the headlines.~A Kate teve uma ideia: uma jovem jornalista podia ler as manchetes.|The journalist stood on a box and was reading the news when more people arrived.~A jornalista subiu numa caixa e estava lendo as notícias quando chegou mais gente.|Soon a big crowd was listening.~Logo uma multidão estava ouvindo.|Then the truck was fixed by a mechanic, and the newspapers arrived.~Então o caminhão foi consertado por um mecânico, e os jornais chegaram.|Everyone bought a newspaper, and Kate was thanked by the editor.~Todos compraram um jornal, e a Kate foi agradecida pelo editor.|After that day, her newsstand has been famous for its morning news.~Depois daquele dia, a banca dela ficou famosa pelas notícias da manhã."];
englishA2Plans[170]={"title": "Cuidado ao dirigir à noite", "file": "", "grammar": "Advérbios de modo (carefully, slowly)", "goal": "Descreva como algo é feito usando advérbios.", "words": [["headlight", "farol"], ["windshield", "para-brisa"], ["wipers", "limpadores de para-brisa"], ["pay attention", "prestar atenção"], ["curve", "curva"], ["low beam", "farol baixo"], ["wet road", "pista molhada"], ["speed up", "acelerar"]]};
englishA2Content[170]=[[["Rosa drives home from the plaza at night.", "Rosa dirige para casa saindo da praça à noite."], ["There is thick fog, so she drives slowly.", "Há uma neblina espessa, então ela dirige devagar."], ["The road is slippery, and there is a sharp curve ahead.", "A pista está escorregadia, e há uma curva fechada à frente."], ["She turns on her headlights and sees a reflector in her lane.", "Ela acende os faróis e vê um refletor na sua faixa."], ["Rosa brakes carefully and checks the dashboard.", "Rosa freia com cuidado e confere o painel."], ["Then she hears a short horn and smiles.", "Então ela ouve uma buzina curta e sorri."]], [["Rosa, did you drive home from the plaza last night?", "Rosa, você voltou dirigindo da praça ontem à noite?"], ["Yes, I did. The fog was really thick, so I drove slowly.", "Sim. A neblina estava bem espessa, então dirigi devagar."], ["Really? Did your headlights work well?", "É mesmo? Seus faróis funcionaram bem?"], ["Yes, but the wipers didn't work properly on the windshield.", "Sim, mas os limpadores não funcionaram direito no para-brisa."], ["That sounds dangerous. What did you do?", "Isso parece perigoso. O que você fez?"], ["I stopped across from the newsstand and cleaned the windshield carefully.", "Parei em frente à banca de jornal e limpei o para-brisa com cuidado."], ["Smart. You have to pay attention at night.", "Esperta. Você tem que prestar atenção à noite."], ["I know. Now I check my wipers before every long trip.", "Eu sei. Agora confiro meus limpadores antes de toda viagem longa."]], ["/ɔr/ em horn e short", "O som /ɔr/ de horn e short: arredonde bem os lábios, abra a boca como em 'ó' e puxe a língua para trás no final, sem rolar o R como no português.", ["horn", "short"]], ["Rosa drives ___ in the fog.", "slowly", "slow", "Rosa dirige devagar na neblina.", "O advérbio slowly descreve o verbo drives; slow é adjetivo."], [["There is thick fog, so she drives slowly.", "Há uma neblina espessa, então ela dirige devagar."], ["Rosa brakes carefully and checks the dashboard.", "Rosa freia com cuidado e confere o painel."]], [{"t": "c", "q": "Please close the door ___.", "o": ["quietly", "quiet", "quietness"], "pt": "Por favor, feche a porta em silêncio.", "why": "O advérbio quietly descreve como fechar a porta."}, {"t": "l", "say": "She drives carefully at night.", "o": ["She drives carefully at night.", "She drives careful at night.", "She drive carefully at night."], "why": "Verbo no presente com -s e advérbio carefully."}, {"t": "b", "pt": "Ele dirige muito devagar.", "w": ["He", "drives", "very", "slowly"]}, {"t": "b", "pt": "Ela limpa o para-brisa com cuidado.", "w": ["She", "cleans", "the", "windshield", "carefully"]}]];
