englishA2Plans[174]={"title": "Informação na rodoviária", "file": "", "grammar": "Perguntas indiretas: Could you tell me where...?", "goal": "Peça uma informação usando Could you tell me.", "words": [["ticket window", "guichê"], ["luggage locker", "armário de bagagem"], ["arrivals board", "painel de chegadas"], ["information desk", "balcão de informações"], ["terminal", "terminal"], ["baggage", "bagagem"], ["porter", "carregador"], ["round-trip", "ida e volta"]]};
englishA2Content[174]=[[["Tom is a journalist, and he arrives at the bus terminal early.", "Tom é jornalista e chega cedo ao terminal rodoviário."], ["He needs to get to a press conference in Boston.", "Ele precisa chegar a uma coletiva de imprensa em Boston."], ["He looks at the arrivals board, but he can't find his bus.", "Ele olha o painel de chegadas, mas não acha seu ônibus."], ["At the information desk, he asks, \"Could you tell me where platform six is?\"", "No balcão de informações, ele pergunta: \"Pode me dizer onde fica a plataforma seis?\""], ["The woman says it's past the ticket window, on the left.", "A mulher diz que fica depois do guichê, à esquerda."], ["Tom buys a coffee at the newsstand and waits for his departure.", "Tom compra um café na banca e espera a hora de partir."]], [["Excuse me. Could you tell me where the luggage lockers are?", "Com licença. Pode me dizer onde ficam os armários de bagagem?"], ["Sure. They're next to the ticket window, near the main entrance.", "Claro. Ficam ao lado do guichê, perto da entrada principal."], ["Thanks. Could you also tell me how much a round-trip ticket to Boston costs?", "Obrigado. Também pode me dizer quanto custa uma passagem de ida e volta para Boston?"], ["It costs forty dollars. A porter can help you with your baggage.", "Custa quarenta dólares. Um carregador pode ajudar com sua bagagem."], ["Great. Could you tell me what time the next bus leaves?", "Ótimo. Pode me dizer a que horas sai o próximo ônibus?"], ["It leaves at 3:15 from platform six. You can see it on the arrivals board.", "Sai às 15h15 da plataforma seis. Dá para ver no painel de chegadas."], ["Perfect. So I have time for a coffee before the departure?", "Perfeito. Então tenho tempo para um café antes da partida?"], ["Yes, you do. There's a newsstand right by the main entrance.", "Tem, sim. Há uma banca de jornal bem na entrada principal."]], ["/ɛ/ em departure e desk", "O som /ɛ/ de departure e desk: boca meio aberta e língua no meio, parecido com o 'é' de 'café', mas mais curto. Cuidado para não dizer 'dísk'.", ["departure", "desk"]], ["Could you tell me where ___ is?", "the gate", "is the gate", "Pode me dizer onde fica o portão?", "Na pergunta indireta o sujeito vem antes do verbo: where the gate is."], [["Sure. They're next to the ticket window, near the main entrance.", "Claro. Ficam ao lado do guichê, perto da entrada principal."], ["Great. Could you tell me what time the next bus leaves?", "Ótimo. Pode me dizer a que horas sai o próximo ônibus?"]], [{"t": "c", "q": "Could you tell me what time the bus ___?", "o": ["leaves", "does it leave", "does leave"], "pt": "Pode me dizer a que horas o ônibus sai?", "why": "Na pergunta indireta não se usa does; o verbo leaves vem depois do sujeito."}, {"t": "l", "say": "Could you tell me where the lockers are?", "o": ["Could you tell me where the lockers are?", "Could you tell me where are the lockers?", "Could you tell me where the lockers is?"], "why": "A ordem certa é where + sujeito + verbo, e lockers pede are."}, {"t": "b", "pt": "Pode me dizer onde fica o portão?", "w": ["Could", "you", "tell", "me", "where", "the", "gate", "is"]}, {"t": "b", "pt": "Pode me dizer quando ele sai?", "w": ["Could", "you", "tell", "me", "when", "it", "leaves"]}]];
