englishA2ExtraWordExamples[181]={"hold hands": ["The two friends hold hands and help each other.", "Os dois amigos dão as mãos e se ajudam."]};
englishA2Plans[182]={"title": "Procurando alguém na multidão do festival", "file": "", "grammar": "Someone, anyone, no one, everyone", "goal": "Use pronomes indefinidos para pessoas.", "words": [["lineup", "programação de shows"], ["wristband", "pulseira de evento"], ["crowd barrier", "grade de contenção"], ["front row", "primeira fila"], ["headliner", "atração principal"], ["live band", "banda ao vivo"], ["loud music", "música alta"], ["main stage", "palco principal"]]};
englishA2Content[182]=[[["Lia is at a music festival at a big venue with her friends.", "Lia está num festival de música num grande local com os amigos."], ["Everyone wants to be in the front row by the crowd barrier.", "Todo mundo quer ficar na primeira fila, perto da grade."], ["The lineup is great, and the headliner starts at nine.", "A programação é ótima, e a atração principal começa às nove."], ["But Lia can't find her brother, and she doesn't see anyone she knows.", "Mas a Lia não acha o irmão e não vê ninguém que conheça."], ["Someone waves at her from the lawn.", "Alguém acena para ela do gramado."], ["It's Noah, and he has a pair of earplugs for her!", "É o Noah, e ele tem protetores de ouvido para ela!"]], [["Noah, where are you? I don't see anyone I know.", "Noah, onde você está? Não vejo ninguém que eu conheça."], ["I'm on the lawn, near the meeting point. Wave to me!", "Estou no gramado, perto do ponto de encontro. Acene para mim!"], ["Okay, I see someone with a red wristband. Is that you?", "Ok, vejo alguém com uma pulseira vermelha. É você?"], ["Yes, it's me! I got this wristband at the sign in desk.", "Sou eu! Peguei esta pulseira na mesa de credenciamento."], ["Nice. The headliner starts soon, and I forgot my earplugs.", "Legal. A atração principal começa logo, e esqueci meus protetores."], ["No problem. I have extra earplugs in my bag. Do you want some?", "Sem problema. Tenho protetores extras na bolsa. Quer?"], ["Yes, please. And I already have a sunburn on my nose!", "Quero, por favor. E eu já estou com o nariz queimado de sol!"], ["Ouch! Let's find shade near the campsite. Then everyone will be happy.", "Ai! Vamos achar uma sombra perto do camping. Aí todo mundo fica feliz."], ["Sure. But first, I want to see the lineup.", "Claro. Mas primeiro quero ver a programação."], ["Okay, deal. The first band starts at eight.", "Tá bom, combinado. A primeira banda começa às oito."]], ["/ɪ/ em wristband e festival", "O /ɪ/ é um 'i' curto e relaxado, entre 'i' e 'e', com a boca quase parada. Não alongue como em 'feet': diga 'RIST-band', não 'RIIST-band'.", ["wristband", "festival"]], ["Ben doesn't know ___ at the party.", "anyone", "no one", "Ben não conhece ninguém na festa.", "Com don't (negativa), usamos anyone, não no one."], [["But Lia can't find her brother, and she doesn't see anyone she knows.", "Mas a Lia não acha o irmão e não vê ninguém que conheça."], ["Someone waves at her from the lawn.", "Alguém acena para ela do gramado."]], [{"t": "c", "q": "I think ___ is calling you. Look at your phone!", "o": ["someone", "anyone", "no one"], "pt": "Acho que alguém está te ligando. Olhe o celular!", "why": "Someone é 'alguém' numa frase afirmativa sobre uma pessoa que não sabemos quem é."}, {"t": "l", "say": "Someone waves at her from the lawn.", "o": ["Someone waves at her from the lawn.", "Anyone waves at her from the lawn.", "No one waves at her from the lawn."], "why": "Someone = alguém, numa frase afirmativa."}, {"t": "b", "pt": "Eu não vejo ninguém que eu conheço.", "w": ["I", "don't", "see", "anyone", "I", "know"]}, {"t": "b", "pt": "Alguém está na primeira fila.", "w": ["Someone", "is", "in", "the", "front", "row"]}]];
