englishA2ExtraWordExamples[182]={"live band": ["Is anyone near the live band?", "Tem alguém perto da banda ao vivo?"], "loud music": ["Everyone is dancing to the loud music.", "Todo mundo está dançando com a música alta."], "main stage": ["No one is standing near the main stage.", "Ninguém está perto do palco principal."]};
englishA2Plans[183]={"title": "Procurando um objeto na mala", "file": "", "grammar": "Something, anything, nothing, everything", "goal": "Use pronomes indefinidos para coisas.", "words": [["duffel bag", "bolsa de viagem"], ["padlock", "cadeado"], ["hanger", "cabide"], ["pack light", "viajar com pouca bagagem"], ["toothpaste", "pasta de dente"], ["keychain", "chaveiro"], ["hairspray", "laquê"], ["cologne", "colônia"]]};
englishA2Content[183]=[[["Rosa packs a duffel bag for a weekend trip.", "A Rosa arruma uma bolsa de viagem para o fim de semana."], ["She wants to pack light, so she doesn't take much.", "Ela quer viajar com pouca bagagem, então não leva muita coisa."], ["At the hotel, the zipper is stuck, and the padlock is locked.", "No hotel, o zíper está emperrado, e o cadeado está trancado."], ["She opens the pocket and finds something small.", "Ela abre o bolso e acha uma coisa pequena."], ["It's her keychain with the little key!", "É o chaveiro dela com a chavinha!"], ["Now she has everything for the zoo tomorrow.", "Agora ela tem tudo para o zoológico amanhã."]], [["Rosa, did you pack everything for the zoo trip?", "Rosa, você colocou tudo para a viagem ao zoológico?"], ["Almost. But I can't find my toothpaste.", "Quase. Mas não acho minha pasta de dente."], ["Is there anything in the side pocket?", "Tem alguma coisa no bolso lateral?"], ["No, nothing! Only a hanger and a shoelace.", "Não, nada! Só um cabide e um cadarço."], ["Look again. I packed my cologne, my razor, and your hairspray together.", "Procure de novo. Coloquei minha colônia, minha lâmina e seu laquê juntos."], ["Oh, here it is! It's next to the lotion.", "Ah, aqui está! Fica ao lado do hidratante."], ["Great. We should leave early, before the zoo gets busy.", "Ótimo. A gente deve sair cedo, antes de o zoológico encher."], ["Yes, we'll meet Tom at the meeting point at eight. I'm ready!", "Sim, vamos encontrar o Tom no ponto de encontro às oito. Estou pronta!"]], ["/z/ em zipper e zoo", "O /z/ vibra a garganta, como o 'z' de 'zona'. Ponha a mão no pescoço: se não vibrar, virou /s/. Em zipper e zoo, comece já com o zumbido.", ["zipper", "zoo"]], ["Did you pack ___ for the zoo?", "anything", "nothing", "Você colocou alguma coisa para o zoológico?", "Em perguntas usamos anything; nothing seria uma resposta."], [["She opens the pocket and finds something small.", "Ela abre o bolso e acha uma coisa pequena."], ["No, nothing! Only a hanger and a shoelace.", "Não, nada! Só um cabide e um cadarço."]], [{"t": "c", "q": "I'm hungry. Is there ___ to eat?", "o": ["anything", "nothing", "everything"], "pt": "Estou com fome. Tem alguma coisa para comer?", "why": "Em perguntas, usamos anything para 'alguma coisa'."}, {"t": "l", "say": "I can't find anything in my bag.", "o": ["I can't find anything in my bag.", "I can find anything in my bag.", "I can't find everything in my bag."], "why": "Com can't (negativa), usamos anything."}, {"t": "b", "pt": "Eu coloquei tudo na bolsa.", "w": ["I", "put", "everything", "in", "the", "bag"]}, {"t": "b", "pt": "Não há nada no bolso.", "w": ["There", "is", "nothing", "in", "the", "pocket"]}]];
