englishA2ExtraWordExamples[186]={"gift card": ["However, I got a gift card, not a refund.", "Porém, recebi um vale-presente, não um reembolso."]};
englishA2Plans[187]={"title": "Atraso de voo e reclamação", "file": "", "grammar": "Because of vs because; revisão geral de conectivos", "goal": "Explique atrasos usando because of e although.", "words": [["delay", "atraso"], ["runway", "pista de pouso"], ["airline", "companhia aérea"], ["lose track of time", "perder a noção do tempo"], ["crew", "tripulação"], ["takeoff", "decolagem"], ["layover", "escala"], ["duty free", "livre de impostos"]]};
englishA2Content[187]=[[["Tom and Mia wait in the terminal because of a delay.", "Tom e Mia esperam no terminal por causa de um atraso."], ["The airline makes an announcement about the rainstorm.", "A companhia aérea faz um aviso sobre o temporal."], ["The runway is wet, so the crew can't start takeoff.", "A pista está molhada, então a tripulação não pode iniciar a decolagem."], ["Although they are tired, they stay at the gate.", "Embora estejam cansados, eles ficam no portão."], ["They talk and play games, and they lose track of time.", "Eles conversam e jogam, e perdem a noção do tempo."], ["Because of the delay, they will have a short layover.", "Por causa do atraso, eles terão uma escala curta."]], [["Why are all these people at the gate?", "Por que todas essas pessoas estão no portão?"], ["Our flight has a delay because of the storm.", "Nosso voo tem um atraso por causa da tempestade."], ["How long? I hate waiting. The airline didn't send a message.", "Quanto tempo? Odeio esperar. A companhia não mandou mensagem."], ["There was an announcement. We leave in two hours because the runway is wet.", "Teve um aviso. Saímos em duas horas porque a pista está molhada."], ["Two hours! Although we're tired, we can't sleep here.", "Duas horas! Embora estejamos cansados, não dá para dormir aqui."], ["Let's get a snack and talk. We always lose track of time together.", "Vamos comer algo e conversar. A gente sempre perde a noção do tempo juntos."], ["Good idea. I like to pack light. My duffel bag is easy to carry.", "Boa ideia. Eu gosto de viajar com pouca bagagem. Minha bolsa é fácil de carregar."], ["Do you know if the crew is here?", "Você sabe se a tripulação já chegou?"], ["Yes, they arrived early. We'll still make our layover in Denver.", "Sim, chegaram cedo. Ainda vamos pegar nossa escala em Denver."], ["Great. Then let's get coffee, and I'll pay.", "Ótimo. Então vamos tomar café, e eu pago."]], ["/eɪ/ em delay e gate", "O /eɪ/ é um ditongo: comece em 'ê' e deslize até um 'i' curto. Diga 'di-LÊI' e 'GUÊIT', sem cortar o som no meio.", ["delay", "gate"]], ["We are late ___ the traffic.", "because of", "because", "Estamos atrasados por causa do trânsito.", "Because of vem antes de um substantivo (the traffic); because vem antes de uma frase."], [["Tom and Mia wait in the terminal because of a delay.", "Tom e Mia esperam no terminal por causa de um atraso."], ["Our flight has a delay because of the storm.", "Nosso voo tem um atraso por causa da tempestade."]], [{"t": "c", "q": "We stayed home ___ it was raining.", "o": ["because", "because of", "so"], "pt": "Ficamos em casa porque estava chovendo.", "why": "Because é seguido por sujeito e verbo (it was raining)."}, {"t": "l", "say": "We have a delay because of the storm.", "o": ["We have a delay because of the storm.", "We have a delay because the storm.", "We have a delay although the storm."], "why": "Because of + substantivo explica o motivo do atraso."}, {"t": "b", "pt": "Estamos atrasados por causa da chuva.", "w": ["We", "are", "late", "because", "of", "the", "rain"]}, {"t": "b", "pt": "Embora estejamos cansados, vamos ficar.", "w": ["Although", "we're", "tired", "we", "will", "stay"]}]];
