englishA2Plans[188]={"title": "Economizando energia em casa", "file": "", "grammar": "So that para finalidade", "goal": "Explique um objetivo usando so that.", "words": [["lightbulb", "lâmpada"], ["thermostat", "termostato"], ["insulation", "isolamento"], ["switch off", "desligar"], ["draft", "corrente de ar"], ["blinds", "persianas"], ["socket", "tomada"], ["radiator", "aquecedor"], ["cost", "custo"]]};
englishA2Content[188]=[[["Rosa wants a lower bill, so she checks the house with Ben.", "A Rosa quer uma conta mais baixa, então confere a casa com o Ben."], ["They change every old lightbulb so that the house uses less energy.", "Eles trocam toda lâmpada velha para a casa gastar menos energia."], ["Ben sets the thermostat lower so that the heat doesn't run all day.", "O Ben baixa o termostato para o aquecimento não funcionar o dia todo."], ["There is a draft by the window, so they add insulation.", "Tem uma corrente de ar na janela, então eles colocam isolamento."], ["At night, they switch off the lights and take a short bath.", "À noite, eles desligam as luzes e tomam um banho rápido."], ["Now the cost is lower, and they are happy.", "Agora o custo está menor, e eles estão felizes."]], [["Our energy bill is high again. I'm disappointed.", "Nossa conta de energia está alta de novo. Estou decepcionada."], ["I know. I changed the lightbulb in the kitchen so that we use less power.", "Eu sei. Troquei a lâmpada da cozinha para gastarmos menos energia."], ["Good. Our old thermostat is stubborn. Did you check it?", "Bom. Nosso termostato velho é teimoso. Você conferiu?"], ["Yes. I lowered it so that the radiator doesn't work all night.", "Conferi. Baixei para o aquecedor não funcionar a noite toda."], ["And after the last rainstorm, I felt a draft near the window.", "E depois do último temporal, senti uma corrente de ar perto da janela."], ["I'll close the blinds so that cold air stays outside.", "Vou fechar as persianas para o ar frio ficar do lado de fora."], ["Also, please switch off the socket when you leave.", "Também, por favor, desligue a tomada quando sair."], ["Sure. And I'll take a short bath, not a long one.", "Claro. E vou tomar um banho curto, não um longo."], ["Perfect. Then the cost will go down next month.", "Perfeito. Então o custo vai cair no mês que vem."], ["I promise. Let's check the bill together in a month.", "Prometo. Vamos conferir a conta juntos daqui a um mês."]], ["/θ/ em thermostat e bath", "Para o /θ/, coloque a ponta da língua entre os dentes e sopre, sem vibrar a garganta. Não troque por 's' nem por 't': thermostat e bath começam e terminam com esse som.", ["thermostat", "bath"]], ["I close the door ___ the cold air stays out.", "so that", "because", "Eu fecho a porta para o ar frio ficar de fora.", "So that mostra a finalidade: fechamos a porta com esse objetivo."], [["They change every old lightbulb so that the house uses less energy.", "Eles trocam toda lâmpada velha para a casa gastar menos energia."], ["I'll close the blinds so that cold air stays outside.", "Vou fechar as persianas para o ar frio ficar do lado de fora."]], [{"t": "c", "q": "She uses a timer ___ she doesn't forget.", "o": ["so that", "because of", "although"], "pt": "Ela usa um timer para não esquecer.", "why": "So that + sujeito + verbo explica o objetivo da ação."}, {"t": "l", "say": "I switch off the lights so that we save energy.", "o": ["I switch off the lights so that we save energy.", "I switch off the lights so that we spend energy.", "I switch on the lights so that we save energy."], "why": "Desligar a luz serve ao objetivo de economizar energia."}, {"t": "b", "pt": "Eu saio cedo para chegar a tempo.", "w": ["I", "leave", "early", "so", "that", "I'm", "on", "time"]}, {"t": "b", "pt": "Eu fecho tudo para ficar quente.", "w": ["I", "close", "windows", "so", "that", "it's", "warm"]}]];
