englishA2Plans[196]={"title": "Sonhando com uma loteria", "file": "", "grammar": "Segunda condicional: If I had..., I would...", "goal": "Imagine situações irreais com if e would.", "words": [["lottery", "loteria"], ["jackpot", "prêmio principal"], ["mansion", "mansão"], ["pie in the sky", "sonho impossível"], ["billionaire", "bilionário"], ["yacht", "iate"], ["villa", "casa de campo luxuosa"], ["helicopter", "helicóptero"]]};
englishA2Content[196]=[[["Ana buys a lottery ticket every Friday.", "Ana compra um bilhete de loteria toda sexta."], ["Tonight the jackpot is very big.", "Hoje à noite o prêmio principal é muito grande."], ["She dreams about a mansion in the countryside.", "Ela sonha com uma mansão no interior."], ["If she won, she would buy a villa and a yacht.", "Se ela ganhasse, compraria uma casa luxuosa e um iate."], ["Her brother Noah says it is pie in the sky.", "O irmão dela, Noah, diz que é um sonho impossível."], ["But Ana smiles and checks her ticket.", "Mas Ana sorri e confere o bilhete."]], [["Hi, Ana. I got your voicemail. What's the big news?", "Oi, Ana. Recebi seu recado. Qual é a grande novidade?"], ["The jackpot is so big tonight! If I won, I would buy a mansion.", "O prêmio está tão grande hoje! Se eu ganhasse, compraria uma mansão."], ["Ha! Where? In the city?", "Ha! Onde? Na cidade?"], ["No, in the countryside, with a pool and a helicopter.", "Não, no interior, com piscina e um helicóptero."], ["That sounds like pie in the sky. If you were a billionaire, you would forget your friends.", "Isso parece sonho impossível. Se você fosse bilionária, esqueceria seus amigos."], ["Never! I would donate half of it, and you would get a yacht.", "Nunca! Eu doaria metade, e você ganharia um iate."], ["Ha, ha. Okay, I have to hang up now. My boss is calling.", "Ha, ha. Certo, preciso desligar agora. Meu chefe está ligando."], ["Sure. I'll call you after the draw tonight.", "Claro. Eu ligo para você depois do sorteio hoje à noite."]], ["/ɒ/ em lottery e jackpot", "O 'o' de lottery e jackpot é aberto e curto, parecido com o 'a' de 'pá' no inglês americano (lá-ri e djékpat). Abra a boca e mantenha a língua baixa, sem arredondar os lábios.", ["lottery", "jackpot"]], ["If I ___ a lot of money, I would buy a mansion.", "had", "have", "Se eu tivesse muito dinheiro, compraria uma mansão.", "Em If I had..., I would... usamos o passado (had) para uma situação imaginária."], [["The jackpot is so big tonight! If I won, I would buy a mansion.", "O prêmio está tão grande hoje! Se eu ganhasse, compraria uma mansão."], ["Never! I would donate half of it, and you would get a yacht.", "Nunca! Eu doaria metade, e você ganharia um iate."]], [{"t": "c", "q": "If she won the jackpot, she ___ a yacht.", "o": ["would buy", "will buy", "buys"], "pt": "Se ela ganhasse o prêmio, compraria um iate.", "why": "If + passado pede would + verbo na outra parte da frase."}, {"t": "l", "say": "If I had a helicopter, I would fly to the villa.", "o": ["If I had a helicopter, I would fly to the villa.", "If I have a helicopter, I would fly to the villa.", "If I had a helicopter, I will fly to the villa."], "why": "A estrutura correta é If + passado (had), would + verbo."}, {"t": "b", "pt": "Se eu ganhasse, eu doaria tudo.", "w": ["If", "I", "won,", "I", "would", "donate", "everything"]}, {"t": "b", "pt": "Se eu tivesse um iate, eu viajaria.", "w": ["If", "I", "had", "a", "yacht,", "I", "would", "travel"]}]];
