englishA2Plans[198]={"title": "Planos fixos na agenda", "file": "", "grammar": "Presente contínuo para planos futuros", "goal": "Fale de planos marcados com o presente contínuo.", "words": [["conference", "congresso"], ["itinerary card", "ficha de roteiro"], ["badge holder", "porta-crachá"], ["lined up", "agendado"], ["registration", "inscrição"], ["workshop", "oficina"], ["keynote", "palestra principal"], ["sponsor", "patrocinador"]]};
englishA2Content[198]=[[["Mia is flying to the conference on Monday.", "Mia vai voar para o congresso na segunda-feira."], ["She is meeting her team at the registration desk at nine.", "Ela vai encontrar a equipe na mesa de inscrição às nove."], ["Then she is picking up a badge holder and an itinerary card.", "Depois ela vai pegar um porta-crachá e uma ficha de roteiro."], ["Tomorrow, a famous speaker is giving the keynote.", "Amanhã, uma palestrante famosa vai dar a palestra principal."], ["In the afternoon, she is joining a workshop.", "À tarde, ela vai participar de uma oficina."], ["Her whole week is lined up, so she is putting a sticky tab on each day.", "A semana inteira dela está agendada, então ela vai colocar um marcador adesivo em cada dia."]], [["Hi, Mia. What's your plan for Monday?", "Oi, Mia. Qual é seu plano para segunda?"], ["I'm flying to the conference in Denver. My plane leaves at six.", "Vou voar para o congresso em Denver. Meu avião sai às seis."], ["Nice! Is your hotel near the registration desk?", "Legal! Seu hotel fica perto da mesa de inscrição?"], ["Yes, I'm staying there for three nights. We're meeting the sponsor for dinner on Tuesday.", "Sim, vou ficar lá por três noites. Vamos encontrar o patrocinador para jantar na terça."], ["Wow, your week is lined up! Did you print the handout and the document for the workshop?", "Uau, sua semana está toda agendada! Você imprimiu o material e o documento da oficina?"], ["Yes, I have them in my bag. I'll turn off my ringtone during the talks.", "Sim, estão na minha bolsa. Vou desligar o toque do celular durante as palestras."], ["Good idea. Call me if there's any gossip, or leave a voicemail.", "Boa ideia. Me ligue se tiver alguma fofoca, ou deixe um recado."], ["Sure. I'll send you a photo of my sticky tab schedule.", "Claro. Vou mandar uma foto da minha agenda com os marcadores adesivos."]], ["/ɑ/ em conference e document", "O /ɑ/ de conference e document é a vogal aberta de 'pá' no inglês americano: abra bem a boca e deixe a língua baixa. Fale 'cán-fe-rens' e 'dá-kiu-ment', sem fechar para 'ó'.", ["conference", "document"]], ["Tomorrow, we ___ the sponsor at noon.", "are meeting", "met", "Amanhã, vamos encontrar o patrocinador ao meio-dia.", "Para planos já marcados no futuro usamos o presente contínuo (are meeting); met é passado."], [["I'm flying to the conference in Denver. My plane leaves at six.", "Vou voar para o congresso em Denver. Meu avião sai às seis."], ["Yes, I'm staying there for three nights. We're meeting the sponsor for dinner on Tuesday.", "Sim, vou ficar lá por três noites. Vamos encontrar o patrocinador para jantar na terça."]], [{"t": "c", "q": "On Friday, Mia ___ a workshop.", "o": ["is joining", "joined", "join"], "pt": "Na sexta, Mia vai participar de uma oficina.", "why": "Plano marcado no futuro: presente contínuo (is joining)."}, {"t": "l", "say": "We are meeting at nine tomorrow.", "o": ["We are meeting at nine tomorrow.", "We are meeting at nine yesterday.", "We were meeting at nine tomorrow."], "why": "Para o futuro usamos are meeting com tomorrow."}, {"t": "b", "pt": "Eu estou voando para o congresso amanhã.", "w": ["I", "am", "flying", "to", "the", "conference", "tomorrow"]}, {"t": "b", "pt": "Ela está pegando o porta-crachá.", "w": ["She", "is", "getting", "her", "badge", "holder"]}]];
