englishA2Plans[199]={"title": "Revisão: Visita a uma fazenda de ecoturismo", "file": "", "grammar": "Revisão: perguntas indiretas, tags, passiva e relativos", "goal": "Pergunte e confirme informações sobre a fazenda.", "words": [["haystack", "monte de feno"], ["harvest", "colheita"], ["scarecrow", "espantalho"], ["milk the cow", "ordenhar a vaca"], ["orchard", "pomar"], ["lamb", "cordeiro"], ["dirt road", "estrada de terra"], ["fresh eggs", "ovos frescos"]]};
englishA2Content[199]=[[["Lia and Noah visit an eco farm for the weekend.", "Lia e Noah visitam uma fazenda ecológica no fim de semana."], ["The barn is big, and a little lamb sleeps next to the hay.", "O celeiro é grande, e um cordeirinho dorme ao lado do feno."], ["A scarecrow stands in the field near the haystack.", "Um espantalho fica no campo, perto do monte de feno."], ["The farmer who owns the farm shows them an orchard.", "A fazendeira que é dona da fazenda mostra um pomar a eles."], ["The corn is picked by hand in the harvest season.", "O milho é colhido à mão na época da colheita."], ["In the morning, Lia learns to milk the cow, and Noah pushes a wheelbarrow.", "De manhã, Lia aprende a ordenhar a vaca, e Noah empurra um carrinho de mão."]], [["Excuse me, could you tell me where the barn is?", "Com licença, você poderia me dizer onde fica o celeiro?"], ["Sure. It's behind the orchard, next to the haystack.", "Claro. Fica atrás do pomar, ao lado do monte de feno."], ["Thanks. Do you know what time we milk the cow tomorrow?", "Obrigada. Você sabe a que horas vamos ordenhar a vaca amanhã?"], ["At six. The rooster wakes everyone up early.", "Às seis. O galo acorda todo mundo cedo."], ["Wow, early! The harvest season must be busy.", "Uau, cedo! A época da colheita deve ser movimentada."], ["It is. The corn is picked by hand, and the work starts at dawn.", "É. O milho é colhido à mão, e o trabalho começa de madrugada."], ["I love it. It's my new hobby, and I have spare time this weekend.", "Eu adoro. É meu novo passatempo, e tenho tempo livre neste fim de semana."], ["Great! Come back for the harvest festival, and bring your friends.", "Ótimo! Volte para o festival da colheita e traga seus amigos."], ["I will. Can you leave a voicemail about the date?", "Eu volto. Você pode deixar um recado de voz com a data?"], ["Of course. I'll leave one tonight, and we'll have it lined up.", "Claro. Deixo um hoje à noite, e deixamos tudo agendado."]], ["/ɑr/ em barn e farm", "O /ɑr/ de barn e farm junta a vogal aberta de 'pá' com o 'r' americano: a língua sobe e se curva para trás, sem tocar o céu da boca. Não faça o 'r' vibrado nem o 'rr' do português.", ["barn", "farm"]], ["Could you tell me where the barn ___?", "is", "is it", "Você poderia me dizer onde fica o celeiro?", "Em perguntas indiretas a ordem é de afirmação (where the barn is), sem inverter o verbo."], [["Excuse me, could you tell me where the barn is?", "Com licença, você poderia me dizer onde fica o celeiro?"], ["It is. The corn is picked by hand, and the work starts at dawn.", "É. O milho é colhido à mão, e o trabalho começa de madrugada."]], [{"t": "c", "q": "The corn ___ by hand every year.", "o": ["is picked", "picks", "is picking"], "pt": "O milho é colhido à mão todo ano.", "why": "O milho não colhe: ele é colhido, então usamos a voz passiva is picked."}, {"t": "l", "say": "Do you know where the scarecrow is?", "o": ["Do you know where the scarecrow is?", "Do you know where is the scarecrow?", "Do you know where the scarecrow are?"], "why": "Na pergunta indireta o verbo vem depois do sujeito, e scarecrow é singular (is)."}, {"t": "b", "pt": "O fazendeiro que mora aqui é gentil.", "w": ["The", "farmer", "who", "lives", "here", "is", "kind"]}, {"t": "b", "pt": "Você pode me dizer onde fica o celeiro?", "w": ["Could", "you", "tell", "me", "where", "the", "barn", "is"]}]];
englishA2PhotoThemes[199]="flag";
englishA2MiniStories[199]=["O galo desaparecido", "Early on Saturday, Lia hears a loud noise on the farm.~Cedo no sábado, Lia ouve um barulho alto na fazenda.|The rooster is not in the barn!~O galo não está no celeiro!|\"Where is he?\" Noah asks, and they look in the orchard.~\"Onde ele está?\", Noah pergunta, e eles olham no pomar.|They check the haystack, but he is not there.~Eles olham o monte de feno, mas ele não está lá.|Rosa says that he is never late for breakfast.~Rosa diz que ele nunca se atrasa para o café da manhã.|Lia asks if anyone looked in the wheelbarrow.~Lia pergunta se alguém olhou no carrinho de mão.|Noah looks inside, and the rooster is sleeping there!~Noah olha dentro, e o galo está dormindo ali!|The rooster opens one eye and gives Noah a long look.~O galo abre um olho e lança um longo olhar para Noah.|Everyone laughs, and Rosa says it is the warmest bed on the farm.~Todos riem, e Rosa diz que é a cama mais quentinha da fazenda.|After breakfast, the rooster walks back to the barn, and he is happy.~Depois do café da manhã, o galo volta para o celeiro, e está feliz."];
englishA2ExtraWordExamples[199]={"dirt road": ["The farm is at the end of a dirt road.", "A fazenda fica no fim de uma estrada de terra."], "fresh eggs": ["We bought fresh eggs from the farmer.", "Compramos ovos frescos do fazendeiro."]};
englishA2Plans[200]={"title": "Antes de dormir e depois de acordar", "file": "", "grammar": "Before e after + -ing", "goal": "Una ações com before e after seguidos de -ing.", "words": [["toothbrush", "escova de dentes"], ["pajamas", "pijama"], ["lullaby", "cantiga de ninar"], ["turn in", "ir dormir"], ["nightlight", "luz de cabeceira"], ["bedtime story", "história de dormir"], ["turn off", "desligar"], ["sweet dreams", "bons sonhos"]]};
englishA2Content[200]=[[["Ben always brushes his teeth before going to bed.", "Ben sempre escova os dentes antes de ir para a cama."], ["He puts on his pajamas after taking a shower.", "Ele veste o pijama depois de tomar banho."], ["His mom sings a lullaby before turning off the light.", "A mãe dele canta uma cantiga de ninar antes de apagar a luz."], ["After turning on the nightlight in his room, he hugs his quilt.", "Depois de acender a luz de cabeceira no quarto, ele abraça o edredom."], ["In the morning, he puts on his bathrobe after waking up.", "De manhã, ele veste o roupão depois de acordar."], ["Then he takes his toothbrush again before eating breakfast.", "Depois ele pega a escova de dentes de novo antes de tomar café da manhã."]], [["You look tired, Ben. What time did you turn in last night?", "Você parece cansado, Ben. A que horas você foi dormir ontem à noite?"], ["Around midnight. I watched videos in my room for too long.", "Por volta da meia-noite. Assisti vídeos no quarto por tempo demais."], ["Oh no. I always put on my pajamas before watching anything in bed.", "Ah, não. Eu sempre visto o pijama antes de assistir qualquer coisa na cama."], ["Really? I usually fall asleep in my clothes. My dad snores every night, too.", "Sério? Eu geralmente durmo de roupa. Meu pai ronca toda noite também."], ["That's bad for your sleep. After brushing my teeth, I read for ten minutes.", "Isso é ruim para o sono. Depois de escovar os dentes, eu leio por dez minutos."], ["Sounds relaxing. In my spare time I only play loud games, haha.", "Parece relaxante. No meu tempo livre eu só jogo jogos barulhentos, haha."], ["Try some soft music tonight before closing your eyes.", "Experimente uma música suave hoje à noite antes de fechar os olhos."], ["Good idea. I'll turn off my ringtone and send calls to voicemail tonight.", "Boa ideia. Vou desligar o toque e mandar as chamadas para a caixa postal hoje à noite."]], ["/uː/ em toothbrush e room", "O /uː/ de toothbrush e room é um 'u' longo: arredonde bem os lábios e leve a língua para trás, segurando o som um pouco mais que o 'u' do português.", ["toothbrush", "room"]], ["She puts on her pajamas ___ going to bed.", "before", "after", "Ela veste o pijama antes de ir para a cama.", "Vestir o pijama vem antes de deitar, então usamos before + -ing."], [["Ben always brushes his teeth before going to bed.", "Ben sempre escova os dentes antes de ir para a cama."], ["He puts on his pajamas after taking a shower.", "Ele veste o pijama depois de tomar banho."]], [{"t": "c", "q": "Before ___ off the light, Mom sings a lullaby.", "o": ["turning", "turn", "turned"], "pt": "Antes de apagar a luz, a mãe canta uma cantiga de ninar.", "why": "Depois de before usamos o verbo com -ing: before turning."}, {"t": "l", "say": "He puts on his pajamas after taking a shower.", "o": ["He puts on his pajamas after taking a shower.", "He puts on his pajamas before taking a shower.", "He puts on his pajamas after taking a bath."], "why": "A frase ouvida diz que ele veste o pijama depois (after) do banho."}, {"t": "b", "pt": "Antes de dormir eu escovo os dentes.", "w": ["Before", "sleeping", "I", "brush", "my", "teeth"]}, {"t": "b", "pt": "Depois de jantar ela escova os dentes.", "w": ["After", "having", "dinner", "she", "brushes", "her", "teeth"]}]];
