englishA2Plans[204]={"title": "Medos e talentos de um aluno novo", "file": "", "grammar": "Adjetivo + preposição (afraid of, good at)", "goal": "Use adjetivos com preposições fixas.", "words": [["stage fright", "medo de palco"], ["audition", "teste de seleção"], ["fear", "medo"], ["nervous", "nervoso"], ["blush", "corar"], ["stammer", "gaguejar"], ["gulp", "gole"], ["new student", "aluno novo"]]};
englishA2Content[204]=[[["Mia is the new student, and she is a little shy.", "Mia é a aluna nova, e ela é um pouco tímida."], ["She is afraid of speaking in front of the class, and she blushes easily.", "Ela tem medo de falar na frente da turma, e fica vermelha com facilidade."], ["But she is very good at singing.", "Mas ela é muito boa em cantar."], ["Today she has an audition for the school choir.", "Hoje ela tem um teste para o coral da escola."], ["Her stage fright is strong, her hands are sweaty, and she feels nervous.", "O medo de palco dela é forte, as mãos estão suadas e ela se sente nervosa."], ["Noah is proud of her, and her fear gets smaller.", "Noah tem orgulho dela, e o medo dela diminui."]], [["Hi Mia! Are you ready for the audition?", "Oi, Mia! Você está pronta para o teste?"], ["Not really. I'm nervous, and all this stress makes me yawn.", "Na verdade não. Estou nervosa, e todo esse estresse me dá bocejos."], ["Why? You're so good at singing. I heard you whisper a song in the hallway yesterday.", "Por quê? Você canta muito bem. Eu ouvi você sussurrar uma música no corredor ontem."], ["Thanks, but I'm shy in front of people. I'm worried about forgetting the words, and I stammer.", "Obrigada, mas sou tímida na frente das pessoas. Tenho medo de esquecer a letra, e eu gaguejo."], ["Everyone forgets words sometimes. Last year I almost ran away from the stage!", "Todo mundo esquece a letra às vezes. Ano passado eu quase fugi do palco!"], ["Really? What did you do to cheer up?", "Sério? O que você fez para se animar?"], ["I took a deep breath and a gulp of water. I'm proud of you already, you know.", "Respirei fundo e tomei um gole de água. Eu já tenho orgulho de você, sabia?"], ["Thanks, Noah. Okay, I'm going in now, and I'll sing my best!", "Obrigada, Noah. Certo, vou entrar agora e vou cantar o melhor que posso!"]], ["/ɪ/ em fright e shy", "O som de fright e shy é o ditongo /aɪ/: comece com a boca bem aberta, como em 'a', e deslize para um 'i' curto, igual ao 'ai' de 'pai'.", ["fright", "shy"]], ["Mia is afraid ___ speaking in front of the class.", "of", "for", "Mia tem medo de falar na frente da turma.", "O adjetivo afraid pede a preposição of."], [["She is afraid of speaking in front of the class, and she blushes easily.", "Ela tem medo de falar na frente da turma, e fica vermelha com facilidade."], ["But she is very good at singing.", "Mas ela é muito boa em cantar."]], [{"t": "c", "q": "She is very good ___ singing.", "o": ["at", "in", "to"], "pt": "Ela é muito boa em cantar.", "why": "Usamos good at para falar de habilidade."}, {"t": "l", "say": "Noah is proud of her.", "o": ["Noah is proud of her.", "Noah is proud for her.", "Noah is afraid of her."], "why": "A frase ouvida diz proud of, a preposição correta."}, {"t": "b", "pt": "Eu tenho medo de falar em público.", "w": ["I'm", "afraid", "of", "speaking", "in", "public"]}, {"t": "b", "pt": "Ela é boa em cantar.", "w": ["She", "is", "good", "at", "singing"]}]];
