englishA2Plans[205]={"title": "Tarefas domésticas e passatempos", "file": "", "grammar": "Make vs do", "goal": "Escolha entre make e do nas frases.", "words": [["chore", "tarefa doméstica"], ["dustpan", "pá de lixo"], ["laundry basket", "cesto de roupa suja"], ["make a mess", "fazer bagunça"], ["fold", "dobrar"], ["detergent", "detergente"], ["scrub", "esfregar"], ["wash dishes", "lavar a louça"]]};
englishA2Content[205]=[[["Saturday is chore day at Rosa's house.", "O sábado é dia de tarefas na casa da Rosa."], ["She does the laundry and puts the clothes in the laundry basket.", "Ela lava a roupa e coloca as peças no cesto de roupa."], ["Her brother likes to make a mess in the kitchen when he makes lunch.", "O irmão dela adora fazer bagunça na cozinha quando faz o almoço."], ["Rosa grabs a broom and a dustpan.", "Rosa pega uma vassoura e uma pá de lixo."], ["After that, she makes the bed and does her homework.", "Depois disso, ela arruma a cama e faz a lição de casa."], ["Then they sit on a chair and rest.", "Depois eles se sentam numa cadeira e descansam."]], [["Look at this kitchen! Juice is all over the floor.", "Olha essa cozinha! Tem suco por todo o chão."], ["Sorry! I was making lunch, and the cup fell. Can you help me?", "Desculpa! Eu estava fazendo o almoço, e o copo caiu. Você pode me ajudar?"], ["I did the laundry with new detergent, and I'm making the bed next.", "Eu lavei a roupa com detergente novo, e agora vou arrumar a cama."], ["Okay. I'll scrub the floor, so pass me the sponge and a towel, please.", "Tá bom. Eu esfrego o chão, então me passe a esponja e uma toalha, por favor."], ["Here. Sweep first, and use the dustpan behind the chair. I'll fold the towels.", "Aqui. Varra primeiro e use a pá de lixo atrás da cadeira. Eu dobro as toalhas."], ["Thanks. Chores give me so much stress on weekends.", "Obrigado. As tarefas me dão muito estresse nos fins de semana."], ["Let's tidy up the living room first. Noodle soup always helps me cheer up.", "Vamos arrumar a sala primeiro. Sopa de macarrão sempre me ajuda a me animar."], ["Perfect! I'll do the dishes after lunch, I promise.", "Perfeito! Eu lavo a louça depois do almoço, prometo."]], ["/tʃ/ em chore e chair", "O /tʃ/ de chore e chair é o 'tch' de 'tchau': comece com a língua encostada no céu da boca e solte o ar de uma vez. Não o transforme em 'x' como em 'chuva'.", ["chore", "chair"]], ["I ___ the laundry on Sundays.", "do", "make", "Eu lavo a roupa aos domingos.", "Com laundry usamos do (do the laundry), não make."], [["She does the laundry and puts the clothes in the laundry basket.", "Ela lava a roupa e coloca as peças no cesto de roupa."], ["After that, she makes the bed and does her homework.", "Depois disso, ela arruma a cama e faz a lição de casa."]], [{"t": "c", "q": "She ___ the bed every morning.", "o": ["makes", "does", "do"], "pt": "Ela arruma a cama todas as manhãs.", "why": "A expressão certa é make the bed."}, {"t": "l", "say": "My brother makes a mess in the kitchen.", "o": ["My brother makes a mess in the kitchen.", "My brother makes a meal in the kitchen.", "My mother makes a mess in the kitchen."], "why": "A frase ouvida diz makes a mess."}, {"t": "b", "pt": "Eu faço a lição de casa.", "w": ["I", "do", "my", "homework"]}, {"t": "b", "pt": "Ele fez bagunça na cozinha.", "w": ["He", "made", "a", "mess", "in", "the", "kitchen"]}]];
