englishA2Plans[206]={"title": "Pensando em mudar de carreira", "file": "", "grammar": "Preposição + gerúndio (thinking about, good at)", "goal": "Fale de planos usando preposição + -ing.", "words": [["profession", "profissão"], ["degree", "diploma universitário"], ["internship", "estágio"], ["change your mind", "mudar de ideia"], ["portfolio", "portfólio"], ["employer", "empregador"], ["tutor", "professor particular"], ["wage", "salário"]]};
englishA2Content[206]=[[["Ana is thinking about changing her career.", "A Ana está pensando em mudar de carreira."], ["She is tired of working in an office all day.", "Ela está cansada de trabalhar num escritório o dia todo."], ["Teaching is a great profession, and she is interested in becoming a teacher.", "Ensinar é uma ótima profissão, e ela tem interesse em se tornar professora."], ["First she needs a degree, so she plans to study at night.", "Primeiro ela precisa de um diploma, então planeja estudar à noite."], ["She is also excited about finding an internship with a good employer.", "Ela também está animada com a ideia de achar um estágio com um bom empregador."], ["She isn't sure yet, and you can always change your mind.", "Ela ainda não tem certeza, e a gente sempre pode mudar de ideia."]], [["You look serious, Ana. What are you thinking about?", "Você parece séria, Ana. Em que está pensando?"], ["My job. My mood is bad, and I'm tired of answering emails every day.", "No meu trabalho. Meu humor está ruim, e estou cansada de responder e-mails todo dia."], ["Really? I thought you liked it. Does the stress come from your boss?", "Sério? Achei que você gostasse. O estresse vem do seu chefe?"], ["I did like it, at first. Now I'm interested in becoming a teacher.", "Eu gostava, no começo. Agora tenho interesse em me tornar professora."], ["That's a big change. Do you have a degree in education?", "É uma grande mudança. Você tem diploma em educação?"], ["Not yet, but I'm good at explaining things, and I'm excited about learning.", "Ainda não, mas sou boa em explicar as coisas, e estou animada para aprender."], ["Then start as a tutor or with an internship. The wage is small, but you'll learn a lot.", "Então comece como professora particular ou com um estágio. O salário é pequeno, mas você vai aprender muito."], ["Good idea. I'll send my portfolio to an employer tomorrow, and I won't get nervous.", "Boa ideia. Vou mandar meu portfólio para um empregador amanhã, e não vou ficar nervosa."]], ["/n/ em career e internship", "O /n/ de career e internship: a ponta da língua toca a gengiva atrás dos dentes de cima e o som sai pelo nariz. Em internship, o n vem antes do t, como em 'canto'.", ["career", "internship"]], ["She is thinking about ___ her career.", "changing", "change", "Ela está pensando em mudar de carreira.", "Depois de uma preposição (about) usamos o verbo com -ing."], [["Ana is thinking about changing her career.", "A Ana está pensando em mudar de carreira."], ["She is also excited about finding an internship with a good employer.", "Ela também está animada com a ideia de achar um estágio com um bom empregador."]], [{"t": "c", "q": "She is excited about ___ a new job.", "o": ["starting", "start", "to start"], "pt": "Ela está animada para começar um novo emprego.", "why": "Depois da preposição about vem o verbo com -ing: starting."}, {"t": "l", "say": "Ana is thinking about changing her career.", "o": ["Ana is thinking about changing her career.", "Ana is thinking about changing her car.", "Ana is thinking about changing her house."], "why": "A frase ouvida diz changing her career."}, {"t": "b", "pt": "Estou cansado de trabalhar aqui.", "w": ["I'm", "tired", "of", "working", "here"]}, {"t": "b", "pt": "Ele está pensando em estudar à noite.", "w": ["He", "is", "thinking", "about", "studying", "at", "night"]}]];
