englishA2Plans[207]={"title": "Notícias da cidade nos últimos anos", "file": "", "grammar": "There has been / there have been", "goal": "Fale de mudanças usando there has been.", "words": [["population", "população"], ["landfill", "aterro"], ["pollution", "poluição"], ["go up", "subir"], ["smog", "fumaça poluente"], ["council", "câmara municipal"], ["petition", "abaixo-assinado"], ["cleanup", "mutirão de limpeza"]]};
englishA2Content[207]=[[["Rosa reads the city news at breakfast.", "Rosa lê as notícias da cidade no café da manhã."], ["The city's population goes up every year.", "A população da cidade sobe a cada ano."], ["There have been more cars, so there has been more smog.", "Houve mais carros, então houve mais fumaça poluente."], ["The old landfill is full, and there have been many complaints.", "O aterro antigo está cheio, e houve muitas reclamações."], ["The mayor and the city council want a new factory, but people are not happy.", "O prefeito e a câmara municipal querem uma fábrica nova, mas as pessoas não estão felizes."], ["There has also been good news: a cleanup group meets every Saturday.", "Também houve boas notícias: um grupo de limpeza se reúne todo sábado."]], [["What are you reading, Rosa? Your face shows a lot of stress.", "O que você está lendo, Rosa? Seu rosto mostra muito estresse."], ["The city news. There has been a lot of pollution this month.", "As notícias da cidade. Houve muita poluição este mês."], ["Yeah, I know. My throat hurts when I ride my bike, and I get nervous about the air.", "Pois é, eu sei. Minha garganta dói quando ando de bicicleta, e fico nervoso com o ar."], ["Also, the landfill is almost full. There have been many meetings at the city council.", "Além disso, o aterro está quase cheio. Houve muitas reuniões na câmara municipal."], ["Do you think the mayor will change his mind about the factory?", "Você acha que o prefeito vai mudar de ideia sobre a fábrica?"], ["I hope so. Prices go up every year, and the smog is terrible.", "Espero que sim. Os preços sobem todo ano, e a fumaça está horrível."], ["Cleaning is a chore, but I want to join the cleanup group and sign the petition.", "Limpar é uma tarefa chata, mas quero entrar no grupo de limpeza e assinar o abaixo-assinado."], ["Great! There has been a meeting at the park every Saturday. I'll go with you.", "Ótimo! Tem havido uma reunião no parque todo sábado. Vou com você."]], ["/ʃ/ em population e pollution", "O /ʃ/ de population e pollution é o som de 'chuva': lábios um pouco projetados e o ar passando contínuo, sem 'tch'. Em population, o -tion soa como 'shân'.", ["population", "pollution"]], ["There ___ been a lot of pollution this year.", "has", "have", "Houve muita poluição este ano.", "Pollution é incontável, então usamos there has been."], [["There have been more cars, so there has been more smog.", "Houve mais carros, então houve mais fumaça poluente."], ["The old landfill is full, and there have been many complaints.", "O aterro antigo está cheio, e houve muitas reclamações."]], [{"t": "c", "q": "There ___ been more traffic lately.", "o": ["has", "have", "is"], "pt": "Tem havido mais trânsito ultimamente.", "why": "Traffic é incontável (singular), então there has been."}, {"t": "l", "say": "There have been many complaints.", "o": ["There have been many complaints.", "There have been many comments.", "There has been one complaint."], "why": "A frase ouvida diz there have been many complaints."}, {"t": "b", "pt": "Houve muita poluição.", "w": ["There", "has", "been", "a", "lot", "of", "pollution"]}, {"t": "b", "pt": "Houve muitas reuniões.", "w": ["There", "have", "been", "many", "meetings"]}]];
