englishA2Plans[208]={"title": "Superando um desafio no esporte", "file": "", "grammar": "Be able to e manage to", "goal": "Fale de capacidade e conseguir fazer algo.", "words": [["climber", "alpinista"], ["ledge", "saliência"], ["carabiner", "mosquetão"], ["make it", "conseguir chegar"], ["steep", "íngreme"], ["grip", "apoio para a mão"], ["knot", "nó"], ["slip", "escorregar"]]};
englishA2Content[208]=[[["Noah is a climber, and today he is on a steep rock wall.", "Noah é alpinista, e hoje ele está num paredão de pedra íngreme."], ["The rope has a tight knot, and there is a small ledge above him.", "A corda tem um nó apertado, e há uma pequena saliência acima dele."], ["At first, he isn't able to reach it.", "No começo, ele não consegue alcançá-la."], ["He clips the carabiner to the rope and tries again.", "Ele prende o mosquetão na corda e tenta de novo."], ["Finally, he manages to pull himself up.", "Finalmente, ele consegue se puxar para cima."], ["Lia cheers from below because he made it to the summit.", "Lia comemora lá embaixo porque ele chegou ao cume."]], [["Noah, you did it! Were you scared up there?", "Noah, você conseguiu! Você ficou com medo lá em cima?"], ["A little. At first I wasn't able to find a good grip for my hand.", "Um pouco. No começo eu não consegui achar um bom apoio para a mão."], ["I saw that. Your foot slipped once, and I was so nervous.", "Eu vi. Seu pé escorregou uma vez, e eu fiquei muito nervosa."], ["Yeah, but I managed to reach the ledge after three tries.", "Pois é, mas consegui alcançar a saliência depois de três tentativas."], ["The fear came back near the top. I had to go up very slowly.", "O medo voltou perto do topo. Tive que subir bem devagar."], ["The wall was steep, with only a small crack for your fingers.", "O paredão era íngreme, com só uma pequena fenda para os seus dedos."], ["Do you think you'll be able to climb it again next month?", "Você acha que vai conseguir escalar de novo no mês que vem?"], ["Definitely. I'll practice more, and I'll make it to the top faster.", "Com certeza. Vou treinar mais e vou chegar ao topo mais rápido."]], ["/ɪ/ em summit e climber", "O /ɪ/ de summit é curto: língua relaxada, boca quase fechada, entre o 'i' e o 'e' do português. Em climber, o primeiro som é o ditongo /aɪ/ (clái-mer), e o b final do início é mudo.", ["summit", "climber"]], ["At first, he wasn't ___ to reach the ledge.", "able", "can", "No começo, ele não conseguiu alcançar a saliência.", "Depois de be usamos able to; can não entra nessa estrutura."], [["At first, he isn't able to reach it.", "No começo, ele não consegue alcançá-la."], ["Finally, he manages to pull himself up.", "Finalmente, ele consegue se puxar para cima."]], [{"t": "c", "q": "After three tries, she ___ to climb the wall.", "o": ["managed", "could", "can"], "pt": "Depois de três tentativas, ela conseguiu escalar o paredão.", "why": "Manage to descreve o esforço que deu certo; could e can não levam to."}, {"t": "l", "say": "He managed to reach the ledge.", "o": ["He managed to reach the ledge.", "He managed to reach the bridge.", "He wanted to reach the ledge."], "why": "A frase ouvida diz managed to reach the ledge."}, {"t": "b", "pt": "Eu não consegui abrir a porta.", "w": ["I", "wasn't", "able", "to", "open", "the", "door"]}, {"t": "b", "pt": "Ele conseguiu chegar ao topo.", "w": ["He", "managed", "to", "reach", "the", "top"]}]];
