englishA2Plans[209]={"title": "Revisão final: Retrospectiva do ano", "file": "", "grammar": "Revisão final: todas as estruturas do bloco A2", "goal": "Conte o que mudou, o que já fez e o que fará.", "words": [["keepsake", "lembrança"], ["scrapbook", "álbum de recortes"], ["milestone", "marco"], ["look back", "olhar para trás"], ["dusty", "empoeirado"], ["magnet", "ímã"], ["family photo", "foto de família"], ["new year", "ano novo"]]};
englishA2Content[209]=[[["It's the last night of the year, and Ana opens her dusty scrapbook.", "É a última noite do ano, e Ana abre o álbum de recortes empoeirado."], ["Every keepsake has a memory: a pebble, a magnet, a photo.", "Cada lembrança guarda uma memória: uma pedrinha, um ímã, uma foto."], ["She is proud of finishing her degree, and she is happy about starting an internship.", "Ela tem orgulho de ter terminado a faculdade e está feliz por começar um estágio."], ["There has been a lot of change this year.", "Houve muita mudança neste ano."], ["She was afraid of speaking in public, but now she is good at it.", "Ela tinha medo de falar em público, mas agora é boa nisso."], ["She looks back and gets excited about next year.", "Ela olha para trás e fica animada com o ano que vem."]], [["Ana, what's that big book on your lap?", "Ana, que livro grande é esse no seu colo?"], ["It's my scrapbook, like a diary with pictures! I look back at my year every December.", "É meu álbum de recortes, tipo um diário com imagens! Eu olho para trás no meu ano todo dezembro."], ["Wow, you keep everything. Is that a ticket from the concert in April?", "Uau, você guarda tudo. Esse é um ingresso do show de abril?"], ["Yes! Before going on stage, I had terrible stage fright. But I managed to sing.", "Sim! Antes de subir ao palco, eu tive um medo de palco terrível. Mas consegui cantar."], ["I remember. I was in the front row, and I almost cried.", "Eu me lembro. Eu estava na primeira fila e quase chorei."], ["And look, this is a keepsake from my first day at the internship.", "E olha, esta é uma lembrança do meu primeiro dia no estágio."], ["That small badge holder was a big milestone. There has been so much change this year!", "Esse pequeno porta-crachá foi um grande marco. Houve tanta mudança neste ano!"], ["True. I got tired a lot, but I'm very happy now.", "Verdade. Eu fiquei cansada muitas vezes, mas estou muito feliz agora."], ["So, what are you going to do next year?", "Então, o que você vai fazer no ano que vem?"], ["I'm going to learn to paint, and you're invited to my first show. I'll save you a seat!", "Vou aprender a pintar, e você está convidada para a minha primeira exposição. Vou guardar um lugar para você!"]], ["/m/ em memory e milestone", "O /m/ de memory e milestone: feche os lábios, deixe a voz vibrar e o ar sair pelo nariz, como no 'm' de 'mala'. Em milestone, o m vem no começo, então segure um instante antes de abrir.", ["memory", "milestone"]], ["Ana is proud ___ finishing her degree.", "of", "at", "Ana tem orgulho de ter terminado a faculdade.", "O adjetivo proud pede a preposição of."], [["There has been a lot of change this year.", "Houve muita mudança neste ano."], ["She was afraid of speaking in public, but now she is good at it.", "Ela tinha medo de falar em público, mas agora é boa nisso."]], [{"t": "c", "q": "There ___ been many milestones this year.", "o": ["have", "has", "is"], "pt": "Houve muitos marcos neste ano.", "why": "Milestones é plural, então there have been."}, {"t": "l", "say": "She managed to finish her degree.", "o": ["She managed to finish her degree.", "She managed to finish her dinner.", "She hoped to finish her degree."], "why": "A frase ouvida diz managed to finish her degree."}, {"t": "b", "pt": "Houve muitas mudanças este ano.", "w": ["There", "have", "been", "many", "changes", "this", "year"]}, {"t": "b", "pt": "Ela é boa em contar histórias.", "w": ["She", "is", "good", "at", "telling", "stories"]}]];
englishA2PhotoThemes[209]="flag";
englishA2MiniStories[209]=["A caixa de lembranças", "Last weekend, Tom cleaned his room and found a dusty box.~No fim de semana passado, Tom limpou o quarto e achou uma caixa empoeirada.|Inside, there was a scrapbook with a red cover.~Dentro, havia um álbum de recortes com capa vermelha.|It had photos, tickets, and a small keepsake from every trip.~Tinha fotos, ingressos e uma pequena lembrança de cada viagem.|Tom sat on the floor and began to look back at his year.~Tom sentou no chão e começou a olhar para trás, para o ano dele.|He remembered the first day of his internship and how nervous he was.~Ele se lembrou do primeiro dia de estágio e de como estava nervoso.|There was a photo of his team after their big project.~Havia uma foto da equipe dele depois do grande projeto.|Then he found an envelope with his name on it.~Então ele achou um envelope com o nome dele.|It was from his sister, who wrote it a year ago.~Era da irmã dele, que escreveu um ano atrás.|She wrote that she was proud of him and sure he would make it.~Ela escreveu que tinha orgulho dele e que tinha certeza de que ele ia conseguir.|Tom smiled, called her, and said thank you for the best milestone of the year.~Tom sorriu, ligou para ela e agradeceu pelo melhor marco do ano."];
englishA2ExtraWordExamples[209]={"family photo": ["We looked at a family photo from January.", "Olhamos uma foto de família de janeiro."], "new year": ["The new year has been great so far.", "O ano novo tem sido ótimo até agora."]};
englishA2Plans[210]={"title": "Falando com a veterinária por telefone", "file": "", "grammar": "Pedir para falar com alguém: Could I speak to…? / May I…?", "goal": "Peça para falar com alguém usando Could I speak to…? e entenda quando pedem para esperar.", "words": [["reception", "recepção"], ["available", "disponível"], ["put through", "transferir a ligação"], ["hold the line", "esperar na linha"], ["hold on", "aguardar um momento"], ["wrong number", "número errado"], ["switchboard", "central telefônica"], ["extension number", "número do ramal"], ["on hold", "em espera"]]};
englishA2Content[210]=[[["Ben dials the number of the pet clinic, but he gets a wrong number.", "Ben disca o número da clínica veterinária, mas cai em um número errado."], ["He tries again, and a woman at the switchboard answers.", "Ele tenta de novo, e uma mulher da central telefônica atende."], ["\"Could I speak to Dr. Lopez, please?\" Ben asks.", "\"Eu poderia falar com a Dra. Lopez, por favor?\", pergunta Ben."], ["\"Hold on, I'll find out if she's free,\" the woman says.", "\"Um momento, vou ver se ela está livre\", diz a mulher."], ["Ben is on hold for two minutes and listens to piano music.", "Ben fica em espera por dois minutos e ouve música de piano."], ["Then Dr. Lopez says, \"Hello, Ben. May I ask what's wrong with Max?\"", "Então a Dra. Lopez diz: \"Olá, Ben. Posso perguntar o que o Max tem?\""]], [["Happy Paws Clinic, reception. How can I help you?", "Clínica Happy Paws, recepção. Como posso ajudar?"], ["Hello, could I speak to Dr. Lopez, please?", "Olá, eu poderia falar com a Dra. Lopez, por favor?"], ["I'm sorry, she's with a patient. May I ask who's calling?", "Sinto muito, ela está com um paciente. Posso perguntar quem fala?"], ["It's Ben Ward. My dog Max stopped eating yesterday.", "É o Ben Ward. Meu cachorro, o Max, parou de comer ontem."], ["Oh no. Let me see if she's available. Please hold the line.", "Ai, não. Vou ver se ela está disponível. Por favor, espere na linha."], ["Sure. Could I also have her extension number for next time?", "Claro. Posso ter também o ramal dela para a próxima vez?"], ["It's 214. She's free now, so I'll put through your call.", "É 214. Ela está livre agora, então vou transferir a sua ligação."], ["Great, 214. Thank you so much!", "Ótimo, 214. Muito obrigado!"]], ["/h/ em hold e hello", "O 'h' inglês é só um sopro de ar saindo da garganta, bem suave, como se você embaçasse um vidro. Não o pronuncie como o 'r' de 'rato'.", ["hold", "hello"]], ["___ I speak to Dr. Lopez, please?", "Could", "Do", "Eu poderia falar com a Dra. Lopez, por favor?", "Para pedir para falar com alguém ao telefone, usamos Could I ou May I, nunca Do I."], [["\"Could I speak to Dr. Lopez, please?\" Ben asks.", "\"Eu poderia falar com a Dra. Lopez, por favor?\", pergunta Ben."], ["Hello, could I speak to Dr. Lopez, please?", "Olá, eu poderia falar com a Dra. Lopez, por favor?"]], [{"t": "c", "q": "Could I ___ to the manager, please?", "o": ["speak", "to speak", "speaking"], "pt": "Eu poderia falar com o gerente, por favor?", "why": "Depois de Could I vem o verbo simples, sem to e sem -ing."}, {"t": "l", "say": "Could I speak to the doctor?", "o": ["Could I speak to the doctor?", "Could I speak to the doctors?", "Could she speak to the doctor?"], "why": "Você ouviu I (eu) e doctor no singular: Could I speak to the doctor?"}, {"t": "b", "pt": "Eu poderia falar com o gerente, por favor?", "w": ["Could", "I", "speak", "to", "the", "manager", "please"]}, {"t": "b", "pt": "Posso perguntar quem está falando?", "w": ["May", "I", "ask", "who's", "calling"]}]];
englishA2PhotoThemes[210]="chat";
englishA2Plans[211]={"title": "Recado para o contador que está fora", "file": "", "grammar": "Deixar e anotar recados: Can I take a message? / Tell him that…", "goal": "Deixe e anote recados usando Can I take a message? e Tell him that…", "words": [["voice mail", "caixa postal de voz"], ["ring back", "ligar de volta"], ["get through", "conseguir completar a ligação"], ["take down", "anotar"], ["take a message", "anotar um recado"], ["missed call", "chamada perdida"], ["busy signal", "sinal de ocupado"], ["cut off", "cair, ser cortado"]]};
englishA2Content[211]=[[["Omar needs to talk to his accountant, but the line gives a busy signal.", "Omar precisa falar com o contador, mas a linha dá sinal de ocupado."], ["He tries three times, and then he gets the voice mail.", "Ele tenta três vezes e depois cai na caixa postal."], ["An hour later, he sees a missed call from the same office.", "Uma hora depois, ele vê uma chamada perdida do mesmo escritório."], ["He calls again, and the receptionist asks, \"Can I take a message?\"", "Ele liga de novo, e a recepcionista pergunta: \"Posso anotar um recado?\""], ["\"Yes,\" says Omar. \"Tell him that I'm free after four.\"", "\"Sim\", diz Omar. \"Diga a ele que estou livre depois das quatro.\""], ["The receptionist writes it down, and Omar finally relaxes.", "A recepcionista anota, e Omar finalmente relaxa."]], [["Brown Accounting, this is Lia speaking.", "Contabilidade Brown, Lia falando."], ["Hi, this is Omar Reyes. I called twice, but I couldn't get through.", "Oi, aqui é o Omar Reyes. Liguei duas vezes, mas não consegui completar a ligação."], ["Mr. Brown is out until three. Can I take a message?", "O Sr. Brown está fora até as três. Posso anotar um recado?"], ["Yes, please. Tell him that my tax papers are ready.", "Sim, por favor. Diga a ele que meus papéis do imposto estão prontos."], ["Okay, I'll take down the message. Anything else?", "Certo, vou anotar o recado. Mais alguma coisa?"], ["Yes. Tell him that I'm free after four, so he can ring back.", "Sim. Diga a ele que estou livre depois das quatro, para ele poder retornar."], ["After four, got it. Is your number 555-0142?", "Depois das quatro, entendi. O seu número é 555-0142?"], ["That's right. And thanks! My call got cut off this morning, too.", "Isso mesmo. E obrigado! Minha ligação também caiu hoje de manhã."], ["Sorry about that. I'll give him the message right now.", "Desculpe por isso. Vou dar o recado a ele agora mesmo."], ["Perfect, he'll ring back after four. Thanks, Lia.", "Perfeito, ele retorna depois das quatro. Obrigado, Lia."]], ["/θ/ em three e thanks", "Coloque a ponta da língua entre os dentes e sopre, sem vibrar a voz. Não troque por 's' nem por 't': three não é 'tree'.", ["three", "thanks"]], ["Can I ___ a message?", "take", "make", "Posso anotar um recado?", "Em inglês, recados são anotados com take (take a message), não com make."], [["\"Yes,\" says Omar. \"Tell him that I'm free after four.\"", "\"Sim\", diz Omar. \"Diga a ele que estou livre depois das quatro.\""], ["Yes, please. Tell him that my tax papers are ready.", "Sim, por favor. Diga a ele que meus papéis do imposto estão prontos."]], [{"t": "c", "q": "Tell her ___ the meeting is at noon.", "o": ["that", "to", "what"], "pt": "Diga a ela que a reunião é ao meio-dia.", "why": "Para passar uma informação usamos Tell her that + frase."}, {"t": "l", "say": "Can I take a message?", "o": ["Can I take a message?", "Can I take a massage?", "Can I make a message?"], "why": "Message (recado) é diferente de massage (massagem), e usamos take, não make."}, {"t": "b", "pt": "Diga a ele que eu volto às quatro.", "w": ["Tell", "him", "that", "I'll", "be", "back", "at", "four"]}, {"t": "b", "pt": "Posso anotar um recado?", "w": ["Can", "I", "take", "a", "message"]}]];
