englishA2Plans[212]={"title": "Comprando ingressos de show e soletrando o nome", "file": "", "grammar": "Soletrar nomes e repetir números: Could you spell…? / Do you mean…?", "goal": "Soletre nomes e confirme números usando Could you spell…? e Do you mean…?", "words": [["initial", "inicial"], ["digit", "dígito"], ["area code", "código de área"], ["capital letter", "letra maiúscula"], ["hyphen", "hífen"], ["at sign", "arroba"], ["zip code", "CEP"], ["mix up", "confundir"]]};
englishA2Content[212]=[[["Katya calls the box office to buy two concert tickets.", "Katya liga para a bilheteria para comprar dois ingressos de show."], ["The man asks, \"Could you spell your last name, please?\"", "O homem pergunta: \"Você poderia soletrar o seu sobrenome, por favor?\""], ["\"Sure. It's Nowak, with a capital letter N,\" she says.", "\"Claro. É Nowak, com N maiúsculo\", ela diz."], ["Then she gives her phone number: first the area code, then each digit slowly.", "Depois ela diz o telefone: primeiro o código de área, depois cada dígito devagar."], ["He doesn't want to mix up any numbers, so he says them back.", "Ele não quer confundir nenhum número, então repete tudo."], ["\"Do you mean 0198, not 0189?\" he asks. \"Yes, 0198,\" says Katya.", "\"Você quer dizer 0198, e não 0189?\", ele pergunta. \"Sim, 0198\", diz Katya."]], [["Rock Hall box office. How can I help?", "Bilheteria do Rock Hall. Como posso ajudar?"], ["I'd like two tickets for Saturday, please.", "Eu queria dois ingressos para sábado, por favor."], ["Sure. Could you spell your last name for me?", "Claro. Você poderia soletrar o seu sobrenome para mim?"], ["It's Nowak, N-O-W-A-K, and my first initial is K.", "É Nowak, N-O-W-A-K, e a minha primeira inicial é K."], ["Thanks. And what's your zip code, please?", "Obrigado. E qual é o seu CEP, por favor?"], ["It's 94110. My email is k, hyphen, nowak, then the at sign, then gmail dot com.", "É 94110. Meu e-mail é k, hífen, nowak, depois a arroba, depois gmail ponto com."], ["Let me read that back. Do you mean k-nowak at gmail dot com?", "Deixe-me reler. Você quer dizer k-nowak arroba gmail ponto com?"], ["Yes, that's it. I always mix up my old zip code and my new one!", "Sim, é isso. Eu sempre confundo o meu CEP antigo com o novo!"], ["No problem. Your tickets will be waiting under Nowak.", "Sem problema. Seus ingressos ficarão esperando no nome Nowak."], ["Perfect, under Nowak. Thanks a lot!", "Perfeito, no nome Nowak. Muito obrigada!"]], ["/ɪ/ curto em digit e initial", "O 'i' de digit e initial é curto e relaxado, bem diferente do 'i' longo de see. Não estique a vogal.", ["digit", "initial"]], ["___ you mean 0198 or 0189?", "Do", "Are", "Você quer dizer 0198 ou 0189?", "Com mean (querer dizer), a pergunta usa Do you mean…?, não Are you mean."], [["The man asks, \"Could you spell your last name, please?\"", "O homem pergunta: \"Você poderia soletrar o seu sobrenome, por favor?\""], ["Let me read that back. Do you mean k-nowak at gmail dot com?", "Deixe-me reler. Você quer dizer k-nowak arroba gmail ponto com?"]], [{"t": "c", "q": "Could you ___ your name, please?", "o": ["spell", "to spell", "spelling"], "pt": "Você poderia soletrar o seu nome, por favor?", "why": "Depois de Could you vem o verbo simples: spell."}, {"t": "l", "say": "Do you mean 0198?", "o": ["Do you mean 0198?", "Do you mean 0189?", "Did you mean 0198?"], "why": "Você ouviu o número 0198 e a pergunta no presente: Do you mean…?"}, {"t": "b", "pt": "Você poderia soletrar o seu sobrenome?", "w": ["Could", "you", "spell", "your", "last", "name"]}, {"t": "b", "pt": "Você quer dizer zero um nove oito?", "w": ["Do", "you", "mean", "zero", "one", "nine", "eight"]}]];
