englishA2Plans[213]={"title": "Ligação ruim do metrô para o achados e perdidos", "file": "", "grammar": "Pedir para repetir ou falar mais devagar com perguntas indiretas", "goal": "Peça para repetir e pergunte com educação usando Could you tell me where…? e Do you know what time…?", "words": [["speak up", "falar mais alto"], ["slow down", "falar mais devagar"], ["say again", "repetir (Say again?)"], ["come again", "como? (pedir repetição)"], ["bad connection", "ligação ruim"], ["static", "chiado na linha"], ["break up", "falhar, cortar (sinal)"], ["cut out", "ficar mudo, cair por um instante"], ["loud and clear", "alto e claro"]]};
englishA2Content[213]=[[["Mia is on the train, and she can't find her blue backpack.", "Mia está no trem e não acha a mochila azul dela."], ["She calls the lost and found, but the signal is going to break up in the tunnel.", "Ela liga para o achados e perdidos, mas o sinal vai falhar no túnel."], ["There is a lot of static, and the man mumbles a little.", "Há muito chiado, e o homem murmura um pouco."], ["Mia asks, \"Could you tell me where I can pick up my bag?\"", "Mia pergunta: \"Você poderia me dizer onde posso pegar minha bolsa?\""], ["He says, \"Do you know which train it was?\"", "Ele diz: \"Você sabe qual trem era?\""], ["\"Yes, the 8:15,\" she says, and he tells her to come to Central Station.", "\"Sim, o das 8:15\", ela diz, e ele a manda ir à Estação Central."]], [["Metro Lost and Found. Can I help you?", "Achados e Perdidos do Metrô. Posso ajudar?"], ["Hi, I'm in a tunnel, so I have a bad connection. Can you hear me?", "Oi, estou em um túnel, então a ligação está ruim. Você me ouve?"], ["There's a lot of static. Could you speak up, please?", "Há muito chiado. Você pode falar mais alto, por favor?"], ["Sure. I left a blue backpack on the 8:15 train. Do you know where I can pick it up?", "Claro. Esqueci uma mochila azul no trem das 8:15. Você sabe onde posso buscá-la?"], ["Come again? You cut out for a second.", "Como? Você ficou mudo por um segundo."], ["A blue backpack on the 8:15 train. Can you tell me where I can find it?", "Uma mochila azul no trem das 8:15. Você pode me dizer onde posso encontrá-la?"], ["Sorry, say again? And could you slow down a little?", "Desculpe, pode repetir? E poderia falar um pouco mais devagar?"], ["Okay. The train just left the tunnel. Do you know what time the office opens?", "Certo. O trem acabou de sair do túnel. Você sabe a que horas o escritório abre?"], ["Loud and clear now! It opens at nine, and your bag is at Central Station.", "Agora ouvi bem! Abre às nove, e a sua mochila está na Estação Central."], ["Great, Central Station at nine. Thanks so much!", "Ótimo, Estação Central às nove. Muito obrigada!"]], ["/ʌ/ em mumble e come", "O /ʌ/ é um 'a' curto e relaxado, com a boca quase parada. Não diga 'mumbôl' nem 'cômi': pense num 'â' bem rápido.", ["mumble", "come"]], ["Do you know what time the office ___?", "opens", "does open", "Você sabe a que horas o escritório abre?", "Na pergunta indireta o verbo vem depois do sujeito, sem do: the office opens."], [["Mia asks, \"Could you tell me where I can pick up my bag?\"", "Mia pergunta: \"Você poderia me dizer onde posso pegar minha bolsa?\""], ["He says, \"Do you know which train it was?\"", "Ele diz: \"Você sabe qual trem era?\""]], [{"t": "c", "q": "Could you tell me where the station ___?", "o": ["is", "is it", "does"], "pt": "Você poderia me dizer onde fica a estação?", "why": "Na pergunta indireta mantemos a ordem da afirmação: where the station is."}, {"t": "l", "say": "Could you tell me where it is?", "o": ["Could you tell me where it is?", "Could you tell me where is it?", "Could you tell me were it is?"], "why": "A pergunta indireta mantém a ordem normal (where it is), e a palavra é where, não were."}, {"t": "b", "pt": "Você poderia falar mais devagar, por favor?", "w": ["Could", "you", "slow", "down", "please"]}, {"t": "b", "pt": "Você sabe a que horas eles fecham?", "w": ["Do", "you", "know", "what", "time", "they", "close"]}]];
