englishA2Plans[214]={"title": "Remarcando o corte de cabelo no salão", "file": "", "grammar": "Marcar e remarcar horários: How about…? / I'm afraid I can't…", "goal": "Remarque um horário usando How about…? e recuse com educação com I'm afraid I can't…", "words": [["reschedule", "remarcar"], ["booked up", "lotado, sem vagas"], ["fully booked", "totalmente reservado"], ["slot", "horário disponível"], ["inconvenient", "inconveniente, ruim para mim"], ["I'm afraid", "infelizmente"], ["pencil in", "reservar provisoriamente"], ["first available", "primeiro livre"], ["move to", "passar para"], ["free up", "liberar"]]};
englishA2Content[214]=[[["Rosa has a haircut tomorrow at ten, but ten is inconvenient because she has to work.", "Rosa tem um corte de cabelo amanhã às dez, mas dez é ruim porque ela precisa trabalhar."], ["She calls the salon, and the stylist says, \"How about Thursday?\"", "Ela liga para o salão, e a cabeleireira diz: \"Que tal quinta?\""], ["\"I'm afraid I can't,\" Rosa says. \"Could we move to Friday?\"", "\"Infelizmente não posso\", diz Rosa. \"Podemos passar para sexta?\""], ["\"Friday is booked up,\" says the stylist.", "\"Sexta está lotada\", diz a cabeleireira."], ["Then she remembers that a client canceled, so she can free up a slot on Saturday.", "Então ela lembra que uma cliente cancelou, então pode liberar um horário no sábado."], ["\"How about two o'clock?\" she asks, and Rosa says, \"Perfect!\"", "\"Que tal às duas?\", ela pergunta, e Rosa diz: \"Perfeito!\""]], [["Style Salon, this is Dana.", "Salão Style, Dana falando."], ["Hi, Dana. It's Rosa Silva. I have a haircut tomorrow, but I need to reschedule.", "Oi, Dana. É a Rosa Silva. Tenho um corte amanhã, mas preciso remarcar."], ["No problem. How about Thursday at ten?", "Sem problema. Que tal quinta às dez?"], ["I'm afraid I can't. I work until six on Thursday.", "Infelizmente não posso. Trabalho até as seis na quinta."], ["Let me look. We're fully booked on Friday, but I have a slot on Saturday at nine.", "Deixe-me ver. Estamos totalmente reservados na sexta, mas tenho um horário no sábado às nove."], ["Nine is a little early for me. Is there anything later?", "Nove é um pouco cedo para mim. Tem algo mais tarde?"], ["How about two o'clock? That's the first available time after lunch.", "Que tal às duas? É o primeiro horário livre depois do almoço."], ["Two works. Could you pencil in Saturday at two? I'll confirm tomorrow.", "Duas serve. Pode reservar sábado às duas provisoriamente? Eu confirmo amanhã."], ["Sure. I'll pencil in Saturday at two for Rosa Silva.", "Claro. Vou reservar sábado às duas para Rosa Silva."], ["Great, Saturday at two. Thanks, Dana!", "Ótimo, sábado às duas. Obrigada, Dana!"]], ["/sl/ em slot e salon", "Comece com um 's' limpo e emende o 'l', sem 'i' na frente: slot, não 'islot'. Em salon, a ênfase vai na primeira sílaba.", ["slot", "salon"]], ["I'm afraid I ___ come on Thursday.", "can't", "don't", "Infelizmente não posso ir na quinta.", "Para dizer que não é possível, usamos can't depois de I'm afraid I, não don't."], [["She calls the salon, and the stylist says, \"How about Thursday?\"", "Ela liga para o salão, e a cabeleireira diz: \"Que tal quinta?\""], ["I'm afraid I can't. I work until six on Thursday.", "Infelizmente não posso. Trabalho até as seis na quinta."]], [{"t": "c", "q": "How ___ Saturday at two?", "o": ["about", "if", "to"], "pt": "Que tal sábado às duas?", "why": "A sugestão em inglês é How about + horário ou dia."}, {"t": "l", "say": "I'm afraid I can't come on Friday.", "o": ["I'm afraid I can't come on Friday.", "I'm afraid I can come on Friday.", "I'm afraid I can't come on Sunday."], "why": "Você ouviu can't (não posso) e Friday (sexta)."}, {"t": "b", "pt": "Que tal sábado às duas?", "w": ["How", "about", "Saturday", "at", "two"]}, {"t": "b", "pt": "Infelizmente não posso ir na quinta.", "w": ["I'm", "afraid", "I", "can't", "come", "on", "Thursday"]}]];
