englishA2Plans[215]={"title": "Reclamando de uma cobrança na conta do celular", "file": "", "grammar": "Reclamar de uma cobrança: I'm calling about… / There's a problem with…", "goal": "Reclame de uma cobrança usando I'm calling about… e There's a problem with…", "words": [["phone bill", "conta de celular"], ["double-charged", "cobrado em dobro"], ["dispute", "contestar"], ["reference number", "número de referência"], ["overcharge", "cobrar a mais"], ["look into", "investigar"], ["adding up", "fazer sentido (contas)"], ["on my account", "na minha conta"], ["sort out", "resolver"], ["that's not right", "isso não está certo"]]};
englishA2Content[215]=[[["Ana opens her phone bill and sees the same charge twice.", "Ana abre a conta do celular e vê a mesma cobrança duas vezes."], ["The numbers aren't adding up.", "Os números não batem."], ["She thinks she was double-charged $40, so she wants to dispute it.", "Ela acha que foi cobrada $40 em dobro, então quer contestar."], ["She calls the company and says, \"I'm calling about my phone bill. There's a problem with the total.\"", "Ela liga para a empresa e diz: \"Estou ligando sobre a minha conta de celular. Há um problema com o total.\""], ["The agent says, \"I'll look into it, Ms. Silva.\"", "O atendente diz: \"Vou investigar, Sra. Silva.\""], ["Ana feels better and writes down the reference number.", "Ana se sente melhor e anota o número de referência."]], [["Thank you for calling Blue Mobile. How can I help?", "Obrigado por ligar para a Blue Mobile. Como posso ajudar?"], ["Hi, I'm calling about my March bill. There's a problem with the total.", "Oi, estou ligando sobre a minha conta de março. Há um problema com o total."], ["Let me pull up your account. What's wrong exactly?", "Deixe-me abrir a sua conta. O que há de errado exatamente?"], ["I paid $40 twice for the same plan. That's not right!", "Paguei $40 duas vezes pelo mesmo plano. Isso não está certo!"], ["I see it. It looks like we overcharged you when your plan changed.", "Estou vendo. Parece que cobramos a mais quando o seu plano mudou."], ["So will the extra $40 go back on my account?", "Então os $40 a mais voltam para a minha conta?"], ["Yes, within three days. I'm sorry about that.", "Sim, em até três dias. Sinto muito por isso."], ["Thanks. Is there anything else I need to do?", "Obrigada. Preciso fazer mais alguma coisa?"], ["No, I'll sort out the problem today. Your reference number is 7741.", "Não, eu resolvo o problema hoje. O seu número de referência é 7741."], ["Okay, 7741. Thanks for your help.", "Certo, 7741. Obrigada pela ajuda."]], ["/tʃ/ em March e charge", "O 'ch' inglês é como o 'tch' de 'tchau', mas com os lábios um pouco projetados. March termina com esse som: não diga 'Márqui'.", ["March", "charge"]], ["I'm calling ___ my phone bill.", "about", "for", "Estou ligando sobre a minha conta de celular.", "Para dizer o assunto da ligação usamos calling about, não calling for."], [["She calls the company and says, \"I'm calling about my phone bill. There's a problem with the total.\"", "Ela liga para a empresa e diz: \"Estou ligando sobre a minha conta de celular. Há um problema com o total.\""], ["Hi, I'm calling about my March bill. There's a problem with the total.", "Oi, estou ligando sobre a minha conta de março. Há um problema com o total."]], [{"t": "c", "q": "There's a problem ___ my bill.", "o": ["with", "in", "on"], "pt": "Há um problema com a minha conta.", "why": "Com problem usamos with: a problem with something."}, {"t": "l", "say": "I'm calling about my bill.", "o": ["I'm calling about my bill.", "I'm falling about my bill.", "I'm calling about my ball."], "why": "Você ouviu calling (ligando) e bill (conta), não falling nem ball."}, {"t": "b", "pt": "Estou ligando sobre a minha conta de celular.", "w": ["I'm", "calling", "about", "my", "phone", "bill"]}, {"t": "b", "pt": "Há um problema com o total.", "w": ["There's", "a", "problem", "with", "the", "total"]}]];
