englishA2Plans[216]={"title": "Confirmando a entrega de um sofá", "file": "", "grammar": "Confirmar dados: Let me check / So that's… / Let me read back", "goal": "Confirme dados por telefone usando Let me check, So that's… e Let me read back.", "words": [["read back", "reler em voz alta para confirmar"], ["let me check", "deixe-me conferir"], ["double-check", "conferir de novo"], ["correct", "correto"], ["jot down", "anotar rápido"], ["ID number", "número do documento"], ["gate code", "código do portão"], ["confirm", "confirmar"], ["all set", "tudo pronto"], ["sorry to keep you waiting", "desculpe a demora"]]};
englishA2Content[216]=[[["Elena calls the store to confirm her sofa delivery.", "Elena liga para a loja para confirmar a entrega do sofá."], ["The clerk says, \"Let me check,\" and finds her order.", "O atendente diz: \"Deixe-me conferir\" e acha o pedido dela."], ["\"So that's 21 Pine Street, apartment 6B?\" he asks. \"Yes, that's correct,\" says Elena.", "\"Então é Pine Street 21, apartamento 6B?\", ele pergunta. \"Sim, está correto\", diz Elena."], ["The driver will need her ID number, so she gets her license.", "O motorista vai precisar do número do documento dela, então ela pega a carteira."], ["Before they hang up, the clerk says, \"Let me read back the details.\"", "Antes de desligarem, o atendente diz: \"Deixe-me reler os detalhes.\""], ["Everything is right, and Elena is all set.", "Está tudo certo, e Elena está pronta."]], [["Home Comfort deliveries, this is Sam.", "Entregas Home Comfort, Sam falando."], ["Hi, Sam. This is Elena Park. I'm calling about my sofa for Friday.", "Oi, Sam. Aqui é a Elena Park. Estou ligando sobre o meu sofá de sexta."], ["Let me check. Sorry to keep you waiting. Yes, it's on the truck for one to four.", "Deixe-me conferir. Desculpe a demora. Sim, está no caminhão, entre uma e quatro."], ["Perfect. My building has a gate, so the driver will need the gate code.", "Perfeito. Meu prédio tem portão, então o motorista vai precisar do código do portão."], ["Go ahead. I'll jot down the number.", "Pode falar. Vou anotar o número."], ["It's 4291. And I'm in apartment 6B, 21 Pine Street.", "É 4291. E eu estou no apartamento 6B, Pine Street 21."], ["So that's 4291, apartment 6B, 12 Pine Street?", "Então é 4291, apartamento 6B, Pine Street 12?"], ["No, 21, not 12. Twenty-one Pine Street.", "Não, 21, e não 12. Pine Street vinte e um."], ["Oh, sorry. I'll double-check the address on the label. Okay, you're all set.", "Ah, desculpe. Vou conferir o endereço de novo na etiqueta. Pronto, está tudo certo."], ["Great. So Friday, between one and four, 21 Pine Street. Thanks!", "Ótimo. Então sexta, entre uma e quatro, Pine Street 21. Obrigada!"]], ["/r/ em correct e read", "Para o 'r' inglês, a língua fica puxada para trás, sem encostar em nada, e os lábios arredondam um pouco. Não use o som de 'h' do 'r' de 'rato' em read.", ["correct", "read"]], ["Let me ___ your order.", "check", "to check", "Deixe-me conferir o seu pedido.", "Depois de Let me vem o verbo simples, sem to."], [["The clerk says, \"Let me check,\" and finds her order.", "O atendente diz: \"Deixe-me conferir\" e acha o pedido dela."], ["So that's 4291, apartment 6B, 12 Pine Street?", "Então é 4291, apartamento 6B, Pine Street 12?"]], [{"t": "c", "q": "So ___ 4291, apartment 6B?", "o": ["that's", "that", "those"], "pt": "Então é 4291, apartamento 6B?", "why": "Para confirmar um dado usamos So that's… (that is)."}, {"t": "l", "say": "Let me read back the address.", "o": ["Let me read back the address.", "Let me lead back the address.", "Let me read back the addresses."], "why": "Você ouviu read (com r) e address no singular."}, {"t": "b", "pt": "Deixe-me conferir o pedido.", "w": ["Let", "me", "check", "the", "order"]}, {"t": "b", "pt": "Então é 4291, apartamento 6B.", "w": ["So", "that's", "4291", "apartment", "6B"]}]];
