englishA2Plans[217]={"title": "Pedindo ajuda para um vizinho que passou mal", "file": "", "grammar": "Descrever um problema de saúde e o lugar numa ligação de emergência", "goal": "Descreva o problema e o endereço numa ligação de emergência com He has… e I'm on the corner of…", "words": [["dispatcher", "atendente de emergência"], ["paramedic", "paramédico"], ["chest pain", "dor no peito"], ["conscious", "consciente"], ["cross street", "rua transversal"], ["stay calm", "manter a calma"], ["on the way", "a caminho"], ["stay on the line", "ficar na linha"], ["right away", "agora mesmo"]]};
englishA2Content[217]=[[["Tom finds his neighbor on the floor, holding his chest.", "Tom encontra o vizinho no chão, segurando o peito."], ["He calls 911, and the dispatcher asks, \"What's your emergency?\"", "Ele liga para o 911, e a atendente pergunta: \"Qual é a emergência?\""], ["\"My neighbor has chest pain, and he can't stand up,\" Tom says.", "\"Meu vizinho está com dor no peito e não consegue ficar de pé\", diz Tom."], ["The dispatcher says, \"Stay calm, and tell me where you are.\"", "A atendente diz: \"Mantenha a calma e diga onde você está.\""], ["\"I'm at 48 Main Street, near Oak,\" Tom says.", "\"Estou na Main Street 48, perto da Oak\", diz Tom."], ["Soon he hears a siren, and the paramedics come in.", "Logo ele ouve uma sirene, e os paramédicos entram."]], [["911, what's your emergency?", "911, qual é a sua emergência?"], ["My neighbor is on the floor, and he says he has chest pain.", "Meu vizinho está no chão, e ele diz que está com dor no peito."], ["Is he conscious? Is he breathing normally?", "Ele está consciente? Está respirando normalmente?"], ["Yes, he's conscious, but he looks very pale and he's sweating.", "Sim, está consciente, mas parece muito pálido e está suando."], ["Okay. What's your address, and what's the cross street?", "Certo. Qual é o seu endereço e qual é a rua transversal?"], ["It's 48 Main Street, on the corner of Main and Oak. Apartment 3.", "É Main Street 48, na esquina da Main com a Oak. Apartamento 3."], ["Thanks. I'm sending an ambulance right away. Help is on the way, so please stay on the line.", "Obrigada. Estou enviando uma ambulância agora mesmo. A ajuda está a caminho, então fique na linha."], ["Okay, I'm staying on the line. Should I unlock the front door?", "Certo, estou na linha. Devo destrancar a porta da frente?"], ["Yes, please. And keep him sitting down until the paramedics arrive.", "Sim, por favor. E mantenha-o sentado até os paramédicos chegarem."], ["The door is open, and he's sitting down. Please hurry!", "A porta está aberta, e ele está sentado. Por favor, venham rápido!"]], ["/eɪ/ em stay e Main", "O /eɪ/ é um ditongo: comece em 'e' e deslize para 'i'. Em stay, o 's' vem limpo, sem 'e' na frente.", ["stay", "Main"]], ["My neighbor ___ chest pain.", "has", "is", "Meu vizinho está com dor no peito.", "Para dizer que alguém sente dor, usamos have/has (has chest pain), não is."], [["\"My neighbor has chest pain, and he can't stand up,\" Tom says.", "\"Meu vizinho está com dor no peito e não consegue ficar de pé\", diz Tom."], ["It's 48 Main Street, on the corner of Main and Oak. Apartment 3.", "É Main Street 48, na esquina da Main com a Oak. Apartamento 3."]], [{"t": "c", "q": "I'm ___ 48 Main Street.", "o": ["at", "in", "on"], "pt": "Estou na Main Street 48.", "why": "Com número de endereço usamos at: at 48 Main Street."}, {"t": "l", "say": "He has chest pain.", "o": ["He has chest pain.", "He has chest paint.", "She has chest pain."], "why": "Você ouviu He (ele) e pain (dor), não paint nem She."}, {"t": "b", "pt": "Meu vizinho está com dor no peito.", "w": ["My", "neighbor", "has", "chest", "pain"]}, {"t": "b", "pt": "Estou na esquina da Main com a Oak.", "w": ["I'm", "on", "the", "corner", "of", "Main", "and", "Oak"]}]];
