englishA2Plans[218]={"title": "Encerrando uma ligação com o suporte de internet", "file": "", "grammar": "Encerrar a ligação com educação: Is there anything else? / Thanks for calling", "goal": "Encerre uma ligação com educação usando Is there anything else? e Thanks for calling.", "words": [["thanks for calling", "obrigado por ligar"], ["anything else", "mais alguma coisa"], ["have a nice day", "tenha um bom dia"], ["take care", "se cuide"], ["that's all", "é só isso"], ["pleasure", "prazer (My pleasure = por nada)"], ["likewise", "igualmente"], ["bye for now", "tchau por enquanto"], ["get back", "retornar (get back to you)"]]};
englishA2Content[218]=[[["Priya calls her internet company because her Wi-Fi keeps dropping.", "Priya liga para a empresa de internet porque o Wi-Fi dela vive caindo."], ["The agent fixes it in a minute, and Priya says, \"Thank you so much!\"", "O atendente resolve em um minuto, e Priya diz: \"Muito obrigada!\""], ["\"Is there anything else I can help you with?\" he asks.", "\"Posso ajudar com mais alguma coisa?\", ele pergunta."], ["\"No, that's all,\" says Priya.", "\"Não, é só isso\", diz Priya."], ["\"Thanks for calling, and take care,\" says the agent.", "\"Obrigado por ligar, e se cuide\", diz o atendente."], ["Priya smiles and says, \"Thanks, Ravi. Bye for now!\"", "Priya sorri e diz: \"Obrigada, Ravi. Tchau por enquanto!\""]], [["Net Plus, this is Ravi. How can I help?", "Net Plus, Ravi falando. Como posso ajudar?"], ["Hi, Ravi. My Wi-Fi keeps dropping every evening.", "Oi, Ravi. Meu Wi-Fi fica caindo toda noite."], ["Let me reset your router from here. It will take a minute.", "Vou reiniciar o seu roteador daqui. Leva um minuto."], ["Okay... Yes, it's working now. Thank you so much!", "Certo... Sim, está funcionando agora. Muito obrigada!"], ["My pleasure. Is there anything else I can help you with?", "Por nada. Posso ajudar com mais alguma coisa?"], ["Yes, one more thing. Could someone check the line this week?", "Sim, mais uma coisa. Alguém poderia verificar a linha esta semana?"], ["Sure. A technician will get back to you tomorrow morning. Is there anything else?", "Claro. Um técnico entra em contato com você amanhã de manhã. Mais alguma coisa?"], ["No, that's all. Thank you, Ravi.", "Não, é só isso. Obrigada, Ravi."], ["Thanks for calling Net Plus, and have a nice day!", "Obrigado por ligar para a Net Plus, e tenha um bom dia!"], ["Likewise, Ravi. I'll wait for the call. Bye for now!", "Igualmente, Ravi. Vou esperar a ligação. Tchau por enquanto!"]], ["/ŋ/ em calling e anything", "O 'ng' final é um som nasal feito no fundo da boca, sem um 'g' forte depois. Diga calling, não 'callingue'.", ["calling", "anything"]], ["Is there ___ else I can help you with?", "anything", "something", "Posso ajudar com mais alguma coisa?", "Em perguntas usamos anything (Is there anything else?), não something."], [["\"Is there anything else I can help you with?\" he asks.", "\"Posso ajudar com mais alguma coisa?\", ele pergunta."], ["My pleasure. Is there anything else I can help you with?", "Por nada. Posso ajudar com mais alguma coisa?"]], [{"t": "c", "q": "Thanks ___ calling.", "o": ["for", "to", "at"], "pt": "Obrigado por ligar.", "why": "Agradecemos por algo com thanks for + -ing."}, {"t": "l", "say": "Thanks for calling.", "o": ["Thanks for calling.", "Thanks for falling.", "Thanks for coming."], "why": "Você ouviu calling (ligando), com o som /k/, e não falling nem coming."}, {"t": "b", "pt": "Mais alguma coisa?", "w": ["Is", "there", "anything", "else"]}, {"t": "b", "pt": "Obrigado por ligar para a Net Plus.", "w": ["Thanks", "for", "calling", "Net", "Plus"]}]];
