englishA2Plans[219]={"title": "Revisão: um dia de ligações na loja de bicicletas", "file": "", "grammar": "Revisão: um dia de ligações (mini-história)", "goal": "Revise pedidos, recados, números, remarcações, confirmações e despedidas em ligações.", "words": [["wrap up", "terminar, encerrar"], ["touch base", "falar rapidamente com alguém"], ["follow up", "dar seguimento"], ["heads up", "aviso prévio"], ["keep in touch", "manter contato"], ["dead battery", "bateria descarregada"], ["speak soon", "até logo"], ["call it a day", "encerrar por hoje"], ["phone tag", "pega-pega do telefone"]]};
englishA2Content[219]=[[["It's almost six at Noah's bike shop, and he wants to wrap up.", "Quase seis horas na loja de bicicletas do Noah, e ele quer encerrar o dia."], ["He still has one call to make, but he hates playing phone tag.", "Ele ainda tem uma ligação para fazer, mas odeia ficar no pega-pega do telefone."], ["\"Could I speak to Ms. Cruz?\" he asks. \"She's out,\" says her husband. \"Can I take a message?\"", "\"Eu poderia falar com a Sra. Cruz?\", ele pergunta. \"Ela saiu\", diz o marido. \"Posso anotar um recado?\""], ["\"Yes. Tell her that her bike is ready, and I'll follow up tomorrow.\"", "\"Sim. Diga a ela que a bicicleta está pronta, e eu retorno amanhã.\""], ["\"I'm afraid she's busy tomorrow,\" he says. \"How about Saturday?\"", "\"Infelizmente ela está ocupada amanhã\", ele diz. \"Que tal sábado?\""], ["\"Perfect,\" says Noah, and he decides to call it a day.", "\"Perfeito\", diz Noah, e ele decide encerrar por hoje."]], [["Noah's Bikes, thanks for calling. How can I help?", "Noah's Bikes, obrigado por ligar. Como posso ajudar?"], ["Hi, could I speak to the repair guy? My e-bike has a dead battery.", "Oi, eu poderia falar com o mecânico? Minha bicicleta elétrica está com a bateria descarregada."], ["That's me. I'm afraid we're booked up this week, but how about Monday at ten?", "Sou eu. Infelizmente estamos lotados esta semana, mas que tal segunda às dez?"], ["Monday works. Sorry, I have a bad connection. Could you speak up a little?", "Segunda serve. Desculpe, a ligação está ruim. Você poderia falar um pouco mais alto?"], ["Sure. Could you spell your last name, and what's your area code?", "Claro. Você poderia soletrar o seu sobrenome e qual é o seu código de área?"], ["It's Ito, I-T-O, and the area code is 415. My number is 555-0133.", "É Ito, I-T-O, e o código de área é 415. Meu número é 555-0133."], ["Let me read back the number to double-check it. Okay, 555-0133.", "Deixe-me reler o número para conferir de novo. Certo, 555-0133."], ["That's correct. Also, I think I was double-charged for my last repair.", "Está correto. Além disso, acho que fui cobrado em dobro no último conserto."], ["I'll look into it right away and ring back this afternoon. Just a heads up, I might call after six.", "Vou investigar agora mesmo e ligo de volta à tarde. Só um aviso: posso ligar depois das seis."], ["Okay, Monday at ten. That's all. Speak soon!", "Certo, segunda às dez. É só isso. Até logo!"]], ["/ɛ/ em dead e heads", "O /ɛ/ é um 'é' aberto e curto, como em 'pé'. Não troque por 'i': dead não é 'did'.", ["dead", "heads"]], ["I'm afraid we ___ booked up this week.", "are", "do", "Infelizmente estamos lotados esta semana.", "Com booked up (estar lotado) usamos o verbo be: we are booked up."], [["\"Could I speak to Ms. Cruz?\" he asks. \"She's out,\" says her husband. \"Can I take a message?\"", "\"Eu poderia falar com a Sra. Cruz?\", ele pergunta. \"Ela saiu\", diz o marido. \"Posso anotar um recado?\""], ["That's me. I'm afraid we're booked up this week, but how about Monday at ten?", "Sou eu. Infelizmente estamos lotados esta semana, mas que tal segunda às dez?"]], [{"t": "c", "q": "Do you know what time the shop ___?", "o": ["closes", "does close", "closing"], "pt": "Você sabe a que horas a loja fecha?", "why": "Na pergunta indireta o verbo vem depois do sujeito, sem do: the shop closes."}, {"t": "l", "say": "Tell her that the bike is ready.", "o": ["Tell her that the bike is ready.", "Tell her that the bike is red.", "Tell her that the bike was ready."], "why": "Você ouviu ready (pronta), não red, e o verbo no presente."}, {"t": "b", "pt": "Que tal segunda às dez?", "w": ["How", "about", "Monday", "at", "ten"]}, {"t": "b", "pt": "Você poderia falar mais alto, por favor?", "w": ["Could", "you", "speak", "up", "please"]}]];
