englishA2MiniStories[219]=["Um dia de ligações do Noah", "Noah's bike shop is busy, and the phone rings all day.~A loja de bicicletas do Noah está cheia, e o telefone toca o dia todo.|First, he calls a supplier, but reception puts him on hold, and he ends up with a voice mail.~Primeiro, ele liga para um fornecedor, mas a recepção o deixa em espera, e ele cai na caixa postal.|A customer rings back, but there is a bad connection, so Noah asks her to speak up and slow down.~Uma cliente liga de volta, mas a ligação está ruim, então Noah pede que ela fale mais alto e mais devagar.|She spells her last name, says each digit of her number, and Noah jots it down.~Ela soletra o sobrenome, diz cada dígito do número, e Noah anota.|She wants to reschedule her repair, but the only slot is on Friday.~Ela quer remarcar o conserto, mas o único horário é na sexta.|Another customer was double-charged, so Noah says he will look into it and reads back the receipt.~Outro cliente foi cobrado em dobro, então Noah diz que vai investigar e relê o recibo.|Then a boy calls about his grandpa, who fell off a bike, and Noah tells him to stay calm because the paramedics are on the way.~Então um menino liga por causa do avô, que caiu de uma bicicleta, e Noah diz para manter a calma porque os paramédicos estão a caminho.|Luckily, the grandpa is fine, and the family says, \"Thanks for calling!\"~Por sorte, o avô está bem, e a família diz: \"Obrigado por ligar!\"|At six, Noah asks himself, \"Is there anything else?\" and decides to call it a day.~Às seis, Noah se pergunta: \"Mais alguma coisa?\" e decide encerrar por hoje.|He checks the gate code, locks up, and says, \"Bye for now, phone!\"~Ele confere o código do portão, tranca tudo e diz: \"Tchau por enquanto, telefone!\""];
englishA2ExtraWordExamples[219]={"touch base": ["Let's touch base on Friday about the new order.", "Vamos nos falar rapidinho na sexta sobre o novo pedido."], "keep in touch": ["Thanks for your help. Let's keep in touch.", "Obrigado pela ajuda. Vamos manter contato."]};
englishA2Plans[220]={"title": "Meu trabalho no atendimento ao cliente", "file": "", "grammar": "Descrever o trabalho: I'm responsible for… / my job involves + -ing", "goal": "Descreva seu trabalho com I'm responsible for… e My job involves + verbo com -ing.", "words": [["responsible", "responsável"], ["in charge of", "encarregado de"], ["client", "cliente"], ["customer service", "atendimento ao cliente"], ["full-time", "período integral"], ["junior", "júnior, de nível inicial"], ["employee", "funcionário"], ["expert", "especialista"], ["on duty", "de plantão"]]};
englishA2Content[220]=[[["I work full-time in customer service at a phone company.", "Eu trabalho em período integral no atendimento ao cliente de uma empresa de telefone."], ["I'm responsible for answering calls from angry clients.", "Sou responsável por atender ligações de clientes zangados."], ["My job involves listening, typing notes, and solving problems.", "Meu trabalho envolve ouvir, digitar anotações e resolver problemas."], ["My brother Sam is a junior employee at a bank, and he works part-time.", "Meu irmão Sam é um funcionário júnior de um banco e trabalha meio período."], ["He's in charge of the new accounts on Fridays.", "Ele é encarregado das contas novas às sextas."], ["Last Monday a client thanked me, and now I feel like an expert.", "Na segunda passada um cliente me agradeceu, e agora me sinto um especialista."]], [["Omar, what do you do at the phone company?", "Omar, o que você faz na empresa de telefone?"], ["I work in customer service. I'm responsible for the calls about internet problems.", "Eu trabalho no atendimento ao cliente. Sou responsável pelas ligações sobre problemas de internet."], ["That sounds hard. What does your job involve every day?", "Parece difícil. O que seu trabalho envolve todo dia?"], ["It involves talking to about forty clients and writing a short report.", "Envolve falar com uns quarenta clientes e escrever um relatório curto."], ["Forty? Are you a full-time employee?", "Quarenta? Você é funcionário de período integral?"], ["Yes, I am. I'm on duty until six. My sister works part-time in the same office, and she's still junior.", "Sim. Fico de plantão até as seis. Minha irmã trabalha meio período no mesmo escritório e ainda é júnior."], ["Who is in charge of your team?", "Quem é o responsável pela sua equipe?"], ["A woman named Rosa. She's an expert, so I'm learning a lot of things.", "Uma mulher chamada Rosa. Ela é especialista, então estou aprendendo muitas coisas."]], ["/θ/ em thanked e things", "Ponha a ponta da língua entre os dentes e solte o ar, sem trocar por 't' ou 'f'. Em thanked e things o som vem no começo.", ["thanked", "things"]], ["I'm responsible ___ answering the phone.", "for", "of", "Sou responsável por atender o telefone.", "Depois de responsible, a preposição certa é for."], [["I'm responsible for answering calls from angry clients.", "Sou responsável por atender ligações de clientes zangados."], ["It involves talking to about forty clients and writing a short report.", "Envolve falar com uns quarenta clientes e escrever um relatório curto."]], [{"t": "c", "q": "My job involves ___ emails all day.", "o": ["answering", "answer", "to answer"], "pt": "Meu trabalho envolve responder e-mails o dia todo.", "why": "Depois de involves usamos o verbo com -ing."}, {"t": "l", "say": "I'm in charge of the new clients.", "o": ["I'm in charge of the new clients.", "I'm in charge of the new classes.", "I'm in charge for the new clients."], "why": "A expressão certa é in charge of, e você ouviu clients."}, {"t": "b", "pt": "Eu sou responsável pelos clientes novos.", "w": ["I'm", "responsible", "for", "the", "new", "clients"]}, {"t": "b", "pt": "Meu trabalho envolve atender o telefone.", "w": ["My", "job", "involves", "answering", "the", "phone"]}]];
