englishA2Plans[221]={"title": "A copiadora travada antes da reunião", "file": "", "grammar": "Pedir ajuda a um colega: Could you give me a hand with…?", "goal": "Peça ajuda a um colega com Could you give me a hand with…?", "words": [["give me a hand", "me dar uma mão"], ["paper jam", "papel atolado"], ["photocopy", "fotocópia"], ["out of order", "fora de serviço"], ["show me how", "me mostrar como"], ["figure out", "descobrir"], ["toner", "toner"], ["cartridge", "cartucho"], ["staple", "grampear"]]};
englishA2Content[221]=[[["The photocopy machine in our office has a paper jam again.", "A copiadora do nosso escritório está com papel atolado de novo."], ["Ben needs fifty copies before ten, but he can't figure out how to open it.", "Ben precisa de cinquenta cópias antes das dez, mas não consegue descobrir como abri-la."], ["He asks Lia, \"Could you give me a hand with this machine?\"", "Ele pergunta à Lia: \"Você poderia me dar uma mão com esta máquina?\""], ["She shows him the green button, and together they pull out the paper.", "Ela mostra o botão verde, e juntos eles puxam o papel."], ["Then the toner runs out, and Ben asks, \"Could you give me a hand with the cartridge?\"", "Depois o toner acaba, e Ben pergunta: \"Você poderia me dar uma mão com o cartucho?\""], ["The machine on the second floor is out of order, so he is glad Lia is there.", "A máquina do segundo andar está fora de serviço, então ele fica feliz por Lia estar ali."]], [["Lia, could you give me a hand with the photocopy machine?", "Lia, você poderia me dar uma mão com a copiadora?"], ["Sure, Ben. What's the problem?", "Claro, Ben. Qual é o problema?"], ["There's a paper jam, and I can't figure out how to open the back.", "Tem um papel atolado, e não consigo descobrir como abrir a parte de trás."], ["Press the green button, then pull the paper out slowly.", "Aperte o botão verde e puxe o papel devagar."], ["Could you show me how? I need fifty copies before the meeting at ten.", "Você pode me mostrar como? Preciso de cinquenta cópias antes da reunião das dez."], ["Okay, watch my hands. Just press and pull. Now you try.", "Ok, olhe minhas mãos. É só apertar e puxar. Agora tente você."], ["It works! But now the toner is low. Could you give me a hand with the cartridge, too?", "Funcionou! Mas agora o toner está acabando. Você poderia me dar uma mão com o cartucho também?"], ["Sure. First, could you give me a hand with this box? The new cartridge is heavy.", "Claro. Primeiro, você poderia me dar uma mão com esta caixa? O cartucho novo é pesado."], ["Of course. Okay, it's in. Where can I staple the copies?", "Claro. Pronto, já está dentro. Onde posso grampear as cópias?"], ["Use the one on my desk. The machine upstairs is out of order, too.", "Use o grampeador da minha mesa. A máquina lá de cima também está fora de serviço."]], ["/dʒ/ em jam e just", "Encoste a língua no céu da boca e solte com voz, como um 'dj' rápido (diferente do 'j' do português). Em jam e just o som abre a palavra.", ["jam", "just"]], ["Could you give me a hand ___ these boxes?", "with", "for", "Você poderia me dar uma mão com estas caixas?", "Depois de give me a hand, a ajuda com algo usa with."], [["Lia, could you give me a hand with the photocopy machine?", "Lia, você poderia me dar uma mão com a copiadora?"], ["It works! But now the toner is low. Could you give me a hand with the cartridge, too?", "Funcionou! Mas agora o toner está acabando. Você poderia me dar uma mão com o cartucho também?"]], [{"t": "c", "q": "Could you ___ me a hand with this report?", "o": ["give", "make", "do"], "pt": "Você poderia me dar uma mão com este relatório?", "why": "A expressão fixa é give me a hand; em português dizemos 'dar', não 'fazer'."}, {"t": "l", "say": "I can't figure out how to open it.", "o": ["I can't figure out how to open it.", "I can't figure out how to close it.", "I can't find out how to open it."], "why": "Você ouviu figure out e open."}, {"t": "b", "pt": "Você poderia me dar uma mão?", "w": ["Could", "you", "give", "me", "a", "hand"]}, {"t": "b", "pt": "Você pode me mostrar como?", "w": ["Could", "you", "show", "me", "how"]}]];
