englishA2Plans[222]={"title": "Ensinando a enviar uma encomenda", "file": "", "grammar": "Dar instruções em sequência: first, next, make sure you…", "goal": "Explique um passo a passo com first, next e make sure you…", "words": [["instruction", "instrução"], ["procedure", "procedimento"], ["step by step", "passo a passo"], ["make sure", "certificar-se"], ["carry on", "continuar"], ["go over", "revisar"], ["check twice", "conferir duas vezes"], ["scan", "escanear"], ["barcode", "código de barras"]]};
englishA2Content[222]=[[["Rosa has a new job: she trains Tom to send packages.", "Rosa tem uma nova função: ela treina o Tom para enviar encomendas."], ["First, she gives him the written instructions.", "Primeiro, ela dá a ele as instruções escritas."], ["Next, they go over the procedure step by step.", "Depois, eles revisam o procedimento passo a passo."], ["\"Make sure you check twice,\" she says. \"One wrong address costs money.\"", "\"Certifique-se de conferir duas vezes\", ela diz. \"Um endereço errado custa dinheiro.\""], ["The boss gives Tom ten boxes, and he has to carry on alone.", "O chefe dá dez caixas ao Tom, e ele tem que continuar sozinho."], ["He is slow at first, but by noon he scans each barcode in two seconds.", "Ele é lento no começo, mas ao meio-dia escaneia cada código de barras em dois segundos."]], [["Tom, first, scan the barcode on the box.", "Tom, primeiro, escaneie o código de barras da caixa."], ["Like this? The light is red.", "Assim? A luz está vermelha."], ["Hold it closer. Good. Next, type the weight, and make sure it's correct.", "Chegue mais perto. Bom. Depois, digite o peso e certifique-se de que está certo."], ["It's four kilos. What do I do after that?", "São quatro quilos. O que faço depois?"], ["Then print the receipt and put it in the plastic bag. Don't forget the tape.", "Depois imprima o recibo e coloque na sacola plástica. Não esqueça a fita."], ["Got it. Could you go over the steps once more? I'm a little nervous.", "Entendi. Você pode revisar os passos mais uma vez? Estou um pouco nervoso."], ["Of course. Scan, type the weight, print, and then carry on with the next box. Make sure you check twice.", "Claro. Escaneie, digite o peso, imprima e continue com a próxima caixa. Confira duas vezes."], ["Okay. I'll call you if there's a problem. Thanks, Rosa!", "Ok. Ligo para você se houver problema. Obrigado, Rosa!"]], ["/ʃ/ em sure e she", "Arredonde os lábios e deixe o ar sair contínuo, como quem pede 'shhh'. Em sure o som vem no começo; não diga 'sur' com s.", ["sure", "she"]], ["___ sure you check the address twice.", "Make", "Do", "Certifique-se de conferir o endereço duas vezes.", "A expressão fixa é make sure, nunca do sure."], [["Next, they go over the procedure step by step.", "Depois, eles revisam o procedimento passo a passo."], ["Hold it closer. Good. Next, type the weight, and make sure it's correct.", "Chegue mais perto. Bom. Depois, digite o peso e certifique-se de que está certo."]], [{"t": "c", "q": "___, open the box. Next, check the label.", "o": ["First", "Last", "After"], "pt": "Primeiro, abra a caixa. Depois, confira a etiqueta.", "why": "First abre a sequência e combina com next."}, {"t": "l", "say": "Make sure you check the address.", "o": ["Make sure you check the address.", "Make sure you change the address.", "Make sure you checked the address."], "why": "Depois de make sure you usamos o verbo simples: check."}, {"t": "b", "pt": "Primeiro, escaneie a etiqueta.", "w": ["First", "scan", "the", "label"]}, {"t": "b", "pt": "Certifique-se de que o peso está certo.", "w": ["Make", "sure", "the", "weight", "is", "correct"]}]];
