englishA2Plans[223]={"title": "Reunião para planejar a festa de fim de ano", "file": "", "grammar": "Opinar em reunião: I think we should… / I agree / I'm not sure", "goal": "Dê sua opinião em uma reunião com I think we should…, I agree e I'm not sure.", "words": [["proposal", "proposta"], ["committee", "comitê"], ["point of view", "ponto de vista"], ["conclude", "concluir"], ["come up with", "ter uma ideia, bolar"], ["disagree", "discordar"], ["take a vote", "votar"], ["good point", "boa observação"], ["on the other hand", "por outro lado"]]};
englishA2Content[223]=[[["The office committee meets on Tuesday to plan the year-end party.", "O comitê do escritório se reúne na terça para planejar a festa de fim de ano."], ["Elena has a proposal: a picnic in the park instead of a dinner.", "Elena tem uma proposta: um piquenique no parque em vez de um jantar."], ["Kenji disagrees because December is cold, and he's not sure about the park.", "Kenji discorda porque dezembro é frio, e ele não tem certeza sobre o parque."], ["\"I think we should ask everyone,\" Priya says, and Elena says, \"I agree.\"", "\"Acho que devemos perguntar a todos\", diz Priya, e Elena diz: \"Concordo\"."], ["From Kenji's point of view, an office lunch is simpler, and Priya can't come up with a better idea.", "Do ponto de vista de Kenji, um almoço no escritório é mais simples, e Priya não consegue pensar em nada melhor."], ["In the end, they take a vote and conclude that the lunch is best.", "No fim, eles votam e concluem que o almoço é a melhor opção."]], [["Okay, so what do you think about my proposal for the party?", "Então, o que você acha da minha proposta para a festa?"], ["Honestly, I'm not sure. A picnic in December could be very cold.", "Sinceramente, não tenho certeza. Um piquenique em dezembro pode ser muito frio."], ["True. On the other hand, a restaurant costs forty dollars per person.", "Verdade. Por outro lado, um restaurante custa quarenta dólares por pessoa."], ["Really? That's expensive. I think we should ask everyone first.", "Sério? Isso é caro. Acho que devemos perguntar a todos primeiro."], ["Good point. Can you come up with a cheaper idea by Friday?", "Boa observação. Você pode bolar uma ideia mais barata até sexta?"], ["Maybe an office lunch. From my point of view, it's easy and cheap.", "Talvez um almoço no escritório. Do meu ponto de vista, é fácil e barato."], ["I agree! Let's take a vote, and I'll write the notes for the committee.", "Concordo! Vamos votar, e eu escrevo as anotações para o comitê."], ["Perfect. I count ten hands, so the lunch wins.", "Ótimo. Conto dez mãos, então o almoço ganha."]], ["/ɪ/ curto em think e picnic", "Faça um 'i' curto e relaxado, bem diferente do 'i' longo de feet. Em think e picnic a boca quase não se mexe.", ["think", "picnic"]], ["I think we ___ ask the manager.", "should", "should to", "Acho que devemos perguntar ao gerente.", "Depois de should vem o verbo sem to."], [["Honestly, I'm not sure. A picnic in December could be very cold.", "Sinceramente, não tenho certeza. Um piquenique em dezembro pode ser muito frio."], ["Really? That's expensive. I think we should ask everyone first.", "Sério? Isso é caro. Acho que devemos perguntar a todos primeiro."]], [{"t": "c", "q": "I think we ___ start earlier.", "o": ["should", "should to", "have"], "pt": "Acho que devemos começar mais cedo.", "why": "Should é seguido do verbo sem to: we should start."}, {"t": "l", "say": "I'm not sure about the date.", "o": ["I'm not sure about the date.", "I'm not sure about the data.", "I'm not sure about that day."], "why": "Você ouviu date, a data, e não data, os dados."}, {"t": "b", "pt": "Eu concordo com você.", "w": ["I", "agree", "with", "you"]}, {"t": "b", "pt": "Acho que devemos perguntar a todos.", "w": ["I", "think", "we", "should", "ask", "everyone"]}]];
