englishA2ExtraWordExamples[224]={"be late with": ["I don't want to be late with the report again.", "Não quero me atrasar com o relatório de novo."]};
englishA2Plans[225]={"title": "Um e-mail para um cliente novo", "file": "", "grammar": "E-mails simples: I'm writing to… / I attach… / formal e informal", "goal": "Escreva um e-mail curto com I'm writing to…, I attach… e um fecho adequado.", "words": [["attach", "anexar"], ["regards", "cumprimentos"], ["sincerely", "atenciosamente"], ["dear sir", "prezado senhor"], ["best wishes", "os melhores votos"], ["look forward to", "aguardar com expectativa"], ["get in touch", "entrar em contato"], ["feel free to", "sinta-se à vontade para"], ["subject line", "assunto do e-mail"]]};
englishA2Content[225]=[[["Priya writes a business e-mail to a new client, Mr. Brown.", "Priya escreve um e-mail profissional para um cliente novo, o Sr. Brown."], ["The subject line is short: Price list for March.", "O assunto é curto: Lista de preços de março."], ["She starts: Dear Mr. Brown, I'm writing to ask about your order.", "Ela começa: Prezado Sr. Brown, escrevo para perguntar sobre o seu pedido."], ["Then she writes: I attach the price list, and I look forward to your answer.", "Depois escreve: Anexo a lista de preços e aguardo sua resposta."], ["She ends with Sincerely, and Kind regards would be okay, too.", "Ela termina com Sincerely, e Kind regards também serviria."], ["At the end she adds: Feel free to get in touch if you have questions.", "No fim ela acrescenta: Sinta-se à vontade para entrar em contato se tiver dúvidas."]], [["Priya, are you still writing that business e-mail to Mr. Brown?", "Priya, você ainda está escrevendo aquele e-mail profissional para o Sr. Brown?"], ["Yes. I'm writing to ask about his order, but I don't know how to start.", "Sim. Estou escrevendo para perguntar sobre o pedido dele, mas não sei como começar."], ["Write Dear Mr. Brown, not Hi. Use Dear Sir only if you don't know the name. And keep the subject line short.", "Escreva Dear Mr. Brown, não Hi. Use Dear Sir só se não souber o nome. E deixe o assunto curto."], ["Okay. Should I put the price list inside the e-mail?", "Ok. Devo colocar a lista de preços dentro do e-mail?"], ["No, you attach it. Then write: I attach the price list.", "Não, você anexa. Depois escreva: I attach the price list."], ["Good to know. How do I end it? With Sincerely or Best wishes?", "Bom saber. Como termino? Com Sincerely ou Best wishes?"], ["Use Sincerely for Mr. Brown. Best wishes is for friends.", "Use Sincerely para o Sr. Brown. Best wishes é para amigos."], ["Perfect. I'll also write: Feel free to get in touch. I look forward to hearing from you.", "Perfeito. Também vou escrever: Sinta-se à vontade para entrar em contato. Aguardo seu retorno."]], ["/aɪ/ em writing e price", "Comece com 'a' aberto e termine num 'i' rápido, como em 'pai'. Em writing e price o som é o mesmo.", ["writing", "price"]], ["I'm writing ___ ask about the price.", "to", "for", "Estou escrevendo para perguntar sobre o preço.", "Para dar o motivo, usamos to + verbo, não for."], [["Yes. I'm writing to ask about his order, but I don't know how to start.", "Sim. Estou escrevendo para perguntar sobre o pedido dele, mas não sei como começar."], ["No, you attach it. Then write: I attach the price list.", "Não, você anexa. Depois escreva: I attach the price list."]], [{"t": "c", "q": "I look forward ___ your answer.", "o": ["to", "for", "at"], "pt": "Aguardo sua resposta.", "why": "A expressão fixa é look forward to."}, {"t": "l", "say": "I attach the price list.", "o": ["I attach the price list.", "I attached the price list.", "I attach the prize list."], "why": "Você ouviu o presente, attach, e price, o preço."}, {"t": "b", "pt": "Escrevo para perguntar sobre o pedido.", "w": ["I'm", "writing", "to", "ask", "about", "the", "order"]}, {"t": "b", "pt": "Anexo a lista de preços.", "w": ["I", "attach", "the", "price", "list"]}]];
