englishA2Plans[227]={"title": "Pedindo folga para o casamento da irmã", "file": "", "grammar": "Pedir folga: Can I take… off? / I'd like to…", "goal": "Peça uma folga com Can I take… off? e I'd like to…", "words": [["day off", "dia de folga"], ["sick leave", "licença médica"], ["take off", "tirar folga"], ["request", "pedido formal"], ["swap shifts", "trocar de turno"], ["cover for", "cobrir alguém"], ["short notice", "aviso de última hora"], ["time off", "tempo de folga"], ["ask for", "pedir"]]};
englishA2Content[227]=[[["Omar's sister is getting married on Friday, May 9th.", "A irmã do Omar vai se casar na sexta, 9 de maio."], ["He wants to take Friday off, but it's short notice.", "Ele quer tirar a sexta de folga, mas é de última hora."], ["Rosa is on sick leave this month, so the shop is very busy.", "A Rosa está de licença médica este mês, então a loja está muito cheia."], ["Omar asks his friend Ben to be his substitute, and Ben says yes if they swap shifts.", "Omar pede ao amigo Ben para ser seu substituto, e Ben aceita se eles trocarem de turno."], ["\"I'd like to ask for a day off,\" Omar tells his boss.", "\"Eu gostaria de pedir um dia de folga\", Omar diz à chefe."], ["He sends a written request, and she says yes.", "Ele envia um pedido por escrito, e ela diz que sim."]], [["Ms. Park, can I take Friday off? My sister's wedding is that day.", "Sra. Park, posso tirar a sexta de folga? O casamento da minha irmã é nesse dia."], ["Friday the ninth? We're busy, and Rosa is on sick leave.", "Sexta, dia nove? Estamos cheios, e a Rosa está de licença médica."], ["I know it's short notice, but I'd like to ask for just one day.", "Sei que é de última hora, mas eu gostaria de pedir só um dia."], ["Do you have someone in mind?", "Você tem alguém em mente?"], ["Yes, Ben can cover for me. We can swap shifts: I'll work next Saturday for him.", "Sim, o Ben pode me cobrir. Podemos trocar de turno: trabalho no próximo sábado por ele."], ["That sounds fair. Please send me a written request, and next time ask for time off earlier.", "Parece justo. Mande-me um pedido por escrito e, da próxima vez, peça folga mais cedo."], ["I will, I promise. Thank you so much!", "Vou pedir, prometo. Muito obrigado!"], ["Okay, take Friday off. Congratulations to your sister!", "Ok, pode tirar a sexta. Parabéns à sua irmã!"]], ["/ʌ/ em substitute e just", "Faça um 'a' curto e relaxado, com a boca quase parada e sem arredondar os lábios. Em just e substitute é o mesmo som.", ["substitute", "just"]], ["Can I ___ Friday off?", "take", "make", "Posso tirar sexta de folga?", "Para folga usamos o verbo take: take a day off."], [["Ms. Park, can I take Friday off? My sister's wedding is that day.", "Sra. Park, posso tirar a sexta de folga? O casamento da minha irmã é nesse dia."], ["I know it's short notice, but I'd like to ask for just one day.", "Sei que é de última hora, mas eu gostaria de pedir só um dia."]], [{"t": "c", "q": "I'd like ___ take Monday off.", "o": ["to", "for", "that"], "pt": "Eu gostaria de tirar a segunda de folga.", "why": "I'd like é seguido de to + verbo."}, {"t": "l", "say": "Can I take Friday off?", "o": ["Can I take Friday off?", "Can I make Friday off?", "Can I take Sunday off?"], "why": "Você ouviu take e Friday."}, {"t": "b", "pt": "Posso tirar sexta de folga?", "w": ["Can", "I", "take", "Friday", "off"]}, {"t": "b", "pt": "Eu gostaria de pedir um dia de folga.", "w": ["I'd", "like", "to", "ask", "for", "a", "day", "off"]}]];
