englishA2Plans[228]={"title": "Falta de entregadores na pizzaria", "file": "", "grammar": "Resolver problemas em equipe: Why don't we…? / Let us…", "goal": "Proponha soluções com Why don't we…? e Let us…", "words": [["solution", "solução"], ["alternative", "alternativa"], ["brainstorm", "chuva de ideias"], ["deal with", "lidar com"], ["compromise", "acordo"], ["short-staffed", "com falta de pessoal"], ["chip in", "ajudar, contribuir"], ["take over", "assumir"], ["in a rush", "com pressa"]]};
englishA2Content[228]=[[["At Rosa's Pizza, two drivers are sick, and twenty orders are waiting.", "Na Rosa's Pizza, dois entregadores estão doentes, e vinte pedidos estão esperando."], ["The shop is short-staffed, so Rosa calls a quick brainstorm to find a solution.", "A loja está com falta de pessoal, então a Rosa chama uma rápida chuva de ideias para achar uma solução."], ["Tom says, \"Why don't we split up the orders by neighborhood?\"", "Tom diz: \"Por que não dividimos os pedidos por bairro?\""], ["Mia can't deliver before six, so they find a compromise: she takes the near orders.", "A Mia não pode entregar antes das seis, então eles chegam a um acordo: ela fica com os pedidos próximos."], ["Rosa says, \"Why don't we all chip in? Let's answer the phones one at a time.\"", "Rosa diz: \"Por que não ajudamos todos? Vamos atender os telefones um de cada vez.\""], ["The alternative is to close early, but they work together until nine, and every pizza arrives hot.", "A alternativa seria fechar mais cedo, mas eles trabalham juntos até as nove, e todas as pizzas chegam quentes."]], [["Tom, we have twenty orders and only two drivers. What can we do?", "Tom, temos vinte pedidos e só dois entregadores. O que podemos fazer?"], ["Why don't we ask the kitchen staff to chip in with the nearby orders?", "Por que não pedimos à equipe da cozinha para ajudar com os pedidos próximos?"], ["Good idea. Everybody is in a rush tonight, so I'll call the team.", "Boa ideia. Todo mundo está com pressa esta noite, então vou chamar a equipe."], ["Let us start with the north side. It's the farthest.", "Vamos começar pelo lado norte. É o mais distante."], ["Okay. Who can deal with the phone calls while we're out?", "Ok. Quem pode lidar com as ligações enquanto estamos fora?"], ["Why don't we ask Mia to take over the phones? She's quick.", "Por que não pedimos à Mia para assumir os telefones? Ela é rápida."], ["Perfect. The alternative is closing early, and nobody wants that.", "Perfeito. A alternativa é fechar mais cedo, e ninguém quer isso."], ["Agreed. This solution is simple, so I'm leaving now.", "Combinado. Esta solução é simples, então estou saindo agora."]], ["/ð/ em together e they", "Ponha a língua entre os dentes e faça vibrar, com som de voz. Não troque por 'd' ou 'z'.", ["together", "they"]], ["Why ___ we ask the team for help?", "don't", "not", "Por que não pedimos ajuda à equipe?", "Para sugerir, usamos Why don't we, nunca Why not we."], [["Why don't we ask the kitchen staff to chip in with the nearby orders?", "Por que não pedimos à equipe da cozinha para ajudar com os pedidos próximos?"], ["Let us start with the north side. It's the farthest.", "Vamos começar pelo lado norte. É o mais distante."]], [{"t": "c", "q": "Why ___ we call the manager?", "o": ["don't", "aren't", "not"], "pt": "Por que não ligamos para o gerente?", "why": "A sugestão é Why don't we + verbo."}, {"t": "l", "say": "Let us start with the north side.", "o": ["Let us start with the north side.", "Let us start with the south side.", "Let us stop with the north side."], "why": "Você ouviu start e north."}, {"t": "b", "pt": "Por que não dividimos os pedidos?", "w": ["Why", "don't", "we", "split", "up", "the", "orders"]}, {"t": "b", "pt": "Por que não pedimos ajuda à Mia?", "w": ["Why", "don't", "we", "ask", "Mia", "for", "help"]}]];
