englishA2Plans[229]={"title": "Primeira semana na loja de bicicletas", "file": "", "grammar": "Revisão: primeira semana no novo emprego (mini-história)", "goal": "Revise o vocabulário do trabalho contando como você se adapta a um emprego novo.", "words": [["break room", "sala de descanso"], ["name tag", "crachá"], ["lunch break", "pausa para o almoço"], ["settle in", "se adaptar"], ["fit in", "se enturmar"], ["get used to", "se acostumar com"], ["mentor", "mentor"], ["trial period", "período de experiência"], ["pay day", "dia do pagamento"]]};
englishA2Content[229]=[[["On Monday, Kenji gets a name tag, and he's responsible for the front desk.", "Na segunda, Kenji recebe um crachá e fica responsável pela recepção."], ["His mentor, Elena, says, \"First, make sure you smile at every customer.\"", "A mentora dele, Elena, diz: \"Primeiro, certifique-se de sorrir para todo cliente.\""], ["At the lunch break, the others teach him the shop jokes, and he starts to fit in.", "Na pausa para o almoço, os outros ensinam as piadas da loja a ele, e ele começa a se enturmar."], ["He hasn't learned all the names yet, so Elena says, \"Why don't we practice in the break room?\"", "Ele ainda não aprendeu todos os nomes, então Elena diz: \"Por que não praticamos na sala de descanso?\""], ["He's still getting used to the noise, but the trial period is going well.", "Ele ainda está se acostumando com o barulho, mas o período de experiência vai bem."], ["By Friday he can settle in, and he's already looking forward to his first pay day.", "Na sexta ele já consegue se adaptar e está ansioso pelo primeiro pagamento."]], [["Kenji, how was your first week?", "Kenji, como foi sua primeira semana?"], ["Pretty good. I'm still getting used to the noise, but everybody's nice.", "Muito boa. Ainda estou me acostumando com o barulho, mas todos são legais."], ["Good. Could you give me a hand with these flat tires before lunch?", "Bom. Você poderia me dar uma mão com estes pneus furados antes do almoço?"], ["Sure. First I'll move the boxes, and next I'll make sure the pumps work.", "Claro. Primeiro tiro as caixas, depois vou me certificar de que as bombas funcionam."], ["Thanks. I think we should talk about your trial period next week.", "Obrigada. Acho que devemos conversar sobre seu período de experiência na semana que vem."], ["Okay. I'm not sure I'm ready. I've worked with bikes before, but only at my uncle's garage.", "Ok. Não tenho certeza se estou pronto. Já trabalhei com bicicletas, mas só na oficina do meu tio."], ["Relax, you learn fast. I'm writing to the boss today, and I attach your first report.", "Relaxe, você aprende rápido. Estou escrevendo para o chefe hoje e anexo seu primeiro relatório."], ["Thanks! One more thing. Can I take Monday off? I'd like to visit my sister.", "Obrigado! Mais uma coisa. Posso tirar a segunda de folga? Gostaria de visitar minha irmã."], ["We're busy, but okay. Let us finish the orders today, and I'll tell the boss.", "Estamos ocupados, mas tudo bem. Vamos terminar os pedidos hoje, e eu aviso o chefe."], ["Deal. Thanks, Elena, and see you Tuesday!", "Combinado. Obrigado, Elena, e até terça!"]], ["/æ/ em tag e flat", "Abra a boca como para dizer 'a' e leve a língua um pouco para a frente, entre 'é' e 'a'. Em tag e flat o som é o mesmo.", ["tag", "flat"]], ["I'm not used ___ the noise yet.", "to", "for", "Eu ainda não estou acostumado com o barulho.", "Depois de used, a preposição certa é to."], [["He hasn't learned all the names yet, so Elena says, \"Why don't we practice in the break room?\"", "Ele ainda não aprendeu todos os nomes, então Elena diz: \"Por que não praticamos na sala de descanso?\""], ["Pretty good. I'm still getting used to the noise, but everybody's nice.", "Muito boa. Ainda estou me acostumando com o barulho, mas todos são legais."]], [{"t": "c", "q": "By Friday, I started to ___ in.", "o": ["settle", "sit", "stay"], "pt": "Na sexta, eu comecei a me adaptar.", "why": "A expressão fixa é settle in."}, {"t": "l", "say": "I'm still getting used to the noise.", "o": ["I'm still getting used to the noise.", "I'm still getting used to the news.", "I was still getting used to the noise."], "why": "Você ouviu noise, o barulho, e o presente I'm."}, {"t": "b", "pt": "Ele ainda não aprendeu os nomes.", "w": ["He", "hasn't", "learned", "the", "names", "yet"]}, {"t": "b", "pt": "Posso tirar segunda de folga?", "w": ["Can", "I", "take", "Monday", "off"]}]];
englishA2PhotoThemes[229]="city";
englishA2MiniStories[229]=["A primeira semana da Lia", "Lia starts a full-time job at a bike shop, and she's responsible for the customers.~Lia começa um emprego de período integral numa loja de bicicletas e fica responsável pelos clientes.|On Monday her mentor Tom says, \"First, take off the wheel. Next, check the tire, and make sure you clean the chain.\"~Na segunda, o mentor Tom diz: \"Primeiro, tire a roda. Depois, confira o pneu e certifique-se de limpar a corrente.\"|The pump is stuck, so she asks, \"Could you give me a hand with this?\"~A bomba está emperrada, então ela pergunta: \"Você poderia me dar uma mão com isso?\"|On Wednesday she is late with the weekly report because she hasn't finished the numbers yet.~Na quarta ela está atrasada com o relatório semanal porque ainda não terminou os números.|She writes to the boss, \"I'm writing to ask for more time, and I attach the first part.\"~Ela escreve ao chefe: \"Escrevo para pedir mais tempo, e anexo a primeira parte.\"|At Thursday's meeting she says, \"I think we should open on Sundays,\" and Tom says, \"I agree.\"~Na reunião de quinta, ela diz: \"Acho que devemos abrir aos domingos\", e Tom diz: \"Concordo\".|Lia has never worked with bikes, but she has worked with customers for years.~Lia nunca trabalhou com bicicletas, mas já trabalhou com clientes por anos.|On Friday the shop is full, so she asks the boss, \"Can I take Monday off? I'd like to visit my family.\"~Na sexta a loja está cheia, então ela pergunta ao chefe: \"Posso tirar a segunda de folga? Gostaria de visitar minha família.\"|The boss says, \"Why don't we all work together today? Let us finish the orders, and then you can go.\"~O chefe diz: \"Por que não trabalhamos todos juntos hoje? Vamos terminar os pedidos, e então você pode ir.\"|By closing time, Lia has settled in, and Tom says she fits in well.~Na hora de fechar, Lia já se adaptou, e Tom diz que ela se enturmou bem."];
englishA2ExtraWordExamples[229]={"get used to": ["He needs time to get used to the noise.", "Ele precisa de tempo para se acostumar com o barulho."]};
englishA2Plans[230]={"title": "Acordei com um resfriado", "file": "", "grammar": "Descrever sintomas: have, feel, hurt e how long", "goal": "Descreva seus sintomas e diga há quanto tempo você os sente.", "words": [["sore throat", "dor de garganta"], ["runny nose", "nariz escorrendo"], ["have a cold", "estar resfriado"], ["symptom", "sintoma"], ["sneezing", "espirrando"], ["aching", "doendo, dolorido"], ["feel sick", "sentir enjoo"], ["throw up", "vomitar"], ["earache", "dor de ouvido"]]};
englishA2Content[230]=[[["Ana woke up with a sore throat and a runny nose.", "Ana acordou com dor de garganta e nariz escorrendo."], ["She kept sneezing, and her whole body was aching.", "Ela não parava de espirrar, e o corpo todo estava doendo."], ["\"I have a cold,\" she said, and she stayed home.", "\"Estou resfriada\", disse ela, e ficou em casa."], ["She also has an earache in her left ear.", "Ela também está com dor de ouvido no ouvido esquerdo."], ["At noon she began to feel sick, but she didn't throw up.", "Ao meio-dia ela começou a sentir enjoo, mas não vomitou."], ["By night her only symptom was a runny nose, so she slept well.", "À noite, o único sintoma era o nariz escorrendo, então ela dormiu bem."]], [["Ben, you look terrible this morning. What's wrong?", "Ben, você está com uma cara péssima hoje. O que houve?"], ["I think I have a cold. I have a sore throat and a runny nose.", "Acho que estou resfriado. Estou com dor de garganta e nariz escorrendo."], ["Oh no. How long has your throat hurt?", "Poxa. Há quanto tempo sua garganta dói?"], ["Since Sunday night. I keep sneezing, and my body is aching.", "Desde domingo à noite. Não paro de espirrar, e meu corpo está doendo."], ["Do you have a fever, or any other symptom?", "Você está com febre ou tem algum outro sintoma?"], ["No fever, but I have an earache, and I feel sick when I eat.", "Sem febre, mas estou com dor de ouvido e sinto enjoo quando como."], ["Please don't throw up on my desk! Really, go home and rest.", "Por favor, não vomite na minha mesa! Sério, vá para casa descansar."], ["Ha! Don't worry. I'm going home at ten, and I'll call the doctor tomorrow.", "Ha! Não se preocupe. Vou para casa às dez e ligo para o médico amanhã."]], ["/θ/ em throat e think", "Coloque a ponta da língua entre os dentes e solte o ar, sem vibrar a voz. Não diga tróut nem fróut.", ["throat", "think"]], ["My throat has hurt ___ Sunday night.", "since", "for", "Minha garganta dói desde domingo à noite.", "Sunday night é um ponto no tempo, então usamos since; for é para períodos como two days."], [["Oh no. How long has your throat hurt?", "Poxa. Há quanto tempo sua garganta dói?"], ["Since Sunday night. I keep sneezing, and my body is aching.", "Desde domingo à noite. Não paro de espirrar, e meu corpo está doendo."]], [{"t": "c", "q": "How long ___ you felt sick?", "o": ["have", "do", "are"], "pt": "Há quanto tempo você está se sentindo mal?", "why": "Para perguntar há quanto tempo algo dura, usamos How long have you + particípio."}, {"t": "l", "say": "I have a runny nose and a sore throat.", "o": ["I have a runny nose and a sore throat.", "I had a runny nose and a sore throat.", "I have a runny nose and an earache."], "why": "A frase diz que agora você tem nariz escorrendo e dor de garganta."}, {"t": "b", "pt": "Minha garganta dói desde domingo.", "w": ["My", "throat", "has", "hurt", "since", "Sunday"]}, {"t": "b", "pt": "Estou com dor de ouvido desde ontem.", "w": ["I", "have", "had", "an", "earache", "since", "yesterday"]}]];
englishA2PhotoThemes[230]="map";
englishA2Plans[231]={"title": "Torci o joelho no futebol", "file": "", "grammar": "Perguntas do médico e respostas com present perfect e for/since", "goal": "Responda às perguntas do médico sobre uma lesão usando for e since.", "words": [["injury", "lesão"], ["sprain", "torção"], ["limp", "mancar"], ["bandaged", "enfaixado"], ["allergic", "alérgico"], ["infection", "infecção"], ["recover", "se recuperar"], ["stiff", "rígido, duro"], ["pull a muscle", "distender um músculo"]]};
englishA2Content[231]=[[["Tom plays soccer every Saturday, but last week he got an injury.", "Tom joga futebol todo sábado, mas na semana passada ele se machucou."], ["He has had a limp since the game, and his knee has been stiff for four days.", "Ele manca desde o jogo, e o joelho está rígido há quatro dias."], ["The doctor says it's a sprain, not a broken bone.", "A médica diz que é uma torção, não um osso quebrado."], ["The nurse has bandaged the knee and checked for infection.", "A enfermeira enfaixou o joelho e verificou se havia infecção."], ["Tom has never been allergic to any medicine.", "Tom nunca foi alérgico a nenhum remédio."], ["He needs two weeks to recover, and he hasn't played since Saturday.", "Ele precisa de duas semanas para se recuperar e não joga desde sábado."]], [["Good morning, Tom. What happened? Did you pull a muscle?", "Bom dia, Tom. O que aconteceu? Você distendeu um músculo?"], ["I'm not sure. I fell during a game last Saturday, and I have had a limp since then.", "Não tenho certeza. Eu caí durante um jogo no sábado passado e manco desde então."], ["How long has your knee been stiff?", "Há quanto tempo seu joelho está rígido?"], ["For about four days. It hurts when I go down the stairs.", "Há uns quatro dias. Dói quando eu desço a escada."], ["Let me see. It's a sprain, and there's no infection. Are you allergic to any medicine?", "Deixe-me ver. É uma torção, e não há infecção. Você é alérgico a algum remédio?"], ["No, I've never been allergic to anything. How long will I need to recover?", "Não, nunca fui alérgico a nada. Quanto tempo vou levar para me recuperar?"], ["Probably two weeks. Keep it bandaged, and please don't play soccer yet.", "Provavelmente duas semanas. Mantenha enfaixado e, por favor, não jogue futebol ainda."], ["Okay, I'll stay home. I've already told my coach about the injury.", "Certo, vou ficar em casa. Já avisei meu treinador sobre a lesão."]], ["/ɪ/ curto em limp e infection", "Faça o i bem curto, com a boca relaxada, entre o i e o e do português. Limp não rima com o i longo de leap.", ["limp", "infection"]], ["How long ___ your knee been stiff?", "has", "is", "Há quanto tempo seu joelho está rígido?", "Para perguntar a duração até agora, usamos How long has + sujeito + particípio (been)."], [["How long has your knee been stiff?", "Há quanto tempo seu joelho está rígido?"], ["For about four days. It hurts when I go down the stairs.", "Há uns quatro dias. Dói quando eu desço a escada."]], [{"t": "c", "q": "I haven't played soccer ___ Saturday.", "o": ["since", "for", "ago"], "pt": "Não jogo futebol desde sábado.", "why": "Saturday é um ponto no tempo, então usamos since."}, {"t": "l", "say": "Tom has had a limp since Saturday.", "o": ["Tom has had a limp since Saturday.", "Tom has had a sprain since Saturday.", "Tom has had a limp since Sunday."], "why": "A frase diz que o limp (mancar) começou no sábado."}, {"t": "b", "pt": "Eu não sou alérgico a nenhum remédio.", "w": ["I'm", "not", "allergic", "to", "any", "medicine"]}, {"t": "b", "pt": "Há quanto tempo seu joelho está rígido?", "w": ["How", "long", "has", "your", "knee", "been", "stiff"]}]];
