englishA2Plans[232]={"title": "Entendendo o xarope na farmácia", "file": "", "grammar": "Receitas e remédios: take… twice a day / before meals", "goal": "Peça um remédio e entenda como tomá-lo: twice a day, with food.", "words": [["cough syrup", "xarope para tosse"], ["dose", "dose"], ["side effect", "efeito colateral"], ["with food", "junto com comida"], ["on an empty stomach", "em jejum"], ["wear off", "passar (o efeito)"], ["ointment", "pomada"], ["eye drops", "colírio"], ["get better", "melhorar"]]};
englishA2Content[232]=[[["Rosa has a bad cough, so she goes to the pharmacy.", "Rosa está com uma tosse forte, então vai à farmácia."], ["The pharmacist gives her cough syrup and says, \"Take one dose three times a day.\"", "O farmacêutico dá a ela xarope e diz: \"Tome uma dose três vezes ao dia.\""], ["She also buys ointment for her dry hands and eye drops for her red eyes.", "Ela também compra pomada para as mãos secas e colírio para os olhos vermelhos."], ["\"Don't take the syrup on an empty stomach,\" he says.", "\"Não tome o xarope em jejum\", diz ele."], ["One side effect is sleepiness, so Rosa shouldn't drive after a dose.", "Um efeito colateral é sonolência, então Rosa não deve dirigir depois de uma dose."], ["She hopes to feel better by Friday.", "Ela espera se sentir melhor até sexta."]], [["Hi. I need something for a cough. It's been bad for five days.", "Oi. Preciso de algo para tosse. Está forte há cinco dias."], ["Try this cough syrup. Take one spoon twice a day, in the morning and at night.", "Experimente este xarope. Tome uma colher duas vezes ao dia, de manhã e à noite."], ["Can I take it before breakfast, on an empty stomach?", "Posso tomar antes do café da manhã, em jejum?"], ["No, please take it with food. It's hard on your stomach.", "Não, por favor, tome junto com comida. Pesa no estômago."], ["Does it have any side effect? I have to drive to work.", "Tem algum efeito colateral? Eu preciso dirigir até o trabalho."], ["It can make you sleepy, so don't drive for two hours after each dose.", "Pode dar sono, então não dirija por duas horas depois de cada dose."], ["Understood. How long does it last? When does it start to wear off?", "Entendi. Quanto tempo dura? Quando começa a passar o efeito?"], ["About six hours. Do you need anything else? We have ointment and eye drops on sale.", "Cerca de seis horas. Precisa de mais alguma coisa? Temos pomada e colírio em promoção."], ["Yes, one bottle of eye drops, please. My eyes are red from the dust.", "Sim, um frasco de colírio, por favor. Meus olhos estão vermelhos por causa da poeira."], ["Sure. Take two drops in each eye before bed, and you should get better in a week.", "Claro. Pingue duas gotas em cada olho antes de dormir, e você deve melhorar em uma semana."]], ["/ð/ em with e this", "Ponha a ponta da língua entre os dentes e vibre a voz. Não troque por d nem por z: with não é uid.", ["with", "this"]], ["Take one spoon ___ a day, in the morning and at night.", "twice", "two", "Tome uma colher duas vezes ao dia, de manhã e à noite.", "Para dizer duas vezes, usamos twice; two sozinho não funciona nessa posição."], [["Try this cough syrup. Take one spoon twice a day, in the morning and at night.", "Experimente este xarope. Tome uma colher duas vezes ao dia, de manhã e à noite."], ["No, please take it with food. It's hard on your stomach.", "Não, por favor, tome junto com comida. Pesa no estômago."]], [{"t": "c", "q": "Please take it ___ food.", "o": ["with", "in", "at"], "pt": "Por favor, tome junto com comida.", "why": "Take it with food quer dizer tomar junto com a refeição."}, {"t": "l", "say": "Take two drops in each eye before bed.", "o": ["Take two drops in each eye before bed.", "Take two drops in each ear before bed.", "Take two drops in each eye after breakfast."], "why": "A frase fala de colírio nos olhos antes de dormir."}, {"t": "b", "pt": "Tome o xarope duas vezes por dia.", "w": ["Take", "the", "cough", "syrup", "twice", "a", "day"]}, {"t": "b", "pt": "Não tome com o estômago vazio.", "w": ["Don't", "take", "it", "on", "an", "empty", "stomach"]}]];
