englishA2Plans[235]={"title": "Menos besteira, mais comida de verdade", "file": "", "grammar": "Dieta: much, many, a little, a few com comida", "goal": "Fale da sua dieta com much, many, a little e a few.", "words": [["lose weight", "perder peso"], ["junk food", "besteira, comida industrializada"], ["portion", "porção"], ["cut back on", "reduzir o consumo de"], ["crave", "ter muita vontade de comer"], ["nutritious", "nutritivo"], ["skip a meal", "pular uma refeição"], ["overweight", "acima do peso"], ["hunger", "fome"]]};
englishA2Content[235]=[[["Noah wants to lose weight, so he is trying to cut back on junk food.", "Noah quer perder peso, então está tentando reduzir a besteira."], ["He used to crave sugary snacks, and he ate many cookies every day.", "Ele tinha muita vontade de comer doces e comia muitos biscoitos por dia."], ["Now he eats only a few cookies a week.", "Agora ele come só alguns biscoitos por semana."], ["He doesn't drink much soda, just a little at lunch.", "Ele não bebe muito refrigerante, só um pouco no almoço."], ["His portions are smaller, and his lunch is nutritious.", "As porções dele são menores, e o almoço é nutritivo."], ["Dinner is a light meal with a little rice and many vegetables.", "O jantar é uma refeição leve, com um pouco de arroz e muitos legumes."]], [["Ms. Cruz, I want to lose weight. I'm a little overweight, and I crave junk food all the time.", "Dra. Cruz, quero perder peso. Estou um pouco acima do peso e vivo com vontade de comer besteira."], ["What do you eat in a day? Tell me everything.", "O que você come num dia? Me conte tudo."], ["I skip a meal when I'm busy, and then hunger hits at night, and I eat a big portion.", "Pulo refeições quando estou ocupado, a fome bate à noite e como uma porção grande."], ["That's a bad habit. Don't skip lunch, and try a light meal at dinner.", "É um mau hábito. Não pule o almoço e tente uma refeição leve no jantar."], ["Okay. Should I stop sugary drinks, too?", "Certo. Devo parar com as bebidas açucaradas também?"], ["Cut back on them. How much soda do you drink now?", "Reduza. Quanto refrigerante você bebe agora?"], ["Not much. Just a little, about one can a day.", "Não muito. Só um pouco, uma lata por dia."], ["Fine. Eat only a few cookies a week, and choose something nutritious, like fruit.", "Ótimo. Coma só alguns biscoitos por semana e escolha algo nutritivo, como fruta."], ["Really? Okay, I'll buy fruit instead of candy this week.", "Sério? Tá bom, vou comprar fruta em vez de doce esta semana."], ["Good. See you in a month, Noah, and we'll check your weight.", "Bom. Até daqui a um mês, Noah, e vamos ver seu peso."]], ["/ʌ/ em much e lunch", "Abra pouco a boca e deixe a língua relaxada, num som curto entre o a e o é do português. Não diga muche nem lonche com o fechado.", ["much", "lunch"]], ["How ___ cookies do you eat a week?", "many", "much", "Quantos biscoitos você come por semana?", "Cookies é contável, então usamos How many; much é para incontáveis."], [["Now he eats only a few cookies a week.", "Agora ele come só alguns biscoitos por semana."], ["He doesn't drink much soda, just a little at lunch.", "Ele não bebe muito refrigerante, só um pouco no almoço."]], [{"t": "c", "q": "I drink ___ water, only one glass.", "o": ["a little", "a few", "many"], "pt": "Eu bebo um pouco de água, só um copo.", "why": "Water é incontável, então usamos a little; a few é para contáveis."}, {"t": "l", "say": "I eat a few cookies a week.", "o": ["I eat a few cookies a week.", "I ate a few cookies a week.", "I eat a few cookies a day."], "why": "A frase está no presente e diz que são poucos biscoitos por semana."}, {"t": "b", "pt": "Quantos biscoitos você come por semana?", "w": ["How", "many", "cookies", "do", "you", "eat", "a", "week"]}, {"t": "b", "pt": "Eu não bebo muita água.", "w": ["I", "don't", "drink", "much", "water"]}]];
