englishA2Plans[236]={"title": "Noites sem sono antes do trabalho novo", "file": "", "grammar": "Dormir bem: used to, because e so", "goal": "Fale do sono e dos hábitos de antes com used to, because e so.", "words": [["fall asleep", "pegar no sono"], ["toss and turn", "rolar na cama sem dormir"], ["night owl", "pessoa noturna"], ["sleep in", "dormir até tarde"], ["alarm clock", "despertador"], ["worn out", "exausto"], ["wind down", "desacelerar, relaxar"], ["doze off", "cochilar"], ["deep sleep", "sono profundo"], ["wake up", "acordar"]]};
englishA2Content[236]=[[["Priya used to be a night owl, but now she has an early job.", "Priya era uma pessoa noturna, mas agora tem um emprego cedo."], ["She used to sleep in on weekends, so mornings are hard now.", "Ela costumava dormir até tarde nos fins de semana, então as manhãs são difíceis agora."], ["She's worn out because her alarm clock rings at five.", "Ela está exausta porque o despertador toca às cinco."], ["At night she can't fall asleep, so she starts to toss and turn.", "À noite ela não consegue pegar no sono, então começa a rolar na cama."], ["Now she puts her phone away at nine to wind down.", "Agora ela guarda o celular às nove para relaxar."], ["Last night she began to doze off at ten, and she finally had a deep sleep.", "Ontem à noite ela começou a cochilar às dez e finalmente teve um sono profundo."]], [["You look worn out and tired, Priya. Did you sleep badly?", "Você parece exausta e cansada, Priya. Dormiu mal?"], ["Yes. I couldn't fall asleep because I'm nervous about my new job.", "Sim. Não consegui pegar no sono porque estou nervosa com o emprego novo."], ["You used to fall asleep in five minutes. Do you toss and turn now?", "Você pegava no sono em cinco minutos. Agora rola na cama?"], ["All night, so I can't wake up when my alarm clock rings.", "A noite toda, então não consigo acordar quando o despertador toca."], ["Well, you used to be a night owl, and now you start at seven.", "Bom, você era uma pessoa noturna e agora começa às sete."], ["I know. On weekends I used to sleep in until noon.", "Eu sei. Nos fins de semana eu dormia até o meio-dia."], ["Try this: put your phone away at nine to wind down, and read a book.", "Tente isto: guarde o celular às nove para relaxar e leia um livro."], ["Okay. Maybe I'll doze off faster.", "Tá bom. Talvez eu pegue no sono mais rápido."], ["I hope you get a deep sleep tonight. Call me tomorrow, okay?", "Espero que você tenha um sono profundo hoje. Me ligue amanhã, certo?"], ["Deal. I'll tell you how I slept.", "Combinado. Eu conto como dormi."]], ["/aɪ/ em night e tired", "Comece com o a aberto e deslize para o i, num único movimento. Em night, o gh é mudo: não diga nigit; em tired, pense em taiâd.", ["night", "tired"]], ["Priya ___ sleep in on weekends.", "used to", "use to", "Priya costumava dormir até tarde nos fins de semana.", "Para hábitos do passado, usamos used to com d: used to + verbo."], [["Priya used to be a night owl, but now she has an early job.", "Priya era uma pessoa noturna, mas agora tem um emprego cedo."], ["She used to sleep in on weekends, so mornings are hard now.", "Ela costumava dormir até tarde nos fins de semana, então as manhãs são difíceis agora."]], [{"t": "c", "q": "I went to bed early ___ I was worn out.", "o": ["because", "but", "or"], "pt": "Fui dormir cedo porque eu estava exausto.", "why": "Because dá a razão: a causa de ir dormir cedo é estar exausto."}, {"t": "l", "say": "I used to fall asleep in five minutes.", "o": ["I used to fall asleep in five minutes.", "I used to fall asleep in fifteen minutes.", "I used to wake up in five minutes."], "why": "A frase diz que antes você pegava no sono em cinco minutos."}, {"t": "b", "pt": "Eu costumava dormir até tarde aos sábados.", "w": ["I", "used", "to", "sleep", "in", "on", "Saturdays"]}, {"t": "b", "pt": "Estou cansada, então vou dormir cedo.", "w": ["I'm", "tired", "so", "I'm", "going", "to", "bed", "early"]}]];
