englishA2Plans[237]={"title": "Uma pausa na segunda-feira caótica", "file": "", "grammar": "Estresse e relaxamento: conselhos com you could / why not", "goal": "Dê ideias para relaxar com You could… e Why not…?", "words": [["stressed out", "estressado"], ["overwhelmed", "sobrecarregado"], ["take a break", "fazer uma pausa"], ["take a deep breath", "respirar fundo"], ["calm down", "se acalmar"], ["unwind", "relaxar"], ["soothing", "calmante"], ["inhale", "inspirar"], ["let go", "deixar para lá"], ["tension", "tensão"]]};
englishA2Content[237]=[[["Sam had a terrible Monday, and he felt overwhelmed.", "Sam teve uma segunda-feira terrível e se sentiu sobrecarregado."], ["His boss needed a report by five, and Sam was stressed out.", "O chefe precisava de um relatório até as cinco, e Sam estava estressado."], ["His coworker Rosa said, \"You could take a break and calm down.\"", "A colega Rosa disse: \"Você poderia fazer uma pausa e se acalmar.\""], ["\"Why not take a deep breath? Inhale slowly, then exhale for four seconds.\"", "\"Por que não respirar fundo? Inspire devagar, depois expire por quatro segundos.\""], ["\"You could listen to soothing music, too,\" she said.", "\"Você poderia ouvir música calmante também\", ela disse."], ["Sam tried both, began to let go of the stress, and was able to unwind.", "Sam tentou os dois, começou a deixar o estresse para lá e conseguiu relaxar."]], [["Sam, you look stressed out. Your shoulders are full of tension.", "Sam, você parece estressado. Seus ombros estão cheios de tensão."], ["My boss needs this report by five, and I feel overwhelmed.", "Meu chefe quer este relatório até as cinco e estou sobrecarregado."], ["You could take a break for ten minutes. Why not walk outside?", "Você poderia fazer uma pausa de dez minutos. Por que não caminhar lá fora?"], ["I can't. I haven't even finished the first page.", "Não posso. Nem terminei a primeira página."], ["Then why not take a deep breath first? Inhale slowly, and exhale slowly.", "Então por que não respirar fundo primeiro? Inspire devagar e expire devagar."], ["Does that really work? I've never tried it.", "Isso funciona mesmo? Nunca tentei."], ["It does. It helps me calm down and let go of the stress.", "Funciona. Me ajuda a me acalmar e a deixar o estresse para lá."], ["Okay. Maybe I could put on some soothing music, too.", "Tá bom. Talvez eu possa colocar uma música calmante também."], ["Good idea. That will help you unwind. Call me when you finish.", "Boa ideia. Isso vai ajudar você a relaxar. Me ligue quando terminar."], ["Thanks, Rosa. Let's meet at five, and I'll show you the report.", "Obrigado, Rosa. Vamos nos encontrar às cinco, e eu mostro o relatório."]], ["/iː/ em deep e meet", "Estique os lábios como num sorriso e alongue o i. Deep não é dip, e meet não é mit: o i longo muda a palavra.", ["deep", "meet"]], ["Why not ___ a break?", "take", "to take", "Por que não fazer uma pausa?", "Depois de Why not usamos o verbo no infinitivo sem to."], [["His coworker Rosa said, \"You could take a break and calm down.\"", "A colega Rosa disse: \"Você poderia fazer uma pausa e se acalmar.\""], ["You could take a break for ten minutes. Why not walk outside?", "Você poderia fazer uma pausa de dez minutos. Por que não caminhar lá fora?"]], [{"t": "c", "q": "You ___ take a break for ten minutes.", "o": ["could", "could to", "should to"], "pt": "Você poderia fazer uma pausa de dez minutos.", "why": "Depois de could usamos o verbo sem to."}, {"t": "l", "say": "Why not take a deep breath?", "o": ["Why not take a deep breath?", "Why not take a deep bath?", "Why not take a long breath?"], "why": "A sugestão é respirar fundo (deep breath)."}, {"t": "b", "pt": "Por que não fazer uma pausa?", "w": ["Why", "not", "take", "a", "break"]}, {"t": "b", "pt": "Você poderia ouvir música calmante.", "w": ["You", "could", "listen", "to", "soothing", "music"]}]];
