englishA2Plans[238]={"title": "Corte na mão no piquenique", "file": "", "grammar": "Primeiros socorros: imperativos em sequência", "goal": "Dê instruções em ordem com First…, Then… e imperativos.", "words": [["first aid", "primeiros socorros"], ["bleeding", "sangrando"], ["wound", "ferimento"], ["apply pressure", "pressionar o local"], ["clean the cut", "limpar o corte"], ["antiseptic", "antisséptico"], ["band-aid", "curativo adesivo"], ["faint", "desmaiar"], ["painful", "doloroso"]]};
englishA2Content[238]=[[["At the picnic, Omar fell and cut his hand on a rock.", "No piquenique, Omar caiu e cortou a mão numa pedra."], ["The wound was bleeding a lot, and he felt like he could faint.", "O ferimento sangrava muito, e ele sentiu que podia desmaiar."], ["Lia knew first aid, so she stayed calm and gave him orders.", "Lia sabia primeiros socorros, então manteve a calma e deu instruções."], ["\"First, apply pressure with this towel. Then clean the cut and use the antiseptic.\"", "\"Primeiro, pressione com esta toalha. Depois limpe o corte e use o antisséptico.\""], ["\"Last, put on a band-aid, and don't touch it. It's painful now, but it will be okay.\"", "\"Por fim, ponha um curativo e não mexa. Dói agora, mas vai ficar bem.\""], ["After ten minutes the bleeding stopped, and Omar felt better.", "Depois de dez minutos o sangramento parou, e Omar se sentiu melhor."]], [["Omar, what happened? Your hand is bleeding a lot.", "Omar, o que houve? Sua mão está sangrando muito."], ["I fell on a rock. It's a deep wound, and it's painful. I think I'm going to faint.", "Caí numa pedra. É um ferimento fundo e dói muito. Acho que vou desmaiar."], ["I know first aid, so you'll be okay.", "Eu sei primeiros socorros, então você vai ficar bem."], ["Okay. Should I wash it first, or press on it?", "Tá bom. Devo lavar primeiro ou pressionar?"], ["First, apply pressure with this towel. Don't take it off.", "Primeiro, pressione com esta toalha. Não tire."], ["Like this? It hurts when I press.", "Assim? Dói quando eu aperto."], ["Yes, keep pressing. Then clean the cut with water and use the antiseptic.", "Isso, continue. Depois limpe o corte com água e use o antisséptico."], ["Ouch! That stings! Do we have a band-aid?", "Ai! Arde! Temos um curativo?"], ["Yes. Last, put on a band-aid, and wait ten minutes.", "Temos. Por fim, ponha um curativo e espere dez minutos."], ["Thanks, Lia. I feel better already.", "Obrigado, Lia. Já me sinto melhor."]], ["/eɪ/ em faint e painful", "Comece num e aberto e deslize para o i. Em faint, o som é de duas vogais seguidas, não fent.", ["faint", "painful"]], ["First, wash the wound. ___, apply pressure.", "Then", "Than", "Primeiro, lave o ferimento. Depois, pressione.", "Then marca o passo seguinte da sequência; than é só para comparar."], [["\"First, apply pressure with this towel. Then clean the cut and use the antiseptic.\"", "\"Primeiro, pressione com esta toalha. Depois limpe o corte e use o antisséptico.\""], ["First, apply pressure with this towel. Don't take it off.", "Primeiro, pressione com esta toalha. Não tire."]], [{"t": "c", "q": "Sit down and ___ look at the wound.", "o": ["don't", "doesn't", "not"], "pt": "Sente-se e não olhe para o ferimento.", "why": "O imperativo negativo usa don't + verbo."}, {"t": "l", "say": "First clean the cut, then put on a band-aid.", "o": ["First clean the cut, then put on a band-aid.", "First clean the cut, then take off the band-aid.", "First put on a band-aid, then clean the cut."], "why": "A ordem é limpar o corte e só depois pôr o curativo."}, {"t": "b", "pt": "Primeiro, pressione o corte com a toalha.", "w": ["First", "apply", "pressure", "with", "the", "towel"]}, {"t": "b", "pt": "Depois limpe o corte com antisséptico.", "w": ["Then", "clean", "the", "cut", "with", "antiseptic"]}]];
