englishA2Plans[239]={"title": "Preparando a corrida de domingo", "file": "", "grammar": "Revisão: uma semana de corrida e descanso", "goal": "Fale de treino, descanso e metas usando a revisão do bloco.", "words": [["rest day", "dia de descanso"], ["stay hydrated", "se manter hidratado"], ["keep an eye on", "ficar de olho em"], ["injure", "machucar"], ["recovery", "recuperação"], ["take it easy", "pegar leve"], ["personal best", "recorde pessoal"], ["finish line", "linha de chegada"], ["give up", "desistir"]]};
englishA2Content[239]=[[["Kenji hasn't run for four days because he had a sore throat and a runny nose.", "Kenji não corre há quatro dias porque teve dor de garganta e nariz escorrendo."], ["He took cough syrup twice a day, and he has felt better since Wednesday.", "Ele tomou xarope duas vezes ao dia e se sente melhor desde quarta."], ["He used to be a night owl, so early training is hard, and he's worn out.", "Ele era uma pessoa noturna, então treinar cedo é difícil, e ele está exausto."], ["His friend Lia says, \"You should take it easy on your rest day, and you shouldn't skip a meal.\"", "A amiga Lia diz: \"Você deve pegar leve no dia de descanso e não deve pular uma refeição.\""], ["She also says, \"Why not stay hydrated? Drink many glasses of water, but only a little coffee.\"", "Ela também diz: \"Por que não ficar hidratado? Beba muitos copos de água, mas só um pouco de café.\""], ["Sunday's race will be the hardest of his life, and he won't give up before the finish line.", "A corrida de domingo será a mais difícil da vida dele, e ele não vai desistir antes da linha de chegada."]], [["Kenji, how long have you had that cough?", "Kenji, há quanto tempo você está com essa tosse?"], ["For about a week, but it's better since I took the syrup twice a day.", "Há cerca de uma semana, mas melhorou desde que tomei o xarope duas vezes ao dia."], ["Good. You should keep an eye on your knee. You don't want to injure it again.", "Bom. Você deve ficar de olho no joelho. Não quer se machucar de novo."], ["I know. My recovery is slower than last year because I used to run every day.", "Eu sei. Minha recuperação é mais lenta que no ano passado, porque eu corria todo dia."], ["Why not take a rest day tomorrow? You could just walk and stay hydrated.", "Por que não fazer um dia de descanso amanhã? Você poderia só caminhar e se manter hidratado."], ["Okay. I'll take it easy. How much food should I eat before the race?", "Certo. Vou pegar leve. Quanta comida devo comer antes da corrida?"], ["Just a little rice and a few bananas. Don't skip a meal, though.", "Só um pouco de arroz e algumas bananas. Mas não pule refeição."], ["Got it. Will you be at the finish line on Sunday?", "Entendi. Você vai estar na linha de chegada no domingo?"], ["Of course. First, warm up. Then run slowly, and don't give up.", "Claro. Primeiro, aqueça. Depois corra devagar e não desista."], ["Deal. I want a personal best, so I'll do exactly that.", "Combinado. Quero um recorde pessoal, então farei exatamente isso."]], ["/f/ em finish e food", "Encoste os dentes de cima no lábio de baixo e sopre. Não troque por p nem por h.", ["finish", "food"]], ["Kenji hasn't run ___ Monday.", "since", "for", "Kenji não corre desde segunda.", "Monday é um ponto no tempo, então usamos since; for é para períodos como four days."], [["He used to be a night owl, so early training is hard, and he's worn out.", "Ele era uma pessoa noturna, então treinar cedo é difícil, e ele está exausto."], ["Kenji hasn't run for four days because he had a sore throat and a runny nose.", "Kenji não corre há quatro dias porque teve dor de garganta e nariz escorrendo."]], [{"t": "c", "q": "I've had this cough ___ a week.", "o": ["for", "since", "ago"], "pt": "Estou com esta tosse há uma semana.", "why": "A week é um período de tempo, então usamos for."}, {"t": "l", "say": "Don't give up before the finish line.", "o": ["Don't give up before the finish line.", "Don't give up after the finish line.", "Don't get up before the finish line."], "why": "A frase manda não desistir antes da linha de chegada."}, {"t": "b", "pt": "Eu costumava correr todo dia.", "w": ["I", "used", "to", "run", "every", "day"]}, {"t": "b", "pt": "Primeiro aqueça, depois corra devagar.", "w": ["First", "warm", "up", "then", "run", "slowly"]}]];
