englishA2MiniStories[239]=["A semana da corrida do Kenji", "Kenji wanted to run his first 10K, but on Monday he woke up with a sore throat.~Kenji queria correr seus primeiros 10 km, mas na segunda acordou com dor de garganta.|He took cough syrup twice a day, with food, and he got better in three days.~Ele tomou xarope duas vezes ao dia, com comida, e melhorou em três dias.|His doctor said, \"You should get enough sleep and cut down on sugary drinks.\"~O médico disse: \"Você deve dormir o suficiente e reduzir as bebidas açucaradas.\"|So he went to bed earlier, because he used to be a night owl.~Então ele foi dormir mais cedo, porque costumava ser uma pessoa noturna.|On Wednesday he worked out with his team, and he did not forget to warm up.~Na quarta ele treinou com o time e não esqueceu de se aquecer.|On Friday he felt overwhelmed, so he took a deep breath and went for a walk.~Na sexta ele se sentiu sobrecarregado, então respirou fundo e foi caminhar.|On Saturday Lia cut her hand, and Kenji used first aid to stop the bleeding.~No sábado Lia cortou a mão, e Kenji usou primeiros socorros para parar o sangramento.|On Sunday it was hot, so he drank a lot of water and stayed hydrated.~No domingo estava quente, então ele bebeu muita água e se manteve hidratado.|The race was hard, and he was out of breath, but he didn't give up.~A corrida foi difícil, e ele ficou sem fôlego, mas não desistiu.|He crossed the finish line with a personal best, and Lia was there with a big sign.~Ele cruzou a linha de chegada com um recorde pessoal, e Lia estava lá com um cartaz enorme."];
englishA2Plans[240]={"title": "Tudo quebrou no apartamento da Ana", "file": "", "grammar": "Descrever problemas: it doesn’t work / it’s broken", "goal": "Diga o que está quebrado em casa usando doesn’t work e it’s broken.", "words": [["light bulb", "lâmpada"], ["burn out", "queimar (lâmpada)"], ["stop working", "parar de funcionar"], ["water heater", "aquecedor de água"], ["dripping", "pingando"], ["kitchen sink", "pia da cozinha"], ["fuse box", "caixa de fusíveis"], ["circuit breaker", "disjuntor"], ["wall socket", "tomada de parede"], ["make a noise", "fazer barulho"]]};
englishA2Content[240]=[[["Ana’s apartment has three problems this week.", "O apartamento da Ana tem três problemas esta semana."], ["The light bulb in the hall doesn’t work, and the water heater doesn’t make hot water.", "A lâmpada do corredor não funciona, e o aquecedor de água não esquenta a água."], ["The kitchen sink is dripping all night, and the old fridge likes to make a noise at two a.m.", "A pia da cozinha pinga a noite toda, e a geladeira velha gosta de fazer barulho às duas da manhã."], ["The wall socket by the window is dead, so her phone charger is useless there.", "A tomada de parede perto da janela está morta, então o carregador do celular é inútil ali."], ["She opens the fuse box and checks the circuit breaker, but everything looks fine.", "Ela abre a caixa de fusíveis e confere o disjuntor, mas tudo parece normal."], ["Now she’s afraid the oven will stop working too, so she’s calling the landlord.", "Agora ela tem medo de que o forno também pare de funcionar, então vai ligar para o proprietário."]], [["Ana, why is it so dark in the hall? Did the light bulb burn out?", "Ana, por que está tão escuro no corredor? A lâmpada queimou?"], ["Yes, it’s broken. The one in the kitchen looks weak, too.", "Sim, está queimada. A da cozinha também está fraquinha."], ["Wow. What else is wrong in this place?", "Nossa. O que mais está errado neste lugar?"], ["The water heater doesn’t work. I took a cold shower this morning, and I almost cried.", "O aquecedor de água não funciona. Tomei banho frio hoje de manhã e quase chorei."], ["Oh no! Did you check the fuse box?", "Ai, não! Você olhou a caixa de fusíveis?"], ["Yes, I did. I turned the circuit breaker off and on, but nothing happened.", "Olhei sim. Desliguei e liguei o disjuntor, mas nada aconteceu."], ["And the sink? I can hear it dripping from here.", "E a pia? Dá para ouvir pingando daqui."], ["Yes, the kitchen sink. And the wall socket by my bed doesn’t work either.", "É, a pia da cozinha. E a tomada de parede perto da minha cama também não funciona."], ["OK. Tomorrow we’re calling the landlord together, right?", "Certo. Amanhã a gente liga para o proprietário junto, né?"], ["Yes, first thing in the morning. I’m tired of cold showers.", "Sim, logo de manhã. Estou cansada de banho frio."]], ["/w/ em water e wall", "Arredonde os lábios como para dizer 'u' antes de começar: 'uóter', 'uól'. Não troque o w por v.", ["water", "wall"]], ["The water heater ___ work.", "doesn’t", "don’t", "O aquecedor de água não funciona.", "Com he/she/it (the water heater), a negativa do presente é doesn’t."], [["The light bulb in the hall doesn’t work, and the water heater doesn’t make hot water.", "A lâmpada do corredor não funciona, e o aquecedor de água não esquenta a água."], ["The water heater doesn’t work. I took a cold shower this morning, and I almost cried.", "O aquecedor de água não funciona. Tomei banho frio hoje de manhã e quase chorei."]], [{"t": "c", "q": "The light bulb is ___, so the room is dark.", "o": ["broken", "break", "breaking"], "pt": "A lâmpada está quebrada, então o quarto está escuro.", "why": "Depois de is usamos o adjetivo broken (quebrado)."}, {"t": "l", "say": "The wall socket doesn’t work.", "o": ["The wall socket doesn’t work.", "The water socket doesn’t work.", "The wall socket does work."], "why": "Você ouviu wall socket e a negativa doesn’t work."}, {"t": "b", "pt": "A pia da cozinha está pingando.", "w": ["The", "kitchen", "sink", "is", "dripping"]}, {"t": "b", "pt": "O aquecedor de água não funciona.", "w": ["The", "water", "heater", "doesn’t", "work"]}]];
