englishA2Plans[241]={"title": "Ligando para o zelador do prédio", "file": "", "grammar": "Pedir um conserto: Could you come and look at…?", "goal": "Peça a alguém para vir ver um problema usando Could you come and look at…?", "words": [["look at", "dar uma olhada em"], ["work order", "ordem de serviço"], ["maintenance man", "zelador, técnico de manutenção"], ["come over", "passar aqui, vir até aqui"], ["as soon as possible", "o mais rápido possível"], ["emergency repair", "reparo de emergência"], ["boiler", "caldeira, aquecedor"], ["front door", "porta da frente"], ["power outage", "queda de energia"], ["jammed", "emperrada"]]};
englishA2Content[241]=[[["Priya lives on the fourth floor, and her boiler is making a strange sound.", "Priya mora no quarto andar, e a caldeira dela está fazendo um barulho estranho."], ["She calls the maintenance man and asks, “Could you come and look at it today?”", "Ela liga para o zelador e pergunta: “O senhor poderia vir dar uma olhada hoje?”"], ["He says he can come over after lunch if she fills out a work order online.", "Ele diz que pode passar lá depois do almoço se ela preencher um pedido de serviço online."], ["Priya writes, “Please come as soon as possible,” because the water is cold.", "Priya escreve: “Venha o mais rápido possível, por favor”, porque a água está fria."], ["At three o’clock, Mr. Cole arrives and says it’s an emergency repair after the power outage.", "Às três horas, o Sr. Cole chega e diz que é um conserto de emergência depois da queda de energia."], ["Priya asks, “Could you come and look at the front door too? The lock is jammed.”", "Priya pergunta: “O senhor poderia dar uma olhada na porta da frente também? A fechadura está emperrada.”"]], [["Hello, Mr. Cole? This is Priya in apartment 4B. Could you come and look at my boiler?", "Alô, Sr. Cole? Aqui é a Priya do apartamento 4B. O senhor poderia vir dar uma olhada no meu aquecedor?"], ["Sure. What’s the problem, exactly?", "Claro. Qual é o problema, exatamente?"], ["It makes a loud noise, and the water is cold. After the power outage last night, nothing is the same.", "Faz um barulho alto, e a água está fria. Depois da queda de energia de ontem à noite, nada é igual."], ["I see. That sounds like an emergency repair. Did you send a work order?", "Entendi. Parece um reparo de emergência. Você mandou uma ordem de serviço?"], ["Not yet. Could I send it now, or should I call the office?", "Ainda não. Posso mandar agora ou devo ligar para o escritório?"], ["Send it online, and I’ll come over as soon as possible. Could you wait for me at the front door? The buzzer doesn’t work.", "Mande on-line, e eu passo aí o mais rápido possível. Poderia me esperar na porta da frente? A campainha não funciona."], ["Of course. Could you come before five? I have to leave for work at six.", "Claro. O senhor poderia vir antes das cinco? Preciso sair para o trabalho às seis."], ["No problem. I’ll be there at four-thirty.", "Sem problema. Estarei aí às quatro e meia."]], ["/ʊ/ em could e look", "O u de could e look é curto e relaxado, com os lábios só um pouco arredondados: 'cud', 'luk'. Não estique como em 'cool' nem diga 'cúlde'; o l de could é mudo.", ["could", "look"]], ["___ you come and look at the heater?", "Could", "Do", "Você poderia vir dar uma olhada no aquecedor?", "Para pedir com educação usamos Could you + verbo; Do you come… muda o sentido."], [["She calls the maintenance man and asks, “Could you come and look at it today?”", "Ela liga para o zelador e pergunta: “O senhor poderia vir dar uma olhada hoje?”"], ["Hello, Mr. Cole? This is Priya in apartment 4B. Could you come and look at my boiler?", "Alô, Sr. Cole? Aqui é a Priya do apartamento 4B. O senhor poderia vir dar uma olhada no meu aquecedor?"]], [{"t": "c", "q": "Could you ___ over this afternoon?", "o": ["come", "to come", "coming"], "pt": "Você poderia passar aqui esta tarde?", "why": "Depois de Could you usamos o verbo simples: come."}, {"t": "l", "say": "Could you come and look at it today?", "o": ["Could you come and look at it today?", "Could you come and look at it Monday?", "Could you come and look at it tonight?"], "why": "A palavra final da frase é today."}, {"t": "b", "pt": "Você poderia vir dar uma olhada?", "w": ["Could", "you", "come", "and", "look", "at", "it"]}, {"t": "b", "pt": "Eu passo aí o mais rápido possível.", "w": ["I’ll", "come", "over", "as", "soon", "as", "possible"]}]];
