englishA2Plans[242]={"title": "Usando a máquina de lavar do primo", "file": "", "grammar": "Instruções de uso: press, turn, plug in", "goal": "Explique como usar um aparelho com press, turn on / turn off e plug in.", "words": [["plug in", "ligar na tomada"], ["turn on", "ligar"], ["turn off", "desligar"], ["press the button", "apertar o botão"], ["remote control", "controle remoto"], ["washing machine", "máquina de lavar"], ["microwave oven", "forno de micro-ondas"], ["set the timer", "ajustar o timer"], ["hold down", "manter pressionado"], ["extension cord", "extensão elétrica"]]};
englishA2Content[242]=[[["Lia is staying at her cousin Omar’s apartment this weekend.", "A Lia está passando o fim de semana no apartamento do primo Omar."], ["Omar leaves a note: “Plug in the extension cord first, then turn on the washing machine.”", "O Omar deixa um bilhete: “Primeiro ligue a extensão na tomada, depois ligue a máquina de lavar.”"], ["The note also says: “Press the button twice and set the timer to forty minutes.”", "O bilhete também diz: “Aperte o botão duas vezes e ajuste o timer para quarenta minutos.”"], ["For the microwave oven, hold down the start key for two seconds.", "Para o micro-ondas, mantenha a tecla de início pressionada por dois segundos."], ["The TV remote control is on the sofa, and Lia must turn off the lights at night.", "O controle remoto da TV está no sofá, e a Lia precisa apagar as luzes à noite."], ["When she finishes, she writes, “Everything works, and the clothes are clean!”", "Quando termina, ela escreve: “Tudo funciona, e as roupas estão limpas!”"]], [["Hi, Lia. Did you find my note about the washing machine?", "Oi, Lia. Você achou meu bilhete sobre a máquina de lavar?"], ["Yes, but I’m confused. Do I plug in the cord first, or turn on the machine?", "Achei, mas estou confusa. Ligo o cabo na tomada primeiro ou ligo a máquina?"], ["Plug in the extension cord first. Then press the button with the little sun on it.", "Ligue a extensão primeiro. Depois aperte o botão com o solzinho."], ["OK, it’s on! Now what? There are twelve programs here.", "Pronto, ligou! E agora? Tem doze programas aqui."], ["Choose the third one, and set the timer to forty minutes.", "Escolha o terceiro e ajuste o timer para quarenta minutos."], ["Done. And how do I use your microwave oven? I want to heat some soup.", "Pronto. E como uso seu micro-ondas? Quero esquentar uma sopa."], ["Close the door, then hold down the start key for two seconds. Don’t press it quickly.", "Feche a porta e mantenha a tecla de início pressionada por dois segundos. Não aperte rápido."], ["It works! One more thing: where is the TV remote control? I can’t find it.", "Funcionou! Mais uma coisa: onde está o controle remoto da TV? Não consigo achar."], ["It’s always under the sofa pillow. You’ll find it there.", "Está sempre embaixo da almofada do sofá. Você vai achar lá."], ["Found it! Thanks, Omar. I’ll turn off the lights before bed.", "Achei! Obrigada, Omar. Vou apagar as luzes antes de dormir."]], ["/ʌ/ em button e plug", "O u de button e plug é um 'â' curto e relaxado, com a boca quase parada, parecido com o 'a' de 'cama' dito rápido. Não diga 'u' (boot) nem 'o'.", ["button", "plug"]], ["First, ___ in the cord. Then press the button.", "plug", "plugs", "Primeiro, ligue o cabo na tomada. Depois aperte o botão.", "No imperativo usamos o verbo simples, sem -s: plug in."], [["The note also says: “Press the button twice and set the timer to forty minutes.”", "O bilhete também diz: “Aperte o botão duas vezes e ajuste o timer para quarenta minutos.”"], ["Plug in the extension cord first. Then press the button with the little sun on it.", "Ligue a extensão primeiro. Depois aperte o botão com o solzinho."]], [{"t": "c", "q": "Don’t ___ the button too hard.", "o": ["press", "pressing", "pressed"], "pt": "Não aperte o botão com muita força.", "why": "Depois de Don’t usamos o verbo simples: press."}, {"t": "l", "say": "Hold down the start key for two seconds.", "o": ["Hold down the start key for two seconds.", "Hold down the start key for two minutes.", "Hold on the start key for two seconds."], "why": "Você ouviu hold down e two seconds."}, {"t": "b", "pt": "Aperte o botão e ajuste o timer.", "w": ["Press", "the", "button", "and", "set", "the", "timer"]}, {"t": "b", "pt": "Desligue a luz quando sair.", "w": ["Turn", "off", "the", "lights", "when", "you", "leave"]}]];
