englishA2Plans[243]={"title": "Pedindo um favor ao vizinho do lado", "file": "", "grammar": "Combinar com vizinhos: Could you…? / Would you mind…?", "goal": "Peça um favor a um vizinho com Could you…? e Would you mind + -ing?", "words": [["next door", "ao lado, na casa vizinha"], ["keep it down", "fazer menos barulho"], ["loud music", "música alta"], ["turn the music down", "abaixar a música"], ["knock on the door", "bater na porta"], ["quiet hours", "horário de silêncio"], ["water the plants", "regar as plantas"], ["while I’m away", "enquanto estou fora"], ["parking space", "vaga de estacionamento"], ["spare key", "chave reserva"]]};
englishA2Content[243]=[[["Sam lives next door to Elena, and they get along well.", "Sam mora ao lado da Elena, e os dois se dão bem."], ["On Friday night, there is loud music coming from Elena’s party.", "Na sexta à noite, há música alta vindo da festa da Elena."], ["At eleven, Sam decides to knock on the door and ask nicely.", "Às onze, Sam decide bater na porta e pedir com educação."], ["He says, “Would you mind turning the music down? Quiet hours start at ten.”", "Ele diz: “Você se importaria de abaixar a música? O horário de silêncio começa às dez.”"], ["Elena is sorry and agrees to keep it down.", "Elena pede desculpas e concorda em fazer menos barulho."], ["A week later, Sam asks, “Could you water the plants while I’m away?” and gives her his spare key.", "Uma semana depois, Sam pergunta: “Você poderia regar as plantas enquanto eu estiver fora?” e entrega a ela a chave reserva."]], [["Elena, would you mind if I borrowed your parking space tomorrow? My sister is visiting.", "Elena, você se importaria se eu usasse sua vaga amanhã? Minha irmã vem me visitar."], ["Not at all. Just move your car by six, please. I need it for work.", "Imagina. Só tire seu carro até as seis, por favor. Preciso dele para o trabalho."], ["Thanks! Also, please turn the music down tonight after ten. I have an early flight.", "Obrigado! E, por favor, abaixe a música hoje depois das dez. Tenho um voo cedo."], ["Sorry about last Friday! Next time, please knock on the door. I didn’t hear my phone.", "Desculpe pela sexta passada! Da próxima vez, bata na porta, por favor. Eu não ouvi o celular."], ["No problem. Actually, could you water the plants while I’m away? I’ll be in Denver for a week.", "Sem problema. Aliás, você poderia regar as plantas enquanto eu estiver fora? Vou ficar uma semana em Denver."], ["Sure. Would you mind leaving your spare key with me?", "Claro. Você se importaria de deixar sua chave reserva comigo?"], ["I’ll bring it tonight. Thanks so much, Elena!", "Trago hoje à noite. Muito obrigado, Elena!"], ["Anytime. And I promise, no more loud music after quiet hours!", "Quando precisar. E prometo, nada de música alta depois do horário de silêncio!"]], ["/aɪ/ em mind e quiet", "Mind rima com find: o ditongo 'ai' é longo. Em quiet, diga 'cuái-et', com duas sílabas.", ["mind", "quiet"]], ["Would you mind ___ the music down?", "turning", "turn", "Você se importaria de abaixar a música?", "Depois de Would you mind usamos o verbo com -ing: turning."], [["Elena, would you mind if I borrowed your parking space tomorrow? My sister is visiting.", "Elena, você se importaria se eu usasse sua vaga amanhã? Minha irmã vem me visitar."], ["No problem. Actually, could you water the plants while I’m away? I’ll be in Denver for a week.", "Sem problema. Aliás, você poderia regar as plantas enquanto eu estiver fora? Vou ficar uma semana em Denver."]], [{"t": "c", "q": "Could you ___ the plants while I’m away?", "o": ["water", "watering", "to water"], "pt": "Você poderia regar as plantas enquanto estou fora?", "why": "Depois de Could you usamos o verbo simples: water."}, {"t": "l", "say": "Would you mind keeping it down?", "o": ["Would you mind keeping it down?", "Would you mind keeping it up?", "Would you mind turning it up?"], "why": "O pedido é keeping it down, fazer menos barulho."}, {"t": "b", "pt": "Você se importaria de abaixar a música?", "w": ["Would", "you", "mind", "turning", "the", "music", "down"]}, {"t": "b", "pt": "Você poderia regar as plantas?", "w": ["Could", "you", "water", "the", "plants"]}]];
