englishA2ExtraWordExamples[243]={"while I’m away": ["Please water the plants while I’m away.", "Por favor, regue as plantas enquanto eu estiver fora."]};
englishA2Plans[244]={"title": "Mudando os móveis da sala de lugar", "file": "", "grammar": "Posição dos móveis: next to / in front of / behind", "goal": "Diga onde colocar os móveis com next to, in front of, behind e against.", "words": [["move the sofa", "mover o sofá"], ["coffee table", "mesa de centro"], ["push aside", "empurrar para o lado"], ["against the wall", "encostado na parede"], ["rearrange", "reorganizar"], ["power strip", "régua de tomadas"], ["trash can", "lixeira"], ["dining table", "mesa de jantar"], ["TV stand", "rack da TV"], ["bed frame", "estrutura da cama"]]};
englishA2Content[244]=[[["Mia wants to rearrange her small living room this weekend.", "A Mia quer reorganizar a sala pequena dela neste fim de semana."], ["Tom helps her move the sofa against the wall, next to the window.", "O Tom ajuda a mover o sofá, encostado na parede, ao lado da janela."], ["They push aside the coffee table and put it in front of the sofa.", "Eles empurram a mesa de centro para o lado e a colocam na frente do sofá."], ["The TV stand goes in the corner, and the power strip goes behind it.", "O rack da TV vai para o canto, e a régua de tomadas fica atrás dele."], ["They put the trash can next to the dining table, and Mia laughs.", "Eles põem a lixeira ao lado da mesa de jantar, e a Mia ri."], ["Finally, they carry the bed frame to the other room, and the living room looks bigger.", "Por fim, levam a estrutura da cama para o outro quarto, e a sala parece maior."]], [["Tom, can you help me rearrange the living room? Nothing fits here.", "Tom, você pode me ajudar a reorganizar a sala? Nada cabe aqui."], ["Sure. Where do you want the sofa?", "Claro. Onde você quer o sofá?"], ["Put it against the wall, next to the window. Then the light is better.", "Coloque encostado na parede, ao lado da janela. Assim a luz fica melhor."], ["OK. Should I push aside the coffee table first?", "Certo. Devo empurrar a mesa de centro para o lado primeiro?"], ["Yes, please. Then it goes back in front of the sofa.", "Sim, por favor. Depois ela volta para a frente do sofá."], ["Done. And the TV stand? It’s too heavy for one person.", "Pronto. E o rack da TV? É pesado demais para uma pessoa."], ["Leave it in the corner. The power strip goes behind it, so nobody sees the cords.", "Deixe no canto. A régua de tomadas vai atrás, assim ninguém vê os fios."], ["Good idea. Where does the trash can go? Under the sink?", "Boa ideia. Onde vai a lixeira? Embaixo da pia?"], ["No, it’s too small there. Keep it in the kitchen.", "Não, lá é pequeno demais. Deixe na cozinha."], ["Great. I’ll carry the bed frame to the other room, and then we’re done.", "Ótimo. Eu levo a cama para o outro quarto e aí terminamos."]], ["/ð/ em then e other", "Ponha a ponta da língua entre os dentes e faça vibrar com voz, como um 'z' com a língua para fora. Não troque por 'd' (den) nem por 'z'. É diferente do th de month, que é sem voz.", ["then", "other"]], ["Put the coffee table ___ the sofa.", "in front of", "in front", "Ponha a mesa de centro na frente do sofá.", "Em português dizemos “na frente do”; em inglês precisamos de in front of, com of."], [["They push aside the coffee table and put it in front of the sofa.", "Eles empurram a mesa de centro para o lado e a colocam na frente do sofá."], ["Yes, please. Then it goes back in front of the sofa.", "Sim, por favor. Depois ela volta para a frente do sofá."]], [{"t": "c", "q": "The power strip is ___ the TV stand, so nobody sees it.", "o": ["behind", "in behind", "on behind"], "pt": "A régua de tomadas está atrás do rack da TV, então ninguém a vê.", "why": "Behind já significa “atrás de”, sem preposição extra."}, {"t": "l", "say": "Put it next to the window.", "o": ["Put it next to the window.", "Put it in front of the window.", "Put it behind the window."], "why": "Você ouviu next to, que é “ao lado de”."}, {"t": "b", "pt": "Coloque o sofá encostado na parede.", "w": ["Put", "the", "sofa", "against", "the", "wall"]}, {"t": "b", "pt": "A lixeira fica atrás da porta.", "w": ["The", "trash", "can", "goes", "behind", "the", "door"]}]];
englishA2PhotoThemes[244]="map";
englishA2Plans[245]={"title": "Dividindo a faxina com o colega de apartamento", "file": "", "grammar": "Rotina da casa: have to e don’t have to", "goal": "Fale das tarefas da casa com have to / has to e don’t have to.", "words": [["do the laundry", "lavar a roupa"], ["wash the dishes", "lavar a louça"], ["sweep the floor", "varrer o chão"], ["mop the floor", "passar pano no chão"], ["vacuum the carpet", "passar aspirador no tapete"], ["clean the bathroom", "limpar o banheiro"], ["cleaning supplies", "produtos de limpeza"], ["put away", "guardar (no lugar)"], ["dust the shelves", "tirar o pó das prateleiras"], ["take out the trash", "levar o lixo para fora"]]};
englishA2Content[245]=[[["Rosa and Kenji share an apartment, and they have a chore chart on the fridge.", "A Rosa e o Kenji dividem um apartamento e têm uma tabela de tarefas na geladeira."], ["On Mondays, Rosa has to do the laundry and wash the dishes.", "Às segundas, a Rosa tem que lavar a roupa e a louça."], ["Kenji doesn’t have to cook, but he has to sweep the floor and mop the floor.", "O Kenji não precisa cozinhar, mas tem que varrer e passar pano no chão."], ["Every Saturday, someone has to vacuum the carpet and clean the bathroom.", "Todo sábado, alguém tem que passar aspirador no tapete e limpar o banheiro."], ["The cleaning supplies are under the sink, and the laundry basket is in the hall.", "Os produtos de limpeza ficam embaixo da pia, e o cesto de roupa suja fica no corredor."], ["Today Kenji has to dust the shelves and take out the trash, so he starts early.", "Hoje o Kenji tem que tirar o pó das prateleiras e levar o lixo para fora, então começa cedo."]], [["Kenji, do you remember the chart? It’s your week to clean the bathroom.", "Kenji, você lembra da tabela? Esta semana é sua vez de limpar o banheiro."], ["I know. Do I have to clean the shower too, or just the toilet?", "Eu sei. Eu tenho que limpar o chuveiro também ou só o vaso?"], ["You have to do everything. But you don’t have to dust the shelves today.", "Tem que fazer tudo. Mas você não precisa tirar o pó das prateleiras hoje."], ["Great. Where are the cleaning supplies? I can’t find them.", "Ótimo. Onde estão os produtos de limpeza? Não consigo achar."], ["They’re under the sink. The laundry basket is full, so I’ll do the laundry tonight.", "Estão embaixo da pia. O cesto de roupa suja está cheio, então vou lavar a roupa hoje à noite."], ["Thanks. I don’t work until noon tomorrow, so I can wash the dishes and put away the clean clothes.", "Valeu. Só trabalho ao meio-dia amanhã, então posso lavar a louça e guardar as roupas limpas."], ["Really? Then I’ll sweep the floor, and you mop the floor.", "Sério? Então eu varro o chão, e você passa o pano."], ["Deal. We’ll even vacuum the carpet before the guests come.", "Combinado. Vamos até passar aspirador no tapete antes de os convidados chegarem."]], ["/ʃ/ em shelves e dishes", "O sh é como o 'ch' de 'chuva' dito com a boca arredondada, sem o t antes. Em dishes, o final é 'ish-iz'.", ["shelves", "dishes"]], ["Kenji ___ have to cook.", "doesn’t", "don’t", "O Kenji não precisa cozinhar.", "Com he/she/it, a negativa é doesn’t have to."], [["Kenji doesn’t have to cook, but he has to sweep the floor and mop the floor.", "O Kenji não precisa cozinhar, mas tem que varrer e passar pano no chão."], ["You have to do everything. But you don’t have to dust the shelves today.", "Tem que fazer tudo. Mas você não precisa tirar o pó das prateleiras hoje."]], [{"t": "c", "q": "Rosa ___ do the laundry on Mondays.", "o": ["has to", "have to", "having to"], "pt": "A Rosa tem que lavar a roupa às segundas.", "why": "Com Rosa (she) usamos has to."}, {"t": "l", "say": "You don’t have to take out the trash.", "o": ["You don’t have to take out the trash.", "You have to take out the trash.", "You didn’t have to take out the trash."], "why": "Você ouviu don’t have to, que quer dizer “não precisa”."}, {"t": "b", "pt": "Eu tenho que lavar a louça.", "w": ["I", "have", "to", "wash", "the", "dishes"]}, {"t": "b", "pt": "Você não precisa varrer o chão.", "w": ["You", "don’t", "have", "to", "sweep", "the", "floor"]}]];
