englishA2Plans[246]={"title": "Dividindo as contas de casa", "file": "", "grammar": "Contas e serviços: pay, bill, due, included", "goal": "Fale de contas com bill, due, included e pay.", "words": [["electricity bill", "conta de luz"], ["water bill", "conta de água"], ["internet bill", "conta de internet"], ["due date", "data de vencimento"], ["pay online", "pagar pela internet"], ["bank transfer", "transferência bancária"], ["monthly rent", "aluguel mensal"], ["per month", "por mês"], ["included", "incluído"], ["pay the bill", "pagar a conta"]]};
englishA2Content[246]=[[["Noah and Lia split the monthly rent, which is nine hundred dollars.", "O Noah e a Lia dividem o aluguel mensal, que é de novecentos dólares."], ["Water is included in the rent, so they don’t get a water bill.", "A água está incluída no aluguel, então eles não recebem conta de água."], ["The electricity bill is about sixty dollars per month.", "A conta de luz é de cerca de sessenta dólares por mês."], ["The internet bill is due on the fifth, and they put the due date on the fridge.", "A conta de internet vence no dia cinco, e eles colocam a data de vencimento na geladeira."], ["Noah likes to pay online, but Lia prefers a bank transfer.", "O Noah gosta de pagar pela internet, mas a Lia prefere transferência bancária."], ["This month Lia forgets to pay the bill, and the internet stops on the sixth.", "Este mês a Lia esquece de pagar a conta, e a internet para no dia seis."]], [["Lia, the electricity bill came today. It’s seventy-two dollars this month.", "Lia, a conta de luz chegou hoje. São setenta e dois dólares este mês."], ["Seventy-two? That’s a lot! What’s the due date?", "Setenta e dois? É muito! Qual é o vencimento?"], ["The twelfth. I can pay online tonight if you send me your half.", "Dia doze. Posso pagar pela internet hoje à noite se você me mandar sua metade."], ["I’ll make a bank transfer right now. Is the water included in the rent?", "Vou fazer uma transferência agora mesmo. A água está incluída no aluguel?"], ["Yes, it is. But the internet isn’t included, and it’s forty dollars per month.", "Está sim. Mas a internet não está incluída, e custa quarenta dólares por mês."], ["OK. When is that one due? I don’t want to forget again.", "Certo. Quando vence essa? Não quero esquecer de novo."], ["On the fifth. Last time you forgot to pay the bill, and we had no wifi for two days.", "Dia cinco. Da última vez você esqueceu de pagar a conta, e ficamos dois dias sem wifi."], ["I know, I know! This time I’ll put a reminder on my phone. Promise.", "Eu sei, eu sei! Desta vez vou colocar um lembrete no celular. Prometo."]], ["/θ/ em month e monthly", "Ponha a ponta da língua entre os dentes e sopre, sem virar o som em 's' ou 'f'. Month termina com th: 'mânth'.", ["month", "monthly"]], ["Water is ___ in the rent.", "included", "include", "A água está incluída no aluguel.", "Depois de is usamos o particípio included, que significa “incluído”."], [["Water is included in the rent, so they don’t get a water bill.", "A água está incluída no aluguel, então eles não recebem conta de água."], ["Yes, it is. But the internet isn’t included, and it’s forty dollars per month.", "Está sim. Mas a internet não está incluída, e custa quarenta dólares por mês."]], [{"t": "c", "q": "When is the internet bill ___?", "o": ["due", "do", "dues"], "pt": "Quando vence a conta de internet?", "why": "Be due é “vencer, estar com vencimento”."}, {"t": "l", "say": "I will pay the bill online tonight.", "o": ["I will pay the bill online tonight.", "I will pay the bill online tomorrow.", "I will pay the bell online tonight."], "why": "Você ouviu tonight e bill."}, {"t": "b", "pt": "A conta de luz vence no dia doze.", "w": ["The", "electricity", "bill", "is", "due", "on", "the", "twelfth"]}, {"t": "b", "pt": "O aluguel mensal inclui a água.", "w": ["The", "monthly", "rent", "includes", "the", "water"]}]];
englishA2PhotoThemes[246]="map";
englishA2Plans[247]={"title": "Regras do prédio para o novo morador", "file": "", "grammar": "Regras de convivência: must / mustn’t", "goal": "Fale de regras do prédio com must e mustn’t.", "words": [["house rules", "regras da casa"], ["no smoking", "proibido fumar"], ["no pets", "animais não permitidos"], ["recycling bin", "lixeira de reciclagem"], ["garbage day", "dia da coleta de lixo"], ["common area", "área comum"], ["fire exit", "saída de emergência"], ["lock the door", "trancar a porta"], ["fire alarm", "alarme de incêndio"], ["move out", "mudar-se, sair do imóvel"]]};
englishA2Content[247]=[[["Priya gets a paper with the house rules when she moves in.", "A Priya recebe um papel com as regras da casa quando se muda."], ["There is a no smoking sign in the common area, and the lease says no pets.", "Há uma placa de proibido fumar na área comum, e o contrato diz que não pode ter animais."], ["Residents must put glass and paper in the recycling bin on garbage day, which is Tuesday.", "Os moradores devem pôr vidro e papel na lixeira de reciclagem no dia da coleta, que é terça."], ["Everyone must lock the door at night, and you mustn’t block the fire exit with boxes.", "Todos devem trancar a porta à noite, e você não deve bloquear a saída de emergência com caixas."], ["If the fire alarm rings, everyone must leave the building at once.", "Se o alarme de incêndio tocar, todos devem sair do prédio imediatamente."], ["The last rule says you must tell the manager a month before you move out.", "A última regra diz que você deve avisar o síndico um mês antes de se mudar."]], [["Mr. Park, I read the house rules. Can I keep my sister’s cat for a week?", "Sr. Park, li as regras da casa. Posso ficar com o gato da minha irmã por uma semana?"], ["I’m sorry, but pets aren’t allowed. You mustn’t keep any animals here.", "Sinto muito, mas animais não são permitidos. Você não deve ter nenhum bicho aqui."], ["I understand. And where do I put the glass? The recycling bin is full.", "Entendi. E onde ponho o vidro? A lixeira de reciclagem está cheia."], ["Use the big one behind the building. Tuesday is garbage day.", "Use a grande atrás do prédio. A terça é o dia da coleta."], ["Got it. Also, my friend wants to smoke on the balcony. Is that OK?", "Entendi. Outra coisa: meu amigo quer fumar na varanda. Pode?"], ["No, you mustn’t smoke on the balcony. He can smoke on the street.", "Não, você não deve fumar na varanda. Ele pode fumar na rua."], ["Fine. And the front door? Should I lock it every time?", "Tudo bem. E a porta da frente? Devo trancar toda vez?"], ["Yes, you must lock it every night, and please keep the fire exit clear.", "Sim, você deve trancar toda noite, e por favor deixe a saída de emergência livre."], ["Understood. I’ll move my boxes out of the hall today.", "Entendido. Hoje eu tiro minhas caixas do corredor."], ["Thanks. Welcome to the building, Priya!", "Obrigado. Bem-vinda ao prédio, Priya!"]], ["/ɪ/ em bin e /iː/ em leave", "Em bin o i é curto e relaxado, como o 'i' de 'pinta' dito rápido. Em leave o i é longo, com a boca esticada num sorriso: 'liiv'. Não troque um pelo outro: bin não é been, leave não é live.", ["bin", "leave"]], ["You ___ block the fire exit.", "mustn’t", "don’t have to", "Você não deve bloquear a saída de emergência.", "Mustn’t expressa proibição; don’t have to só diz que não é obrigatório."], [["Everyone must lock the door at night, and you mustn’t block the fire exit with boxes.", "Todos devem trancar a porta à noite, e você não deve bloquear a saída de emergência com caixas."], ["I’m sorry, but pets aren’t allowed. You mustn’t keep any animals here.", "Sinto muito, mas animais não são permitidos. Você não deve ter nenhum bicho aqui."]], [{"t": "c", "q": "Pets are not allowed. You ___ keep a cat here.", "o": ["mustn’t", "don’t have to", "can"], "pt": "Animais não são permitidos. Você não deve ter um gato aqui.", "why": "Para proibição usamos mustn’t."}, {"t": "l", "say": "Everyone must leave when the fire alarm rings.", "o": ["Everyone must leave when the fire alarm rings.", "Everyone mustn’t leave when the fire alarm rings.", "Everyone can leave when the fire alarm rings."], "why": "Você ouviu must leave, uma obrigação."}, {"t": "b", "pt": "Você deve trancar a porta à noite.", "w": ["You", "must", "lock", "the", "door", "at", "night"]}, {"t": "b", "pt": "Você não deve fumar na área comum.", "w": ["You", "mustn’t", "smoke", "in", "the", "common", "area"]}]];
