englishA2Plans[248]={"title": "Pedindo orçamento para reformar a cozinha", "file": "", "grammar": "Orçamento de reforma: How much…? / How long…?", "goal": "Pergunte preço e prazo de uma obra com How much…? e How long…?", "words": [["renovation", "reforma"], ["repaint", "pintar de novo"], ["new tiles", "azulejos novos"], ["labor", "mão de obra"], ["materials", "materiais"], ["total cost", "custo total"], ["in writing", "por escrito"], ["quote", "orçamento"], ["contractor", "empreiteiro"], ["free estimate", "orçamento grátis"]]};
englishA2Content[248]=[[["Ben wants a small renovation in his kitchen, so he calls a contractor.", "Ben quer uma pequena reforma na cozinha, então liga para um empreiteiro."], ["The contractor gives him a free estimate and visits the apartment on Saturday.", "O empreiteiro faz um orçamento grátis e visita o apartamento no sábado."], ["Ben asks, “How much does it cost to repaint the walls and put in new tiles?”", "Ben pergunta: “Quanto custa pintar as paredes e colocar azulejos novos?”"], ["The estimate has two parts: materials cost six hundred dollars, and labor costs nine hundred.", "O orçamento tem duas partes: os materiais custam seiscentos dólares e a mão de obra custa novecentos."], ["Ben asks for a second quote to compare the total cost, and he asks, “How long does the work take?”", "Ben pede uma segunda cotação para comparar o custo total e pergunta: “Quanto tempo leva o serviço?”"], ["The second quote is cheaper, but the work takes three weeks instead of two.", "A segunda cotação é mais barata, mas a obra leva três semanas em vez de duas."]], [["Thanks for coming, Mr. Hale. How much does it cost to repaint the kitchen?", "Obrigado por vir, Sr. Hale. Quanto custa pintar a cozinha de novo?"], ["It depends. Do you want new tiles too, or only paint?", "Depende. Você quer azulejos novos também, ou só tinta?"], ["Both, I think. What do the tiles cost?", "Os dois, acho. Quanto custam os azulejos?"], ["About five dollars per square foot. You need around eighty feet, so that’s four hundred.", "Cerca de cinco dólares por pé quadrado. Você precisa de uns oitenta pés, então são quatrocentos."], ["OK. And how long does the whole job take?", "Certo. E quanto tempo leva o serviço todo?"], ["Two weeks, if the materials arrive on time. I only work with a small team.", "Duas semanas, se os materiais chegarem no prazo. Trabalho só com uma equipe pequena."], ["Two weeks is fine. Can I have the total price in writing?", "Duas semanas está bom. Posso ter o preço total por escrito?"], ["Sure. I’ll send a quote tonight. The labor is nine hundred dollars.", "Claro. Mando um orçamento hoje à noite. A mão de obra são novecentos dólares."], ["Great. And how much is the deposit before you start?", "Ótimo. E quanto é o sinal antes de você começar?"], ["Twenty percent. Then we have a deal, and we start on June third.", "Vinte por cento. Então temos um acordo, e começamos no dia três de junho."]], ["/r/ em renovation e repaint", "O r inglês é suave: a língua se enrola para trás sem tocar o céu da boca e sem vibrar. Não diga 'rr' como em 'rato'.", ["renovation", "repaint"]], ["How ___ does the whole renovation take?", "long", "much", "Quanto tempo leva a reforma toda?", "How long pergunta pela duração; how much pergunta pelo preço."], [["OK. And how long does the whole job take?", "Certo. E quanto tempo leva o serviço todo?"], ["Great. And how much is the deposit before you start?", "Ótimo. E quanto é o sinal antes de você começar?"]], [{"t": "c", "q": "How ___ is the total cost?", "o": ["much", "long", "many"], "pt": "Quanto é o custo total?", "why": "Para preço usamos How much."}, {"t": "l", "say": "How long does the work take?", "o": ["How long does the work take?", "How much does the work cost?", "How far does the work take?"], "why": "Você ouviu How long, que pergunta pela duração."}, {"t": "b", "pt": "Quanto é o custo total?", "w": ["How", "much", "is", "the", "total", "cost"]}, {"t": "b", "pt": "Quanto tempo leva o serviço?", "w": ["How", "long", "does", "the", "job", "take"]}]];
englishA2PhotoThemes[248]="cup";
englishA2Plans[249]={"title": "Festa de inauguração da casa reformada", "file": "", "grammar": "Revisão: doesn’t work, Could you…?, Would you mind…?, have to, must, how much / how long", "goal": "Revise problemas, pedidos, regras, contas e prazos ao preparar a festa na casa reformada.", "words": [["remodel", "reformar"], ["start date", "data de início"], ["finish by", "terminar até"], ["rough price", "preço aproximado"], ["smoke detector", "detector de fumaça"], ["trash bag", "saco de lixo"], ["fresh paint", "tinta fresca"], ["new curtains", "cortinas novas"], ["welcome mat", "capacho"], ["housewarming party", "festa de inauguração da casa"]]};
englishA2Content[249]=[[["Rosa and Sam remodel the little house they bought in March, and the contractor gives them a rough price and a start date.", "Rosa e Sam reformam a casinha que compraram em março, e o empreiteiro dá a eles um preço aproximado e uma data de início."], ["The water heater doesn’t work, so Rosa asks him, “Could you come and look at it today?”", "O aquecedor de água não funciona, então Rosa pergunta a ele: “O senhor poderia vir dar uma olhada hoje?”"], ["He promises to finish by the end of May, and he does, so the walls have fresh paint and the new curtains hang next to the window.", "Ele promete terminar até o fim de maio, e termina, então as paredes têm tinta fresca e as cortinas novas ficam ao lado da janela."], ["The first electricity bill is due on the tenth, and Sam has to pay it online.", "A primeira conta de luz vence no dia dez, e Sam tem que pagá-la online."], ["Sam puts a smoke detector in the hall and says, “You mustn’t forget to press the test button.”", "Sam coloca um detector de fumaça no corredor e diz: “Você não deve esquecer de apertar o botão de teste.”"], ["On Saturday, they put a welcome mat in front of the door, and the neighbors next door come to the housewarming party.", "No sábado, eles põem um capacho na frente da porta, e os vizinhos do lado vêm à festa de inauguração."]], [["Sam, the guests come at six. Does the water heater work now?", "Sam, os convidados chegam às seis. O aquecedor de água já funciona?"], ["Yes, Mr. Hale fixed it. But the smoke detector in the hall doesn’t work.", "Funciona, o Sr. Hale consertou. Mas o detector de fumaça do corredor não funciona."], ["Really? Could you come and look at it? Press the test button first.", "Sério? Você pode vir dar uma olhada? Aperte o botão de teste primeiro."], ["I did. Nothing happened. I’ll turn it off and put in a new battery. Where’s the welcome mat?", "Já apertei. Nada aconteceu. Vou desligar e pôr uma pilha nova. Onde está o capacho?"], ["It’s behind the front door. Would you mind putting it in front of the door, next to the plants?", "Está atrás da porta da frente. Você se importaria de pôr na frente da porta, ao lado das plantas?"], ["Sure. Do I have to take out this trash bag too?", "Claro. Eu também tenho que levar este saco de lixo?"], ["No, you don’t have to. I’ll do it. But you mustn’t forget the cake in the fridge!", "Não, você não precisa. Eu faço isso. Mas você não pode esquecer o bolo na geladeira!"], ["Don’t worry. How much was the paint, and how long did the work take?", "Pode deixar. Quanto foi a tinta, e quanto tempo levou a obra?"], ["Two hundred dollars, and six weeks. The bill was due last week, so it’s paid.", "Duzentos dólares e seis semanas. A conta venceu na semana passada, então está paga."], ["Then everything is ready. Let’s enjoy our housewarming party!", "Então está tudo pronto. Vamos aproveitar nossa festa de inauguração!"]], ["/t/ e /d/ finais do -ed em fixed e happened", "Depois de sons surdos (x, k, ch, sh), o -ed vira um 't' rápido, sem vogal extra: 'fikst', 'lukt'. Não diga 'fíquis-ed' nem 'lúquei-d'.", ["fixed", "happened"]], ["Do I ___ take out this trash bag too?", "have to", "must", "Eu também tenho que levar este saco de lixo?", "Em perguntas, use do I have to; must não combina com do."], [["Sure. Do I have to take out this trash bag too?", "Claro. Eu também tenho que levar este saco de lixo?"], ["Really? Could you come and look at it? Press the test button first.", "Sério? Você pode vir dar uma olhada? Aperte o botão de teste primeiro."]], [{"t": "c", "q": "The smoke detector ___ work. We need a new one.", "o": ["doesn’t", "don’t", "isn’t"], "pt": "O detector de fumaça não funciona. Precisamos de um novo.", "why": "Com o sujeito the smoke detector (3ª pessoa) e o verbo work, use doesn’t."}, {"t": "l", "say": "You mustn’t forget the cake.", "o": ["You mustn’t forget the cake.", "You don’t have to forget the cake.", "You mustn’t forget the cape."], "why": "Mustn’t é proibição; don’t have to é falta de obrigação. Cake e cape diferem na última consoante."}, {"t": "b", "pt": "Quanto custou a tinta?", "w": ["How", "much", "was", "the", "paint"]}, {"t": "b", "pt": "Você poderia vir dar uma olhada nisso?", "w": ["Could", "you", "come", "and", "look", "at", "it"]}]];
