englishA2MiniStories[249]=["A casa nova da Rosa", "Rosa and Sam bought an old house, but the water heater didn’t work.~A Rosa e o Sam compraram uma casa velha, mas o aquecedor de água não funcionava.|Rosa asked a contractor, “Could you come and look at the house today?”~A Rosa perguntou a um empreiteiro: “O senhor poderia vir dar uma olhada na casa hoje?”|Sam asked, “How much is the renovation, and how long does it take?”~O Sam perguntou: “Quanto custa a reforma, e quanto tempo leva?”|The contractor said, “Four thousand dollars, and the work takes six weeks.”~O empreiteiro disse: “Quatro mil dólares, e a obra leva seis semanas.”|The neighbors next door said, “Would you mind keeping the noise down after six?”~Os vizinhos do lado disseram: “Vocês se importariam de fazer menos barulho depois das seis?”|Rosa and Sam had to move the sofa, and they put the boxes behind the door.~Rosa e Sam tiveram que mover o sofá, e puseram as caixas atrás da porta.|They paid the electricity bill on the due date, and nothing was broken anymore.~Eles pagaram a conta de luz no vencimento, e nada mais estava quebrado.|At the end, the walls had fresh paint, and the new rule was: you mustn’t wear shoes inside.~No fim, as paredes tinham tinta fresca, e a nova regra era: não se deve usar sapatos dentro de casa.|Sam put a welcome mat at the front door, and Rosa hung new curtains.~O Sam pôs um capacho na porta da frente, e a Rosa pendurou cortinas novas.|Everyone came to the housewarming party, and the little house finally felt like home.~Todos vieram à festa de inauguração, e a casinha finalmente parecia um lar."];
englishA2Plans[250]={"title": "Perguntando o preço dos tênis na loja", "file": "", "grammar": "Pedir preço e desconto: How much is/are…? / Is there a discount?", "goal": "Pergunte o preço com How much is…? e peça desconto com Is there a discount?", "words": [["price tag", "etiqueta de preço"], ["pricey", "caro (informal)"], ["affordable", "acessível"], ["cash register", "caixa registradora"], ["bargain hunter", "caçador de pechinchas"], ["overpriced", "caro demais"], ["spare change", "trocado"], ["store credit", "crédito na loja"], ["gift card", "vale-presente"], ["inexpensive", "barato, em conta"]]};
englishA2Content[250]=[[["Ana sees a pair of red sneakers in the window.", "Ana vê um par de tênis vermelhos na vitrine."], ["The price tag says $89, and that is pricey for her.", "A etiqueta diz US$ 89, e isso é caro para ela."], ["She asks the clerk, \"How much are they today?\"", "Ela pergunta ao vendedor: \"Quanto custam hoje?\""], ["She is a bargain hunter, so she asks, \"Is there a discount?\"", "Ela é caçadora de pechinchas, então pergunta: \"Tem desconto?\""], ["The clerk says the sneakers are 20 percent off today.", "O vendedor diz que os tênis estão com 20 por cento de desconto hoje."], ["At the cash register, she pays $71.20, and now the shoes are affordable.", "No caixa, ela paga US$ 71,20, e agora os tênis cabem no bolso."]], [["Excuse me, how much are these boots? I can't find the price tag.", "Com licença, quanto custam estas botas? Não acho a etiqueta de preço."], ["They're $120. Do you have a gift card or store credit?", "Custam US$ 120. Você tem um vale-presente ou crédito na loja?"], ["I have a gift card for $50. Is there a discount on boots today?", "Tenho um vale-presente de US$ 50. Tem desconto em botas hoje?"], ["Yes! Everything in this aisle is 15 percent off until six.", "Tem! Tudo neste corredor está com 15 por cento de desconto até as seis."], ["Really? That's good, because $120 is overpriced for boots.", "Sério? Que bom, porque US$ 120 é caro demais para botas."], ["These are leather, so they aren't cheap. This other pair is inexpensive.", "São de couro, então não são baratas. Este outro par é barato."], ["How much is the other pair with the discount?", "Quanto custa o outro par com o desconto?"], ["It's $68. After your gift card, you only pay $18.", "Custa US$ 68. Depois do vale-presente, você paga só US$ 18."], ["Great! I even have spare change in my pocket.", "Ótimo! Eu até tenho trocado no bolso."], ["Perfect. Please come to the register, and I'll wrap them.", "Perfeito. Venha ao caixa, e eu embrulho."]], ["/p/ em price e pricey", "O /p/ inglês sai com um sopro de ar: segure um papel na frente da boca e ele deve mexer. Não troque por /b/.", ["price", "pricey"]], ["___ there a discount on this lamp?", "Is", "Are", "Tem desconto nesta luminária?", "Com um item no singular (a discount), a pergunta usa Is there."], [["She is a bargain hunter, so she asks, \"Is there a discount?\"", "Ela é caçadora de pechinchas, então pergunta: \"Tem desconto?\""], ["She asks the clerk, \"How much are they today?\"", "Ela pergunta ao vendedor: \"Quanto custam hoje?\""]], [{"t": "c", "q": "___ are these boots? They're $120.", "o": ["How much", "How many", "How far"], "pt": "Quanto custam estas botas? Custam US$ 120.", "why": "Para perguntar o preço, usamos How much."}, {"t": "l", "say": "Is there a discount on boots today?", "o": ["Is there a discount on boots today?", "Is there a discount on boots tomorrow?", "Are there discounts on shoes today?"], "why": "Você ouviu discount, boots e today."}, {"t": "b", "pt": "Quanto custa este casaco?", "w": ["How", "much", "is", "this", "coat"]}, {"t": "b", "pt": "Tem desconto hoje?", "w": ["Is", "there", "a", "discount", "today"]}]];
