englishA2Plans[251]={"title": "Escolhendo o notebook mais barato na internet", "file": "", "grammar": "Comparar produtos: as… as, not as… as, the cheapest/the best", "goal": "Compare dois produtos com as… as e escolha com the best e the cheapest.", "words": [["cheapest", "o mais barato"], ["second-hand", "de segunda mão"], ["best deal", "melhor negócio"], ["online store", "loja virtual"], ["highest", "o mais alto"], ["lowest", "o mais baixo"], ["buyer", "comprador"], ["monthly payment", "parcela mensal"], ["installments", "parcelas"]]};
englishA2Content[251]=[[["Omar needs a laptop for school, so he checks an online store.", "Omar precisa de um notebook para a escola, então olha uma loja virtual."], ["The new laptop is the best, but it has the highest price.", "O notebook novo é o melhor, mas tem o preço mais alto."], ["The second-hand laptop is the cheapest, and its screen is as big as the new one.", "O notebook de segunda mão é o mais barato, e a tela é tão grande quanto a do novo."], ["Another buyer writes that the battery isn't as good as the new one.", "Outro comprador escreve que a bateria não é tão boa quanto a do novo."], ["Omar looks at the monthly payment: $25 in twelve installments.", "Omar olha a parcela mensal: US$ 25 em doze parcelas."], ["He chooses the middle laptop because it has the lowest monthly payment.", "Ele escolhe o notebook do meio porque tem a menor parcela mensal."]], [["Priya, which laptop is the best deal in this online store?", "Priya, qual notebook é o melhor negócio nesta loja virtual?"], ["Well, the second-hand one is the cheapest, but it isn't as fast as the new ones.", "Bem, o de segunda mão é o mais barato, mas não é tão rápido quanto os novos."], ["I only write essays and watch videos, so I don't need a fast one.", "Eu só escrevo trabalhos e vejo vídeos, então não preciso de um rápido."], ["Then it's as good as a new one for you. The reviews are great.", "Então ele é tão bom quanto um novo para você. As avaliações são ótimas."], ["But the battery lasts only four hours. The new one lasts ten.", "Mas a bateria dura só quatro horas. A do novo dura dez."], ["True. And the gaming laptop costs $1,500!", "Verdade. E o notebook gamer custa US$ 1.500!"], ["No way. I can't pay that, even in twelve installments.", "Nem pensar. Não posso pagar isso, nem em doze parcelas."], ["Then take the middle one. The monthly payment is only $25.", "Então leve o do meio. A parcela mensal é de só US$ 25."], ["That works for my budget. I'm ordering it tonight.", "Isso cabe no meu orçamento. Vou pedir hoje à noite."], ["Great choice. Send me a message when it arrives.", "Ótima escolha. Me mande uma mensagem quando chegar."]], ["/tʃ/ em cheapest e choose", "O /tʃ/ de cheapest é um 'tch' curto. Comece com a língua no céu da boca e solte o ar de uma vez, como em 'tchau'.", ["cheapest", "choose"]], ["This phone is ___ expensive as that one.", "as", "than", "Este celular é tão caro quanto aquele.", "Na comparação de igualdade usamos as… as: as expensive as."], [["The second-hand laptop is the cheapest, and its screen is as big as the new one.", "O notebook de segunda mão é o mais barato, e a tela é tão grande quanto a do novo."], ["Then it's as good as a new one for you. The reviews are great.", "Então ele é tão bom quanto um novo para você. As avaliações são ótimas."]], [{"t": "c", "q": "This chair is the ___ in the store.", "o": ["cheapest", "more cheap", "cheaper"], "pt": "Esta cadeira é a mais barata da loja.", "why": "Com the, usamos o superlativo: the cheapest."}, {"t": "l", "say": "It isn't as fast as the new ones.", "o": ["It isn't as fast as the new ones.", "It isn't so fast than the new ones.", "It is faster as the new ones."], "why": "A comparação negativa usa not as… as."}, {"t": "b", "pt": "Este notebook é tão bom quanto aquele.", "w": ["This", "laptop", "is", "as", "good", "as", "that", "one"]}, {"t": "b", "pt": "Qual é o melhor negócio?", "w": ["Which", "one", "is", "the", "best", "deal"]}]];
