englishA2Plans[253]={"title": "Trocando uma jaqueta que não serviu", "file": "", "grammar": "Devolver um produto: I'd like to return… / It doesn't fit / too + adjetivo", "goal": "Peça para devolver um produto com I'd like to return… e explique o problema com too small ou too tight.", "words": [["return policy", "política de devolução"], ["money back", "dinheiro de volta"], ["wrong size", "tamanho errado"], ["too small", "pequeno demais"], ["too tight", "apertado demais"], ["too loose", "largo demais"], ["try on", "experimentar (roupa)"], ["defective", "com defeito"], ["refundable", "reembolsável"]]};
englishA2Content[253]=[[["Noah bought a jacket online, but it was the wrong size.", "Noah comprou uma jaqueta pela internet, mas era o tamanho errado."], ["It doesn't fit, and the sleeves are too tight.", "Não serve, e as mangas estão apertadas demais."], ["He goes back to the store with the jacket and the bag.", "Ele volta à loja com a jaqueta e a sacola."], ["The return policy says he has thirty days to bring it back.", "A política de devolução diz que ele tem trinta dias para trazê-la de volta."], ["The jacket is refundable, because it still has the tag.", "A jaqueta é reembolsável, porque ainda está com a etiqueta."], ["The clerk gives Noah his money back, and he leaves happy.", "A vendedora devolve o dinheiro a Noah, e ele sai feliz."]], [["Hi, I'd like to return this jacket. It doesn't fit.", "Oi, eu gostaria de devolver esta jaqueta. Ela não serve."], ["Sorry to hear that. What's the problem? Is it too small?", "Sinto muito. Qual é o problema? É pequena demais?"], ["Yes, it's too small. Can I try on a large first?", "Sim, é pequena demais. Posso experimentar uma grande primeiro?"], ["Of course. The fitting rooms are on the left.", "Claro. Os provadores ficam à esquerda."], ["The large is too loose, so I'd like my money back, please.", "A grande é larga demais, então eu gostaria do meu dinheiro de volta, por favor."], ["Okay. Do you have the receipt? I need to check the return policy.", "Certo. Você tem o recibo? Preciso conferir a política de devolução."], ["Here it is. I bought the jacket twelve days ago.", "Aqui está. Comprei a jaqueta há doze dias."], ["Good. It isn't defective, but it's refundable for thirty days.", "Ótimo. Não tem defeito, mas é reembolsável por trinta dias."], ["Then I can give you your money back. Cash or card?", "Então posso devolver seu dinheiro. Em dinheiro ou no cartão?"], ["Card, please. Thank you for your help.", "No cartão, por favor. Obrigado pela ajuda."]], ["/θ/ em thirty e thank", "Em thirty e thank, ponha a ponta da língua entre os dentes e solte o ar. Não troque por /s/ nem por /f/.", ["thirty", "thank"]], ["This jacket is ___ tight. I can't breathe.", "too", "too much", "Esta jaqueta está apertada demais. Não consigo respirar.", "Antes de adjetivo usamos too (demais); too much não vai antes de adjetivo."], [["It doesn't fit, and the sleeves are too tight.", "Não serve, e as mangas estão apertadas demais."], ["Hi, I'd like to return this jacket. It doesn't fit.", "Oi, eu gostaria de devolver esta jaqueta. Ela não serve."]], [{"t": "c", "q": "I'd like to ___ this shirt. It doesn't fit.", "o": ["return", "turn", "devolve"], "pt": "Eu gostaria de devolver esta camisa. Ela não serve.", "why": "Devolver um produto na loja é return. Devolve não existe em inglês (falso cognato)."}, {"t": "l", "say": "The sleeves are too tight.", "o": ["The sleeves are too tight.", "The sleeves are too loose.", "The sleeves are very light."], "why": "Você ouviu too tight: apertado demais."}, {"t": "b", "pt": "Eu gostaria do meu dinheiro de volta.", "w": ["I'd", "like", "my", "money", "back"]}, {"t": "b", "pt": "Posso experimentar um tamanho maior?", "w": ["Can", "I", "try", "on", "a", "bigger", "size"]}]];
englishA2PhotoThemes[253]="map";
englishA2Plans[254]={"title": "Dividindo a conta do jantar", "file": "", "grammar": "Pagar e dividir contas: Let's split… / I'll pay for…", "goal": "Divida a conta com Let's split the bill e ofereça-se para pagar com I'll pay for…", "words": [["split the bill", "dividir a conta"], ["pay cash", "pagar em dinheiro"], ["pay by card", "pagar com cartão"], ["in cash", "em dinheiro"], ["credit card", "cartão de crédito"], ["pay for", "pagar por"], ["pay back", "devolver o dinheiro"], ["owe", "dever"], ["tipping", "dar gorjeta"]]};
englishA2Content[254]=[[["Kenji and Elena have dinner at a small Italian restaurant.", "Kenji e Elena jantam em um pequeno restaurante italiano."], ["The bill is $64, and Kenji says, \"Let's split the bill.\"", "A conta é US$ 64, e Kenji diz: \"Vamos dividir a conta.\""], ["Elena only has a credit card, but the machine is broken, so they must pay cash.", "Elena só tem cartão de crédito, mas a maquininha quebrou, então eles precisam pagar em dinheiro."], ["Kenji says, \"I'll pay for dinner in cash.\"", "Kenji diz: \"Eu pago o jantar em dinheiro.\""], ["Elena says, \"Then I'll pay back my half tomorrow.\"", "Elena diz: \"Então eu pago a minha metade amanhã.\""], ["They both leave a tip and walk home.", "Os dois deixam gorjeta e vão para casa."]], [["The bill is $64. Let's split the bill, okay?", "A conta é US$ 64. Vamos dividir a conta, certo?"], ["Sure. But I only have a credit card. Can we pay by card?", "Claro. Mas só tenho cartão de crédito. Dá para pagar no cartão?"], ["Yes, but the machine is slow tonight. I'll pay for the tip in cash.", "Dá, mas a maquininha está lenta hoje. Eu pago a gorjeta em dinheiro."], ["Thanks. Tipping is normal here, right? About eighteen percent?", "Obrigada. Dar gorjeta é normal aqui, né? Uns dezoito por cento?"], ["Right, that's about $11. We can split that too.", "Isso, dá uns US$ 11. A gente também pode dividir isso."], ["Then I owe you $5.50 for my half of the tip.", "Então devo a você US$ 5,50 pela minha metade da gorjeta."], ["Forget it. Just pay me back with a coffee tomorrow.", "Esqueça. Só me pague com um café amanhã."], ["Deal. I'll bring you the biggest coffee in town.", "Combinado. Vou levar o maior café da cidade para você."]], ["/ɪ/ em split e bill", "O /ɪ/ de split e bill é curto e relaxado, entre 'i' e 'e'. Em split, comece com /sp/ junto, sem um 'e' antes (não diga 'esplit').", ["split", "bill"]], ["It's my birthday, so I'll ___ dinner.", "pay for", "pay", "É meu aniversário, então eu pago o jantar.", "Pagar uma coisa é pay for; sem for, o verbo fica incompleto."], [["Kenji says, \"Let's split the bill.\"", "Kenji diz: \"Vamos dividir a conta.\""], ["Yes, but the machine is slow tonight. I'll pay for the tip in cash.", "Aceita, mas a maquininha está lenta hoje. Eu pago a gorjeta em dinheiro."]], [{"t": "c", "q": "Let's ___ the bill. It's $40 for two people.", "o": ["split", "break", "owe"], "pt": "Vamos dividir a conta. São US$ 40 para duas pessoas.", "why": "Dividir a conta entre pessoas é split the bill."}, {"t": "l", "say": "I'll pay for the tip in cash.", "o": ["I'll pay for the tip in cash.", "I'll pay for the trip in cash.", "I'll pay for the tip by card."], "why": "Você ouviu tip e in cash."}, {"t": "b", "pt": "Eu pago o jantar hoje.", "w": ["I'll", "pay", "for", "dinner", "today"]}, {"t": "b", "pt": "Vamos dividir a conta.", "w": ["Let's", "split", "the", "bill"]}]];
