englishA2Plans[255]={"title": "Juntando dinheiro para uma viagem", "file": "", "grammar": "Economizar dinheiro: saving for, I'm going to save…", "goal": "Fale de uma meta com I'm saving for… e I'm going to save… por mês.", "words": [["piggy bank", "cofrinho"], ["emergency fund", "reserva de emergência"], ["save up", "juntar dinheiro"], ["cut back", "cortar gastos"], ["tight budget", "orçamento apertado"], ["pocket money", "mesada"], ["pay raise", "aumento de salário"], ["make money", "ganhar dinheiro"], ["spend", "gastar"], ["keep track", "ficar de olho, controlar"]]};
englishA2Content[255]=[[["Mia is saving for a trip to Mexico next summer.", "Mia está juntando dinheiro para uma viagem ao México no próximo verão."], ["She keeps coins in a piggy bank on her desk.", "Ela guarda moedas em um cofrinho na mesa."], ["She wants to cut back and spend less on coffee.", "Ela quer cortar gastos e gastar menos com café."], ["She keeps track of every dollar in a small notebook.", "Ela anota cada dólar em um caderninho."], ["Her boss may give her a pay raise in June.", "A chefe pode dar um aumento a ela em junho."], ["Mia is going to save up $1,500 by July.", "Mia vai juntar US$ 1.500 até julho."]], [["Tom, what are you saving for this year?", "Tom, para que você está juntando dinheiro este ano?"], ["A car. But first I need an emergency fund.", "Um carro. Mas primeiro preciso de uma reserva de emergência."], ["Smart. How much are you going to save each month?", "Esperto. Quanto você vai guardar por mês?"], ["About $200. I have a tight budget, so I'm going to cut back on takeout.", "Uns US$ 200. Meu orçamento é apertado, então vou cortar o delivery."], ["Do you keep track of what you spend?", "Você anota o que gasta?"], ["Yes, in an app. Last week I spent $60 on pizza!", "Sim, num app. Semana passada gastei US$ 60 em pizza!"], ["Ha! My little sister gets pocket money, and she wants to make money by washing cars.", "Ha! Minha irmã mais nova ganha mesada e quer ganhar dinheiro lavando carros."], ["Good for her. I'll ask my boss about a pay raise.", "Boa para ela. Vou pedir um aumento ao meu chefe."]], ["/v/ em save e every", "No /v/ de save e every, os dentes de cima tocam o lábio de baixo e a voz vibra. Não troque por /b/.", ["save", "every"]], ["I'm ___ a new phone, so I don't buy snacks.", "saving for", "saving", "Estou juntando dinheiro para um celular novo, então não compro lanches.", "Para dizer o objetivo da economia, usamos saving for + o que você quer."], [["Tom, what are you saving for this year?", "Tom, para que você está juntando dinheiro este ano?"], ["About $200. I have a tight budget, so I'm going to cut back on takeout.", "Uns US$ 200. Meu orçamento é apertado, então vou cortar o delivery."]], [{"t": "c", "q": "I'm going to ___ $50 every month.", "o": ["save", "saves", "saving"], "pt": "Vou guardar US$ 50 todo mês.", "why": "Depois de going to, o verbo fica na forma simples: save."}, {"t": "l", "say": "She is saving for a bike.", "o": ["She is saving for a bike.", "She is saving for a bag.", "He is saving for a bike."], "why": "Você ouviu she e a bike."}, {"t": "b", "pt": "Estou juntando dinheiro para um carro.", "w": ["I'm", "saving", "for", "a", "car"]}, {"t": "b", "pt": "Vou cortar gastos com café.", "w": ["I'm", "going", "to", "cut", "back", "on", "coffee"]}]];
