englishA2Plans[256]={"title": "Pedindo US$ 40 emprestados a uma amiga", "file": "", "grammar": "Emprestar e pagar de volta: lend / borrow", "goal": "Peça dinheiro com Can I borrow…? e ofereça com I can lend you…", "words": [["debt", "dívida"], ["broke", "sem dinheiro"], ["short of", "faltando"], ["pay off", "quitar"], ["pay in full", "pagar tudo"], ["rent money", "dinheiro do aluguel"], ["lose money", "perder dinheiro"], ["poor", "pobre"], ["repay", "pagar de volta, devolver"], ["last month", "mês passado"]]};
englishA2Content[256]=[[["Sam is broke at the end of the month.", "Sam está sem dinheiro no fim do mês."], ["He is $40 short of the rent money.", "Faltam US$ 40 para o dinheiro do aluguel."], ["His friend Ana says she can lend him the money.", "A amiga Ana diz que pode emprestar o dinheiro a ele."], ["Sam wants to borrow it until Friday, and he promises to repay her.", "Sam quer pegar emprestado até sexta e promete pagar de volta."], ["Ana hates debt, so she writes the date on a note.", "Ana odeia dívidas, então anota a data num papel."], ["On Friday, Sam pays in full, and they both smile.", "Na sexta, Sam paga tudo, e os dois sorriem."]], [["Ana, can I borrow $40? I'm broke until Friday.", "Ana, posso pegar US$ 40 emprestados? Estou sem dinheiro até sexta."], ["Sure, I can lend you $40. Did you lose money?", "Claro, posso te emprestar US$ 40. Você perdeu dinheiro?"], ["No, my phone broke, and the repair cost $90.", "Não, meu celular quebrou, e o conserto custou US$ 90."], ["Ouch. Here, take it. Pay me back when you can.", "Nossa. Aqui, pegue. Me pague quando puder."], ["I will. I hate debt, so I'll pay off every dollar.", "Pago. Odeio dívidas, então vou quitar cada dólar."], ["Relax. When I was a poor student, my friends helped me too.", "Relaxe. Quando eu era uma estudante pobre, meus amigos me ajudaram também."], ["Really? That's nice. I'll repay you before the weekend.", "Sério? Que legal. Vou te pagar antes do fim de semana."], ["Just bring it on Friday. You paid for my lunch last month, remember?", "Traga na sexta. Você pagou meu almoço no mês passado, lembra?"], ["Of course! Friday at noon, and I'll pay in full.", "Claro! Sexta ao meio-dia, e eu pago tudo."], ["Perfect. I'll write it on my calendar.", "Perfeito. Vou anotar no meu calendário."]], ["/b/ em borrow e broke", "O /b/ é vozeado: os lábios se abrem e a voz já está ligada. Em broke, junte /br/ sem vogal no meio (não diga 'biroke').", ["borrow", "broke"]], ["Can I ___ your pen? I forgot mine.", "borrow", "lend", "Posso pegar sua caneta emprestada? Esqueci a minha.", "Borrow é pegar emprestado; lend é emprestar a alguém."], [["His friend Ana says she can lend him the money.", "A amiga Ana diz que pode emprestar o dinheiro a ele."], ["Ana, can I borrow $40? I'm broke until Friday.", "Ana, posso pegar US$ 40 emprestados? Estou sem dinheiro até sexta."]], [{"t": "c", "q": "I can ___ you $20 until Monday.", "o": ["lend", "borrow", "owe"], "pt": "Posso te emprestar US$ 20 até segunda.", "why": "Quem dá o dinheiro emprestado usa lend."}, {"t": "l", "say": "Can I borrow forty dollars?", "o": ["Can I borrow forty dollars?", "Can I borrow fourteen dollars?", "Can I lend forty dollars?"], "why": "Você ouviu borrow e forty."}, {"t": "b", "pt": "Posso pegar emprestado seu carregador?", "w": ["Can", "I", "borrow", "your", "charger"]}, {"t": "b", "pt": "Vou te pagar na sexta.", "w": ["I'm", "going", "to", "pay", "you", "back", "on", "Friday"]}]];
