englishA2Plans[257]={"title": "Entendendo cobranças no extrato do banco", "file": "", "grammar": "Ler extrato e fatura: balance, charge, fee", "goal": "Leia um extrato e pergunte sobre uma cobrança com What is this charge?", "words": [["bank statement", "extrato bancário"], ["account balance", "saldo da conta"], ["monthly fee", "taxa mensal"], ["late fee", "multa por atraso"], ["bank fee", "tarifa bancária"], ["utilities", "contas de luz, água etc."], ["groceries", "compras de mercado"], ["subscription", "assinatura"], ["total", "total"], ["extra charge", "cobrança extra"]]};
englishA2Content[257]=[[["Priya opens her bank statement on Sunday morning.", "Priya abre o extrato bancário no domingo de manhã."], ["Her account balance is $412, lower than last month.", "O saldo da conta dela é de US$ 412, menor que o do mês passado."], ["She sees a $9.99 subscription that she forgot to cancel.", "Ela vê uma assinatura de US$ 9,99 que esqueceu de cancelar."], ["There is also a $3 bank fee for using another bank's ATM.", "Há também uma tarifa bancária de US$ 3 por usar o caixa eletrônico de outro banco."], ["The total for utilities and groceries is $290.", "O total de contas e mercado é de US$ 290."], ["Priya cancels the subscription and feels better.", "Priya cancela a assinatura e se sente melhor."]], [["Omar, can you look at this bank statement with me?", "Omar, você pode ver este extrato bancário comigo?"], ["Sure. What's the problem? Your balance looks normal.", "Claro. Qual é o problema? Seu saldo parece normal."], ["There's a $15 late fee here. I paid my phone bill on time!", "Tem uma multa por atraso de US$ 15 aqui. Paguei minha conta de telefone em dia!"], ["Maybe the payment arrived late. Look, there's also a monthly fee of $5 and an extra charge of $2.", "Talvez o pagamento tenha chegado atrasado. Olhe, também tem uma taxa mensal de US$ 5 e uma cobrança extra de US$ 2."], ["A monthly fee? My account was free when I opened it.", "Uma taxa mensal? Minha conta era grátis quando abri."], ["Call the bank. Ask them to remove the charge and explain the fees.", "Ligue para o banco. Peça para tirarem a cobrança e explicarem as taxas."], ["I'll call tomorrow morning. Thank you for your help.", "Vou ligar amanhã de manhã. Obrigada pela ajuda."], ["No problem. Tell me what they say.", "Sem problema. Me conte o que eles disserem."], ["Okay, I'll text you right after the call.", "Certo, mando uma mensagem logo depois da ligação."], ["Great. Then we can check the next statement together.", "Ótimo. Aí conferimos o próximo extrato juntos."]], ["/æ/ em balance e bank", "O /æ/ pede a boca bem aberta, entre 'a' e 'é'. Em bank, não deixe o 'a' ficar nasal como em 'bãnco'.", ["balance", "bank"]], ["What is this $15 ___ on my statement?", "charge", "change", "O que é esta cobrança de US$ 15 no meu extrato?", "Charge é cobrança; change é troco ou mudança, e não combina com extrato."], [["Her account balance is $412, lower than last month.", "O saldo da conta dela é de US$ 412, menor que o do mês passado."], ["Call the bank. Ask them to remove the charge and explain the fees.", "Ligue para o banco. Peça para tirarem a cobrança e explicarem as taxas."]], [{"t": "c", "q": "My account ___ is $412 today.", "o": ["balance", "fee", "charge"], "pt": "O saldo da minha conta é de US$ 412 hoje.", "why": "O dinheiro que sobra na conta é o balance."}, {"t": "l", "say": "There is a late fee on my statement.", "o": ["There is a late fee on my statement.", "There is a late fee on my payment.", "There is a lot of fees on my statement."], "why": "Você ouviu late fee e statement."}, {"t": "b", "pt": "O que é esta cobrança?", "w": ["What", "is", "this", "charge"]}, {"t": "b", "pt": "Meu saldo é menor que o do mês passado.", "w": ["My", "balance", "is", "lower", "than", "last", "month"]}]];
