englishA2Plans[258]={"title": "Mensagem suspeita de um número desconhecido", "file": "", "grammar": "Evitar golpes: Be careful / Never share… (imperativo)", "goal": "Alerte alguém com Be careful e Never share… para evitar golpes.", "words": [["scam", "golpe"], ["scammer", "golpista"], ["suspicious", "suspeito"], ["unknown number", "número desconhecido"], ["verify", "confirmar, verificar"], ["identity", "identidade"], ["fake", "falso"], ["rip off", "enganar, cobrar caro demais"], ["secure", "seguro"]]};
englishA2Content[258]=[[["Rosa gets a text from an unknown number.", "Rosa recebe uma mensagem de um número desconhecido."], ["The message says her card is blocked and asks for her password.", "A mensagem diz que o cartão dela está bloqueado e pede a senha."], ["It looks suspicious, because the grammar is bad.", "Parece suspeita, porque a gramática é ruim."], ["A real bank never asks you to verify your password by text.", "Um banco de verdade nunca pede para você confirmar sua senha por mensagem."], ["Rosa knows it is a scam, so she doesn't click the link.", "Rosa sabe que é um golpe, então não clica no link."], ["She deletes the message and blocks the scammer.", "Ela apaga a mensagem e bloqueia o golpista."]], [["Rosa, you look worried. What's wrong?", "Rosa, você parece preocupada. O que houve?"], ["Ben, I got a weird text from an unknown number. Look!", "Ben, recebi uma mensagem estranha de um número desconhecido. Olhe!"], ["Be careful, Rosa. Don't click that link. It looks fake.", "Cuidado, Rosa. Não clique nesse link. Parece falso."], ["I know. It says I won a free phone, but I have to pay $5 first.", "Eu sei. Diz que ganhei um celular grátis, mas preciso pagar US$ 5 antes."], ["That's a classic trick. They want to rip off people like us.", "Esse é um truque clássico. Eles querem enganar gente como nós."], ["What if they call me? They might ask for my identity number.", "E se eles me ligarem? Podem pedir o número da minha identidade."], ["Never share your password or your identity number, even if they sound polite.", "Nunca compartilhe sua senha ou o número da identidade, mesmo que pareçam educados."], ["Good idea. I'll only shop on secure websites with the lock icon.", "Boa ideia. Só vou comprar em sites seguros com o ícone de cadeado."], ["Exactly. And block that number right now, before you forget.", "Exatamente. E bloqueie esse número agora mesmo, antes que esqueça."], ["Done! It's blocked, and I feel much safer.", "Pronto! Está bloqueado, e me sinto muito mais segura."]], ["/s/ antes de consoante em scam e secure", "Em scam, comece direto no /s/, sem um 'i' antes (não diga 'iscam'). Em secure, o /s/ é limpo e o final soa como 'kiur'.", ["scam", "secure"]], ["___ share your password with anyone.", "Never", "Don't never", "Nunca compartilhe sua senha com ninguém.", "Em inglês não se usa duplo negativo; Never já carrega a ideia de negação."], [["Be careful, Rosa. Don't click that link. It looks fake.", "Cuidado, Rosa. Não clique nesse link. Parece falso."], ["Never share your password or your identity number, even if they sound polite.", "Nunca compartilhe sua senha nem o número da sua identidade, mesmo que pareçam educados."]], [{"t": "c", "q": "___ careful with messages from strangers.", "o": ["Be", "Are", "Do"], "pt": "Tenha cuidado com mensagens de estranhos.", "why": "Na ordem, usamos Be + adjetivo: Be careful."}, {"t": "l", "say": "Never share your password.", "o": ["Never share your password.", "Never change your password.", "Ever share your password."], "why": "Você ouviu never share e password."}, {"t": "b", "pt": "Não clique nesse link.", "w": ["Don't", "click", "that", "link"]}, {"t": "b", "pt": "Nunca compartilhe sua senha.", "w": ["Never", "share", "your", "password"]}]];
