englishA2Plans[259]={"title": "Contando moedas antes do dia do pagamento", "file": "", "grammar": "Revisão: preço, comparação, compras, devolução, conta, economia, empréstimo, extrato e golpe (be careful, going to)", "goal": "Revise o vocabulário do bloco usando Be careful e going to em um fim de mês apertado.", "words": [["sold out", "esgotado"], ["credit card", "cartão de crédito"], ["free shipping", "frete grátis"], ["worth", "valer, merecer"], ["bank account", "conta bancária"], ["be careful", "ter cuidado"], ["for free", "de graça"], ["payday", "dia de pagamento"], ["dime", "moeda de 10 centavos"], ["expense", "despesa, gasto"]]};
englishA2Content[259]=[[["Payday is tomorrow, and Lia's wallet is almost empty.", "O pagamento é amanhã, e a carteira de Lia está quase vazia."], ["Her bank account has only $38 left after a big expense.", "A conta dela tem só US$ 38 depois de uma despesa grande."], ["The book she wants has a $25 price tag, and the local store is sold out.", "O livro que ela quer custa US$ 25, e a loja do bairro está sem estoque."], ["The online store has the cheapest copy, so she adds it to her cart.", "A loja online tem o exemplar mais barato, então ela o põe no carrinho."], ["Free shipping starts at $35, so she is going to wait and be careful.", "O frete grátis começa em US$ 35, então ela vai esperar e ter cuidado."], ["She finds a dime under the sofa and laughs, because the book is worth it.", "Ela acha uma moeda de dez centavos debaixo do sofá e ri, porque o livro vale a pena."]], [["Tom, I'm saving for a book, but my balance is only $38.", "Tom, estou juntando para um livro, mas meu saldo é só US$ 38."], ["Be careful with your credit card this week. The fees are high.", "Cuidado com seu cartão de crédito esta semana. As taxas são altas."], ["I know. I'm going to wait for payday and buy the cheapest copy.", "Eu sei. Vou esperar o pagamento e comprar o exemplar mais barato."], ["Smart. Is there a discount on the online store?", "Esperto. Tem desconto na loja online?"], ["Yes, and the first chapter is free. I can read it for free.", "Tem, e o primeiro capítulo é grátis. Posso ler de graça."], ["Nice. If it doesn't fit your taste, you can return it.", "Legal. Se não for do seu gosto, você pode devolver."], ["True. Last week I almost fell for a scam. A text asked for my password.", "Verdade. Semana passada quase caí num golpe. Uma mensagem pedia minha senha."], ["Wow. Never share your password. Do you want to borrow $20 until payday?", "Nossa. Nunca compartilhe sua senha. Quer pegar US$ 20 emprestados até o pagamento?"], ["Thanks, but I'm going to be careful. Let's split a pizza on Friday instead.", "Obrigada, mas vou ter cuidado. Vamos dividir uma pizza na sexta."], ["Deal. I'll pay for the drinks, and your book is worth it.", "Combinado. Eu pago as bebidas, e seu livro vale a pena."]], ["/w/ em wallet e worth", "No /w/, arredonde os lábios como para dizer 'u' e abra rápido na vogal. Não comece com /v/.", ["wallet", "worth"]], ["She is going to ___ careful with her money.", "be", "is", "Ela vai tomar cuidado com o dinheiro dela.", "Depois de going to, o verbo fica na forma simples: be."], [["Be careful with your credit card this week. The fees are high.", "Cuidado com seu cartão de crédito esta semana. As taxas são altas."], ["I know. I'm going to wait for payday and buy the cheapest copy.", "Eu sei. Vou esperar o pagamento e comprar o exemplar mais barato."]], [{"t": "c", "q": "Be careful. ___ share your password.", "o": ["Never", "Don't never", "Ever"], "pt": "Tenha cuidado. Nunca compartilhe sua senha.", "why": "Never já é negativo; não se usa Don't never (duplo negativo)."}, {"t": "l", "say": "Is there a discount on the book?", "o": ["Is there a discount on the book?", "Are there a discount on the book?", "Is there discount on the book?"], "why": "Com a discount (singular), usamos Is there a discount."}, {"t": "b", "pt": "Vou tomar cuidado com meu dinheiro.", "w": ["I'm", "going", "to", "be", "careful", "with", "money"]}, {"t": "b", "pt": "Este livro é tão barato quanto aquele.", "w": ["This", "book", "is", "as", "cheap", "as", "that", "one"]}]];
englishA2PhotoThemes[259]="map";
englishA2MiniStories[259]=["O mês apertado da Lia", "Lia has only $200 left, and payday is ten days away.~Lia tem só US$ 200 e faltam dez dias para o pagamento.|She wants a coat, but the price tag says $120.~Ela quer um casaco, mas a etiqueta diz US$ 120.|She asks, \"Is there a discount?\" and the clerk says it's 30 percent off.~Ela pergunta: \"Tem desconto?\" e o vendedor diz que são 30 por cento.|At home, she puts boots in her cart, but they are sold out.~Em casa, ela põe botas no carrinho, mas elas estão esgotadas.|At dinner, she and Tom split the bill, and she pays him back the next day.~No jantar, ela e Tom dividem a conta, e ela o paga no dia seguinte.|Her bank statement shows a $3 fee, and the account is almost empty.~O extrato mostra uma tarifa de US$ 3, e a conta está quase vazia.|A text from an unknown number says she can win a phone for free.~Uma mensagem de um número desconhecido diz que ela pode ganhar um celular de graça.|Lia remembers to be careful, so she deletes the message.~Lia lembra de ter cuidado, então apaga a mensagem.|Ana lends her $20, and Lia promises to pay it back on payday.~Ana lhe empresta US$ 20, e Lia promete devolver no dia do pagamento.|On payday, she orders a cheaper coat with free shipping, and it's worth every dollar.~No dia do pagamento, ela pede um casaco mais barato com frete grátis, e vale cada dólar."];
englishA2Plans[260]={"title": "Criando conta no app de ônibus", "file": "", "grammar": "Sequência no passado: download, sign up, log in", "goal": "Conte os passos para usar um app novo: baixar, criar conta e entrar.", "words": [["log in", "entrar (na conta)"], ["log out", "sair (da conta)"], ["profile", "perfil"], ["pop up", "aparecer de repente"], ["storage", "armazenamento"], ["delete", "apagar"], ["icon", "ícone"], ["setting", "configuração"], ["refresh", "atualizar (a tela)"]]};
englishA2Content[260]=[[["Rosa downloaded the bus app on Monday morning.", "Rosa baixou o aplicativo de ônibus na segunda de manhã."], ["First she tapped the green icon, and a window popped up.", "Primeiro ela tocou no ícone verde, e uma janela apareceu."], ["She signed up with her email and chose a password.", "Ela criou a conta com o e-mail e escolheu uma senha."], ["Then she opened her profile and added her photo.", "Depois ela abriu o perfil e colocou a foto."], ["The app needed a lot of storage, so she deleted two old games.", "O app precisava de muito espaço, então ela apagou dois jogos velhos."], ["Now she can log in fast, refresh the bus times, and log out when she's done.", "Agora ela entra rápido, atualiza os horários e sai da conta quando termina."]], [["Tom, did you download the new bus app yet?", "Tom, você já baixou o novo app de ônibus?"], ["Yes, I did. First I tapped the icon, and then I signed up.", "Baixei. Primeiro toquei no ícone e depois criei a conta."], ["Did the app ask for a lot of information?", "O app pediu muitas informações?"], ["Just my email and a password. Then a code popped up.", "Só o e-mail e uma senha. Depois apareceu um código."], ["My phone says there isn't enough storage. I need to delete some photos.", "Meu celular diz que não tem espaço. Preciso apagar umas fotos."], ["Open the settings, and you'll see which apps use the most storage.", "Abra as configurações, e você vai ver quais apps usam mais espaço."], ["Good idea. Okay, I'm in. How do I change my profile picture?", "Boa ideia. Pronto, entrei. Como mudo minha foto de perfil?"], ["Tap your profile, and then tap the little camera.", "Toque no seu perfil e depois na câmera pequena."], ["Done! Should I log out now?", "Pronto! Devo sair da conta agora?"], ["No, stay logged in. Next time it'll open in two seconds.", "Não, fique conectada. Da próxima vez abre em dois segundos."]], ["/aɪ/ em icon e profile", "O som /aɪ/ é como o 'ai' de 'pai', mas termine com um 'i' curto. Diga ICON com força no primeiro pedaço e profile com 'ai' no meio.", ["icon", "profile"]], ["First I downloaded the app, and then I ___ up.", "signed", "sign", "Primeiro baixei o app, e depois criei a conta.", "Na sequência de ações passadas, o segundo verbo também fica no passado: signed."], [["Rosa downloaded the bus app on Monday morning.", "Rosa baixou o aplicativo de ônibus na segunda de manhã."], ["She signed up with her email and chose a password.", "Ela criou a conta com o e-mail e escolheu uma senha."]], [{"t": "c", "q": "She downloaded the app and then she ___ up.", "o": ["signed", "sign", "signing"], "pt": "Ela baixou o app e depois criou a conta.", "why": "Sequência no passado: downloaded, depois signed."}, {"t": "l", "say": "First I tapped the icon, and then I logged in.", "o": ["First I tapped the icon, and then I logged in.", "First I tapped the icon, and then I logged out.", "First I deleted the icon, and then I logged in."], "why": "Você ouviu tapped the icon e logged in."}, {"t": "b", "pt": "Eu baixei o app ontem.", "w": ["I", "downloaded", "the", "app", "yesterday"]}, {"t": "b", "pt": "Preciso apagar fotos velhas.", "w": ["I", "need", "to", "delete", "old", "photos"]}]];
