englishA2Plans[264]={"title": "O vídeo do cachorro que viralizou", "file": "", "grammar": "Redes sociais: post, share, follow com present perfect", "goal": "Conte o que já aconteceu nas redes sociais usando have/has + particípio.", "words": [["follow", "seguir"], ["followers", "seguidores"], ["caption", "legenda"], ["hashtag", "hashtag"], ["comment", "comentário"], ["viral", "viral"], ["unfollow", "deixar de seguir"], ["mention", "mencionar"], ["reaction", "reação"], ["influencer", "influenciador"]]};
englishA2Content[264]=[[["Mia has posted a video of her dog every day this week.", "A Mia postou um vídeo do cachorro todos os dias esta semana."], ["She has added a funny caption and the hashtag #goodboy.", "Ela colocou uma legenda engraçada e a hashtag #goodboy."], ["Her video has gone viral, and 40,000 people have watched it.", "O vídeo dela viralizou, e 40 mil pessoas já assistiram."], ["She has gained 300 new followers since Monday.", "Ela ganhou 300 seguidores novos desde segunda."], ["A famous influencer has shared it and mentioned her name.", "Uma influenciadora famosa compartilhou e citou o nome dela."], ["Mia hasn't read every comment yet, but she has seen a lot of happy reactions.", "A Mia ainda não leu todos os comentários, mas viu muitas reações felizes."]], [["Mia, your dog video is everywhere! Did you see it?", "Mia, seu vídeo do cachorro está em todo lugar! Você viu?"], ["Not yet. I've been at work all day. What's happening?", "Ainda não. Estou no trabalho o dia todo. O que está acontecendo?"], ["A big influencer mentioned you in her story. People are sharing it like crazy.", "Uma influenciadora grande citou você no story dela. As pessoas estão compartilhando sem parar."], ["Really? Last week I only had 50 followers!", "Sério? Na semana passada eu só tinha 50 seguidores!"], ["Now you have more than 300. Some comments are really funny, too.", "Agora você tem mais de 300. Alguns comentários são muito engraçados também."], ["I can't read them now. One person wrote, “This dog is my hero!”", "Não consigo ler agora. Uma pessoa escreveu: “Esse cachorro é meu herói!”"], ["Careful. One person was rude. Just delete the comment and unfollow.", "Cuidado. Uma pessoa foi grosseira. Apague o comentário e deixe de seguir."], ["Good idea. I've already deleted it. Did you like my hashtag?", "Boa ideia. Eu já apaguei. Você gostou da minha hashtag?"], ["Yes! It's perfect. Have you posted anything new?", "Gostei! É perfeita. Você postou algo novo?"], ["Yes, I've just posted a second video. The reaction is great.", "Sim, acabei de postar um segundo vídeo. A reação está ótima."]], ["/æ/ em hashtag e caption", "O /æ/ fica entre 'a' e 'é': abra bem a boca e baixe a mandíbula, como em 'ahn?' de surpresa. Não diga 'rashtague'.", ["hashtag", "caption"]], ["Mia ___ posted a video every day this week.", "has", "have", "A Mia postou um vídeo todos os dias esta semana.", "Com she/Mia, o present perfect usa has, não have."], [["Mia has posted a video of her dog every day this week.", "A Mia postou um vídeo do cachorro todos os dias esta semana."], ["She has gained 300 new followers since Monday.", "Ela ganhou 300 seguidores novos desde segunda."]], [{"t": "c", "q": "They ___ shared my photo three times today.", "o": ["have", "has", "are"], "pt": "Eles compartilharam minha foto três vezes hoje.", "why": "Com they, o present perfect usa have."}, {"t": "l", "say": "She has gained 300 new followers.", "o": ["She has gained 300 new followers.", "She has gained 300 new flowers.", "She had gained 300 new followers."], "why": "Followers são seguidores; flowers são flores."}, {"t": "b", "pt": "Eu já postei outro vídeo", "w": ["I've", "already", "posted", "another", "video"]}, {"t": "b", "pt": "Ele ainda não leu os comentários", "w": ["He", "hasn't", "read", "the", "comments", "yet"]}]];
