englishA2Plans[265]={"title": "Escolhendo um celular novo na loja", "file": "", "grammar": "Comprar um aparelho: which one / the newest / the battery lasts", "goal": "Compare aparelhos na loja e escolha um com Which one…? e the newest.", "words": [["newest", "o mais novo"], ["specs", "especificações"], ["compare", "comparar"], ["wireless", "sem fio"], ["smartwatch", "relógio inteligente"], ["device", "aparelho"], ["storage space", "espaço de armazenamento"], ["hotspot", "roteador do celular"], ["screen protector", "película da tela"]]};
englishA2Content[265]=[[["Lia needs a new device because her old phone is very slow.", "A Lia precisa de um aparelho novo porque o celular velho está muito lento."], ["At the store, she compared three different models.", "Na loja, ela comparou três modelos diferentes."], ["The newest one has the best screen, but it costs $350.", "O mais novo tem a melhor tela, mas custa 350 dólares."], ["The cheaper phone has a battery that lasts two days.", "O celular mais barato tem uma bateria que dura dois dias."], ["It also has wireless charging and enough storage space for her music.", "Ele também tem carregamento sem fio e espaço suficiente para as músicas dela."], ["She chose that one, and the salesman gave her a free screen protector.", "Ela escolheu esse, e o vendedor deu uma película de tela de brinde."]], [["Lia, which phone are you going to buy?", "Lia, qual celular você vai comprar?"], ["I can't decide. Can you help me compare the specs?", "Não consigo decidir. Você me ajuda a comparar as especificações?"], ["Sure. This one is the newest, but the battery only lasts one day.", "Claro. Este é o mais novo, mas a bateria só dura um dia."], ["One day is too short. I forget to charge it a lot.", "Um dia é pouco. Eu esqueço de carregar o tempo todo."], ["Then take this one. The battery lasts two days, and it's $120 cheaper.", "Então leve este. A bateria dura dois dias, e é 120 dólares mais barato."], ["Does it have wireless charging? And how much storage space does it have?", "Tem carregamento sem fio? E quanto espaço de armazenamento tem?"], ["Yes, it does. It has 128 gigabytes, and it can be a hotspot for your laptop.", "Tem sim. Tem 128 gigabytes e pode ser um roteador para o seu notebook."], ["Perfect! Which one do you like, the black one or the blue one?", "Perfeito! De qual você gosta, o preto ou o azul?"], ["The blue one. And the salesman has a smartwatch on sale, too.", "O azul. E o vendedor tem um relógio inteligente em promoção também."], ["No, thanks. I'll take the blue phone and pay now.", "Não, obrigada. Vou levar o celular azul e pagar agora."]], ["/w/ em wireless e which", "No /w/, arredonde bem os lábios como para assoprar uma vela e depois abra. Diga 'uái-erless', não 'vaierless'. Em which, o 'h' não soa.", ["wireless", "which"]], ["The battery on this phone ___ two days.", "lasts", "last", "A bateria deste celular dura dois dias.", "Com 'the battery' (ele/ela), o verbo no presente leva -s: lasts."], [["Sure. This one is the newest, but the battery only lasts one day.", "Claro. Este é o mais novo, mas a bateria só dura um dia."], ["Then take this one. The battery lasts two days, and it's $120 cheaper.", "Então leve este. A bateria dura dois dias, e é 120 dólares mais barato."]], [{"t": "c", "q": "This is ___ phone in the store. It came out last week.", "o": ["the newest", "the most new", "newer"], "pt": "Este é o celular mais novo da loja. Saiu semana passada.", "why": "Adjetivo curto forma o superlativo com the -est: the newest."}, {"t": "l", "say": "Which one has wireless charging?", "o": ["Which one has wireless charging?", "Which one has wireless charger?", "Which one is wireless charging?"], "why": "Has wireless charging é 'tem carregamento sem fio'."}, {"t": "b", "pt": "A bateria dura dois dias", "w": ["The", "battery", "lasts", "two", "days"]}, {"t": "b", "pt": "Qual aparelho você vai comprar", "w": ["Which", "device", "are", "you", "going", "to", "buy"]}]];
