englishA2Plans[266]={"title": "Pesquisando como consertar o pneu da bike", "file": "", "grammar": "Pesquisar na internet: look up, find out, search for", "goal": "Fale de pesquisar algo online usando search for, look up e find out.", "words": [["search for", "procurar, pesquisar"], ["find out", "descobrir"], ["look up", "consultar, procurar (palavra)"], ["browser", "navegador"], ["reliable", "confiável"], ["search engine", "site de busca"], ["search results", "resultados da busca"], ["click on", "clicar em"], ["scroll down", "rolar a tela para baixo"]]};
englishA2Content[266]=[[["Noah's bike had a flat tire, so he opened his browser.", "A bike do Noah estava com o pneu furado, então ele abriu o navegador."], ["He typed a question in a search engine and got two million search results.", "Ele digitou uma pergunta num site de busca e recebeu dois milhões de resultados."], ["First he looked up the word patch in an online dictionary.", "Primeiro ele consultou a palavra patch num dicionário online."], ["He wanted to find out which website was reliable, so he clicked on a bike shop's page.", "Ele queria descobrir qual site era confiável, então clicou na página de uma loja de bicicletas."], ["He scrolled down and found a short video with clear steps.", "Ele rolou a tela e achou um vídeo curto com passos claros."], ["Twenty minutes later, the tire was fixed, and Noah rode to the park.", "Vinte minutos depois, o pneu estava consertado, e o Noah foi de bike ao parque."]], [["Noah, why is your bike in the hallway?", "Noah, por que sua bike está no corredor?"], ["The back tire is flat. I'm trying to find out how to fix it.", "O pneu de trás está furado. Estou tentando descobrir como consertar."], ["Just search for it in your browser. There must be a video.", "É só pesquisar no navegador. Deve ter um vídeo."], ["I did. The search engine gave me two million search results!", "Já fiz isso. O site de busca me deu dois milhões de resultados!"], ["Wow. Click on a bike shop's website. Those are more reliable.", "Nossa. Clique no site de uma loja de bicicletas. Esses são mais confiáveis."], ["Good idea. Wait, there's a word I don't know: patch. Let me look it up.", "Boa ideia. Espera, tem uma palavra que não conheço: patch. Deixa eu procurar."], ["It's a small piece of rubber. Scroll down, and you'll see the steps.", "É um pedacinho de borracha. Role a tela para baixo, e você vai ver os passos."], ["Found it! I need a patch, a pump, and twenty minutes.", "Achei! Preciso de um remendo, uma bomba de ar e vinte minutos."], ["I have a pump in the garage. Do you want it?", "Tenho uma bomba de ar na garagem. Você quer?"], ["Yes, please. Thanks, Ana! I'll come get it in five minutes.", "Quero, sim. Valeu, Ana! Vou buscar em cinco minutos."]], ["/r/ em browser e reliable", "O 'r' inglês não vibra: enrole a língua para trás sem encostar no céu da boca. Em browser e reliable, não pronuncie como o 'h' brasileiro de 'rato'.", ["browser", "reliable"]], ["I want to ___ out what time the store closes.", "find", "look", "Quero descobrir a que horas a loja fecha.", "Find out significa descobrir; look out significa tomar cuidado."], [["The back tire is flat. I'm trying to find out how to fix it.", "O pneu de trás está furado. Estou tentando descobrir como consertar."], ["Just search for it in your browser. There must be a video.", "É só pesquisar no navegador. Deve ter um vídeo."]], [{"t": "c", "q": "I don't know this word. I'll ___ it up.", "o": ["look", "see", "watch"], "pt": "Não conheço essa palavra. Vou procurar.", "why": "Look up é procurar uma palavra num dicionário."}, {"t": "l", "say": "Search for bike repair videos.", "o": ["Search for bike repair videos.", "Search at bike repair videos.", "Search bike repair for videos."], "why": "Search for + o que você procura."}, {"t": "b", "pt": "Preciso descobrir o horário do trem", "w": ["I", "need", "to", "find", "out", "the", "train", "time"]}, {"t": "b", "pt": "Esse site é confiável", "w": ["This", "website", "is", "reliable"]}]];
