englishA2Plans[269]={"title": "Revisão: uma tarde sem internet", "file": "", "grammar": "Revisão: passado simples, present perfect e conselhos no mundo digital", "goal": "Revise o vocabulário de tecnologia contando uma tarde sem internet.", "words": [["power cut", "queda de energia"], ["paper map", "mapa de papel"], ["rely on", "depender de"], ["boredom", "tédio"], ["disconnect", "desconectar-se"], ["addicted", "viciado"], ["cope", "lidar, dar conta"], ["back online", "de volta à internet"], ["restore", "restabelecer"]]};
englishA2Content[269]=[[["A power cut stopped the Wi-Fi in Priya's building, and her phone kept freezing.", "Uma queda de energia parou o Wi-Fi no prédio da Priya, e o celular dela ficava travando."], ["She couldn't log in to her bus app, so she used a paper map to find the bakery.", "Ela não conseguiu entrar no app de ônibus, então usou um mapa de papel para achar a padaria."], ["Her brother Sam heard that the company would restore the Wi-Fi by seven.", "O irmão dela, Sam, ouviu dizer que a empresa restauraria o Wi-Fi até as sete."], ["Priya has posted a photo every day this week, so she felt boredom without her followers.", "A Priya postou uma foto todo dia esta semana, então sentiu tédio sem os seguidores."], ["Her newest phone has a battery that lasts two days, but she decided to disconnect anyway.", "O celular mais novo dela tem bateria que dura dois dias, mas ela decidiu se desconectar mesmo assim."], ["By evening, she could cope without screens, and Sam said she should rely on cards more often.", "À noite, ela já aguentava ficar sem telas, e o Sam disse que ela deveria contar mais com as cartas."]], [["Sam, did the Wi-Fi come back yet?", "Sam, o Wi-Fi já voltou?"], ["No. I heard that the company will restore it by seven.", "Não. Ouvi dizer que a empresa vai restaurar até as sete."], ["Seven? My phone keeps freezing, and the connection is terrible anyway.", "Sete? Meu celular fica travando, e a conexão está péssima de qualquer jeito."], ["I'm addicted to my videos, and I can't search for anything now.", "Sou viciado nos meus vídeos, e agora não consigo pesquisar nada."], ["Let's disconnect for once. We can play cards, and I'll cook dinner.", "Vamos nos desconectar por uma vez. Podemos jogar cartas, e eu faço o jantar."], ["Okay, I can cope for one evening. My newest phone's battery lasts two days, so I'll just mute it.", "Tudo bem, aguento uma noite. A bateria do meu celular mais novo dura dois dias, então vou só silenciar."], ["Good. Later you must log in to your bank app. Do you remember the password?", "Bom. Mais tarde você precisa entrar no app do banco. Lembra a senha?"], ["No, but my password manager does. Wait, we're back online! A voice message from Tom says he'll call back at eight.", "Não, mas meu gerenciador de senhas lembra. Espera, voltamos à internet! Uma mensagem de voz do Tom diz que ele liga de volta às oito."], ["Already? We should finish this game first. Tom can wait until eight.", "Já? Devemos terminar este jogo primeiro. O Tom pode esperar até as oito."], ["Deal. Cards first, phone later.", "Fechado. Cartas primeiro, celular depois."]], ["/b/ em back e boredom", "No /b/, os lábios se fecham e soltam o ar com a garganta vibrando. Em boredom, o acento cai na primeira sílaba: BOR-dom.", ["back", "boredom"]], ["I ___ a paper map because my phone had no signal.", "used", "use", "Usei um mapa de papel porque o celular estava sem sinal.", "A história aconteceu no passado, então o verbo é used."], [["Priya has posted a photo every day this week, so she felt boredom without her followers.", "A Priya postou uma foto todo dia esta semana, então sentiu tédio sem os seguidores."], ["By evening, she could cope without screens, and Sam said she should rely on cards more often.", "À noite, ela já aguentava ficar sem telas, e o Sam disse que ela deveria contar mais com as cartas."]], [{"t": "c", "q": "The power was off, so we ___ cards.", "o": ["played", "play", "playing"], "pt": "A luz estava apagada, então jogamos cartas.", "why": "Ação terminada no passado: played."}, {"t": "l", "say": "My phone keeps freezing, and the connection is weak.", "o": ["My phone keeps freezing, and the connection is weak.", "My phone keep freezing, and the connection is weak.", "My phone keeps freezing, and the collection is weak."], "why": "Keeps leva -s com 'phone'; connection é conexão, collection é coleção."}, {"t": "b", "pt": "Você deveria usar um gerenciador de senhas", "w": ["You", "should", "use", "a", "password", "manager"]}, {"t": "b", "pt": "Ouvi dizer que vão restaurar o Wi-Fi", "w": ["I", "heard", "that", "they", "will", "restore", "the", "Wi-Fi"]}]];
englishA2PhotoThemes[269]="flag";
englishA2MiniStories[269]=["Um dia sem internet", "On Saturday, Rosa tried to log in to her bus app, but her phone kept freezing up.~No sábado, a Rosa tentou entrar no app de ônibus, mas o celular ficava travando.|She wanted to find out the route, so she searched for it in her browser.~Ela queria descobrir o trajeto, então procurou no navegador.|Nothing loaded because a power cut had stopped the Wi-Fi in the whole street.~Nada carregou porque uma queda de energia parou o Wi-Fi na rua inteira.|Her friend Tom sent a voice message, but she couldn't receive it.~O amigo Tom mandou uma mensagem de voz, mas ela não conseguiu receber.|She thought, I must buy a paper map for days like this.~Ela pensou: preciso comprar um mapa de papel para dias assim.|Later Tom texted, “Don't believe the rumors about the bus. I'll call back soon.”~Mais tarde o Tom escreveu: “Não acredite nos boatos sobre o ônibus. Eu ligo de volta logo.”|Rosa decided to disconnect, and she walked to the bakery.~A Rosa decidiu se desconectar e foi a pé até a padaria.|She has never felt such boredom, but she has never seen her street so quiet.~Ela nunca sentiu tanto tédio, mas também nunca viu a rua tão silenciosa.|At six, the network was back online, and she saw Tom's reaction to her photo.~Às seis, a rede voltou, e ela viu a reação do Tom à foto dela.|She wrote a caption and posted, “I can cope without the internet!”~Ela escreveu uma legenda e postou: “Eu dou conta sem internet!”"];
englishA2Plans[270]={"title": "Planejando um passeio a pé pelo centro histórico", "file": "", "grammar": "How do we get there? by + transporte (by bus, by train) e on foot", "goal": "Planeje o dia e pergunte How do we get there? respondendo com by bus, by train ou on foot.", "words": [["city tour", "passeio pela cidade"], ["walking tour", "passeio a pé guiado"], ["tourist attraction", "atração turística"], ["on foot", "a pé"], ["day trip", "bate-volta de um dia"], ["opening hours", "horário de funcionamento"], ["worth visiting", "que vale a visita"], ["scenic", "de paisagem bonita"], ["travel guide", "guia de viagem"]]};
englishA2Content[270]=[[["Ana and Ben have one free day, so they plan a city tour.", "Ana e Ben têm um dia livre, então planejam um passeio pela cidade."], ["The travel guide says the old town is worth visiting.", "O guia de viagem diz que a cidade velha vale a visita."], ["It isn't far, so they can get there on foot.", "Não é longe, então eles podem chegar lá a pé."], ["The museum has short opening hours, so they go there first.", "O museu tem horário curto, então eles vão lá primeiro."], ["After lunch, they join a walking tour with a funny guide.", "Depois do almoço, eles entram num passeio a pé com um guia engraçado."], ["In the evening, they go back to the hotel by bus and plan a day trip for tomorrow.", "À noite, eles voltam para o hotel de ônibus e planejam um bate-volta para amanhã."]], [["Which tourist attraction should we see first, Ben?", "Qual atração turística devemos ver primeiro, Ben?"], ["The castle is the biggest one, but it closes at four.", "O castelo é o maior, mas fecha às quatro."], ["Then let's go now. How do we get there from the hotel?", "Então vamos agora. Como chegamos lá a partir do hotel?"], ["We can go by bus, or we can walk. It's only twenty minutes on foot.", "Podemos ir de ônibus ou andando. São só vinte minutos a pé."], ["I'd rather walk. I want to take photos of the old streets.", "Prefiro andar. Quero tirar fotos das ruas antigas."], ["Good idea. Tomorrow we can do a day trip to the coast, if it's sunny.", "Boa ideia. Amanhã podemos fazer um bate-volta até a costa, se fizer sol."], ["Great! Is it a scenic trip?", "Ótimo! É uma viagem com paisagem bonita?"], ["Yes, we go by train along the coast. Let's buy the tickets after dinner.", "Sim, vamos de trem pela costa. Vamos comprar as passagens depois do jantar."]], ["/ɪ/ curto em visit e city", "O 'i' é curto e relaxado, bem diferente do 'i' longo de 'vi'. Diga 'VIZ-it' e 'SIT-i', sem alongar a vogal.", ["visit", "city"]], ["We can go to the castle ___ bus.", "by", "on", "Nós podemos ir ao castelo de ônibus.", "Com transporte usamos by (by bus, by train); só a pé é on foot."], [["It isn't far, so they can get there on foot.", "Não é longe, então eles podem chegar lá a pé."], ["We can go by bus, or we can walk. It's only twenty minutes on foot.", "Podemos ir de ônibus ou andando. São só vinte minutos a pé."]], [{"t": "c", "q": "The old market is close. We can go ___ foot.", "o": ["on", "by", "with"], "pt": "O mercado antigo é perto. Podemos ir a pé.", "why": "A expressão fixa é on foot; by é para veículos, como by bus."}, {"t": "l", "say": "We can go by bus.", "o": ["We can go by bus.", "We can go on bus.", "We can go with bus."], "why": "De ônibus é by bus; on bus e with bus não são usados."}, {"t": "b", "pt": "Como chegamos ao castelo?", "w": ["How", "do", "we", "get", "to", "the", "castle"]}, {"t": "b", "pt": "Podemos ir de ônibus ou a pé.", "w": ["We", "can", "go", "by", "bus", "or", "on", "foot"]}]];
