englishA2Plans[272]={"title": "Assistindo ao desfile do festival da cidade", "file": "", "grammar": "Presente simples para tradições (every year, usually, always) com he/she/it + s", "goal": "Descreva um evento que acontece todo ano: The parade starts at noon every year.", "words": [["parade", "desfile"], ["local festival", "festival da cidade"], ["traditional", "tradicional"], ["folk dance", "dança folclórica"], ["street food", "comida de rua"], ["take part", "participar"], ["celebrating", "comemorando"], ["historic", "histórico"], ["marching band", "banda de música (de desfile)"]]};
englishA2Content[272]=[[["Every June, our town has a local festival.", "Todo junho, nossa cidade tem um festival local."], ["The parade starts at noon on Main Street.", "O desfile começa ao meio-dia na Rua Principal."], ["A marching band plays traditional songs, and kids wear bright clothes.", "Uma banda de música toca canções tradicionais, e as crianças usam roupas coloridas."], ["Groups of dancers take part in a folk dance on the square.", "Grupos de dançarinos participam de uma dança folclórica na praça."], ["People are celebrating with street food and cold lemonade.", "As pessoas estão comemorando com comida de rua e limonada gelada."], ["The parade stops at the historic church, and everybody sings.", "O desfile para na igreja histórica, e todo mundo canta."]], [["Sam, are you coming to the festival on Saturday?", "Sam, você vem ao festival no sábado?"], ["Of course! What time does the parade start?", "Claro! A que horas começa o desfile?"], ["It usually starts at noon, but the music starts at eleven.", "Normalmente começa ao meio-dia, mas a música começa às onze."], ["Do you take part every year?", "Você participa todo ano?"], ["Yes, I dance in a folk group. We practice every Thursday.", "Sim, danço num grupo folclórico. Ensaiamos toda quinta."], ["Cool! I'll bring my cousin. He loves street food.", "Legal! Vou levar meu primo. Ele adora comida de rua."], ["Tell him to try the corn cakes. They always go fast.", "Diga a ele para provar os bolinhos de milho. Eles acabam rápido."], ["Perfect! See you at the church at eleven, then.", "Perfeito! Até às onze na igreja, então."]], ["/oʊ/ em folk e local", "Em folk o 'l' é mudo: diga 'FÔUK'. Em local a primeira sílaba também soa 'ôu': 'LÔU-kul'.", ["folk", "local"]], ["The parade ___ at noon every year.", "starts", "start", "O desfile começa ao meio-dia todo ano.", "Com the parade (it) no presente simples, o verbo ganha -s: starts."], [["The parade starts at noon on Main Street.", "O desfile começa ao meio-dia na Rua Principal."], ["It usually starts at noon, but the music starts at eleven.", "Normalmente começa ao meio-dia, mas a música começa às onze."]], [{"t": "c", "q": "Our town ___ a festival every June.", "o": ["has", "have", "having"], "pt": "Nossa cidade tem um festival todo junho.", "why": "Our town é terceira pessoa (it), então usamos has."}, {"t": "l", "say": "The parade starts at noon.", "o": ["The parade starts at noon.", "The parades start at noon.", "The parade started at noon."], "why": "Você ouviu starts: singular e presente, não passado."}, {"t": "b", "pt": "Eu participo do desfile todo ano.", "w": ["I", "take", "part", "in", "the", "parade", "every", "year"]}, {"t": "b", "pt": "O festival começa às dez.", "w": ["The", "festival", "starts", "at", "ten"]}]];
