englishA2Plans[273]={"title": "Reservando um quarto de hotel por telefone", "file": "", "grammar": "Would like to + verbo para reservar; perguntas com How much is it per night?", "goal": "Reserve um quarto dizendo I'd like to book a room e pergunte o preço per night.", "words": [["book a room", "reservar um quarto"], ["availability", "disponibilidade"], ["per night", "por noite"], ["double room", "quarto de casal"], ["single room", "quarto de solteiro"], ["breakfast included", "café da manhã incluso"], ["check in", "fazer o check-in"], ["front desk", "recepção"], ["cancellation", "cancelamento"], ["confirmation", "confirmação"]]};
englishA2Content[273]=[[["Lia would like to book a room in Denver for the weekend.", "Lia gostaria de reservar um quarto em Denver para o fim de semana."], ["She calls the hotel and asks about availability for Friday.", "Ela liga para o hotel e pergunta sobre a disponibilidade para sexta."], ["A double room is ninety-five dollars per night, with breakfast included.", "Um quarto de casal custa noventa e cinco dólares por noite, com café da manhã incluso."], ["A single room is cheaper, but Lia is traveling with her sister.", "Um quarto de solteiro é mais barato, mas Lia está viajando com a irmã."], ["They can check in after three o'clock at the front desk.", "Elas podem fazer o check-in depois das três na recepção."], ["The hotel sends a confirmation by email and explains the cancellation rules.", "O hotel envia uma confirmação por e-mail e explica as regras de cancelamento."]], [["Good morning, Sunset Hotel. How can I help you?", "Bom dia, Hotel Sunset. Como posso ajudar?"], ["Hi, I'd like to book a room for this Friday and Saturday.", "Oi, eu gostaria de reservar um quarto para esta sexta e sábado."], ["Let me check availability. Do you want a single room or a double room?", "Vou verificar a disponibilidade. Quer um quarto de solteiro ou de casal?"], ["A double room, please. We'd like to stay two nights. How much is it per night?", "Um quarto duplo, por favor. Gostaríamos de ficar duas noites. Quanto custa por noite?"], ["It's ninety-five dollars per night, and breakfast is included.", "São noventa e cinco dólares por noite, e o café da manhã está incluso."], ["Great. What time can we check in, and can we cancel later?", "Ótimo. A que horas podemos fazer o check-in, e podemos cancelar depois?"], ["You can check in after three at the front desk, and the cancellation is free until Thursday.", "Vocês podem fazer o check-in depois das três na recepção, e o cancelamento é grátis até quinta."], ["Perfect. I'd like to get the confirmation by email. Thank you!", "Perfeito. Eu gostaria de receber a confirmação por e-mail. Obrigada!"]], ["/tʃ/ em check e cheaper", "O 'ch' inglês é como o 'tch' de 'tchau'. Em check termina com esse som, sem 'i' no fim: 'tchék', não 'tchéki'.", ["check", "cheaper"]], ["I would like ___ book a double room.", "to", "for", "Eu gostaria de reservar um quarto de casal.", "Depois de would like, o verbo vem com to: would like to book."], [["Hi, I'd like to book a room for this Friday and Saturday.", "Oi, eu gostaria de reservar um quarto para esta sexta e sábado."], ["A double room, please. We'd like to stay two nights. How much is it per night?", "Um quarto duplo, por favor. Gostaríamos de ficar duas noites. Quanto custa por noite?"]], [{"t": "c", "q": "We'd like ___ a double room for two nights.", "o": ["to have", "have", "having"], "pt": "Gostaríamos de ficar com um quarto duplo por duas noites.", "why": "Depois de would like usamos to + verbo: would like to have."}, {"t": "l", "say": "Is breakfast included?", "o": ["Is breakfast included?", "Is breakfast in the room?", "Is lunch included?"], "why": "Você ouviu breakfast e included, o café da manhã já pago."}, {"t": "b", "pt": "Eu gostaria de reservar um quarto duplo.", "w": ["I", "would", "like", "to", "book", "a", "double", "room"]}, {"t": "b", "pt": "Quanto custa por noite?", "w": ["How", "much", "is", "it", "per", "night"]}]];
