englishA2Plans[274]={"title": "Comprando passagem de trem numa estação desconhecida", "file": "", "grammar": "Single ou return? Which platform? e There is a delay", "goal": "Compre uma passagem de ida ou de ida e volta e pergunte Which platform?", "words": [["single ticket", "passagem só de ida"], ["return ticket", "passagem de ida e volta"], ["round trip", "viagem de ida e volta"], ["ticket machine", "máquina de bilhetes"], ["peak hour", "horário de pico"], ["aboard", "a bordo"], ["railroad", "ferrovia"], ["overnight", "durante a noite"], ["departure board", "painel de partidas"]]};
englishA2Content[274]=[[["Noah arrives at the railroad station in Chicago at eight.", "Noah chega à estação de trem em Chicago às oito."], ["It's peak hour, so he uses the ticket machine.", "É horário de pico, então ele usa a máquina de passagens."], ["The machine asks, \"Single ticket or return ticket?\"", "A máquina pergunta: \"Passagem de ida ou de ida e volta?\""], ["Noah chooses a round trip because he'll come back on Sunday.", "Noah escolhe ida e volta porque voltará no domingo."], ["The departure board shows a delay for the overnight train, so he waits on platform four.", "O painel de partidas mostra um atraso no trem noturno, então ele espera na plataforma quatro."], ["Finally, he gets aboard and finds a window seat.", "Por fim, ele embarca e encontra um lugar na janela."]], [["Excuse me, the ticket machine doesn't take my card.", "Com licença, a máquina de passagens não aceita meu cartão."], ["Sorry about that. Where are you going?", "Sinto muito. Para onde você vai?"], ["To Boston. I need a return ticket for Sunday evening.", "Para Boston. Preciso de uma passagem de ida e volta para domingo à noite."], ["A return ticket is sixty dollars. It's cheaper than two single tickets.", "A passagem de ida e volta custa sessenta dólares. É mais barata que duas de ida."], ["Okay. Which platform does the train leave from?", "Certo. De qual plataforma o trem sai?"], ["Platform six, but there's a twenty-minute delay because of a signal problem.", "Plataforma seis, mas há um atraso de vinte minutos por causa de um problema de sinal."], ["That's okay. Does the train go straight to Boston?", "Tudo bem. O trem vai direto para Boston?"], ["Yes, it's an overnight train. It arrives at six, so you'll be there for breakfast.", "Sim, é um trem noturno. Chega às seis, então você estará lá para o café da manhã."]], ["/eɪ/ em delay e railroad", "Diga 'êi' como em 'lei', com a boca fechando no fim: di-LÊI e RÊIL-roud. Não corte o som em 'dilé'.", ["delay", "railroad"]], ["There ___ a twenty-minute delay today.", "is", "has", "Há um atraso de vinte minutos hoje.", "Em inglês 'tem/há' é there is, não there has."], [["The machine asks, \"Single ticket or return ticket?\"", "A máquina pergunta: \"Passagem de ida ou de ida e volta?\""], ["Platform six, but there's a twenty-minute delay because of a signal problem.", "Plataforma seis, mas há um atraso de vinte minutos por causa de um problema de sinal."]], [{"t": "c", "q": "Which ___ does the train leave from?", "o": ["platform", "ticket", "delay"], "pt": "De qual plataforma o trem sai?", "why": "Se pergunta o lugar de onde o trem sai: platform."}, {"t": "l", "say": "There's a delay of twenty minutes.", "o": ["There's a delay of twenty minutes.", "There's a delay of twenty minute.", "There has a delay of twenty minutes."], "why": "Delay com there is; minutes fica no plural."}, {"t": "b", "pt": "Há um atraso de vinte minutos.", "w": ["There", "is", "a", "delay", "of", "twenty", "minutes"]}, {"t": "b", "pt": "Eu preciso de uma passagem só de ida.", "w": ["I", "need", "a", "single", "ticket"]}]];
