englishA2Plans[275]={"title": "Pedindo dicas de comida local ao recepcionista", "file": "", "grammar": "Pedir e dar recomendações: What do you recommend? / You should try…", "goal": "Peça uma dica com What do you recommend? e responda com You should try…", "words": [["recommend", "recomendar"], ["hidden gem", "joia escondida"], ["must-see", "imperdível"], ["off the beaten track", "fora do roteiro comum"], ["local dish", "prato típico"], ["highly recommended", "muito recomendado"], ["tourist trap", "armadilha para turistas"], ["specialty", "especialidade"], ["worth a visit", "vale a visita"]]};
englishA2Content[275]=[[["Mia is new in Oaxaca and wants to eat something local.", "Mia é nova em Oaxaca e quer comer algo típico."], ["She asks the hotel clerk, \"What do you recommend?\"", "Ela pergunta ao recepcionista: \"O que você recomenda?\""], ["He says the main square is a tourist trap, so she should walk to a smaller street.", "Ele diz que a praça principal é uma armadilha para turistas, então ela deve ir a uma rua menor."], ["A tiny restaurant there is a hidden gem, and its specialty is chicken with a dark chocolate sauce.", "Um restaurantezinho lá é uma joia escondida, e sua especialidade é frango com molho de chocolate amargo."], ["It's off the beaten track, but locals say it's worth a visit.", "Fica fora do roteiro comum, mas os moradores dizem que vale a visita."], ["Mia follows his advice, and she says everybody should try the local dish.", "Mia segue o conselho dele e diz que todo mundo deveria provar o prato típico."]], [["Excuse me, what do you recommend for dinner tonight?", "Com licença, o que você recomenda para o jantar hoje?"], ["You should try Casa Lupe. It's highly recommended.", "Você deveria experimentar a Casa Lupe. É muito recomendada."], ["Is it near here? I don't want a tourist trap.", "Fica perto daqui? Não quero uma armadilha para turistas."], ["No, it's a hidden gem, off the beaten track, about ten minutes on foot. Order the black mole.", "Não, é uma joia escondida, fora do roteiro, uns dez minutos a pé. Peça o mole preto."], ["Sounds good. Is there anything else that's a must-see?", "Parece ótimo. Tem mais alguma coisa imperdível?"], ["Definitely the Sunday market. Don't miss it.", "Com certeza a feira de domingo. Não perca."], ["Great. Should I book a table?", "Ótimo. Devo reservar uma mesa?"], ["Yes, you should. I'll call them for you right now.", "Sim, deve. Vou ligar para eles agora mesmo."]], ["Acento em recommend e specialty", "Em recommend a força vai para a última sílaba: rek-uh-MEND. Em specialty a força fica no começo: SPESH-ul-tee.", ["recommend", "specialty"]], ["You should ___ the fish soup.", "try", "to try", "Você deveria experimentar a sopa de peixe.", "Depois de should o verbo fica sem to: should try."], [["She asks the hotel clerk, \"What do you recommend?\"", "Ela pergunta ao recepcionista: \"O que você recomenda?\""], ["You should try Casa Lupe. It's highly recommended.", "Você deveria experimentar a Casa Lupe. É muito recomendada."]], [{"t": "c", "q": "You should ___ the local dish.", "o": ["try", "to try", "trying"], "pt": "Você deveria experimentar o prato típico.", "why": "Should é modal e pede verbo simples, sem to e sem -ing."}, {"t": "l", "say": "What do you recommend?", "o": ["What do you recommend?", "What do you remember?", "What do you wear?"], "why": "Você ouviu recommend, pedir uma dica, e não remember."}, {"t": "b", "pt": "Você deveria experimentar o prato típico.", "w": ["You", "should", "try", "the", "local", "dish"]}, {"t": "b", "pt": "É uma joia escondida.", "w": ["It", "is", "a", "hidden", "gem"]}]];
