englishA2Plans[277]={"title": "Reclamando da mala perdida no aeroporto", "file": "", "grammar": "Problemas na viagem: so e because (The flight was late, so I missed my connection)", "goal": "Explique um problema de viagem ligando causa e resultado com so e because.", "words": [["lost luggage", "bagagem perdida"], ["baggage claim", "esteira de bagagens"], ["claim form", "formulário de reclamação"], ["missed connection", "conexão perdida"], ["rebook", "remarcar"], ["compensation", "indenização"], ["stranded", "sem ter como seguir viagem"], ["overbooked", "com excesso de reservas"], ["lost property", "achados e perdidos"]]};
englishA2Content[277]=[[["Elena lands in Miami after a long flight.", "Elena pousa em Miami depois de um voo longo."], ["She waits at the baggage claim for forty minutes, but her bag never comes.", "Ela espera na esteira de bagagens por quarenta minutos, mas a mala dela nunca chega."], ["Her first flight was late, so she also had a missed connection.", "O primeiro voo dela atrasou, então ela também teve uma conexão perdida."], ["At the desk, she fills out a claim form for her lost luggage.", "No balcão, ela preenche um formulário de reclamação pela bagagem perdida."], ["The clerk is kind, but Elena feels tired and stranded because she has no clothes.", "A atendente é gentil, mas Elena se sente cansada e sem saída porque não tem roupas."], ["The next day, the airline brings her bag to the hotel, and she smiles again.", "No dia seguinte, a companhia traz a mala dela ao hotel, e ela volta a sorrir."]], [["Excuse me, my suitcase didn't come out, so I don't know where to ask.", "Com licença, minha mala não saiu, então não sei onde perguntar."], ["I'm sorry. Did you already check lost property?", "Sinto muito. Você já olhou nos achados e perdidos?"], ["Yes, they don't have it. I also missed my connection because my first flight was late.", "Sim, não têm. Eu também perdi minha conexão porque meu primeiro voo atrasou."], ["Your flight to Orlando was overbooked, so I can rebook you for tomorrow at nine.", "Seu voo para Orlando estava com excesso de reservas, então posso remarcar para amanhã às nove."], ["Tomorrow? That's a long time. Will the airline pay for a hotel?", "Amanhã? É muito tempo. A companhia paga um hotel?"], ["Yes, you'll get compensation of one hundred dollars, and we'll find your bag.", "Sim, você receberá uma indenização de cem dólares, e vamos achar sua mala."], ["Thanks. Where do I get the claim form?", "Obrigada. Onde pego o formulário de reclamação?"], ["Right here. Fill it out, and we'll call you tonight.", "Aqui mesmo. Preencha, e ligaremos para você hoje à noite."]], ["/æ/ em baggage e stranded", "O 'a' é aberto, entre 'é' e 'a': 'BÉ-gij' e 'STRÉN-did'. Não diga 'bagagi' como em português.", ["baggage", "stranded"]], ["The flight was late, ___ I missed my connection.", "so", "because", "O voo atrasou, então perdi minha conexão.", "So introduz o resultado; because introduziria a causa."], [["Her first flight was late, so she also had a missed connection.", "Seu primeiro voo atrasou, então ela também perdeu a conexão."], ["Yes, they don't have it. I also missed my connection because my first flight was late.", "Sim, não têm. Eu também perdi minha conexão porque meu primeiro voo atrasou."]], [{"t": "c", "q": "My flight was late, ___ I missed my connection.", "o": ["so", "because", "or"], "pt": "Meu voo atrasou, então perdi minha conexão.", "why": "A conexão perdida é o resultado do atraso, então usamos so."}, {"t": "l", "say": "She is stranded because she missed her connection.", "o": ["She is stranded because she missed her connection.", "She is stranded so she missed her connection.", "She is stranded because she misses her connection."], "why": "Because dá a causa (perdeu a conexão); so daria o resultado."}, {"t": "b", "pt": "Perdi a conexão porque meu voo atrasou.", "w": ["I", "missed", "my", "connection", "because", "my", "flight", "was", "late"]}, {"t": "b", "pt": "Minha mala está perdida, então preciso de ajuda.", "w": ["My", "bag", "is", "lost", "so", "I", "need", "help"]}]];
