englishA2Plans[278]={"title": "Fotos no mirante e lembrancinhas para a mãe", "file": "", "grammar": "Pedidos educados com Could you + verbo (Could you take a photo of us?)", "goal": "Peça para alguém tirar uma foto com Could you take a photo of us?", "words": [["photo spot", "lugar bom para fotos"], ["group photo", "foto em grupo"], ["take photos", "tirar fotos"], ["memory card", "cartão de memória"], ["memories", "lembranças"], ["souvenir shop", "loja de souvenires"], ["fridge magnet", "ímã de geladeira"], ["handmade", "feito à mão"], ["bring back", "trazer de volta"]]};
englishA2Content[278]=[[["Kenji and Rosa find a great photo spot on top of the hill.", "Kenji e Rosa acham um ótimo lugar para fotos no alto do morro."], ["They ask a stranger, \"Could you take a group photo of us?\"", "Eles pedem a um desconhecido: \"Você poderia tirar uma foto do grupo de nós dois?\""], ["Kenji likes to take photos of food, doors, and cats.", "Kenji gosta de tirar fotos de comida, portas e gatos."], ["His memory card is almost full, so he deletes ten bad pictures.", "O cartão de memória dele está quase cheio, então ele apaga dez fotos ruins."], ["Rosa goes into a souvenir shop and buys a handmade fridge magnet.", "Rosa entra numa loja de souvenires e compra um ímã de geladeira feito à mão."], ["She wants to bring back something small for her mother, and the magnet keeps her memories close.", "Ela quer trazer algo pequeno para a mãe, e o ímã mantém as lembranças por perto."]], [["Excuse me, could you take a photo of us, please?", "Com licença, você poderia tirar uma foto de nós, por favor?"], ["Sure. Where do you want to stand?", "Claro. Onde vocês querem ficar?"], ["By the fountain, with the bridge behind us.", "Perto da fonte, com a ponte atrás de nós."], ["Smile! One, two, three... Oh, it's a little blurry. Let me try again.", "Sorriam! Um, dois, três... Ah, ficou meio borrada. Deixe eu tentar de novo."], ["Thanks! Could you take one more? My eyes were closed.", "Obrigada! Você poderia tirar mais uma? Meus olhos estavam fechados."], ["Sure. That's better. This is a great photo spot, isn't it?", "Claro. Assim está melhor. Este é um ótimo ponto para fotos, né?"], ["Yes! Could you tell me where to buy a gift for my mother?", "Sim! Você poderia me dizer onde comprar um presente para minha mãe?"], ["There's a souvenir shop around the corner with cheap magnets. Turn left at the café.", "Tem uma loja de souvenirs na esquina com ímãs baratos. Vire à esquerda no café."]], ["/ɑ/ em shop e spot", "A boca fica bem aberta, como no 'a' de 'pá' curto. Termine em consoante: 'SHÓP' e 'SPÓT', sem 'i' no fim.", ["shop", "spot"]], ["Could you ___ a photo of us, please?", "take", "make", "Você poderia tirar uma foto de nós, por favor?", "Em inglês a foto se 'toma': take a photo, nunca make a photo."], [["Excuse me, could you take a photo of us, please?", "Com licença, você poderia tirar uma foto de nós, por favor?"], ["Thanks! Could you take one more? My eyes were closed.", "Obrigada! Você poderia tirar mais uma? Meus olhos estavam fechados."]], [{"t": "c", "q": "She wants to ___ something back for her mom.", "o": ["bring", "carry", "put"], "pt": "Ela quer trazer algo de volta para a mãe.", "why": "A expressão fixa é bring back, trazer de volta."}, {"t": "l", "say": "Could you take a photo of us?", "o": ["Could you take a photo of us?", "Could you make a photo of us?", "Could you take a photo for us?"], "why": "Você ouviu take a photo of us, a forma natural do pedido."}, {"t": "b", "pt": "Você poderia tirar uma foto de nós?", "w": ["Could", "you", "take", "a", "photo", "of", "us"]}, {"t": "b", "pt": "Meu cartão de memória está cheio.", "w": ["My", "memory", "card", "is", "full"]}]];
