englishA2Plans[279]={"title": "Revisão: o diário de viagem de Ben no Japão", "file": "", "grammar": "Revisão: passado simples, present perfect, should, would like, so e because", "goal": "Conte a viagem revisando passado, present perfect, should, would like e could you.", "words": [["travel diary", "diário de viagem"], ["bucket list", "lista de desejos de vida"], ["pack up", "arrumar as malas"], ["last day", "último dia"], ["hostel", "albergue"], ["local guide", "guia local"], ["airport shuttle", "van do aeroporto"], ["boarding gate", "portão de embarque"], ["travel plans", "planos de viagem"]]};
englishA2Content[279]=[[["On his last day in Kyoto, Ben has to pack up his things at the hostel.", "No último dia em Kyoto, Ben tem que arrumar as coisas no albergue."], ["The airport shuttle is late, so he sits outside and reads his travel diary.", "A van do aeroporto está atrasada, então ele senta lá fora e lê seu diário de viagem."], ["He reads about the missed connection, the hidden gem, and the parade, and he smiles.", "Ele lê sobre a conexão perdida, a joia escondida e o desfile, e sorri."], ["A local guide says, \"You should come back in spring.\"", "Um guia local diz: \"Você deveria voltar na primavera.\""], ["At the boarding gate, Ben looks at his bucket list and writes \"Done!\" next to Japan.", "No portão de embarque, Ben olha sua lista de desejos e escreve \"Feito!\" ao lado do Japão."], ["He has never felt so happy, and he's going to make new travel plans on the plane.", "Ele nunca se sentiu tão feliz e vai fazer novos planos de viagem no avião."]], [["Welcome back, Ben! You look tired. How was Japan?", "Bem-vindo de volta, Ben! Você parece cansado. Como foi o Japão?"], ["Amazing, but I have jet lag. I have never seen such a beautiful city.", "Incrível, mas estou com jet lag. Nunca vi uma cidade tão bonita."], ["Did you get around on foot, or did you go by bus?", "Você andou a pé ou foi de ônibus?"], ["Mostly on foot, because the buses were always full. Did I tell you about the train?", "Quase sempre a pé, porque os ônibus viviam cheios. Contei do trem?"], ["No! What happened?", "Não! O que aconteceu?"], ["There was a delay, so I missed my connection. A local guide said I should try the ramen near the station.", "Houve um atraso, então perdi a conexão. Um guia local disse que eu deveria provar o lámen perto da estação."], ["That sounds stressful, but I would like to go next spring. How much is a hostel per night?", "Parece estressante, mas eu gostaria de ir na próxima primavera. Quanto custa um albergue por noite?"], ["About thirty dollars per night. Could you wait a minute? My travel diary has all the prices.", "Uns trinta dólares por noite. Você poderia esperar um minuto? Meu diário de viagem tem todos os preços."], ["Sure. Did you take a lot of photos?", "Claro. Você tirou muitas fotos?"], ["Yes, about five hundred. I'll show you all of them tonight.", "Sim, umas quinhentas. Vou mostrar todas para você hoje à noite."]], ["/h/ aspirado em hostel e have", "O 'h' inglês é um sopro suave na garganta, sem o 'rr' do português. Diga 'HÓS-tel' e 'HÉV', não 'rostel'.", ["hostel", "have"]], ["I have never ___ such a beautiful city.", "seen", "saw", "Eu nunca vi uma cidade tão bonita.", "Com have + never usamos o particípio seen, não o passado saw."], [["A local guide says, \"You should come back in spring.\"", "Um guia local diz: \"Você deveria voltar na primavera.\""], ["Amazing, but I have jet lag. I have never seen such a beautiful city.", "Incrível, mas estou com jet lag. Nunca vi uma cidade tão bonita."]], [{"t": "c", "q": "The shuttle was late, ___ Ben read his diary.", "o": ["so", "because", "but"], "pt": "A van estava atrasada, então Ben leu o diário.", "why": "So introduz o resultado do atraso."}, {"t": "l", "say": "You should try the ramen.", "o": ["You should try the ramen.", "You should to try the ramen.", "You shouldn't try the ramen."], "why": "Depois de should vem o verbo sem to."}, {"t": "b", "pt": "Você deveria reservar um albergue.", "w": ["You", "should", "book", "a", "hostel"]}, {"t": "b", "pt": "Eu gostaria de ir na primavera.", "w": ["I", "would", "like", "to", "go", "in", "spring"]}]];
