englishA2MiniStories[279]=["O diário de viagem de Ben", "Ben wrote in his travel diary every night in Kyoto.~Ben escreveu no diário de viagem toda noite em Kyoto.|On day one, he went on foot through the old town and joined a walking tour.~No primeiro dia, ele andou a pé pela cidade velha e fez um passeio a pé guiado.|He took an audio guide at the museum, but he forgot his coat in the cloakroom.~Ele pegou um audioguia no museu, mas esqueceu o casaco no guarda-volumes.|He would like to stay near the station, so he booked a hostel for thirty dollars per night.~Ele queria ficar perto da estação, então reservou um albergue por trinta dólares a noite.|On day two, he bought a return ticket, but there was a delay.~No segundo dia, ele comprou uma passagem de ida e volta, mas houve um atraso.|He missed his connection because the train was an hour late, and he felt stranded.~Ele perdeu a conexão porque o trem atrasou uma hora, e se sentiu sem saída.|A kind woman said, \"You should try the local dish,\" so he went to a hidden gem restaurant.~Uma mulher gentil disse: \"Você deveria provar o prato típico\", então ele foi a um restaurante escondido.|The next morning, he watched a parade and asked a stranger, \"Could you take a photo of me with the dancers?\"~Na manhã seguinte, ele assistiu a um desfile e pediu a um desconhecido: \"Você poderia tirar uma foto minha com os dançarinos?\"|In a souvenir shop, he bought a handmade fridge magnet to bring back for his mom.~Numa loja de souvenirs, ele comprou um ímã de geladeira feito à mão para levar à mãe.|On his last night, Ben wrote, \"I have never had such a great trip, and I want to come back.\"~Na última noite, Ben escreveu: \"Nunca tive uma viagem tão boa, e quero voltar.\""];
englishA2Plans[280]={"title": "Pão de banana passo a passo", "file": "", "grammar": "Seguir uma receita: first, then, add, stir (imperativo em sequência)", "goal": "Explique uma receita simples em ordem usando First, Then e verbos no imperativo.", "words": [["stir in", "acrescentar mexendo"], ["chop up", "picar"], ["pour in", "despejar"], ["mix well", "misturar bem"], ["set aside", "deixar de lado"], ["bake for", "assar por"], ["preheat", "pré-aquecer"], ["sliced", "fatiado"], ["turn down", "abaixar (o fogo)"], ["bring to a boil", "levar à fervura"]]};
englishA2Content[280]=[[["Ana wants to make banana bread, so first she preheats the oven.", "Ana quer fazer pão de banana, então primeiro ela pré-aquece o forno."], ["Then she chops up three bananas and pours in some milk.", "Depois ela pica três bananas e despeja um pouco de leite."], ["Her grandma's note says, \"First, stir in the flour and the sugar. Then mix well.\"", "O bilhete da avó dela diz: \"Primeiro, misture a farinha e o açúcar. Depois, misture bem.\""], ["\"Set aside the bowl, put the batter in a pan, and bake for fifty minutes.\"", "\"Reserve a tigela, ponha a massa numa forma e asse por cinquenta minutos.\""], ["Soon the kitchen smells great, and Ana can't wait.", "Logo a cozinha cheira bem, e a Ana mal pode esperar."], ["Ana serves the bread sliced, and her brother eats three pieces.", "Ana serve o pão fatiado, e o irmão dela come três pedaços."]], [["Ben, are you cooking lunch? I can hear the pan.", "Ben, você está fazendo o almoço? Estou ouvindo a panela."], ["Yes, I'm making tomato soup, but I don't know the steps.", "Sim, estou fazendo sopa de tomate, mas não sei os passos."], ["Easy. First, chop up two onions and fry them in a little oil.", "Fácil. Primeiro pique duas cebolas e frite em um pouco de óleo."], ["OK, the onions are in the pan. What's next?", "Certo, as cebolas estão na panela. E agora?"], ["Pour in the tomatoes and bring to a boil. Then turn down the heat.", "Despeje os tomates e leve à fervura. Depois abaixe o fogo."], ["Wait, the soup is boiling over! Is that bad?", "Espera, a sopa está transbordando! Isso é ruim?"], ["Turn down the heat now! Then stir for one minute.", "Abaixe o fogo agora! Depois mexa por um minuto."], ["Phew, it looks good. Should I add salt?", "Ufa, está com uma cara boa. Devo pôr sal?"], ["Yes, but add just a little. And serve it with sliced bread.", "Sim, mas só um pouquinho. E sirva com pão fatiado."], ["Great, I have some sliced bread. I'll send you a picture in ten minutes.", "Ótimo, tenho pão fatiado. Vou mandar uma foto em dez minutos."]], ["/st/ em stir e steps", "Não coloque um 'e' antes do 'st': diga 'stir', nunca 'estir'. Comece com o 's' e já feche a língua no 't'.", ["stir", "steps"]], ["First, chop the onions. ___, fry them in oil.", "Then", "Than", "Primeiro, pique as cebolas. Depois, frite-as no óleo.", "Para a sequência 'depois' use then; than só aparece em comparações."], [["Easy. First, chop up two onions and fry them in a little oil.", "Fácil. Primeiro pique duas cebolas e frite em um pouco de óleo."], ["Pour in the tomatoes and bring to a boil. Then turn down the heat.", "Despeje os tomates e leve à fervura. Depois abaixe o fogo."]], [{"t": "c", "q": "First, preheat the oven. ___, chop up the bananas.", "o": ["Then", "Than", "Thin"], "pt": "Primeiro, pré-aqueça o forno. Depois, pique as bananas.", "why": "Then liga o próximo passo da receita."}, {"t": "l", "say": "Turn down the heat and stir for one minute.", "o": ["Turn down the heat and stir for one minute.", "Turn up the heat and stir for one minute.", "Turn down the heat and stir for ten minutes."], "why": "Você ouviu turn down (abaixar o fogo) e one minute."}, {"t": "b", "pt": "Primeiro, pique duas cebolas.", "w": ["First", "chop", "up", "two", "onions"]}, {"t": "b", "pt": "Depois, acrescente o sal.", "w": ["Then", "add", "the", "salt"]}]];
