englishA2Plans[285]={"title": "Menu vegano para a irmã da Priya", "file": "", "grammar": "Cardápio e dieta: without, instead of, vegan", "goal": "Descreva um prato com without e instead of para respeitar uma dieta.", "words": [["vegan", "vegano"], ["without", "sem"], ["instead of", "em vez de"], ["gluten-free", "sem glúten"], ["dairy-free", "sem laticínios"], ["leave out", "deixar de fora"], ["meat-free", "sem carne"], ["fill up", "deixar satisfeito"], ["plant-based", "à base de plantas"]]};
englishA2Content[285]=[[["Priya's sister Mina is vegan, so Priya plans a special menu.", "A irmã da Priya, Mina, é vegana, então Priya planeja um cardápio especial."], ["She makes tacos without cheese and uses beans instead of meat.", "Ela faz tacos sem queijo e usa feijão em vez de carne."], ["The cake is gluten-free, and it is also dairy-free.", "O bolo é sem glúten e também é sem laticínios."], ["Priya wants a meat-free main dish that can fill up everyone.", "Priya quer um prato principal sem carne que deixe todo mundo satisfeito."], ["She will leave out the honey and use maple syrup.", "Ela vai deixar o mel de fora e usar xarope de bordo."], ["At dinner, Mina smiles and says, \"I can eat everything!\"", "No jantar, Mina sorri e diz: \"Posso comer tudo!\""]], [["Priya, what's on the menu for Mina's birthday dinner?", "Priya, o que tem no cardápio do jantar de aniversário da Mina?"], ["Tacos without cheese. It's a plant-based menu, so I'm using black beans instead of chicken.", "Tacos sem queijo. É um cardápio à base de plantas, então uso feijão-preto em vez de frango."], ["Nice. Is she vegetarian or vegan? I always forget.", "Legal. Ela é vegetariana ou vegana? Eu sempre esqueço."], ["She's vegan, so no milk and no eggs. Even the cake is dairy-free.", "Ela é vegana, então sem leite e sem ovos. Até o bolo é sem laticínios."], ["And is it gluten-free? My cousin Ana can't eat bread.", "E é sem glúten? Minha prima Ana não pode comer pão."], ["Yes, I use rice flour instead of wheat flour.", "Sim, uso farinha de arroz em vez de farinha de trigo."], ["Great. Can I bring some ice cream?", "Ótimo. Posso levar sorvete?"], ["Sure, but get vegan ice cream. Regular ice cream has milk.", "Claro, mas pegue sorvete vegano. O sorvete comum tem leite."], ["Got it. Should I leave out the honey in the dressing?", "Entendi. Devo deixar o mel de fora do molho?"], ["Yes, please. Use lemon juice instead of honey. Thanks, Omar!", "Sim, por favor. Use suco de limão em vez de mel. Obrigada, Omar!"]], ["/v/ em vegan e vegetarian", "No /v/ os dentes de cima tocam o lábio de baixo e a voz vibra. Não troque por 'b': 'vegan' não é 'began'.", ["vegan", "vegetarian"]], ["I use beans ___ meat in my tacos.", "instead of", "instead", "Eu uso feijão em vez de carne nos meus tacos.", "Antes de um substantivo use instead of; instead sozinho vem no fim da frase."], [["She makes tacos without cheese and uses beans instead of meat.", "Ela faz tacos sem queijo e usa feijão em vez de carne."], ["Yes, I use rice flour instead of wheat flour.", "Sim, uso farinha de arroz em vez de farinha de trigo."]], [{"t": "c", "q": "Mina eats tacos ___ cheese.", "o": ["without", "instead", "not"], "pt": "A Mina come tacos sem queijo.", "why": "Without significa sem e vem antes do substantivo."}, {"t": "l", "say": "I use beans instead of meat.", "o": ["I use beans instead of meat.", "I use meat instead of beans.", "I use beans without meat."], "why": "Você ouviu beans instead of meat (feijão em vez de carne)."}, {"t": "b", "pt": "O bolo não tem leite.", "w": ["The", "cake", "is", "dairy-free"]}, {"t": "b", "pt": "Eu uso arroz em vez de macarrão.", "w": ["I", "use", "rice", "instead", "of", "pasta"]}]];
