englishA2Plans[287]={"title": "Milho, manga e suco na feira de rua", "file": "", "grammar": "Comida de rua e feira: How much for…? / a bag of", "goal": "Pergunte o preço com How much for…? e peça comida em porções com a bag of e a slice of.", "words": [["a bag of", "um saco de"], ["how much for", "quanto custa"], ["a slice of", "uma fatia de"], ["a scoop of", "uma bola de (sorvete)"], ["street vendor", "vendedor de rua"], ["cash only", "só dinheiro"], ["keep the change", "fique com o troco"], ["fresh-squeezed", "espremido na hora"], ["free sample", "amostra grátis"], ["for the road", "para a viagem"]]};
englishA2Content[287]=[[["On Saturday, Lia goes to the street market near her house.", "No sábado, Lia vai à feira de rua perto da casa dela."], ["A street vendor sells corn, mangoes, and fresh-squeezed orange juice.", "Um vendedor de rua vende milho, mangas e suco de laranja espremido na hora."], ["Lia asks, \"How much for a bag of mangoes?\"", "Lia pergunta: \"Quanto custa um saco de mangas?\""], ["\"Four dollars,\" the vendor says, \"but it's cash only.\"", "\"Quatro dólares\", diz o vendedor, \"mas é só dinheiro.\""], ["She pays with five dollars and says, \"Keep the change.\"", "Ela paga com cinco dólares e diz: \"Fique com o troco.\""], ["Then she buys a slice of watermelon and a scoop of coconut ice cream.", "Depois ela compra uma fatia de melancia e uma bola de sorvete de coco."]], [["Good morning! How much for the corn?", "Bom dia! Quanto custa o milho?"], ["One dollar each, or three for two dollars.", "Um dólar cada, ou três por dois dólares."], ["I'll take three. And how much for a bag of mangoes?", "Vou levar três. E quanto custa um saco de mangas?"], ["A bag is four dollars. But it's cash only today, sorry.", "Um saco custa quatro dólares. Mas hoje é só dinheiro, desculpe."], ["No problem. I have ten dollars. Is the juice fresh?", "Sem problema. Tenho dez dólares. O suco é fresco?"], ["Of course, I squeeze it right here.", "Claro, eu espremo aqui mesmo."], ["Great. How much for a large cup?", "Ótimo. Quanto custa um copo grande?"], ["Three dollars. So that's nine dollars in total.", "Três dólares. Então dá nove dólares no total."], ["Here's ten dollars. Keep the change, and thanks!", "Aqui estão dez dólares. Pode ficar com o troco, e obrigado!"], ["Thank you! Here's a free sample of watermelon for the road.", "Obrigado! Aqui vai uma amostra grátis de melancia para a viagem."]], ["/ʃ/ em fresh e cash", "Faça o 'sh' como pedir silêncio: 'shh', sem o 'i' no final. 'Cash' termina em 'sh', não em 'câshi'.", ["fresh", "cash"]], ["___ for a bag of mangoes?", "How much", "How many", "Quanto custa um saco de mangas?", "Para preço use How much; How many é para contar coisas."], [["Lia asks, \"How much for a bag of mangoes?\"", "Lia pergunta: \"Quanto custa um saco de mangas?\""], ["I'll take three. And how much for a bag of mangoes?", "Vou levar três. E quanto custa um saco de mangas?"]], [{"t": "c", "q": "How much ___ a slice of watermelon?", "o": ["for", "to", "of"], "pt": "Quanto custa uma fatia de melancia?", "why": "Para perguntar o preço de algo, use How much for…?"}, {"t": "l", "say": "It's cash only today.", "o": ["It's cash only today.", "It's cash and card today.", "It's cash only tomorrow."], "why": "Você ouviu cash only (só dinheiro) e today."}, {"t": "b", "pt": "Quanto custa um saco de mangas?", "w": ["How", "much", "for", "a", "bag", "of", "mangoes"]}, {"t": "b", "pt": "Pode ficar com o troco.", "w": ["Keep", "the", "change", "please"]}]];
