englishA2Plans[288]={"title": "O segredo do pão de queijo da vovó", "file": "", "grammar": "Contar uma receita de família: used to e passado simples", "goal": "Conte como a sua avó cozinhava usando used to e o passado simples.", "words": [["family recipe", "receita de família"], ["grandma's recipe", "receita da vovó"], ["secret ingredient", "ingrediente secreto"], ["used to", "costumava"], ["from scratch", "do zero"], ["write down", "anotar"], ["by hand", "à mão"], ["pass down", "passar adiante"], ["crispy", "crocante"]]};
englishA2Content[288]=[[["Mia's grandma used to make cheese bread every Sunday, crispy outside and soft inside.", "A avó da Mia costumava fazer pão de queijo todo domingo, crocante por fora e macio por dentro."], ["She never used a mixer, because she mixed everything by hand.", "Ela nunca usava batedeira, porque misturava tudo à mão."], ["She used to make it from scratch and never measure anything.", "Ela costumava fazer do zero e nunca medir nada."], ["The secret ingredient was a little black pepper.", "O ingrediente secreto era um pouco de pimenta-do-reino."], ["Last year, Mia asked her to write down the family recipe.", "No ano passado, Mia pediu a ela que anotasse a receita de família."], ["Now Mia will pass down grandma's recipe to her own daughter.", "Agora Mia vai passar adiante a receita da vovó para a própria filha."]], [["Mia, this cheese bread tastes just like Grandma's!", "Mia, este pão de queijo tem gosto do da vovó!"], ["It's her recipe. I finally got it from her last month.", "É a receita dela. Finalmente consegui no mês passado."], ["Really? She never wanted to share it. She used to say, \"It's a secret.\"", "Sério? Ela nunca quis dividir. Ela costumava dizer: \"É segredo.\""], ["I know. She used to keep it in her head, so I watched her for a whole afternoon.", "Eu sei. Ela costumava guardar a receita de cabeça, então eu a observei a tarde inteira."], ["Was there a secret ingredient?", "Tinha algum ingrediente secreto?"], ["Yes! She used to add a little black pepper. Nobody knew that.", "Tinha! Ela costumava pôr um pouco de pimenta-do-reino. Ninguém sabia."], ["Wow. And did she make everything from scratch?", "Nossa. E ela fazia tudo do zero?"], ["Always. She mixed everything by hand and never used a machine.", "Sempre. Ela misturava tudo à mão e nunca usava máquina."], ["Now we have to keep it in the family. Will you teach my kids?", "Agora temos que manter isso na família. Você vai ensinar meus filhos?"], ["Of course. We'll all cook together next Sunday.", "Claro. Vamos todos cozinhar juntos no próximo domingo."]], ["/j/ em used e you", "No 'used to' o 'u' começa com um 'i' rápido: 'iust tu', e o 'd' quase some. Não diga 'ús tu'.", ["used", "you"]], ["Grandma ___ make cheese bread every Sunday.", "used to", "use to", "A vovó costumava fazer pão de queijo todo domingo.", "No passado, a forma certa é used to, com d no final."], [["Really? She never wanted to share it. She used to say, \"It's a secret.\"", "Sério? Ela nunca quis dividir. Ela costumava dizer: \"É segredo.\""], ["Yes! She used to add a little black pepper. Nobody knew that.", "Tinha! Ela costumava pôr um pouco de pimenta-do-reino. Ninguém sabia."]], [{"t": "c", "q": "My grandma ___ cook for fifteen people.", "o": ["used to", "use to", "was used to"], "pt": "Minha avó costumava cozinhar para quinze pessoas.", "why": "Used to + verbo conta um hábito do passado."}, {"t": "l", "say": "She used to mix everything by hand.", "o": ["She used to mix everything by hand.", "She uses to mix everything by hand.", "She used to make everything by hand."], "why": "Você ouviu used to mix e by hand."}, {"t": "b", "pt": "Minha avó fazia tudo do zero.", "w": ["My", "grandma", "made", "everything", "from", "scratch"]}, {"t": "b", "pt": "Ela costumava usar pimenta preta.", "w": ["She", "used", "to", "use", "black", "pepper"]}]];
