englishA2Plans[289]={"title": "Revisão: sopa de domingo da Rosa", "file": "", "grammar": "Revisão: imperativo, have to, used to e pedidos à mesa", "goal": "Revise o bloco da cozinha usando Dig in!, Help yourself e have to num jantar em família.", "words": [["help yourself", "sirva-se"], ["dig in", "pode comer"], ["second helping", "repetir o prato"], ["clear the table", "tirar a mesa"], ["do the dishes", "lavar a louça"], ["wash up", "lavar as mãos"], ["wipe up", "limpar com pano"], ["refill", "encher de novo"], ["left over", "sobrando"]]};
englishA2Content[289]=[[["Rosa makes chicken soup for Sunday dinner: first she chops up an onion and stirs in a cup of rice.", "A Rosa faz sopa de frango para o jantar de domingo: primeiro pica uma cebola e acrescenta uma xícara de arroz."], ["She ran out of salt, so Tom has to run to the store for a bag of salt.", "O sal acabou, então o Tom tem que correr ao mercado para comprar um saco de sal."], ["Rosa adds only a pinch, because she used to make it too salty.", "A Rosa põe só uma pitada, porque costumava deixar salgado demais."], ["Tom's friend Lia is vegan, so Rosa makes a second pot without meat, with beans instead of chicken.", "A amiga do Tom, a Lia, é vegana, então a Rosa faz uma segunda panela sem carne, com feijão em vez de frango."], ["Before dinner, everyone has to wash up, and then Rosa says, \"Dig in! Help yourself!\"", "Antes do jantar, todos têm que lavar as mãos, e então a Rosa diz: \"Podem comer! Sirvam-se!\""], ["After dinner, there is a lot left over, and Tom has to clear the table and do the dishes.", "Depois do jantar, sobra bastante, e o Tom tem que tirar a mesa e lavar a louça."]], [["Dig in, everybody! Help yourself to bread, too.", "Podem comer, pessoal! Sirvam-se de pão também."], ["Mom, this soup is amazing. Can I have a second helping?", "Mãe, esta sopa está incrível. Posso repetir?"], ["Of course. Would you like some more bread, too?", "Claro. Você gostaria de mais pão também?"], ["Yes, please. And can you refill the glasses? It's hot in here.", "Sim, por favor. E você pode encher os copos de novo? Está quente aqui."], ["Sure. Here you go. Don't spill it, OK?", "Claro. Aqui está. Não derrame, tá?"], ["Oh no, I spilled some on the table!", "Ai não, derramei um pouco na mesa!"], ["Wipe up the spill, please. Then we'll have dessert.", "Limpe o que derramou, por favor. Depois vamos comer a sobremesa."], ["Okay. There's a lot of soup left over. Can I take some to school?", "Tá. Sobrou bastante sopa. Posso levar um pouco para a escola?"], ["Sure. Put it in a box, and I'll write your name on it. You have to eat it in time, though.", "Claro. Ponha numa caixa, e eu escrevo seu nome. Mas você tem que comer a tempo."], ["Thanks, Mom. I'll clear the table and do the dishes after dessert, I promise.", "Obrigado, mãe. Vou tirar a mesa e lavar a louça depois da sobremesa, prometo."]], ["/ɪz/ em dishes e glasses", "Depois de 'sh' e 's', o plural ganha uma sílaba inteira: 'di-shiz', 'gla-siz'. Não diga 'dish' ou 'glass' sem esse 'iz' final.", ["dishes", "glasses"]], ["Please ___ yourself to more rice.", "help", "serve", "Por favor, sirva-se de mais arroz.", "A expressão fixa é help yourself; serve yourself soa estranho."], [["Dig in, everybody! Help yourself to bread, too.", "Podem comer, pessoal! Sirvam-se de pão também."], ["After dinner, there is a lot left over, and Tom has to clear the table and do the dishes.", "Depois do jantar, sobra bastante, e o Tom tem que tirar a mesa e lavar a louça."]], [{"t": "c", "q": "After dinner, I have to do the ___.", "o": ["dishes", "dish", "plate"], "pt": "Depois do jantar, tenho que lavar a louça.", "why": "Do the dishes é a expressão fixa, e dishes fica no plural."}, {"t": "l", "say": "Can I have a second helping?", "o": ["Can I have a second helping?", "Can I have a second cup?", "Can I have a second dish?"], "why": "Você ouviu second helping (repetir o prato)."}, {"t": "b", "pt": "Comece a comer e sirva-se.", "w": ["Dig", "in", "and", "help", "yourself"]}, {"t": "b", "pt": "O Tom tem que tirar a mesa.", "w": ["Tom", "has", "to", "clear", "the", "table"]}]];
englishA2PhotoThemes[289]="flag";
englishA2MiniStories[289]=["O jantar de domingo", "It is Sunday, and Rosa is making soup from her grandma's recipe.~É domingo, e Rosa está fazendo sopa com a receita da avó.|First, she chops up an onion and pours in a cup of rice.~Primeiro, ela pica uma cebola e despeja uma xícara de arroz.|Then she sees that she ran out of salt, so she sends Tom to the market.~Então ela vê que o sal acabou, e manda o Tom ao mercado.|A street vendor has a bag of salt, but it is cash only.~Um vendedor de rua tem um pacote de sal, mas é só dinheiro.|Tom has only a card, so he has to run home for cash.~Tom só tem cartão, então tem que correr para casa atrás de dinheiro.|He gets back just in time, and Rosa stirs in a pinch of salt.~Ele volta na hora certa, e Rosa acrescenta uma pitada de sal.|The soup isn't too salty, and it doesn't taste bland.~A sopa não está salgada demais, e também não está sem sabor.|The family digs in, and Tom has a second helping.~A família começa a comer, e Tom repete o prato.|After dinner, Tom clears the table and does the dishes.~Depois do jantar, Tom tira a mesa e lava a louça.|Rosa smiles and says, \"Grandma used to make it like this, too.\"~Rosa sorri e diz: \"A vovó também fazia assim.\""];
englishA2Plans[290]={"title": "Inscrição numa aula noturna de inglês", "file": "", "grammar": "have to / has to: o que você precisa fazer na matrícula", "goal": "Matricule-se numa aula usando I’d like to sign up… e have to / has to.", "words": [["sign up", "inscrever-se"], ["register", "matricular-se"], ["tuition fee", "mensalidade"], ["fill out", "preencher"], ["placement test", "teste de nível"], ["evening class", "aula noturna"], ["waiting list", "lista de espera"], ["spots left", "vagas sobrando"], ["in installments", "em parcelas"]]};
englishA2Content[290]=[[["Lia wants to sign up for an English class at a language school.", "Lia quer se inscrever numa aula de inglês numa escola de idiomas."], ["First, she has to take a placement test to check her level.", "Primeiro, ela precisa fazer um teste de nível para ver o seu nível."], ["The evening class has only two spots left, so she has to register today.", "A aula noturna tem só duas vagas sobrando, então ela precisa se matricular hoje."], ["At the desk, she has to fill out a short form and show a photo ID.", "No balcão, ela precisa preencher um formulário curto e mostrar um documento com foto."], ["The tuition fee is high, but she can pay in installments.", "A mensalidade é alta, mas ela pode pagar em parcelas."], ["On Monday night, Lia walks into her first class with a big smile.", "Na segunda à noite, Lia entra na primeira aula com um sorriso enorme."]], [["Good morning! How can I help you?", "Bom dia! Como posso ajudar?"], ["Hi. I’d like to sign up for an evening class, please.", "Oi. Eu gostaria de me inscrever numa aula noturna, por favor."], ["Sure. First, you have to take a placement test, so we know your level.", "Claro. Primeiro, você precisa fazer um teste de nível, para sabermos o seu nível."], ["Okay. Do I have to do it today?", "Certo. Eu preciso fazer hoje?"], ["No, but there are only two spots left. After that, you’ll go on the waiting list.", "Não, mas só restam duas vagas. Depois disso, você vai para a lista de espera."], ["Oh no! Then I’ll do the test now. And can I pay the tuition fee in installments?", "Ah, não! Então vou fazer o teste agora. E posso pagar a mensalidade em parcelas?"], ["Yes, in three parts. You also have to bring a photo ID on the first day.", "Sim, em três partes. Você também precisa trazer um documento com foto no primeiro dia."], ["No problem. I’ll register now and come to the first class on Monday.", "Sem problema. Vou me matricular agora e vir à primeira aula na segunda."]], ["/f/ em fill e form", "Encoste os dentes de cima no lábio de baixo e sopre o ar sem fazer a garganta vibrar. Não troque por 'p'.", ["fill", "form"]], ["Lia ___ show a photo ID at the desk.", "has to", "have to", "Lia precisa mostrar um documento com foto no balcão.", "Com she, he e nomes no singular, usa-se has to."], [["At the desk, she has to fill out a short form and show a photo ID.", "No balcão, ela precisa preencher um formulário curto e mostrar um documento com foto."], ["Sure. First, you have to take a placement test, so we know your level.", "Claro. Primeiro, você precisa fazer um teste de nível, para sabermos o seu nível."]], [{"t": "c", "q": "You don’t ___ pay everything today. You can pay in installments.", "o": ["have to", "has to", "having to"], "pt": "Você não precisa pagar tudo hoje. Pode pagar em parcelas.", "why": "Depois de don’t vem a forma simples: don’t have to = não precisa."}, {"t": "l", "say": "Do I have to take the test today?", "o": ["Do I have to take the test today?", "Do I have to take the test tonight?", "Did I have to take the test today?"], "why": "Você ouviu Do I have to… (preciso?) e today (hoje)."}, {"t": "b", "pt": "Ela tem de levar um documento com foto.", "w": ["She", "has", "to", "bring", "a", "photo", "ID"]}, {"t": "b", "pt": "Eu tenho de me matricular hoje.", "w": ["I", "have", "to", "register", "today"]}]];
