englishA2Plans[291]={"title": "Estudando para a prova de biologia", "file": "", "grammar": "remember to e don’t forget to + verbo", "goal": "Combine o estudo para a prova usando remember to e don’t forget to.", "words": [["revise", "revisar"], ["remember", "lembrar"], ["memorize", "memorizar"], ["highlight", "destacar (com marca-texto)"], ["flashcards", "cartões de estudo"], ["cram", "estudar de última hora"], ["by heart", "de cor"], ["slip my mind", "me escapar da memória"], ["get some sleep", "dormir um pouco"]]};
englishA2Content[291]=[[["Ben has a biology exam on Friday, so he has to study for it.", "Ben tem uma prova de biologia na sexta, então precisa estudar para ela."], ["He writes the hard words on flashcards and tries to memorize them.", "Ele escreve as palavras difíceis em cartões e tenta memorizá-las."], ["On Thursday he highlights his notes, but he forgets to eat lunch.", "Na quinta ele destaca suas anotações, mas esquece de almoçar."], ["That night he wants to cram, but his sister says, “Don’t forget to get some sleep.”", "Naquela noite ele quer estudar de última hora, mas a irmã diz: “Não esqueça de dormir um pouco.”"], ["In the morning, he revises one last time and remembers to bring a pen.", "De manhã, ele revisa uma última vez e se lembra de levar uma caneta."], ["The test is hard, but Ben remembers most of the answers.", "A prova é difícil, mas Ben se lembra da maioria das respostas."]], [["Ben, are you ready for the biology exam tomorrow?", "Ben, você está pronto para a prova de biologia amanhã?"], ["Not really. I’m trying to cram, but I can’t remember the names of the bones.", "Na verdade, não. Estou tentando estudar de última hora, mas não lembro os nomes dos ossos."], ["Use flashcards! I learned them by heart, and now the words won’t slip my mind.", "Use cartões! Eu aprendi de cor, e agora as palavras não me escapam da memória."], ["Good idea. I’ll make some now. Did you highlight the whole chapter?", "Boa ideia. Vou fazer alguns agora. Você destacou o capítulo inteiro?"], ["Yes, but I forgot to highlight page ten. Let’s do it together.", "Sim, mas esqueci de destacar a página dez. Vamos fazer juntos."], ["Thanks! Should I get some sleep, or should I keep studying?", "Valeu! Devo dormir um pouco ou continuar estudando?"], ["Get some sleep! And don’t forget to set your alarm.", "Durma um pouco! E não esqueça de colocar o despertador."], ["Okay, okay. I’ll remember to set it. See you at school!", "Tá bom, tá bom. Vou lembrar de colocar. Até a escola!"]], ["/r/ em revise e remember", "No /r/ inglês a língua não encosta em lugar nenhum: puxe-a para trás e arredonde levemente os lábios. Não diga 'h' no início.", ["revise", "remember"]], ["Don’t forget ___ your notes to class.", "to bring", "bringing", "Não esqueça de levar suas anotações para a aula.", "Depois de forget, a ação que ainda vamos fazer usa to + verbo."], [["On Thursday he highlights his notes, but he forgets to eat lunch.", "Na quinta ele destaca suas anotações, mas esquece de almoçar."], ["And don’t forget to set your alarm.", "E não esqueça de colocar o despertador."]], [{"t": "c", "q": "Please remember ___ your ID card tomorrow.", "o": ["to bring", "bring", "bringing"], "pt": "Por favor, lembre de trazer seu documento amanhã.", "why": "Para lembrar de uma ação futura, usa-se remember to + verbo."}, {"t": "l", "say": "I forgot to highlight page ten.", "o": ["I forgot to highlight page ten.", "I forgot to highlight page two.", "I forget to highlight page ten."], "why": "Você ouviu forgot (passado) e ten (dez)."}, {"t": "b", "pt": "Não se esqueça de dormir um pouco.", "w": ["Don’t", "forget", "to", "get", "some", "sleep"]}, {"t": "b", "pt": "Eu preciso estudar para a prova.", "w": ["I", "have", "to", "study", "for", "the", "exam"]}]];
englishA2PhotoThemes[291]="notebook";
englishA2Plans[292]={"title": "Pedindo ajuda ao professor depois da aula", "file": "", "grammar": "I don’t understand… e Could you + verbo…?", "goal": "Peça ajuda ao professor usando I don’t understand… e Could you explain…?", "words": [["explain", "explicar"], ["confused", "confuso"], ["translate", "traduzir"], ["ask for help", "pedir ajuda"], ["make sense", "fazer sentido"], ["office hours", "horário de atendimento"], ["raise your hand", "levantar a mão"], ["one more time", "mais uma vez"], ["go slower", "ir mais devagar"]]};
englishA2Content[292]=[[["Noah is confused in English class again today.", "Noah está confuso na aula de inglês de novo hoje."], ["The teacher talks fast, and he doesn’t understand the new words.", "A professora fala rápido, e ele não entende as palavras novas."], ["After class he asks, “Could you explain this sentence, please?”", "Depois da aula ele pergunta: “A senhora poderia explicar esta frase, por favor?”"], ["Ms. Hill says, “Don’t translate every word. Come to my office hours on Thursday.”", "A Sra. Hill diz: “Não traduza cada palavra. Venha ao meu horário de atendimento na quinta.”"], ["On Thursday she explains it one more time, and it starts to make sense.", "Na quinta ela explica mais uma vez, e começa a fazer sentido."], ["Now Noah isn’t afraid to ask for help.", "Agora Noah não tem medo de pedir ajuda."]], [["Noah, you look confused. Do you have a question?", "Noah, você parece confuso. Tem alguma dúvida?"], ["Yes. I don’t understand this word. Could you explain it, please?", "Sim. Eu não entendo esta palavra. A senhora poderia explicar, por favor?"], ["Sure. Don’t translate it into Portuguese. I’ll say it one more time in simple words.", "Claro. Não traduza para o português. Vou dizer mais uma vez com palavras simples."], ["Wait. Could you go slower, please? I can’t write that fast.", "Espere. A senhora poderia ir mais devagar, por favor? Não consigo escrever tão rápido."], ["No problem. Next time, raise your hand and tell me to go slower.", "Sem problema. Da próxima vez, levante a mão e peça para eu ir mais devagar."], ["I will. Now it starts to make sense, but I still don’t understand the last line.", "Vou fazer isso. Agora começa a fazer sentido, mas ainda não entendo a última linha."], ["Come to my office hours on Thursday, and we’ll do it together. Don’t be shy to ask for help.", "Venha ao meu horário de atendimento na quinta, e faremos juntos. Não tenha vergonha de pedir ajuda."], ["Perfect. I’ll be there at three, and I’ll bring my notebook.", "Perfeito. Estarei lá às três e vou levar meu caderno."]], ["/ə/ fraco em explain e confused", "Em explain e confused a primeira sílaba é fraca e rápida (/ə/); a força cai em 'plain' e 'fused'. Não pronuncie o 'e' como 'é'.", ["explain", "confused"]], ["Could you ___ this sentence, please?", "explain", "to explain", "A senhora poderia explicar esta frase, por favor?", "Depois de could vem o verbo na forma simples, sem to."], [["After class he asks, “Could you explain this sentence, please?”", "Depois da aula ele pergunta: “A senhora poderia explicar esta frase, por favor?”"], ["Could you go slower, please?", "A senhora poderia ir mais devagar, por favor?"]], [{"t": "c", "q": "I ___ understand the last question.", "o": ["don’t", "no", "doesn’t"], "pt": "Eu não entendo a última pergunta.", "why": "Com I, a negativa é I don’t + verbo. Não use no antes do verbo."}, {"t": "l", "say": "I don’t understand this word.", "o": ["I don’t understand this word.", "I do understand this word.", "I don’t understood this word."], "why": "Você ouviu don’t (negativa) e understand na forma simples."}, {"t": "b", "pt": "Você poderia explicar mais uma vez?", "w": ["Could", "you", "explain", "it", "one", "more", "time"]}, {"t": "b", "pt": "Você poderia ir mais devagar, por favor?", "w": ["Could", "you", "go", "slower", "please"]}]];
