englishA2Plans[293]={"title": "Trabalho em grupo sobre reciclagem", "file": "", "grammar": "Let’s + verbo e take turns, share ideas", "goal": "Organize um trabalho em grupo usando Let’s… e take turns.", "words": [["take turns", "revezar-se"], ["share ideas", "trocar ideias"], ["source", "fonte"], ["topic", "tema"], ["divide up", "dividir"], ["agree on", "concordar em"], ["do my part", "fazer a minha parte"], ["give feedback", "dar retorno"], ["fall behind", "ficar para trás"]]};
englishA2Content[293]=[[["Priya, Tom, and Elena have to write a short report about recycling.", "Priya, Tom e Elena precisam escrever um relatório curto sobre reciclagem."], ["Tom says, “Let’s take turns, so everyone can talk.”", "Tom diz: “Vamos nos revezar, para todo mundo poder falar.”"], ["First, they share ideas about the topic and agree on a title.", "Primeiro, eles trocam ideias sobre o tema e concordam em um título."], ["Priya says, “Let’s divide up the work, or we’ll fall behind.”", "Priya diz: “Vamos dividir o trabalho, ou vamos ficar para trás.”"], ["Tom finds a good source online, and Elena writes the first page.", "Tom acha uma boa fonte na internet, e Elena escreve a primeira página."], ["At the end, Elena says, “Let’s ask the teacher to give feedback.”", "No fim, Elena diz: “Vamos pedir para a professora dar retorno.”"]], [["Tom, we have to finish our report by Friday. Where should we start?", "Tom, temos de terminar o relatório até sexta. Por onde devemos começar?"], ["Let’s share ideas first, and then let’s take turns writing.", "Vamos trocar ideias primeiro e depois nos revezar para escrever."], ["Okay. I found a good source: an article about plastic bags.", "Certo. Achei uma boa fonte: um artigo sobre sacolas plásticas."], ["Great. But Priya is absent again today. I’m afraid she’ll fall behind.", "Ótimo. Mas a Priya faltou de novo hoje. Tenho medo de que ela fique para trás."], ["Let’s divide up the work, then. I can write the introduction and send her the part about glass.", "Então vamos dividir o trabalho. Eu posso escrever a introdução e mandar para ela a parte sobre vidro."], ["Good idea. I’ll do my part tonight, and we can agree on the title tomorrow.", "Boa ideia. Faço a minha parte hoje à noite, e podemos concordar no título amanhã."], ["Perfect. And let’s ask Ms. Hill to give feedback before Friday.", "Perfeito. E vamos pedir à Sra. Hill para dar retorno antes de sexta."], ["Sure. See you at the library at four, and I’ll bring my laptop.", "Claro. Nos vemos na biblioteca às quatro, e eu levo meu notebook."]], ["/ɜr/ em turns e first", "O som /ɜr/ é um 'é' fechado com a língua levantada para trás; não separe em 'târ-ns'. Segure o som e termine com o 's'.", ["turns", "first"]], ["Let’s ___ turns with the laptop.", "take", "taking", "Vamos nos revezar com o notebook.", "Depois de Let’s vem o verbo na forma simples: take."], [["Tom says, “Let’s take turns, so everyone can talk.”", "Tom diz: “Vamos nos revezar, para todo mundo poder falar.”"], ["Let’s share ideas first, and then let’s take turns writing.", "Vamos trocar ideias primeiro e depois nos revezar para escrever."]], [{"t": "c", "q": "Let’s ___ the work, so nobody falls behind.", "o": ["divide up", "dividing up", "to divide up"], "pt": "Vamos dividir o trabalho, para ninguém ficar para trás.", "why": "Depois de Let’s usa-se o verbo na forma simples, sem to e sem -ing."}, {"t": "l", "say": "Let’s take turns reading the source.", "o": ["Let’s take turns reading the source.", "Let’s take turns reading the sources.", "Let’s take turns writing the source."], "why": "Você ouviu reading (leitura) e source no singular."}, {"t": "b", "pt": "Vamos trocar ideias primeiro.", "w": ["Let’s", "share", "ideas", "first"]}, {"t": "b", "pt": "Vamos dividir o trabalho.", "w": ["Let’s", "divide", "up", "the", "work"]}]];
