englishA2Plans[294]={"title": "Praticando inglês num encontro de conversação", "file": "", "grammar": "practice + verbo-ing e make mistakes", "goal": "Fale sobre treinar o idioma usando practice + -ing e make mistakes.", "words": [["improve", "melhorar"], ["practise", "praticar (grafia britânica; nos EUA, practice)"], ["fluently", "com fluência"], ["pronounce", "pronunciar"], ["make mistakes", "cometer erros"], ["make progress", "fazer progresso"], ["native speaker", "falante nativo"], ["language exchange", "troca de idiomas"], ["word for word", "palavra por palavra"], ["slip of the tongue", "escorregão na fala"]]};
englishA2Content[294]=[[["Omar goes to a language exchange every Tuesday.", "Omar vai a um encontro de troca de idiomas toda terça."], ["He wants to practice speaking English with a native speaker.", "Ele quer praticar falar inglês com um falante nativo."], ["At first, he can’t pronounce the word “thirty” correctly.", "No começo, ele não consegue pronunciar a palavra “thirty” direito."], ["He says “dirty” instead, but his partner Sara just laughs kindly.", "Ele diz “dirty”, mas a parceira, Sara, só ri com carinho."], ["Now he practices speaking for twenty minutes every day.", "Agora ele pratica falar por vinte minutos todo dia."], ["After two months, he speaks fluently about his day.", "Depois de dois meses, ele fala com fluência sobre o seu dia."]], [["Omar, your English is much better than last month!", "Omar, seu inglês está bem melhor que no mês passado!"], ["Really? I practice speaking every day, but I still make mistakes.", "Sério? Eu pratico falar todo dia, mas ainda cometo erros."], ["Everybody does. When I speak Portuguese, I translate word for word, and it sounds funny.", "Todo mundo comete. Quando falo português, eu traduzo palavra por palavra, e fica engraçado."], ["Ha! I can’t pronounce “comfortable” yet. Listen: com-for-ta-bel.", "Ha! Ainda não consigo pronunciar “comfortable”. Ouça: com-for-ta-bel."], ["Almost! Try again slowly. Practice saying it ten times, and you’ll get it.", "Quase! Tente de novo, devagar. Pratique dizer dez vezes, e você vai conseguir."], ["Comfortable. Yes! Sorry, I’m nervous, so I often have a slip of the tongue.", "Comfortable. Isso! Desculpe, fico nervoso, então muitas vezes escorrego na fala."], ["By the way, my teacher writes practise with an s. Is that wrong?", "A propósito, meu professor escreve practise com s. Está errado?"], ["No, that’s British spelling. In the U.S., we write practice.", "Não, é grafia britânica. Nos EUA, escrevemos practice."], ["Got it! Let’s keep practicing speaking every Tuesday, and I’ll improve and make progress.", "Entendi! Vamos continuar praticando falar toda terça, e eu vou melhorar e fazer progresso."], ["Deal! In three months, you’ll speak fluently on the phone.", "Combinado! Em três meses, você vai falar com fluência ao telefone."]], ["/p/ aspirado em practise e pronounce", "No início de palavra, o /p/ inglês solta um sopro de ar: segure um papel na frente da boca e ele deve mexer. Não troque por 'b'.", ["practise", "pronounce"]], ["Omar practices ___ English with Sara every Tuesday.", "speaking", "to speak", "Omar pratica falar inglês com a Sara toda terça.", "Depois de practice usa-se o verbo com -ing: practice speaking."], [["He wants to practice speaking English with a native speaker.", "Ele quer praticar falar inglês com um falante nativo."], ["Really? I practice speaking every day, but I still make mistakes.", "Sério? Eu pratico falar todo dia, mas ainda cometo erros."]], [{"t": "c", "q": "Sara says, “Practice ___ the word ten times.”", "o": ["saying", "to say", "say"], "pt": "Sara diz: “Pratique dizer a palavra dez vezes.”", "why": "Depois de practice usa-se -ing: practice saying."}, {"t": "l", "say": "I practice speaking every day.", "o": ["I practice speaking every day.", "I practiced speaking every day.", "I practice speaking every night."], "why": "Você ouviu practice (presente) e every day (todo dia)."}, {"t": "b", "pt": "Eu pratico falar inglês todo dia.", "w": ["I", "practice", "speaking", "English", "every", "day"]}, {"t": "b", "pt": "Eu ainda cometo erros.", "w": ["I", "still", "make", "mistakes"]}]];
