englishA2Plans[296]={"title": "Usando a biblioteca da universidade", "file": "", "grammar": "Prazos: due on + data, due in + período", "goal": "Fale de prazos de devolução usando due on May 12 e due in two weeks.", "words": [["library card", "cartão da biblioteca"], ["come back", "voltar"], ["look through", "dar uma olhada em"], ["database", "banco de dados"], ["call number", "código do livro na estante"], ["study room", "sala de estudo"], ["reserve a book", "reservar um livro"], ["print out", "imprimir"], ["quiet zone", "zona de silêncio"], ["overdue book", "livro atrasado"]]};
englishA2Content[296]=[[["Mia needs a library card to borrow books for her science project.", "Mia precisa de uma carteirinha da biblioteca para pegar livros emprestados para o projeto de ciências."], ["She starts to look through the online database and finds a book about birds.", "Ela começa a procurar no banco de dados online e acha um livro sobre pássaros."], ["The call number is 598, so she walks to the third floor.", "O número de chamada é 598, então ela sobe ao terceiro andar."], ["The book is due in two weeks, so she goes to the quiet zone and starts reading.", "O livro vence em duas semanas, então ela vai para a zona de silêncio e começa a ler."], ["Later she finds a free study room, and she wants to print out three pages.", "Mais tarde ela acha uma sala de estudo livre e quer imprimir três páginas."], ["Her friend wants to reserve a book too, so Mia says, “It’s due on May 12, so come back then.”", "A amiga também quer reservar um livro, então Mia diz: “Ele vence em 12 de maio, então volte nessa data.”"]], [["Hi. I’d like to borrow these three books, please.", "Oi. Eu gostaria de pegar estes três livros emprestados, por favor."], ["Sure. Can I see your library card?", "Claro. Posso ver a sua carteirinha da biblioteca?"], ["Here you go. Also, I have an overdue book. How much is the fine?", "Aqui está. Além disso, tenho um livro atrasado. Quanto é a multa?"], ["It’s two dollars. The new books are due on May 12.", "São dois dólares. Os livros novos vencem em 12 de maio."], ["May 12? That’s only two weeks. Can I keep one longer?", "12 de maio? São só duas semanas. Posso ficar com um por mais tempo?"], ["Yes. If you renew it online, it’s due in a month.", "Sim. Se você renovar online, ele vence em um mês."], ["Perfect. And is the study room free this afternoon? I also need to print out a few pages.", "Perfeito. E a sala de estudo está livre esta tarde? Também preciso imprimir algumas páginas."], ["Yes, room 4 is free at two. I’ll write your name down.", "Sim, a sala 4 está livre às duas. Vou anotar o seu nome."]], ["/b/ em borrow e books", "Feche os lábios e faça a voz vibrar logo no início, sem 'i' antes. Em borrow, o 'r' final não é forte como no português.", ["borrow", "books"]], ["The books are due ___ May 12.", "on", "in", "Os livros vencem em 12 de maio.", "Com uma data exata (May 12), usa-se on; com um período (two weeks), usa-se in."], [["The book is due in two weeks, so she goes to the quiet zone and starts reading.", "O livro vence em duas semanas, então ela vai para a zona de silêncio e começa a ler."], ["It’s two dollars. The new books are due on May 12.", "São dois dólares. Os livros novos vencem em 12 de maio."]], [{"t": "c", "q": "The project is due ___ two days.", "o": ["in", "on", "at"], "pt": "O projeto vence em dois dias.", "why": "Para um período a partir de agora (two days), usa-se due in."}, {"t": "l", "say": "The book is due on May twelve.", "o": ["The book is due on May twelve.", "The book is due on May two.", "The book is due in May twelve."], "why": "Você ouviu on e a data twelve (doze)."}, {"t": "b", "pt": "O livro vence na sexta-feira.", "w": ["The", "book", "is", "due", "on", "Friday"]}, {"t": "b", "pt": "O trabalho vence em uma semana.", "w": ["The", "paper", "is", "due", "in", "a", "week"]}]];
