englishA2Plans[297]={"title": "Candidatura a um intercâmbio no Canadá", "file": "", "grammar": "apply for / apply to e planos com will", "goal": "Fale de um intercâmbio usando apply for, apply to e will.", "words": [["apply", "candidatar-se"], ["study abroad", "estudar no exterior"], ["exchange program", "programa de intercâmbio"], ["exchange student", "estudante de intercâmbio"], ["recommendation letter", "carta de recomendação"], ["application form", "formulário de inscrição"], ["acceptance letter", "carta de aceitação"], ["host family", "família anfitriã"], ["living abroad", "morar no exterior"], ["culture shock", "choque cultural"]]};
englishA2Content[297]=[[["Kenji wants to study abroad next year, so he looks for an exchange program.", "Kenji quer estudar no exterior no ano que vem, então procura um programa de intercâmbio."], ["He decides to apply for a scholarship and to apply to a school in Toronto.", "Ele decide se candidatar a uma bolsa e se candidatar a uma escola em Toronto."], ["First, he fills out the application form and asks his teacher for a recommendation letter.", "Primeiro, ele preenche o formulário de inscrição e pede uma carta de recomendação ao professor."], ["Two months later, he gets an acceptance letter by email.", "Dois meses depois, ele recebe uma carta de aceitação por e-mail."], ["He will be an exchange student, and he will live with a host family.", "Ele vai ser estudante de intercâmbio e vai morar com uma família anfitriã."], ["He is excited, but he is a little afraid of culture shock.", "Ele está animado, mas tem um pouco de medo do choque cultural."]], [["Elena, guess what? I got the acceptance letter this morning!", "Elena, adivinha? Recebi a carta de aceitação esta manhã!"], ["Really? That’s great! I didn’t know you applied to a school in Canada.", "Sério? Que ótimo! Não sabia que você se candidatou a uma escola no Canadá."], ["Yes, and I also applied for a scholarship.", "Sim, e também me candidatei a uma bolsa."], ["Wow! Will you get the scholarship too?", "Nossa! Você vai receber a bolsa também?"], ["I don’t know yet. I’ll find out in July, and I’ll leave in August.", "Ainda não sei. Vou saber em julho, e vou embora em agosto."], ["Are you nervous about living abroad? I think I’d feel culture shock.", "Você está nervoso de morar no exterior? Acho que eu sentiria choque cultural."], ["A little. But my host family is really nice, and I’ll send you photos every week, I promise.", "Um pouco. Mas minha família anfitriã é muito legal, e vou mandar fotos toda semana, prometo."], ["Deal! And next year, I’ll apply for the same exchange program.", "Combinado! E no ano que vem, vou me candidatar ao mesmo programa de intercâmbio."]], ["/ɔ/ aberto em abroad e August", "Abra bem a boca e arredonde os lábios, quase um 'ó' longo: a-BRÓÓD, Ó-gust. Não diga 'abrôde' fechado.", ["abroad", "August"]], ["Kenji wants to apply ___ a scholarship.", "for", "to", "Kenji quer se candidatar a uma bolsa.", "Para pedir algo (bolsa, vaga, emprego), usa-se apply for; para a instituição, apply to."], [["He decides to apply for a scholarship and to apply to a school in Toronto.", "Ele decide se candidatar a uma bolsa e se candidatar a uma escola em Toronto."], ["Deal! And next year, I’ll apply for the same exchange program.", "Combinado! E no ano que vem, vou me candidatar ao mesmo programa de intercâmbio."]], [{"t": "c", "q": "She applied ___ three universities in Canada.", "o": ["to", "for", "at"], "pt": "Ela se candidatou a três universidades no Canadá.", "why": "Para a instituição para a qual você se candidata, usa-se apply to."}, {"t": "l", "say": "I’ll find out in July.", "o": ["I’ll find out in July.", "I’ll find out in June.", "I found out in July."], "why": "Você ouviu I’ll (futuro com will) e July (julho)."}, {"t": "b", "pt": "Eu vou me candidatar a uma bolsa.", "w": ["I’ll", "apply", "for", "a", "scholarship"]}, {"t": "b", "pt": "Ele vai morar com uma família anfitriã.", "w": ["He", "will", "live", "with", "a", "host", "family"]}]];
