englishA2Plans[298]={"title": "Apresentação oral curta na aula", "file": "", "grammar": "Sequência: first of all, then, in conclusion, to sum up", "goal": "Organize uma apresentação curta usando first of all, then e to sum up.", "words": [["to sum up", "resumindo"], ["first of all", "antes de tudo"], ["in conclusion", "em conclusão"], ["rehearse", "ensaiar"], ["eye contact", "contato visual"], ["note cards", "fichas de anotações"], ["stand up", "levantar-se"], ["speak clearly", "falar com clareza"], ["mind went blank", "deu branco"], ["in other words", "em outras palavras"]]};
englishA2Content[298]=[[["Priya has to give a short presentation about her hometown.", "Priya precisa fazer uma apresentação curta sobre a cidade dela."], ["She rehearses at home and writes the main points on note cards.", "Ela ensaia em casa e escreve os pontos principais em fichas."], ["In class, she has to stand up and speak clearly.", "Na aula, ela precisa se levantar e falar com clareza."], ["First of all, she shows a map, and then she talks about the food.", "Antes de tudo, ela mostra um mapa, e depois fala sobre a comida."], ["She makes eye contact with the class and answers two questions.", "Ela faz contato visual com a turma e responde a duas perguntas."], ["To sum up, she says, “My city is small, but I love it.”", "Resumindo, ela diz: “Minha cidade é pequena, mas eu a amo.”"]], [["Sam, how was your presentation this morning?", "Sam, como foi sua apresentação hoje de manhã?"], ["Scary! First of all, I was shaking, and then my mind went blank.", "Assustador! Antes de tudo, eu estava tremendo, e depois deu branco."], ["Oh no! What did you do?", "Ai, não! O que você fez?"], ["I looked at my note cards, took a breath, and made eye contact with the teacher.", "Olhei para as minhas fichas, respirei fundo e fiz contato visual com a professora."], ["Good. Did you speak clearly? I always talk too fast.", "Bom. Você falou com clareza? Eu sempre falo rápido demais."], ["Yes, and it was easy after the first minute. In other words, I just need to rehearse more.", "Sim, e foi fácil depois do primeiro minuto. Em outras palavras, só preciso ensaiar mais."], ["You’re right. In conclusion, we both need practice. Can you listen to me tonight at seven?", "Você tem razão. Em conclusão, nós dois precisamos de prática. Pode me ouvir hoje às sete?"], ["Sure. Come to my house, and bring your note cards. Then we’ll rehearse together.", "Claro. Venha à minha casa e traga suas fichas. Depois vamos ensaiar juntos."]], ["/ʃ/ em presentation e shaking", "Faça o som de 'psiu' pedindo silêncio: lábios um pouco arredondados e ar contínuo. É 'sh', não 'ch' de chuva.", ["presentation", "shaking"]], ["First of all, I’ll show a map. ___, I’ll talk about the food.", "Then", "After", "Antes de tudo, vou mostrar um mapa. Depois, vou falar da comida.", "Para a segunda etapa de uma sequência usa-se Then; After precisa de um complemento (After lunch)."], [["First of all, she shows a map, and then she talks about the food.", "Antes de tudo, ela mostra um mapa, e depois fala sobre a comida."], ["To sum up, she says, “My city is small, but I love it.”", "Resumindo, ela diz: “Minha cidade é pequena, mas eu a amo.”"]], [{"t": "c", "q": "___, my city is small but friendly.", "o": ["To sum up", "To summary", "For sum up"], "pt": "Resumindo, minha cidade é pequena, mas simpática.", "why": "To sum up fecha a apresentação; as outras formas não existem."}, {"t": "l", "say": "Then she talks about the food.", "o": ["Then she talks about the food.", "Then she talks about the foot.", "Then she walks about the food."], "why": "Você ouviu talks e food, não walks nem foot."}, {"t": "b", "pt": "Antes de tudo, eu vou mostrar um mapa.", "w": ["First", "of", "all", "I’ll", "show", "a", "map"]}, {"t": "b", "pt": "Para resumir, a cidade é pequena.", "w": ["To", "sum", "up", "the", "city", "is", "small"]}]];
