englishA2Plans[299]={"title": "Revisão: o último dia do semestre", "file": "", "grammar": "Revisão: passado simples e estruturas das lições 641–649", "goal": "Conte como foi o semestre revisando passado simples, have to, Let’s e apply for.", "words": [["end of the semester", "fim do semestre"], ["study schedule", "plano de estudos"], ["all-nighter", "noite em claro estudando"], ["term paper", "trabalho do semestre"], ["semester break", "férias entre semestres"], ["proud of", "orgulhoso de"], ["look back", "olhar para trás"], ["make plans", "fazer planos"], ["in the end", "no fim"]]};
englishA2Content[299]=[[["It’s the end of the semester, and Sam wants to look back.", "É o fim do semestre, e Sam quer olhar para trás."], ["In September, he signed up for an evening class and made a study schedule.", "Em setembro, ele se inscreveu numa aula noturna e fez um plano de estudos."], ["He often felt confused, so he went to office hours and said, “Could you explain it, please?”", "Ele muitas vezes ficava confuso, então foi ao horário de atendimento e disse: “O senhor poderia explicar, por favor?”"], ["Before the final exam, he pulled an all-nighter and made flashcards.", "Antes da prova final, ele passou uma noite em claro e fez cartões de estudo."], ["His term paper is due on June 5, and he hopes he will get a good grade.", "O trabalho do semestre vence em 5 de junho, e ele espera tirar uma boa nota."], ["Now the semester break starts, and Sam wants to make plans with his classmates.", "Agora as férias começam, e Sam quer fazer planos com os colegas."]], [["Sam, tomorrow the semester break starts! Do you remember our first class?", "Sam, amanhã começam as férias! Você se lembra da nossa primeira aula?"], ["Of course! I was so confused, and I had to ask the teacher to explain everything.", "Claro! Eu estava tão confuso, e tive de pedir ao professor para explicar tudo."], ["Ha! First, you forgot your book, and then you lost your pen.", "Ha! Primeiro você esqueceu o livro, e depois perdeu a caneta."], ["True. But I improved a lot. I practiced speaking with a native speaker every week.", "Verdade. Mas melhorei muito. Pratiquei falar com um falante nativo toda semana."], ["Your English is really good now. Are you going to apply for the exchange program in Toronto?", "Seu inglês está muito bom agora. Você vai se candidatar ao programa de intercâmbio em Toronto?"], ["Yes! I’ll apply for it in May, and I’ll rehearse with my note cards.", "Vou sim! Vou me candidatar em maio e vou ensaiar com as minhas fichas."], ["Great. Let’s make plans for the summer, and let’s take turns choosing the place.", "Ótimo. Vamos fazer planos para o verão e nos revezar na escolha do lugar."], ["Perfect. To sum up: we study on Mondays, and we go to the beach on weekends.", "Perfeito. Resumindo: estudamos às segundas e vamos à praia nos fins de semana."], ["Deal. I’m proud of us. We passed every class, even history!", "Combinado. Tenho orgulho de nós. Passamos em todas as matérias, até em história!"], ["In the end, all that hard work was worth it. Meet me at the café at four!", "No fim, todo esse trabalho duro valeu a pena. Encontre-me no café às quatro!"]], ["/h/ em hard e history", "O /h/ inglês é só um sopro de ar saindo da garganta, sem rouquidão. Não troque por 'r' como em 'rard'.", ["hard", "history"]], ["He ___ a study schedule in September.", "made", "maked", "Ele fez um plano de estudos em setembro.", "Make é irregular: o passado é made."], [["In September, he signed up for an evening class and made a study schedule.", "Em setembro, ele se inscreveu numa aula noturna e fez um plano de estudos."], ["Ha! First, you forgot your book, and then you lost your pen.", "Ha! Primeiro você esqueceu o livro, e depois perdeu a caneta."]], [{"t": "c", "q": "Last night, Sam ___ an all-nighter.", "o": ["pulled", "pull", "pulls"], "pt": "Ontem à noite, Sam passou uma noite em claro.", "why": "Last night indica passado, então usa-se pulled."}, {"t": "l", "say": "I practiced speaking every week.", "o": ["I practiced speaking every week.", "I practice speaking every week.", "I practiced speaking every weekend."], "why": "Você ouviu practiced (passado) e week (semana)."}, {"t": "b", "pt": "Vamos nos revezar para escolher o lugar.", "w": ["Let’s", "take", "turns", "choosing", "the", "place"]}, {"t": "b", "pt": "Eu me candidatei a um programa de intercâmbio.", "w": ["I", "applied", "for", "an", "exchange", "program"]}]];
englishA2PhotoThemes[299]="flag";
englishA2MiniStories[299]=["O semestre da Lia", "Lia wants to sign up for an evening English class, but first she has to take a placement test.~Lia quer se inscrever numa aula noturna de inglês, mas primeiro precisa fazer um teste de nível.|She pays the tuition fee in installments and goes to her first class on Monday.~Ela paga a mensalidade em parcelas e vai à primeira aula na segunda.|She is confused by the grammar, so she goes to office hours and says, “Could you explain it one more time?”~Ela fica confusa com a gramática, então vai ao horário de atendimento e diz: “A senhora poderia explicar mais uma vez?”|In her study group, the students take turns and share ideas for their report.~No grupo de estudo, os alunos se revezam e trocam ideias para o relatório.|Lia practices speaking with a native speaker every Tuesday, and her English improves.~Lia pratica falar com uma falante nativa toda terça, e o inglês dela melhora.|Before the final exam, she makes flashcards and learns the words by heart.~Antes da prova final, ela faz cartões de estudo e aprende as palavras de cor.|She remembers to get some sleep, and she passes the exam with a good grade.~Ela lembra de dormir um pouco e passa na prova com uma boa nota.|Her library books are due on May 12, so she returns them early, and then she applies for an exchange program.~Os livros da biblioteca vencem em 12 de maio, então ela os devolve antes e depois se candidata a um intercâmbio.|First of all, she rehearses her speech with note cards, and then she stands up and speaks clearly.~Antes de tudo, ela ensaia o discurso com fichas, e depois se levanta e fala com clareza.|To sum up, it was a hard semester, but Lia is proud of herself.~Resumindo, foi um semestre difícil, mas Lia tem orgulho de si mesma."];
englishA2Plans[300]={"title": "Aviso de nevasca antes da viagem", "file": "", "grammar": "Previsão do tempo: will, might, it’s going to", "goal": "Fale do tempo de amanhã usando will, might e is going to.", "words": [["weather forecast", "previsão do tempo"], ["blizzard", "nevasca"], ["chance of rain", "chance de chuva"], ["heavy rain", "chuva forte"], ["icy", "gelado, com gelo"], ["clear up", "abrir (o tempo)"], ["thaw", "derreter"], ["snowflake", "floco de neve"], ["raindrop", "gota de chuva"]]};
englishA2Content[300]=[[["Omar checked the weather forecast on Thursday morning.", "Omar viu a previsão do tempo na quinta de manhã."], ["A blizzard is going to hit the town tonight.", "Uma nevasca vai atingir a cidade esta noite."], ["There might be heavy rain first, and then the roads will be icy.", "Pode haver chuva forte primeiro, e depois as ruas vão ficar com gelo."], ["He saw one raindrop on the window, then big snowflakes.", "Ele viu uma gota de chuva na janela e depois grandes flocos de neve."], ["The forecast says the sky will clear up on Saturday.", "A previsão diz que o céu vai abrir no sábado."], ["After that, the snow will thaw, so Omar will drive home on Sunday.", "Depois disso, a neve vai derreter, então Omar vai dirigir para casa no domingo."]], [["Did you see the weather forecast for this weekend, Omar?", "Você viu a previsão do tempo para este fim de semana, Omar?"], ["Yes, I did. A blizzard is going to hit the town tonight.", "Vi, sim. Uma nevasca vai atingir a cidade esta noite."], ["Really? Is there still a chance of rain tomorrow?", "Sério? Ainda tem chance de chuva amanhã?"], ["Yes, sixty percent. It might rain until noon, then change to snow.", "Tem, sessenta por cento. Pode chover até o meio-dia e depois virar neve."], ["The roads are always icy after a storm. I’m worried about the drive.", "As ruas ficam sempre com gelo depois de uma tempestade. Estou preocupado com a viagem."], ["Me too. Let’s leave at eight tonight, before it gets bad.", "Eu também. Vamos sair às oito da noite, antes de piorar."], ["Good idea. When does it clear up? I have a meeting on Monday.", "Boa ideia. Quando o tempo abre? Tenho uma reunião na segunda."], ["Saturday afternoon. The snow will thaw on Sunday, so you’ll be fine.", "Sábado à tarde. A neve vai derreter no domingo, então você vai ficar bem."]], ["/θ/ em thaw e Thursday", "Para o /θ/, coloque a ponta da língua entre os dentes e solte o ar, sem virar /f/ nem /t/.", ["thaw", "Thursday"]], ["Look at those black clouds! It ___ rain very soon.", "is going to", "is going", "Olha aquelas nuvens pretas! Vai chover logo.", "Para previsão com sinais no presente use is going to; is going sozinho fica incompleto."], [["A blizzard is going to hit the town tonight.", "Uma nevasca vai atingir a cidade esta noite."], ["Yes, sixty percent. It might rain until noon, then change to snow.", "Tem, sessenta por cento. Pode chover até o meio-dia e depois virar neve."]], [{"t": "c", "q": "I’m not sure, but it ___ snow on Saturday.", "o": ["might", "might to", "mights"], "pt": "Não tenho certeza, mas pode nevar no sábado.", "why": "Might vem direto antes do verbo, sem to e sem -s."}, {"t": "l", "say": "The roads will be icy tonight.", "o": ["The roads will be icy tonight.", "The roads were icy tonight.", "The roads will be rainy tonight."], "why": "Will be icy fala do futuro: esta noite."}, {"t": "b", "pt": "Vai nevar muito esta noite.", "w": ["It", "is", "going", "to", "snow", "a", "lot", "tonight"]}, {"t": "b", "pt": "Talvez chova amanhã.", "w": ["It", "might", "rain", "tomorrow"]}]];
