englishA2Plans[301]={"title": "Escolhendo o lugar da barraca na floresta", "file": "", "grammar": "Acampar com segurança: should e shouldn’t", "goal": "Dê conselhos de segurança no acampamento com should e shouldn’t.", "words": [["set up camp", "montar acampamento"], ["put up", "armar (barraca)"], ["hiker", "trilheiro, caminhante"], ["camper", "acampante"], ["rocky", "pedregoso"], ["meadow", "campo, pradaria"], ["moose", "alce"], ["owl", "coruja"], ["head out", "partir, sair"], ["trail mix", "mistura de castanhas e frutas secas"]]};
englishA2Content[301]=[[["Priya and Sam are hikers, and they want to set up camp before dark.", "Priya e Sam são trilheiros e querem montar acampamento antes de escurecer."], ["They find a flat meadow, but the ground near the trail is rocky.", "Eles acham um campo plano, mas o chão perto da trilha é pedregoso."], ["They put up the tent under a big tree.", "Eles armam a barraca debaixo de uma árvore grande."], ["A friendly camper tells them a moose walks by the river at night.", "Um acampante simpático conta que um alce passa pelo rio à noite."], ["Sam packs the trail mix in a safe bag, far from the tent.", "Sam guarda a mistura de castanhas numa bolsa segura, longe da barraca."], ["At night an owl sings, and in the morning they head out early.", "À noite uma coruja canta, e de manhã eles partem cedo."]], [["We should set up camp before it gets dark, Priya.", "Devemos montar acampamento antes de escurecer, Priya."], ["Agreed. Is this meadow flat enough? The ground near the trail looks rocky.", "Concordo. Este campo é plano o bastante? O chão perto da trilha parece pedregoso."], ["The middle is soft. We can put up the tent there.", "O meio é macio. Podemos armar a barraca ali."], ["Okay. Should we keep the trail mix inside the tent?", "Certo. Devemos guardar a mistura de castanhas dentro da barraca?"], ["No, we shouldn’t. A camper told me a moose and other animals come at night.", "Não, não devemos. Um acampante me disse que um alce e outros animais vêm à noite."], ["Really? Then I’ll hang the food bag on that tree, far from us.", "Sério? Então vou pendurar a sacola de comida naquela árvore, longe de nós."], ["Good idea. Do you hear that? I think it’s an owl. Let’s sleep early and head out at six tomorrow.", "Boa ideia. Está ouvindo? Acho que é uma coruja. Vamos dormir cedo e sair às seis amanhã."], ["Six o’clock it is. I’ll set my alarm.", "Seis horas, então. Vou ligar o despertador."]], ["/aʊ/ em owl e out", "O som /aʊ/ começa aberto, como “a”, e fecha para “u”: owl não é “ól” e out não é “áut” curto.", ["owl", "out"]], ["You ___ keep food in the tent. It isn’t safe.", "shouldn’t", "don’t should", "Você não deve guardar comida na barraca. Não é seguro.", "A negativa de should é shouldn’t, sem do."], [["Okay. Should we keep the trail mix inside the tent?", "Certo. Devemos guardar a mistura de castanhas dentro da barraca?"], ["No, we shouldn’t. A camper told me a moose and other animals come at night.", "Não, não devemos. Um acampante me disse que um alce e outros animais vêm à noite."]], [{"t": "c", "q": "We ___ set up camp before dark.", "o": ["should", "should to", "do should"], "pt": "Devemos montar acampamento antes de escurecer.", "why": "Should é seguido direto do verbo, sem to."}, {"t": "l", "say": "We should put up the tent here.", "o": ["We should put up the tent here.", "We should put up the tent there.", "We shouldn’t put up the tent here."], "why": "A frase fala de armar a barraca aqui, com should."}, {"t": "b", "pt": "Devemos montar a barraca aqui.", "w": ["We", "should", "put", "up", "the", "tent", "here"]}, {"t": "b", "pt": "Você não deve andar na trilha à noite.", "w": ["You", "shouldn’t", "walk", "on", "the", "trail", "at", "night"]}]];
