englishA2Plans[303]={"title": "Reunião de moradores para cortar lixo e conta de luz", "file": "", "grammar": "Reciclar e economizar: reduce, reuse e should", "goal": "Sugira como reduzir e reutilizar usando should e shouldn’t.", "words": [["reduce", "reduzir"], ["recycled", "reciclado"], ["appliance", "eletrodoméstico"], ["energy bill", "conta de energia"], ["reusable bag", "sacola reutilizável"], ["climate", "clima"], ["conservation", "conservação"], ["electric", "elétrico"], ["save energy", "economizar energia"]]};
englishA2Content[303]=[[["Rosa and Tom live in an apartment, and their energy bill is very high.", "Rosa e Tom moram num apartamento, e a conta de energia deles está muito alta."], ["Tom says they should reduce the electric appliances that stay on all day.", "Tom diz que eles devem reduzir os eletrodomésticos que ficam ligados o dia todo."], ["Rosa wants to reuse old jars and bring a reusable bag to the market.", "Rosa quer reutilizar potes velhos e levar uma sacola reutilizável ao mercado."], ["She buys recycled paper because it helps the climate.", "Ela compra papel reciclado porque ele ajuda o clima."], ["They turn off the lights when they leave a room, and that helps them save energy.", "Eles apagam as luzes ao sair do cômodo, e isso ajuda a economizar energia."], ["After one month, their bill is twenty dollars lower.", "Depois de um mês, a conta deles está vinte dólares mais baixa."]], [["Look at this energy bill, Rosa. It’s ninety dollars!", "Olhe esta conta de energia, Rosa. São noventa dólares!"], ["That’s too much. We should reduce the time the appliances are on.", "É demais. Devemos reduzir o tempo em que os eletrodomésticos ficam ligados."], ["Like the old electric heater? I use it every night.", "Como o aquecedor elétrico velho? Eu uso toda noite."], ["Yes. You shouldn’t leave it on while you sleep. A blanket is cheaper.", "Sim. Você não deve deixá-lo ligado enquanto dorme. Um cobertor é mais barato."], ["True. And can we reuse these glass jars instead of buying new ones?", "Verdade. E podemos reutilizar estes potes de vidro em vez de comprar novos?"], ["Sure. I bought a reusable bag, too, so we won’t use plastic.", "Claro. Comprei uma sacola reutilizável também, então não vamos usar plástico."], ["My teacher says conservation starts at home, and it’s good for the climate.", "Minha professora diz que a conservação começa em casa e é boa para o clima."], ["She’s right. Let’s try to save energy for a month and check the bill.", "Ela tem razão. Vamos tentar economizar energia por um mês e conferir a conta."]], ["/r/ em reduce e reuse", "O /r/ inglês não vibra: a língua se enrola para trás sem tocar o céu da boca, diferente do “r” de rato.", ["reduce", "reuse"]], ["We ___ reduce the plastic we use at home.", "should", "should to", "Devemos reduzir o plástico que usamos em casa.", "Depois de should vem o verbo sem to."], [["That’s too much. We should reduce the time the appliances are on.", "É demais. Devemos reduzir o tempo em que os eletrodomésticos ficam ligados."], ["Yes. You shouldn’t leave it on while you sleep. A blanket is cheaper.", "Sim. Você não deve deixá-lo ligado enquanto dorme. Um cobertor é mais barato."]], [{"t": "c", "q": "Can we ___ these jars instead of buying new ones?", "o": ["reuse", "reduce", "reused"], "pt": "Podemos reutilizar estes potes em vez de comprar novos?", "why": "Reuse é usar de novo; reduce é usar menos."}, {"t": "l", "say": "Turn off the lights when you leave.", "o": ["Turn off the lights when you leave.", "Turn on the lights when you leave.", "Turn off the lights when you live."], "why": "A instrução é apagar as luzes ao sair."}, {"t": "b", "pt": "Devemos usar uma sacola reutilizável.", "w": ["We", "should", "use", "a", "reusable", "bag"]}, {"t": "b", "pt": "Você deve desligar os aparelhos.", "w": ["You", "should", "turn", "off", "the", "appliances"]}]];
