englishA2Plans[304]={"title": "Temporal repentino no campo de beisebol", "file": "", "grammar": "Um dia de tempestade: past continuous", "goal": "Conte o que você estava fazendo quando a tempestade começou.", "words": [["take cover", "se abrigar"], ["pour down", "chover forte"], ["knock out", "derrubar, deixar sem energia"], ["blow away", "levar pelo vento"], ["sudden", "repentino"], ["flash flood", "enchente repentina"], ["power line", "fio de energia"], ["get soaked", "ficar encharcado"], ["soaking wet", "encharcado"]]};
englishA2Content[304]=[[["Mia and Ben were playing baseball when a sudden storm started.", "Mia e Ben estavam jogando beisebol quando uma tempestade repentina começou."], ["Rain began to pour down while the coach was calling everyone in.", "A chuva começou a cair forte enquanto o técnico chamava todo mundo."], ["The wind started to blow away the caps and the paper cups.", "O vento começou a levar os bonés e os copos de papel."], ["Nobody wanted to get soaked, so they ran to take cover under the roof of the snack bar.", "Ninguém queria se encharcar, então correram para se abrigar sob o telhado da lanchonete."], ["Water was flowing down the street, and the lights were out.", "A água descia pela rua, e as luzes estavam apagadas."], ["At six, the rain stopped, but a flash flood warning was still on the radio.", "Às seis, a chuva parou, mas o aviso de enchente repentina ainda estava no rádio."]], [["What happened when the storm started, Mia?", "O que aconteceu quando a tempestade começou, Mia?"], ["I was sitting in the car with my mom. The rain was pouring down so hard!", "Eu estava sentada no carro com minha mãe. A chuva caía muito forte!"], ["I was still on the field. In two minutes I was soaking wet!", "Eu ainda estava no campo. Em dois minutos eu estava encharcada!"], ["Wow! Did a tree branch fall on a power line near the park?", "Nossa! Um galho caiu num fio de energia perto do parque?"], ["Yes, it was! And the storm knocked out the power at my house.", "Estava, sim! E a tempestade deixou minha casa sem energia."], ["What were you doing when the power went out?", "O que você estava fazendo quando a energia acabou?"], ["We were watching TV when everything went dark, so we lit candles.", "Estávamos vendo TV quando tudo apagou, então acendemos velas."], ["I’m glad you’re safe. Let’s check on the neighbors tomorrow.", "Que bom que você está bem. Vamos ver como estão os vizinhos amanhã."]], ["-ed: /ɪd/ em started e /t/ em stopped", "Depois de t ou d, o -ed soa /ɪd/ (started); depois de p, soa só /t/ (stopped), sem vogal extra.", ["started", "stopped"]], ["We ___ watching TV when the lights went out.", "were", "was", "Estávamos assistindo TV quando as luzes apagaram.", "We combina com were no past continuous."], [["We were watching TV when everything went dark, so we lit candles.", "Estávamos vendo TV quando tudo apagou, então acendemos velas."], ["I was sitting in the car with my mom. The rain was pouring down so hard!", "Eu estava sentada no carro com minha mãe. A chuva caía muito forte!"]], [{"t": "c", "q": "It ___ pouring down when I left home.", "o": ["was", "were", "is"], "pt": "Estava chovendo forte quando saí de casa.", "why": "It combina com was no passado contínuo."}, {"t": "l", "say": "The wind was blowing hard.", "o": ["The wind was blowing hard.", "The wind blows hard.", "The wind was blown hard."], "why": "Was blowing mostra uma ação em andamento no passado."}, {"t": "b", "pt": "Eu estava jogando quando a chuva começou.", "w": ["I", "was", "playing", "when", "the", "rain", "started"]}, {"t": "b", "pt": "Eles estavam correndo para se proteger.", "w": ["They", "were", "running", "to", "take", "cover"]}]];
