englishA2Plans[305]={"title": "Fotos do mesmo quintal nas quatro estações", "file": "", "grammar": "Estações do ano: comparações e used to", "goal": "Compare as estações e fale do que você costumava fazer com used to.", "words": [["rake leaves", "juntar folhas com rastelo"], ["heat wave", "onda de calor"], ["bloom", "florescer"], ["wither", "murchar"], ["spring break", "férias de primavera"], ["shovel snow", "tirar neve com pá"], ["fall colors", "cores do outono"], ["go sledding", "andar de trenó"], ["sun hat", "chapéu de sol"], ["build a snowman", "fazer um boneco de neve"]]};
englishA2Content[305]=[[["Elena shows Kenji four photos of her grandfather’s yard.", "Elena mostra a Kenji quatro fotos do quintal do avô dela."], ["In spring, the flowers bloom, and it is warmer than winter.", "Na primavera, as flores florescem, e é mais quente que o inverno."], ["In summer there is a heat wave, so Grandpa wears a sun hat.", "No verão há uma onda de calor, então o vovô usa um chapéu de sol."], ["In fall, the family likes to rake leaves, but the flowers wither.", "No outono, a família gosta de juntar folhas, mas as flores murcham."], ["In winter, the kids used to build a snowman and go sledding.", "No inverno, as crianças costumavam fazer um boneco de neve e andar de trenó."], ["Grandpa used to shovel snow every morning, so the path was always clean.", "O vovô costumava tirar a neve com pá toda manhã, então o caminho ficava sempre limpo."]], [["This yard looks bigger than ours. Did your family live here long?", "Este quintal parece maior que o nosso. Sua família morou aqui muito tempo?"], ["Yes. I used to spend every spring break here with my cousins.", "Sim. Eu costumava passar todas as férias de primavera aqui com meus primos."], ["Does it get hot there? Summers in my city are terrible.", "Lá fica quente? Os verões na minha cidade são terríveis."], ["We had a heat wave last July, and it was almost a hundred degrees!", "Tivemos uma onda de calor em julho, e foram quase quarenta graus!"], ["And what about fall? The fall colors in this photo are beautiful.", "E o outono? As cores do outono nesta foto são lindas."], ["They’re my favorite part of the year. We used to rake leaves and jump in them.", "São a minha parte favorita do ano. A gente costumava juntar folhas e pular nelas."], ["Fun! And in winter? Did you shovel snow?", "Divertido! E no inverno? Vocês tiravam a neve?"], ["Every morning, and then we built a snowman. I miss those days.", "Toda manhã, e depois fazíamos um boneco de neve. Tenho saudade daqueles dias."]], ["/ʌ/ em summer e sun", "O /ʌ/ é uma vogal curta e relaxada, entre “a” e “ó”: sun não é “sân” fechado nem “son”.", ["summer", "sun"]], ["I ___ go sledding every winter when I was a kid.", "used to", "use to", "Eu costumava andar de trenó todo inverno quando era criança.", "Em frases afirmativas, o passado de hábito é used to, com d."], [["Yes. I used to spend every spring break here with my cousins.", "Sim. Eu costumava passar todas as férias de primavera aqui com meus primos."], ["In spring, the flowers bloom, and it is warmer than winter.", "Na primavera, as flores florescem, e é mais quente que o inverno."]], [{"t": "c", "q": "Summer is ___ than spring.", "o": ["hotter", "more hot", "most hot"], "pt": "O verão é mais quente que a primavera.", "why": "Adjetivo curto forma o comparativo com -er: hotter."}, {"t": "l", "say": "Fall is colder than summer.", "o": ["Fall is colder than summer.", "Fall is warmer than summer.", "Fall is colder than spring."], "why": "Colder than summer compara o outono ao verão."}, {"t": "b", "pt": "Eu costumava juntar folhas no outono.", "w": ["I", "used", "to", "rake", "leaves", "in", "fall"]}, {"t": "b", "pt": "O inverno é mais frio que o outono.", "w": ["Winter", "is", "colder", "than", "fall"]}]];
