englishA2Plans[307]={"title": "Trocando o carro por outro jeito de ir ao trabalho", "file": "", "grammar": "Poluição e transporte: because, so, therefore", "goal": "Explique causa e resultado com because, so e therefore.", "words": [["traffic jam", "engarrafamento"], ["pollute", "poluir"], ["fumes", "fumaça, gases"], ["polluted", "poluído"], ["clean air", "ar limpo"], ["carpool", "carona solidária"], ["electric car", "carro elétrico"], ["public transportation", "transporte público"], ["environment", "meio ambiente"], ["bike lane", "ciclovia"]]};
englishA2Content[307]=[[["Omar drives to work, but the traffic jam makes him late every day.", "Omar dirige para o trabalho, mas o engarrafamento o atrasa todo dia."], ["Cars pollute the city because their fumes fill the air.", "Os carros poluem a cidade porque a fumaça deles enche o ar."], ["The air is polluted, so many people cough in winter.", "O ar está poluído, então muita gente tosse no inverno."], ["Omar wants clean air for his kids, so he thinks about a hybrid or an electric car.", "Omar quer ar limpo para os filhos, então pensa num carro híbrido ou elétrico."], ["Omar wants clean air for his kids, so he thinks about an electric car or a carpool.", "Omar quer ar limpo para os filhos, então pensa num carro elétrico ou numa carona solidária."], ["Now there is a new bike lane on Main Street, so Omar will try it on Monday.", "Agora há uma ciclovia nova na Main Street, então Omar vai testá-la na segunda."]], [["You look tired, Omar. Was the traffic bad again?", "Você parece cansado, Omar. O trânsito estava ruim de novo?"], ["Terrible. I spent an hour in a traffic jam and I was late again.", "Terrível. Passei uma hora num engarrafamento e me atrasei de novo."], ["That’s why I take public transportation. It’s cheaper because I don’t buy gas.", "Por isso eu uso transporte público. É mais barato porque não compro gasolina."], ["Maybe I should try it, or start a carpool. My car pollutes the air a lot.", "Talvez eu deva tentar, ou montar uma carona solidária. Meu carro polui muito o ar."], ["Right. The fumes are bad for the environment. Therefore, an electric car is better.", "Verdade. A fumaça faz mal ao meio ambiente. Portanto, um carro elétrico é melhor."], ["Electric cars are expensive, so I’m thinking about a bike instead.", "Carros elétricos são caros, então estou pensando numa bicicleta."], ["There’s a new bike lane on Main Street! It’s only twenty minutes from your house.", "Tem uma ciclovia nova na Main Street! Fica a só vinte minutos da sua casa."], ["Great, I’ll ride on Monday. My kids need clean air.", "Ótimo, vou pedalar na segunda. Meus filhos precisam de ar limpo."]], ["/iː/ em clean e /ɪ/ em fill", "Em clean o /iː/ é longo e tenso; em fill o /ɪ/ é curto e relaxado. Não diga as duas iguais.", ["clean", "fill"]], ["The air is polluted, ___ we should use public transportation.", "so", "because", "O ar está poluído, então devemos usar transporte público.", "So liga o resultado; because introduz a causa."], [["That’s why I take public transportation. It’s cheaper because I don’t buy gas.", "Por isso eu uso transporte público. É mais barato porque não compro gasolina."], ["Electric cars are expensive, so I’m thinking about a bike instead.", "Carros elétricos são caros, então estou pensando numa bicicleta."]], [{"t": "c", "q": "I’m late ___ there is a traffic jam.", "o": ["because", "so", "but"], "pt": "Estou atrasado porque há um engarrafamento.", "why": "Because explica a causa do atraso."}, {"t": "l", "say": "The fumes are bad for the environment.", "o": ["The fumes are bad for the environment.", "The fumes are good for the environment.", "The fumes are bad for the government."], "why": "Fumes bad for the environment: fumaça faz mal ao meio ambiente."}, {"t": "b", "pt": "Eu uso transporte público porque é mais barato.", "w": ["I", "use", "public", "transportation", "because", "it’s", "cheaper"]}, {"t": "b", "pt": "Há um engarrafamento, então estou atrasado.", "w": ["There’s", "a", "traffic", "jam", "so", "I’m", "late"]}]];
