englishA2Plans[308]={"title": "Mutirão de limpeza na reserva natural", "file": "", "grammar": "Voluntariado: have to, can e can’t", "goal": "Diga o que você tem que fazer e o que pode ou não pode fazer como voluntário.", "words": [["clean up", "limpar, fazer faxina"], ["wetland", "área alagada, brejo"], ["tree planting", "plantio de árvores"], ["give back", "retribuir, ajudar de volta"], ["pitch in", "ajudar, colaborar"], ["nature reserve", "reserva natural"], ["riverbank", "margem do rio"], ["boardwalk", "passarela de madeira"], ["wear gloves", "usar luvas"]]};
englishA2Content[308]=[[["Ana volunteers at a nature reserve on Saturdays because she wants to give back.", "Ana é voluntária numa reserva natural aos sábados porque quer retribuir."], ["This week, the group has to clean up the riverbank near the wetland.", "Nesta semana, o grupo tem que limpar a margem do rio perto do brejo."], ["Everyone has to wear gloves, and nobody can leave trash on the boardwalk.", "Todos têm que usar luvas, e ninguém pode deixar lixo na passarela."], ["Her friend Ben can’t come, but he can help with tree planting next month.", "O amigo Ben não pode vir, mas pode ajudar no plantio de árvores no mês que vem."], ["The leader says, “If everyone can pitch in, we can finish by noon.”", "O líder diz: “Se todos puderem ajudar, terminamos ao meio-dia.”"], ["They finish at eleven thirty, and they are tired but happy.", "Eles terminam às onze e meia e estão cansados, mas felizes."]], [["Hi, I’m Leo. It’s my first day at the nature reserve.", "Oi, sou o Leo. É meu primeiro dia na reserva natural."], ["Welcome, Leo! I’m Ana. Do you have gloves? You have to wear gloves here.", "Bem-vindo, Leo! Sou a Ana. Você tem luvas? Aqui é preciso usar luvas."], ["Yes, I brought a pair. What do we have to do today?", "Tenho, trouxe um par. O que temos que fazer hoje?"], ["We have to clean up the riverbank by the wetland. It’s full of bottles.", "Temos que limpar a margem do rio perto do brejo. Está cheia de garrafas."], ["Okay. Can I walk on the boardwalk with the bags?", "Certo. Posso andar na passarela com os sacos?"], ["Yes, you can. But you can’t go into the water.", "Pode, sim. Mas você não pode entrar na água."], ["Of course. Why do you volunteer here, Ana?", "Claro. Por que você é voluntária aqui, Ana?"], ["I want to give back to nature. Next month we have a tree planting day. Can you pitch in?", "Quero retribuir à natureza. No mês que vem temos um dia de plantio de árvores. Você pode ajudar?"], ["Sure, count me in. I’ll bring two friends.", "Claro, conte comigo. Vou levar dois amigos."], ["Perfect. See you next Saturday!", "Perfeito. Até sábado que vem!"]], ["/v/ em volunteer e give", "No /v/, os dentes de cima tocam o lábio de baixo e a voz vibra; give termina com /v/, não com /f/ nem com “i”.", ["volunteer", "give"]], ["You ___ wear gloves here.", "have to", "has to", "Você tem que usar luvas aqui.", "Com you, use have to; has to só vai com he, she e it."], [["Welcome, Leo! I’m Ana. Do you have gloves? You have to wear gloves here.", "Bem-vindo, Leo! Sou a Ana. Você tem luvas? Aqui é preciso usar luvas."], ["We have to clean up the riverbank by the wetland. It’s full of bottles.", "Temos que limpar a margem do rio perto do brejo. Está cheia de garrafas."]], [{"t": "c", "q": "Ben ___ come today because he is sick.", "o": ["can’t", "doesn’t can", "isn’t can"], "pt": "O Ben não pode vir hoje porque está doente.", "why": "A negativa de can é can’t, sem do."}, {"t": "l", "say": "We have to clean up the riverbank.", "o": ["We have to clean up the riverbank.", "We had to clean up the riverbank.", "We have to pick up the riverbank."], "why": "Have to clean up fala de uma obrigação agora."}, {"t": "b", "pt": "Temos que limpar a margem do rio.", "w": ["We", "have", "to", "clean", "up", "the", "riverbank"]}, {"t": "b", "pt": "Você pode caminhar na passarela.", "w": ["You", "can", "walk", "on", "the", "boardwalk"]}]];
