englishA2Plans[309]={"title": "Revisão: fim de semana ao ar livre", "file": "", "grammar": "Revisão: will/might, past continuous, have to, because e so", "goal": "Revise o bloco contando um fim de semana no lago.", "words": [["go canoeing", "andar de canoa"], ["life jacket", "colete salva-vidas"], ["sleeping bag", "saco de dormir"], ["bug spray", "repelente"], ["fishing rod", "vara de pescar"], ["shoreline", "margem, orla"], ["bird watching", "observação de pássaros"], ["trail map", "mapa da trilha"], ["sandy", "arenoso"], ["starry sky", "céu estrelado"]]};
englishA2Content[309]=[[["Lia and Noah checked the weather forecast, and it said the sky might clear up on Saturday.", "Lia e Noah olharam a previsão do tempo, e ela dizia que o céu poderia abrir no sábado."], ["They set up camp on the sandy shoreline, and Noah, who loves his garden, brought herbs from his flower bed.", "Eles armaram acampamento na margem arenosa, e o Noah, que ama sua horta, trouxe ervas do canteiro dele."], ["Lia was checking the trail map when a raindrop hit it, so they put up the tent fast.", "A Lia estava olhando o mapa da trilha quando uma gota caiu nele, então eles armaram a barraca rápido."], ["They have to wear a life jacket to go canoeing, because the lake is deep.", "Eles precisam usar colete salva-vidas para ir de canoa, porque o lago é fundo."], ["Noah used to hate fishing, but his new fishing rod is more fun than his old one.", "O Noah costumava odiar pescar, mas a vara nova é mais divertida que a velha."], ["At night they did some bird watching under the starry sky, and Lia saw an owl.", "À noite eles observaram pássaros sob o céu estrelado, e a Lia viu uma coruja."]], [["Did you pack the bug spray and the sleeping bags, Noah? The mosquitoes might be bad.", "Você trouxe o repelente e os sacos de dormir, Noah? Os mosquitos podem estar ruins."], ["Yes, I did. They’re in the reusable bag next to the trail mix.", "Trouxe sim. Estão na sacola reutilizável, ao lado da mistura de castanhas."], ["Great. The forecast says it’s going to be sunny, so we should bring more water.", "Ótimo. A previsão diz que vai fazer sol, então devemos levar mais água."], ["Good idea. And we have to wear a life jacket if we go canoeing.", "Boa ideia. E temos que usar colete salva-vidas se formos de canoa."], ["I know. I was looking at the trail map when you called. The sandy shoreline is ten minutes away.", "Eu sei. Eu olhava o mapa da trilha quando você ligou. A margem arenosa fica a dez minutos."], ["Perfect. I used to hate fishing, but I want to try my new fishing rod there.", "Perfeito. Eu odiava pescar, mas quero testar minha vara nova lá."], ["Then let’s go. Put up the tent first, and we can do some bird watching later.", "Então vamos. Arme a barraca primeiro, e depois podemos observar pássaros."], ["Sounds good. Afterwards we should clean up the shoreline, because we don’t want to leave trash.", "Combinado. Depois devemos limpar a margem, porque não queremos deixar lixo."], ["Of course. The animals that live here need a clean lake.", "Claro. Os animais que vivem aqui precisam de um lago limpo."], ["Agreed. See you at seven, then!", "Combinado. Até as sete, então!"]], ["/ŋ/ em canoeing e fishing", "No /ŋ/ final, a parte de trás da língua toca o céu da boca e o ar sai pelo nariz, sem um “g” forte no fim.", ["canoeing", "fishing"]], ["It’s going to be cold, ___ I’ll bring a sleeping bag.", "so", "because", "Vai fazer frio, então vou levar um saco de dormir.", "So liga o resultado: o frio leva à decisão."], [["Good idea. And we have to wear a life jacket if we go canoeing.", "Boa ideia. E temos que usar colete salva-vidas se formos de canoa."], ["They have to wear a life jacket to go canoeing, because the lake is deep.", "Eles precisam usar colete salva-vidas para ir de canoa, porque o lago é fundo."]], [{"t": "c", "q": "We were ___ when it started to rain.", "o": ["canoeing", "canoe", "canoed"], "pt": "Estávamos remando quando começou a chover.", "why": "Was/were pede o verbo com -ing: canoeing."}, {"t": "l", "say": "Don’t forget the bug spray.", "o": ["Don’t forget the bug spray.", "Don’t forget the big spray.", "Don’t forget the bug stray."], "why": "Bug spray é o repelente de insetos."}, {"t": "b", "pt": "Temos que usar colete salva-vidas.", "w": ["We", "have", "to", "wear", "life", "jackets"]}, {"t": "b", "pt": "Eu costumava odiar pescar.", "w": ["I", "used", "to", "hate", "fishing"]}]];
englishA2PhotoThemes[309]="flag";
englishA2MiniStories[309]=["Um fim de semana no lago", "Last weekend, Lia and Noah checked the weather forecast before their camping trip.~No fim de semana passado, Lia e Noah viram a previsão do tempo antes da viagem de camping.|It said there might be a little rain, but the sky was going to clear up.~Dizia que podia chover um pouco, mas o céu ia abrir.|They had to pack carefully: a tent, a sleeping bag, bug spray, and a trail map.~Eles tiveram que arrumar tudo com cuidado: barraca, saco de dormir, repelente e mapa da trilha.|On Saturday morning, they were canoeing on the lake when a sudden wind started.~No sábado de manhã, eles remavam no lago quando um vento repentino começou.|They wore life jackets, so they were safe, and they took cover under the trees.~Eles usavam coletes salva-vidas, então estavam seguros, e se abrigaram sob as árvores.|After the rain, they saw an eagle that was flying over the lake.~Depois da chuva, viram uma águia que voava sobre o lago.|They cleaned up the sandy shoreline because they wanted to give back to nature.~Eles limparam a margem arenosa porque queriam retribuir à natureza.|At night they didn’t need an electric light, because the starry sky was bright enough.~À noite eles não precisaram de luz elétrica, porque o céu estrelado estava claro o bastante.|Noah used to hate camping, but now he thinks it’s better than staying home.~Noah costumava odiar camping, mas agora acha melhor do que ficar em casa.|On Sunday they drove home without a traffic jam, and they were already planning the next trip.~No domingo eles voltaram para casa sem engarrafamento e já planejavam a próxima viagem."];
englishA2Plans[310]={"title": "Maratona de série no fim de semana", "file": "", "grammar": "Passado simples para contar um filme ou série: watched, played, read", "goal": "Conte o que você assistiu e fale do enredo, do ator e da resenha usando o passado simples.", "words": [["fantasy", "fantasia"], ["plot twist", "reviravolta"], ["special effects", "efeitos especiais"], ["main character", "personagem principal"], ["subtitles", "legendas"], ["teaser", "prévia curta"], ["leading role", "papel principal"], ["rave reviews", "críticas elogiosas"], ["season finale", "final da temporada"]]};
englishA2Content[310]=[[["Last weekend, Lia read some rave reviews and watched the teaser of a new fantasy series.", "No fim de semana passado, Lia leu críticas elogiosas e assistiu à prévia de uma nova série de fantasia."], ["She loved the plot, so she watched the whole season in two days.", "Ela adorou o enredo, então assistiu à temporada inteira em dois dias."], ["The leading role went to a young actor, and he played the main character very well.", "O papel principal ficou com um ator jovem, e ele interpretou muito bem o personagem principal."], ["Ben turned on the subtitles because the actors spoke very fast.", "Ben ligou as legendas porque os atores falavam muito rápido."], ["The special effects were great, and the season finale had a big plot twist.", "Os efeitos especiais eram ótimos, e o final da temporada teve uma grande reviravolta."], ["Lia wrote her own review that night, and she gave the series five stars.", "Lia escreveu a própria resenha naquela noite e deu cinco estrelas à série."]], [["Lia, did you finish that new series last weekend?", "Lia, você terminou aquela série nova no fim de semana passado?"], ["Yes! I watched the whole season on Saturday and Sunday.", "Terminei! Assisti à temporada inteira no sábado e no domingo."], ["Really? I read the rave reviews, but I didn't watch the teaser.", "Sério? Li as críticas elogiosas, mas não vi a prévia."], ["Good. The teaser showed the best scene, and it ruined the surprise.", "Ótimo. A prévia mostrou a melhor cena e estragou a surpresa."], ["Who played the leading role? Was the actor good?", "Quem fez o papel principal? O ator era bom?"], ["He was great. He played the main character, and I cried twice.", "Era ótimo. Ele fez o personagem principal, e eu chorei duas vezes."], ["What about the special effects? Did they look real?", "E os efeitos especiais? Pareciam reais?"], ["Yes, but the plot twist in the season finale was even better.", "Sim, mas a reviravolta no final da temporada foi ainda melhor."], ["No spoilers! I'll watch it tonight with the subtitles on.", "Sem spoilers! Vou assistir hoje à noite com as legendas ligadas."], ["Good idea. Some actors spoke really fast, so I used them too.", "Boa ideia. Alguns atores falavam muito rápido, então eu também usei."]], ["/f/ em fantasy e effects", "Encoste os dentes de cima no lábio de baixo e deixe o ar sair; não troque por 'p'. Em fantasy e effects o /f/ é leve e contínuo.", ["fantasy", "effects"]], ["Lia ___ the whole season last weekend.", "watched", "did watched", "Lia assistiu à temporada inteira no fim de semana passado.", "No passado simples, os verbos regulares ganham -ed (watched); não use did com verbo no passado."], [["She loved the plot, so she watched the whole season in two days.", "Ela adorou o enredo, então assistiu à temporada inteira em dois dias."], ["The leading role went to a young actor, and he played the main character very well.", "O papel principal ficou com um ator jovem, e ele interpretou muito bem o personagem principal."]], [{"t": "c", "q": "Ben ___ the teaser, so he didn't know the plot.", "o": ["didn't watch", "didn't watched", "not watch"], "pt": "Ben não assistiu à prévia, então não sabia o enredo.", "why": "Na negativa do passado, usamos didn't + verbo base: didn't watch."}, {"t": "l", "say": "The actor played the main character.", "o": ["The actor played the main character.", "The actor play the main character.", "The actor plays the main character."], "why": "Contamos algo que já aconteceu: played, com -ed."}, {"t": "b", "pt": "Nós assistimos à série ontem.", "w": ["We", "watched", "the", "series", "yesterday"]}, {"t": "b", "pt": "Ela escreveu uma resenha ontem.", "w": ["She", "wrote", "a", "review", "yesterday"]}]];
