englishA2Plans[311]={"title": "Do ingresso ao autógrafo no show", "file": "", "grammar": "Present perfect com since: has loved, have been", "goal": "Fale de uma banda e de um show usando since e o passado simples.", "words": [["front row", "primeira fila"], ["sing along", "cantar junto"], ["backstage", "bastidores"], ["performer", "artista (no palco)"], ["autograph", "autógrafo"], ["fan club", "fã-clube"], ["tour bus", "ônibus da turnê"], ["sound check", "passagem de som"], ["live music", "música ao vivo"]]};
englishA2Content[311]=[[["Mia has loved the band Blue Roads since she was twelve.", "Mia adora a banda Blue Roads desde os doze anos."], ["She has been in their fan club since last year, and she bought two tickets online.", "Ela está no fã-clube deles desde o ano passado e comprou dois ingressos on-line."], ["At the concert, she and Omar sat in the front row.", "No show, ela e Omar sentaram na primeira fila."], ["The performer sang her favorite song, and everyone started to sing along.", "O artista cantou a música favorita dela, e todo mundo começou a cantar junto."], ["After the show, Mia waited near the tour bus for an autograph.", "Depois do show, Mia esperou perto do ônibus da turnê por um autógrafo."], ["Omar has wanted to see them since January, and now he's a fan too.", "Omar queria ver a banda desde janeiro, e agora ele também é fã."]], [["Mia, how was the concert on Friday night?", "Mia, como foi o show na sexta à noite?"], ["Amazing! I've loved Blue Roads since I was twelve, and we sat in the front row.", "Incrível! Adoro a Blue Roads desde os doze anos, e sentamos na primeira fila."], ["Seriously? How did you get such good seats?", "Sério? Como você conseguiu lugares tão bons?"], ["I've been in their fan club since last year, so I got an email before the sale.", "Estou no fã-clube deles desde o ano passado, então recebi um e-mail antes da venda."], ["Lucky you! Did you go backstage after the show?", "Que sorte! Vocês foram aos bastidores depois do show?"], ["No, but we waited by the tour bus, and the singer signed my ticket.", "Não, mas esperamos perto do ônibus da turnê, e o cantor assinou meu ingresso."], ["I've wanted to see live music since January, but tickets are so expensive.", "Quero ver música ao vivo desde janeiro, mas os ingressos são muito caros."], ["Ours were only forty dollars. Come with me next time.", "Os nossos custaram só quarenta dólares. Venha comigo da próxima vez."], ["Deal! When does the band play here again?", "Combinado! Quando a banda toca aqui de novo?"], ["In March. I'll send you the link tonight.", "Em março. Vou te mandar o link hoje à noite."]], ["/ŋ/ em sing e along", "Em sing e along o 'ng' é um único som nasal no fundo da boca; não solte um 'g' no final.", ["sing", "along"]], ["Mia ___ the band since she was twelve.", "has loved", "loves", "A Mia ama a banda desde os doze anos.", "Com since usamos o present perfect: has loved."], [["Mia has loved the band Blue Roads since she was twelve.", "Mia adora a banda Blue Roads desde os doze anos."], ["I've been in their fan club since last year, so I got an email before the sale.", "Estou no fã-clube deles desde o ano passado, então recebi um e-mail antes da venda."]], [{"t": "c", "q": "My brother ___ this band for three years.", "o": ["has liked", "likes", "is liking"], "pt": "Meu irmão gosta dessa banda há três anos.", "why": "Com for e um período de tempo, usamos o present perfect: has liked."}, {"t": "l", "say": "We sat in the front row.", "o": ["We sat in the front row.", "We sat in the front door.", "We saw in the front row."], "why": "Front row é a primeira fila, e sat é o passado de sit."}, {"t": "b", "pt": "Todos começaram a cantar junto.", "w": ["Everyone", "started", "to", "sing", "along"]}, {"t": "b", "pt": "Nós vimos a passagem de som.", "w": ["We", "watched", "the", "sound", "check"]}]];
