englishA2Plans[312]={"title": "Vendendo um romance no sebo", "file": "", "grammar": "I’ve just finished para ações recém-concluídas", "goal": "Conte que você acabou de terminar um livro usando I've just finished… e converse sobre ele.", "words": [["page-turner", "livro que prende"], ["pen name", "pseudônimo"], ["used bookstore", "sebo"], ["cliffhanger", "final em suspense"], ["book club", "clube do livro"], ["literary", "literário"], ["edition", "edição"], ["paragraph", "parágrafo"], ["tales", "contos"], ["publisher", "editora"]]};
englishA2Content[312]=[[["Ana has just finished a page-turner by a writer with a pen name.", "Ana acabou de terminar um livro que prende, de um autor com pseudônimo."], ["She took it to a used bookstore, but she didn't want to say goodbye to the story.", "Ela levou o livro a um sebo, mas não queria se despedir da história."], ["The owner has just put a new edition on the shelf, with a blue cover.", "O dono acabou de colocar uma edição nova na prateleira, com capa azul."], ["Ana read the last chapter on the bus this morning, and the cliffhanger surprised her.", "Ana leu o último capítulo no ônibus hoje de manhã, e o final em suspense a surpreendeu."], ["The owner invited her to a book club that reads tales from many countries.", "O dono a convidou para um clube do livro que lê contos de vários países."], ["Ana smiled and signed up for the next meeting.", "Ana sorriu e se inscreveu para o próximo encontro."]], [["Hi, Ana. Are you here to sell something today?", "Oi, Ana. Você veio vender alguma coisa hoje?"], ["Yes! I've just finished the new novel, and I couldn't stop reading.", "Sim! Acabei de terminar o romance novo e não consegui parar de ler."], ["Is it a page-turner? People say every chapter ends with a surprise.", "É daqueles que prendem? Dizem que todo capítulo termina com uma surpresa."], ["Totally. I read the last chapter on the bus, and the cliffhanger is crazy.", "Total. Li o último capítulo no ônibus, e o final em suspense é uma loucura."], ["Who is the author? I don't know the name on the cover.", "Quem é o autor? Não conheço o nome na capa."], ["Nobody knows. The publisher says it's a pen name.", "Ninguém sabe. A editora diz que é um pseudônimo."], ["Is it serious literary fiction, or more like a thriller?", "É ficção literária séria, ou mais um suspense?"], ["A little of both. One paragraph on page ninety made me cry.", "Um pouco dos dois. Um parágrafo na página noventa me fez chorar."], ["Then you'll love our book club. We've just chosen a book of tales.", "Então você vai adorar nosso clube do livro. Acabamos de escolher um livro de contos."], ["Sounds great! Sign me up. I'll come on Thursday.", "Que ótimo! Me inscreva. Venho na quinta."]], ["/æ/ em chapter e paragraph", "Abra bem a boca: o 'a' de chapter e paragraph fica entre o 'a' e o 'é' do português; não diga 'chápter' com 'ei'.", ["chapter", "paragraph"]], ["Ana has ___ finished a page-turner.", "just", "yet", "A Ana acabou de terminar um livro que prende.", "Just mostra algo muito recente; yet não é usado em frases afirmativas."], [["Ana has just finished a page-turner by a writer with a pen name.", "Ana acabou de terminar um livro que prende, de um autor com pseudônimo."], ["Yes! I've just finished the new novel, and I couldn't stop reading.", "Sim! Acabei de terminar o romance novo e não consegui parar de ler."]], [{"t": "c", "q": "I've ___ read the first paragraph.", "o": ["just", "yet", "for"], "pt": "Eu acabei de ler o primeiro parágrafo.", "why": "Just + present perfect fala de algo que acabou de acontecer."}, {"t": "l", "say": "I've just finished the last chapter.", "o": ["I've just finished the last chapter.", "I've just finish the last chapter.", "I've just finished the last chapter yet."], "why": "Depois de have, usamos o particípio: finished."}, {"t": "b", "pt": "Eu acabei de terminar o livro.", "w": ["I've", "just", "finished", "the", "book"]}, {"t": "b", "pt": "Todo capítulo termina com um suspense.", "w": ["Every", "chapter", "ends", "with", "a", "cliffhanger"]}]];
