englishA2Plans[314]={"title": "Notícias antes de ir ao trabalho", "file": "", "grammar": "According to para citar uma fonte de notícia", "goal": "Cite de onde vem uma notícia usando According to…", "words": [["breaking news", "notícia de última hora"], ["news anchor", "apresentador de jornal"], ["weather report", "previsão do tempo"], ["front page", "primeira página"], ["local news", "notícias locais"], ["latest news", "últimas notícias"], ["fake news", "notícia falsa"], ["broadcast", "transmissão"], ["reliable source", "fonte confiável"], ["newscast", "telejornal"]]};
englishA2Content[314]=[[["Sam turned on the local news at six o'clock.", "Sam ligou o noticiário local às seis horas."], ["According to the news anchor, the main bridge was closed after a truck accident.", "Segundo o apresentador, a ponte principal estava fechada depois de um acidente com um caminhão."], ["According to the weather report, a storm was coming too.", "Segundo a previsão do tempo, uma tempestade também estava chegando."], ["On the front page of the paper, the headline said, “Bridge Closed.”", "Na primeira página do jornal, a manchete dizia: “Ponte fechada”."], ["Elena read other posts online, but one of them was fake news.", "Elena leu outras publicações on-line, mas uma delas era notícia falsa."], ["Sam learned that a reliable source is better than a shocking post.", "Sam aprendeu que uma fonte confiável é melhor do que uma publicação chocante."]], [["Elena, did you see the breaking news this morning?", "Elena, você viu as notícias de última hora hoje de manhã?"], ["No, I didn't. What happened?", "Não. O que aconteceu?"], ["According to the newscast, the main bridge is closed until Friday.", "Segundo o telejornal, a ponte principal fica fechada até sexta."], ["Oh no! That's my road to work. Is that a reliable source?", "Ai, não! É o meu caminho para o trabalho. Essa fonte é confiável?"], ["Yes, it was a live broadcast from the police station.", "É, foi uma transmissão ao vivo da delegacia."], ["According to a post I read yesterday, the bridge was open.", "Segundo uma publicação que li ontem, a ponte estava aberta."], ["That was probably fake news. According to the latest news, they'll open it on Saturday.", "Provavelmente era notícia falsa. Segundo as últimas notícias, vão abrir no sábado."], ["Thanks. I'll take the train tomorrow and check the news again tonight.", "Obrigado. Vou de trem amanhã e vejo as notícias de novo hoje à noite."]], ["/ð/ em weather e other", "Ponha a ponta da língua entre os dentes e faça vibrar a voz; não troque por 'd' (não diga 'wéder' nem 'âder').", ["weather", "other"]], ["___ the weather report, a storm was coming.", "According to", "According with", "De acordo com a previsão do tempo, uma tempestade estava chegando.", "Em inglês a expressão fixa é according to, não according with."], [["According to the news anchor, the main bridge was closed after a truck accident.", "Segundo o apresentador, a ponte principal estava fechada depois de um acidente com um caminhão."], ["According to the newscast, the main bridge is closed until Friday.", "Segundo o telejornal, a ponte principal fica fechada até sexta."]], [{"t": "c", "q": "___ the newspaper, the mayor will speak today.", "o": ["According to", "According with", "Accord to"], "pt": "De acordo com o jornal, o prefeito vai falar hoje.", "why": "A expressão correta é according to + fonte."}, {"t": "l", "say": "The headline said the bridge was closed.", "o": ["The headline said the bridge was closed.", "The headline said the bridge is close.", "The headline says the bridge was closing."], "why": "Said e was closed combinam: tudo no passado."}, {"t": "b", "pt": "De acordo com a previsão do tempo, vai chover.", "w": ["According", "to", "the", "weather", "report", "it", "will", "rain"]}, {"t": "b", "pt": "Isso é notícia falsa.", "w": ["That", "is", "fake", "news"]}]];
