englishA2Plans[315]={"title": "Surpresa de cinquenta anos para o pai", "file": "", "grammar": "Invite … to e celebrate para convidar e comemorar", "goal": "Convide pessoas com invite … to e fale de comemorar uma surpresa de aniversário.", "words": [["birthday party", "festa de aniversário"], ["guest list", "lista de convidados"], ["party favors", "lembrancinhas"], ["make a wish", "fazer um pedido"], ["throw a party", "dar uma festa"], ["give a toast", "fazer um brinde"], ["dress code", "traje exigido"], ["pop out", "pular de surpresa"], ["thank-you note", "bilhete de agradecimento"], ["slideshow", "apresentação de fotos"]]};
englishA2Content[315]=[[["Rosa and Kenji are going to throw a party for their dad's fiftieth birthday.", "Rosa e Kenji vão dar uma festa para os cinquenta anos do pai."], ["They made a guest list and invited thirty people to the birthday party.", "Eles fizeram uma lista de convidados e convidaram trinta pessoas para a festa de aniversário."], ["Kenji also invited Dad's old neighbors to the dinner, but he asked everyone to keep it a surprise.", "Kenji também convidou os antigos vizinhos do pai para o jantar, mas pediu que todos guardassem segredo."], ["The dress code is simple: everyone wears something blue.", "O traje é simples: todo mundo usa algo azul."], ["Dad will make a wish, and Rosa will show a slideshow of old photos.", "O pai vai fazer um pedido, e a Rosa vai mostrar uma apresentação de fotos antigas."], ["At the end, the guests will get small party favors and a thank-you note.", "No fim, os convidados vão ganhar lembrancinhas e um bilhete de agradecimento."]], [["Rosa, did you invite all of Dad's friends to the party?", "Rosa, você convidou todos os amigos do pai para a festa?"], ["Yes! I sent the invitations in March, and thirty people said yes.", "Sim! Mandei os convites em março, e trinta pessoas disseram que vêm."], ["Great. I invited our cousins to the dinner, too. They're driving from Boston.", "Ótimo. Convidei nossos primos para o jantar também. Eles vêm de carro de Boston."], ["Perfect. Is the surprise still a secret?", "Perfeito. A surpresa ainda é segredo?"], ["Yes! He thinks we're only going to celebrate with a small dinner.", "É! Ele acha que vamos só comemorar com um jantar pequeno."], ["When he opens the door, we'll all pop out and yell, “Surprise!”", "Quando ele abrir a porta, vamos todos pular e gritar: “Surpresa!”"], ["I love it. Uncle Sam will give a toast, and then Dad will make a wish.", "Adorei. O tio Sam vai fazer um brinde, e depois o pai faz um pedido."], ["Don't forget the dress code and the party favors for the kids.", "Não esqueça o traje e as lembrancinhas das crianças."], ["Don't worry. I bought the thank-you notes, and the slideshow is ready.", "Pode deixar. Comprei os bilhetes de agradecimento, e a apresentação está pronta."], ["Wonderful. See you at five!", "Maravilha. Nos vemos às cinco!"]], ["/w/ em wish e wears", "Arredonde os lábios como em 'uau' antes da vogal; não troque por 'v' nem por 'gu' forte. Em wish e wears o /w/ é curto.", ["wish", "wears"]], ["Rosa invited thirty people ___ the birthday party.", "to", "for", "Rosa convidou trinta pessoas para a festa de aniversário.", "Depois de invite alguém, usamos to para indicar a festa ou o evento."], [["They made a guest list and invited thirty people to the birthday party.", "Eles fizeram uma lista de convidados e convidaram trinta pessoas para a festa de aniversário."], ["Great. I invited our cousins to the dinner, too. They're driving from Boston.", "Ótimo. Convidei nossos primos para o jantar também. Eles vêm de carro de Boston."]], [{"t": "c", "q": "We invited our neighbors ___ the dinner.", "o": ["to", "for", "in"], "pt": "Nós convidamos nossos vizinhos para o jantar.", "why": "Com invite, a pessoa vem primeiro e depois usamos to + evento."}, {"t": "l", "say": "I invited them to the party.", "o": ["I invited them to the party.", "I invited to them the party.", "I invited them at the party."], "why": "A ordem é invite + pessoa + to + evento."}, {"t": "b", "pt": "Nós convidamos trinta pessoas para a festa.", "w": ["We", "invited", "thirty", "people", "to", "the", "party"]}, {"t": "b", "pt": "Nós vamos comemorar com um jantar.", "w": ["We", "are", "going", "to", "celebrate", "with", "a", "dinner"]}]];
