englishA2Plans[316]={"title": "Noite de jogos na casa do Noah", "file": "", "grammar": "Whose turn, your turn e take turns nos jogos", "goal": "Organize a vez de cada um em um jogo usando turn: Whose turn is it? / Let's take turns.", "words": [["board game", "jogo de tabuleiro"], ["card game", "jogo de cartas"], ["game night", "noite de jogos"], ["roll the dice", "jogar os dados"], ["your move", "sua jogada"], ["video game", "videogame"], ["game over", "fim de jogo"], ["high score", "recorde de pontos"], ["cheat code", "código de trapaça"], ["jigsaw puzzle", "quebra-cabeça"]]};
englishA2Content[316]=[[["Noah invited three friends to game night on Friday.", "Noah convidou três amigos para a noite de jogos na sexta."], ["They opened a new board game and agreed to take turns.", "Eles abriram um jogo de tabuleiro novo e combinaram de se revezar."], ["“Whose turn is it?” Sam asked after the first round.", "“De quem é a vez?”, perguntou Sam depois da primeira rodada."], ["It was Noah's turn to roll the dice, and he moved six squares.", "Era a vez do Noah de jogar os dados, e ele andou seis casas."], ["“Your move, Sam!” he said with a smile.", "“Sua vez, Sam!”, disse ele sorrindo."], ["Later, they finished a jigsaw puzzle together, and everybody went home happy.", "Mais tarde, terminaram um quebra-cabeça juntos, e todos foram para casa felizes."]], [["Noah, it's late. Should we play a card game or a video game?", "Noah, está tarde. Vamos jogar cartas ou videogame?"], ["Let's play the space video game. Whose turn is it to choose?", "Vamos jogar o videogame espacial. De quem é a vez de escolher?"], ["It's your turn, Noah. I chose last time.", "É a sua vez, Noah. Eu escolhi da última vez."], ["Okay. I'm on level four, and I can't pass it.", "Tá bom. Estou no nível quatro e não consigo passar."], ["Careful! It says game over when the timer reaches zero.", "Cuidado! Aparece game over quando o cronômetro chega a zero."], ["Oh no, I just lost again. Can we use a cheat code?", "Ai, não, acabei de perder de novo. Podemos usar um código de trapaça?"], ["No way. That's not fair. Let's take turns, one level each.", "De jeito nenhum. Não é justo. Vamos nos revezar, um nível cada."], ["Fine. Your move, Sam! Show me how to do it.", "Tá. Sua vez, Sam! Mostre como se faz."], ["Watch this. I'm going to beat the high score in one try.", "Olha só. Vou bater o recorde de primeira."], ["Deal. If you do, I'll buy the pizza.", "Combinado. Se você conseguir, eu pago a pizza."]], ["/dʒ/ em jigsaw e just", "Comece com 'dj' juntos, como em 'djavan' dito rápido; não troque por 'j' do francês. Em jigsaw e just a língua toca o céu da boca.", ["jigsaw", "just"]], ["It was Noah's ___ to roll the dice.", "turn", "time", "Era a vez do Noah de jogar os dados.", "Para falar de vez em um jogo, usamos turn, não time."], [["“Whose turn is it?” Sam asked after the first round.", "“De quem é a vez?”, perguntou Sam depois da primeira rodada."], ["It was Noah's turn to roll the dice, and he moved six squares.", "Era a vez do Noah de jogar os dados, e ele andou seis casas."]], [{"t": "c", "q": "We take ___ with the video game.", "o": ["turns", "times", "moves"], "pt": "Nós nos revezamos no videogame.", "why": "A expressão fixa é take turns."}, {"t": "l", "say": "Whose turn is it?", "o": ["Whose turn is it?", "Who's turn is it?", "Whose time is it?"], "why": "Para perguntar de quem é a vez, usamos Whose turn is it?"}, {"t": "b", "pt": "Agora é a vez da Lia.", "w": ["It's", "Lia's", "turn", "now"]}, {"t": "b", "pt": "Meu recorde é doze mil.", "w": ["My", "high", "score", "is", "twelve", "thousand"]}]];
