englishA2Plans[317]={"title": "Aula de arte e exposição da escola", "file": "", "grammar": "Passado simples com draw e paint: drew, painted", "goal": "Conte o que você desenhou ou pintou usando o passado simples.", "words": [["oil painting", "pintura a óleo"], ["art class", "aula de arte"], ["work of art", "obra de arte"], ["photo album", "álbum de fotos"], ["take a picture", "tirar uma foto"], ["zoom in", "dar zoom"], ["art show", "exposição de arte"], ["color palette", "paleta de cores"], ["wall painting", "pintura de parede"], ["craft", "artesanato"]]};
englishA2Content[317]=[[["Elena joined an art class in September.", "Elena entrou em uma aula de arte em setembro."], ["First she drew small flowers, and then she painted her first oil painting.", "Primeiro ela desenhou pequenas flores, e depois pintou seu primeiro quadro a óleo."], ["It showed a small boat on a blue lake, and her teacher chose it for the school exhibition.", "Mostrava um barquinho em um lago azul, e a professora o escolheu para a exposição da escola."], ["Elena took a picture of it and put it in her photo album.", "Elena tirou uma foto do quadro e colocou no seu álbum de fotos."], ["She said it wasn't a work of art, but everybody clapped.", "Ela disse que não era uma obra de arte, mas todo mundo aplaudiu."], ["Last week she painted a big wall painting at the entrance of the art show.", "Na semana passada ela pintou um grande mural na entrada da mostra de arte."]], [["Mia, did you go to the art show yesterday?", "Mia, você foi à mostra de arte ontem?"], ["Yes! Elena painted a beautiful wall painting at the entrance.", "Fui! A Elena pintou um mural lindo na entrada."], ["How did she do it? That wall is huge.", "Como ela fez isso? Aquela parede é enorme."], ["She used a ladder and a small color palette with only four colors.", "Ela usou uma escada e uma paleta pequena com só quatro cores."], ["Impressive. In school I drew a cat, and everybody thought it was a dog.", "Impressionante. Na escola eu desenhei um gato, e todo mundo achou que era um cachorro."], ["Ha! I took a picture of her work, and I'll zoom in on the small flowers at home.", "Ha! Tirei uma foto da obra dela e vou dar zoom nas florzinhas em casa."], ["Is she going to teach another art class?", "Ela vai dar outra aula de arte?"], ["Yes, next month, on Thursdays. Do you want to join?", "Vai, no mês que vem, às quintas. Quer participar?"], ["Definitely! I'll sign up this week.", "Com certeza! Vou me inscrever esta semana."], ["Great, I'll send you the schedule tonight.", "Ótimo, vou te mandar o horário hoje à noite."]], ["/p/ aspirado em painted e picture", "Em paint e picture solte um sopro de ar junto com o /p/ (ponha a mão na frente da boca e sinta). Em português o 'p' é mais seco.", ["painted", "picture"]], ["Last week, she ___ a wall painting at school.", "painted", "paint", "Na semana passada, ela pintou uma pintura de parede na escola.", "Com last week usamos o passado simples: painted."], [["First she drew small flowers, and then she painted her first oil painting.", "Primeiro ela desenhou pequenas flores, e depois pintou seu primeiro quadro a óleo."], ["Yes! Elena painted a beautiful wall painting at the entrance.", "Fui! A Elena pintou um mural lindo na entrada."]], [{"t": "c", "q": "Last year, Elena ___ a small boat on the lake.", "o": ["drew", "drawed", "drawn"], "pt": "No ano passado, Elena desenhou um barquinho no lago.", "why": "Draw é irregular: o passado é drew, nunca drawed."}, {"t": "l", "say": "I took a picture of the painting.", "o": ["I took a picture of the painting.", "I take a picture of the painting.", "I taken a picture of the painting."], "why": "Took é o passado de take."}, {"t": "b", "pt": "Eu entrei em uma aula de arte em setembro.", "w": ["I", "joined", "an", "art", "class", "in", "September"]}, {"t": "b", "pt": "Ela pintou um quadro a óleo.", "w": ["She", "painted", "an", "oil", "painting"]}]];
