englishA2Plans[318]={"title": "Duas opiniões sobre o mesmo filme", "file": "", "grammar": "I think it’s… e In my opinion para opinar", "goal": "Dê e defenda sua opinião sobre um filme com I think it's… e In my opinion.", "words": [["tragedy", "tragédia"], ["applaud", "aplaudir"], ["celebrity", "celebridade"], ["entertainment", "entretenimento"], ["unforgettable", "inesquecível"], ["unpredictable", "imprevisível"], ["thumbs up", "joinha, aprovação"], ["overrated", "superestimado"], ["plot hole", "furo no roteiro"], ["worth watching", "vale a pena assistir"]]};
englishA2Content[318]=[[["Mia and Sam saw a movie about two sisters last night.", "Mia e Sam viram um filme sobre duas irmãs ontem à noite."], ["“In my opinion, it was a tragedy, but a beautiful one,” Mia said.", "“Na minha opinião, foi uma tragédia, mas linda”, disse Mia."], ["“I think it's overrated,” Sam said. “I found a plot hole in the middle.”", "“Acho que é superestimado”, disse Sam. “Encontrei um furo no roteiro no meio.”"], ["Mia said the lead actress is a celebrity now, and the audience applauded at the end.", "Mia disse que a atriz principal é uma celebridade agora, e a plateia aplaudiu no final."], ["They both agreed that the ending was unpredictable and unforgettable.", "Os dois concordaram que o final foi imprevisível e inesquecível."], ["Sam gave it a thumbs up and said it was good entertainment for a rainy night.", "Sam deu um joinha e disse que era um bom entretenimento para uma noite de chuva."]], [["Sam, what did you think of the movie last night?", "Sam, o que você achou do filme ontem à noite?"], ["Honestly, I think it's overrated. The middle was too slow.", "Sinceramente, acho que é superestimado. O meio foi lento demais."], ["Really? In my opinion, it was a tragedy, but a beautiful one.", "Sério? Na minha opinião, foi uma tragédia, mas linda."], ["Maybe, but I found a plot hole. Why did the father leave?", "Talvez, mas achei um furo no roteiro. Por que o pai foi embora?"], ["Good question. But the ending was unpredictable, and the whole theater applauded.", "Boa pergunta. Mas o final foi imprevisível, e o cinema inteiro aplaudiu."], ["True, and the lead actress is a celebrity now. I think it's worth watching once.", "Verdade, e a atriz principal é uma celebridade agora. Acho que vale a pena assistir uma vez."], ["Ha! For me, it's unforgettable. It's the best entertainment of the year.", "Ha! Para mim, é inesquecível. É o melhor entretenimento do ano."], ["Okay, okay. I'll give it a thumbs up, but only a small one.", "Tá bom, tá bom. Dou um joinha, mas só um pequeno."]], ["/ʌ/ em unforgettable e unpredictable", "O prefixo un- soa como 'an' curto, com a boca relaxada; não diga 'uni'. Em unforgettable e unpredictable a sílaba forte vem depois.", ["unforgettable", "unpredictable"]], ["___ my opinion, the ending was too sad.", "In", "For", "Na minha opinião, o final foi triste demais.", "A expressão fixa é In my opinion; não use for nem on."], [["“In my opinion, it was a tragedy, but a beautiful one,” Mia said.", "“Na minha opinião, foi uma tragédia, mas linda”, disse Mia."], ["Honestly, I think it's overrated. The middle was too slow.", "Sinceramente, acho que é superestimado. O meio foi lento demais."]], [{"t": "c", "q": "___ my opinion, the movie was funny.", "o": ["In", "On", "For"], "pt": "Na minha opinião, o filme foi engraçado.", "why": "A expressão correta é In my opinion; em português é 'na', mas em inglês usamos in."}, {"t": "l", "say": "I think it's overrated.", "o": ["I think it's overrated.", "I think is overrated.", "I thinks it's overrated."], "why": "Depois de I think, falamos it's; e com I o verbo fica think, sem -s."}, {"t": "b", "pt": "Na minha opinião, o final foi triste.", "w": ["In", "my", "opinion", "the", "ending", "was", "sad"]}, {"t": "b", "pt": "Eu acho que vale a pena assistir.", "w": ["I", "think", "it's", "worth", "watching"]}]];
