englishA2Plans[319]={"title": "Revisão: uma noite de cinema", "file": "", "grammar": "Revisão: passado simples, present perfect e opinião", "goal": "Revise a noite de cinema contando o que aconteceu e dando sua opinião.", "words": [["movie night", "noite de cinema"], ["movie theater", "cinema (sala)"], ["ticket booth", "bilheteria"], ["snack bar", "lanchonete"], ["closing credits", "créditos finais"], ["midnight show", "sessão da meia-noite"], ["wait in line", "esperar na fila"], ["movie poster", "pôster de filme"], ["last row", "última fileira"], ["burst into tears", "cair no choro"]]};
englishA2Content[319]=[[["Rosa has loved movies since she was ten, so she invited four friends to a midnight show.", "Rosa adora filmes desde os dez anos, então convidou quatro amigos para uma sessão da meia-noite."], ["According to the movie poster, the new movie had a big plot twist, and the poster looked like an oil painting.", "Segundo o pôster do filme, o filme novo tinha uma grande reviravolta, e o pôster parecia um quadro a óleo."], ["They waited in line at the ticket booth, and Omar read a page-turner for an hour.", "Eles esperaram na fila da bilheteria, e Omar leu um livro que prende por uma hora."], ["At the snack bar, Noah just bought a large popcorn, so it was Omar's turn to pay for the drinks.", "Na lanchonete, Noah acabou de comprar uma pipoca grande, então era a vez do Omar pagar as bebidas."], ["During the last scene, the band's song was unforgettable, and everyone wanted to sing along.", "Na última cena, a música da banda foi inesquecível, e todo mundo queria cantar junto."], ["Rosa burst into tears at the end, but she gave it a thumbs up when the closing credits started.", "Rosa caiu no choro no final, mas deu um joinha quando os créditos finais começaram."]], [["Omar, I've just left the movie theater, and my feet hurt.", "Omar, acabei de sair do cinema, e meus pés estão doendo."], ["Really? Did you wait in line at the ticket booth again?", "Sério? Você esperou na fila da bilheteria de novo?"], ["Yes, for an hour. According to the movie poster, the show started at midnight.", "Esperei, uma hora. Segundo o pôster, a sessão começava à meia-noite."], ["Did Rosa come? You invited her to the movie night, right?", "A Rosa foi? Você a convidou para a noite de cinema, certo?"], ["Yes, and Lia too. Rosa burst into tears at the ending.", "Sim, e a Lia também. A Rosa caiu no choro no final."], ["Wow. Was the plot twist unforgettable?", "Nossa. A reviravolta foi inesquecível?"], ["In my opinion, yes. I think it's the best movie of the year.", "Na minha opinião, foi. Acho que é o melhor filme do ano."], ["I've loved that series since I was twelve. It's my turn to pick the next movie.", "Adoro essa série desde os doze anos. É a minha vez de escolher o próximo filme."], ["Fine, but we sat in the last row today, so let's choose the front row.", "Tá, mas hoje sentamos na última fila, então vamos escolher a primeira."], ["Deal! I'll buy the tickets tomorrow after work.", "Combinado! Compro os ingressos amanhã depois do trabalho."]], ["/aɪ/ em night e midnight", "Em night e midnight o som é o ditongo 'ai', e o t final é leve; não diga 'naite' com um 'e' no fim.", ["night", "midnight"]], ["We ___ the movie poster before the show.", "saw", "see", "Nós vimos o pôster do filme antes da sessão.", "Falamos de algo que já aconteceu, então usamos o passado simples: saw."], [["According to the movie poster, the new movie had a big plot twist, and the poster looked like an oil painting.", "Segundo o pôster do filme, o filme novo tinha uma grande reviravolta, e o pôster parecia um quadro a óleo."], ["In my opinion, yes. I think it's the best movie of the year.", "Na minha opinião, foi. Acho que é o melhor filme do ano."]], [{"t": "c", "q": "Rosa ___ into tears at the end of the movie.", "o": ["burst", "bursted", "bursting"], "pt": "A Rosa caiu no choro no final do filme.", "why": "O passado de burst é burst, igual ao presente."}, {"t": "l", "say": "We waited in line at the ticket booth.", "o": ["We waited in line at the ticket booth.", "We waited on line at the ticket booth.", "We wait in line at the ticket booth."], "why": "Em inglês americano dizemos wait in line, e o passado é waited."}, {"t": "b", "pt": "Eles sentaram na última fileira.", "w": ["They", "sat", "in", "the", "last", "row"]}, {"t": "b", "pt": "Na minha opinião, foi ótimo.", "w": ["In", "my", "opinion", "it", "was", "great"]}]];
