englishA2MiniStories[319]=["A noite de cinema sem luz", "Rosa invited five friends to a movie night at her house.~Rosa convidou cinco amigos para uma noite de cinema na casa dela.|Omar brought a board game, and they took turns while the popcorn cooked.~Omar levou um jogo de tabuleiro, e eles se revezaram enquanto a pipoca estourava.|Noah chose a fantasy movie, and the special effects were spectacular.~Noah escolheu um filme de fantasia, e os efeitos especiais eram espetaculares.|Suddenly the power went out, and the screen turned black.~De repente a luz acabou, e a tela ficou preta.|Nobody panicked, and Ben read the last chapter of his page-turner out loud.~Ninguém entrou em pânico, e Ben leu em voz alta o último capítulo do seu livro que prende.|Lia drew a picture of the candle on a napkin.~Lia desenhou a vela em um guardanapo.|According to Omar's phone, his team lost the game by two points.~Segundo o celular do Omar, o time dele perdeu o jogo por dois pontos.|Then everybody sang along to Rosa's favorite band until the lights came back.~Depois todo mundo cantou junto uma música da banda favorita da Rosa até a luz voltar.|“In my opinion, it was the best movie night ever,” Rosa said.~“Na minha opinião, foi a melhor noite de cinema de todas”, disse Rosa.|Noah has just ordered a movie poster for next year's party.~Noah acabou de encomendar um pôster de filme para a festa do ano que vem."];
englishA2ExtraWordExamples[319]={"movie night": ["Friday is our movie night.", "A sexta é a nossa noite de cinema."], "movie theater": ["The movie theater is near my house.", "O cinema fica perto da minha casa."]};
englishA2Plans[320]={"title": "Conhecendo gente no clube de corrida", "file": "", "grammar": "Fazer novos amigos: How do you know…? e have a lot in common", "goal": "Puxe conversa com alguém novo usando How do you know…? e descubra o que vocês têm em comum.", "words": [["acquaintance", "conhecido(a)"], ["mutual", "em comum, mútuo"], ["in common", "em comum"], ["get along", "se dar bem"], ["talkative", "falante, tagarela"], ["hang out", "passar tempo juntos"], ["nickname", "apelido"], ["run into", "topar com, encontrar por acaso"], ["curious", "curioso(a)"]]};
englishA2Content[320]=[[["Ben joined a running club last month, but he didn't know anyone.", "Ben entrou num clube de corrida no mês passado, mas não conhecia ninguém."], ["At the first meeting, a talkative woman asked him, \"How do you know the coach?\"", "Na primeira reunião, uma mulher muito falante perguntou: \"Como você conhece o treinador?\""], ["\"We're just acquaintances,\" Ben said, \"but I'm curious about this club.\"", "\"Somos só conhecidos\", disse Ben, \"mas estou curioso sobre este clube.\""], ["Her name was Mia, and she asked, \"How do you know Omar, then?\"", "Ela se chamava Mia e perguntou: \"Então como você conhece o Omar?\""], ["They found out they have a lot in common: old movies and spicy food.", "Descobriram que têm muito em comum: filmes antigos e comida apimentada."], ["Now they get along well, and they hang out after every run.", "Agora eles se dão bem e passam tempo juntos depois de cada corrida."]], [["Hi, I'm Omar. Are you new in the club?", "Oi, eu sou o Omar. Você é novo no clube?"], ["Yes, I'm Ben. I joined two weeks ago. How do you know Mia?", "Sim, sou o Ben. Entrei há duas semanas. Como você conhece a Mia?"], ["We went to college together. I ran into her at the gym last year, and she told me about this club.", "Fizemos faculdade juntos. Topei com ela na academia no ano passado, e ela me falou deste clube."], ["Small world! I don't know many people yet, but everybody seems friendly.", "Que mundo pequeno! Ainda não conheço muita gente, mas todo mundo parece simpático."], ["We all get along here. How do you know the coach?", "Aqui todo mundo se dá bem. Como você conhece o treinador?"], ["He lives in my building. We're just acquaintances, but we have a mutual friend.", "Ele mora no meu prédio. Somos só conhecidos, mas temos um amigo em comum."], ["Good! You can hang out with us after the run. What do you do on weekends?", "Ótimo! Você pode ficar com a gente depois da corrida. O que você faz nos fins de semana?"], ["I watch old movies and cook spicy food.", "Eu vejo filmes antigos e cozinho comida apimentada."], ["Really? We have a lot in common! Why don't you come to my place on Friday?", "Sério? Temos muito em comum! Por que você não vem à minha casa na sexta?"], ["Sure, I'd love to. Friday at eight, right?", "Claro, eu adoraria. Sexta às oito, certo?"]], ["/ʌ/ em run e club", "O /ʌ/ de run e club é curto e relaxado, com a boca quase fechada: parecido com o 'â' de 'cama', e não com 'a' aberto nem 'ó'.", ["run", "club"]], ["How ___ you know Mia?", "do", "are", "Como você conhece a Mia?", "Em perguntas no presente com know, usamos do depois de how: How do you know…?"], [["How do you know Mia?", "Como você conhece a Mia?"], ["We have a lot in common!", "Temos muito em comum!"]], [{"t": "c", "q": "We both love hiking. We have a lot ___.", "o": ["in common", "on common", "of common"], "pt": "Nós dois amamos fazer trilhas. Temos muito em comum.", "why": "A expressão fixa é have … in common; in é a preposição certa, e não on ou of."}, {"t": "l", "say": "How do you know Sam?", "o": ["How do you know Sam?", "How did you know Sam?", "Who do you know, Sam?"], "why": "How do you know Sam? pergunta de que jeito vocês se conheceram, no presente. Did mudaria o tempo e who mudaria a pergunta."}, {"t": "b", "pt": "Como você conhece o Ben?", "w": ["How", "do", "you", "know", "Ben"]}, {"t": "b", "pt": "Nós temos muito em comum", "w": ["We", "have", "a", "lot", "in", "common"]}]];
