englishA2ExtraWordExamples[320]={"nickname": ["Her nickname is Rocket because she runs so fast.", "O apelido dela é Rocket porque ela corre muito rápido."], "run into": ["I ran into an old friend at the supermarket yesterday.", "Topei com um velho amigo no supermercado ontem."]};
englishA2Plans[321]={"title": "Esqueci o jantar de aniversário da Lia", "file": "", "grammar": "Pedir desculpas e perdoar: I'm sorry for + -ing e It doesn't matter", "goal": "Peça desculpas com I'm sorry for + -ing e aceite um pedido de desculpas com It doesn't matter.", "words": [["apology", "pedido de desculpas"], ["embarrassed", "constrangido(a)"], ["let down", "decepcionar"], ["my fault", "minha culpa"], ["ashamed", "envergonhado(a)"], ["mean to", "ter a intenção de"], ["regret", "lamentar, se arrepender"], ["make it up to", "compensar alguém"], ["guilt", "culpa"]]};
englishA2Content[321]=[[["Tom forgot Lia's birthday dinner on Friday, so she waited at the restaurant for an hour.", "Tom esqueceu o jantar de aniversário da Lia na sexta, e ela esperou uma hora no restaurante."], ["She felt let down, and Tom felt embarrassed and ashamed when he saw her messages.", "Ela se sentiu decepcionada, e Tom ficou constrangido e envergonhado quando viu as mensagens dela."], ["The next morning he called her and said, \"I'm sorry for forgetting. It was my fault.\"", "Na manhã seguinte ele ligou e disse: \"Desculpe por esquecer. A culpa foi minha.\""], ["\"I didn't mean to hurt you, and I'm sorry for not calling last night,\" he added.", "\"Eu não quis te magoar, e peço desculpas por não ter ligado ontem à noite\", acrescentou."], ["\"Honestly, I was angry,\" Lia said, \"but it doesn't matter now.\"", "\"Para ser sincera, eu estava com raiva\", disse Lia, \"mas agora isso não importa.\""], ["Tom wanted to make it up to her, so he booked a table for Saturday.", "Tom queria compensá-la, então reservou uma mesa para sábado."]], [["Lia, it's me. I'm so sorry for missing your dinner last night.", "Lia, sou eu. Sinto muito por ter perdido o seu jantar ontem à noite."], ["I waited at the restaurant for an hour, Tom. I felt really let down.", "Esperei no restaurante por uma hora, Tom. Me senti muito decepcionada."], ["I know. It was my fault. I didn't mean to forget, and I feel a lot of guilt.", "Eu sei. A culpa foi minha. Não quis esquecer, e me sinto muito culpado."], ["Where were you? You weren't answering your phone.", "Onde você estava? Você não atendia o telefone."], ["My battery died, and I was stuck at the office until nine. I regret not calling you from my desk.", "Minha bateria acabou, e fiquei preso no escritório até as nove. Me arrependo de não ter ligado da minha mesa."], ["Honestly, I want a real apology, not excuses.", "Para ser sincera, quero um pedido de desculpas de verdade, e não desculpas esfarrapadas."], ["You're right. I'm sorry for making you wait. Can I make it up to you tomorrow? I'll book a table at eight.", "Você tem razão. Desculpe por te fazer esperar. Posso compensar amanhã? Reservo uma mesa às oito."], ["OK, it doesn't matter anymore. Saturday at eight works for me.", "Tudo bem, já não importa. Sábado às oito está bom para mim."]], ["/h/ em honestly (h mudo) e hurt", "Em honestly o h é mudo: diga 'ónestli'. Já em hurt o h é um sopro de ar saindo da garganta, como quem embaça um vidro.", ["honestly", "hurt"]], ["I'm sorry ___ being late.", "for", "to", "Desculpe por chegar atrasado.", "Para dar o motivo do pedido de desculpas, usamos sorry for + verbo com -ing."], [["I'm sorry for forgetting.", "Desculpe por esquecer."], ["but it doesn't matter now.", "mas agora isso não importa."]], [{"t": "c", "q": "I'm sorry ___ breaking your cup.", "o": ["for", "of", "by"], "pt": "Desculpe por quebrar a sua xícara.", "why": "Para dar o motivo do pedido de desculpas, usamos sorry for + -ing. Não dizemos sorry of nem sorry by."}, {"t": "l", "say": "I didn't mean to hurt you.", "o": ["I didn't mean to hurt you.", "I didn't mean to hurry you.", "I don't mean to hurt you."], "why": "Hurt (machucar) e hurry (apressar) soam parecido, mas o sentido é outro; didn't fala do passado."}, {"t": "b", "pt": "Desculpe por esquecer o seu aniversário", "w": ["I'm", "sorry", "for", "forgetting", "your", "birthday"]}, {"t": "b", "pt": "Não tem problema agora", "w": ["It", "doesn't", "matter", "now"]}]];
