englishA2Plans[322]={"title": "Agradecendo à vizinha pelo bolo", "file": "", "grammar": "Elogiar e agradecer: That's so kind of you (adjetivo + of you)", "goal": "Agradeça um gesto gentil com That's so kind of you e elogie a atitude da pessoa.", "words": [["compliment", "elogio"], ["generous", "generoso(a)"], ["thankful", "agradecido(a)"], ["grateful", "grato(a)"], ["kindness", "gentileza"], ["appreciate", "valorizar, ser grato por"], ["thoughtful", "atencioso(a)"], ["means a lot", "significa muito"], ["modest", "modesto(a)"], ["homemade", "feito em casa"]]};
englishA2Content[322]=[[["Sam moved into a new apartment on Sunday, and he was very tired.", "Sam se mudou para um apartamento novo no domingo e estava muito cansado."], ["In the evening, his neighbor, Mrs. Green, knocked and gave him a homemade chocolate cake.", "À noite, a vizinha, a Sra. Green, bateu à porta e lhe deu um bolo de chocolate caseiro."], ["\"That's so kind of you,\" Sam said. \"I'm really grateful.\"", "\"Que gentileza a sua\", disse Sam. \"Fico muito grato.\""], ["He tried the cake and gave her a compliment: \"It's delicious, and it was so thoughtful of you to bring it.\"", "Ele provou o bolo e a elogiou: \"Está delicioso, e foi muito atencioso da sua parte trazê-lo.\""], ["Mrs. Green was modest and said, \"A neighbor was generous to me years ago, so I like to do the same.\"", "A Sra. Green foi modesta e disse: \"Uma vizinha foi generosa comigo anos atrás, então gosto de fazer o mesmo.\""], ["Sam felt thankful, and he invited her for coffee the next day.", "Sam se sentiu agradecido e a convidou para um café no dia seguinte."]], [["Good morning, Sam! You brought back my plate, and you washed it.", "Bom dia, Sam! Você trouxe meu prato de volta e ainda o lavou."], ["Of course. And the cake was the best I've ever had. That's so kind of you!", "Claro. E o bolo foi o melhor que já comi. Que gentileza a sua!"], ["I'm glad you liked it. I remember my first week here. I knew nobody.", "Fico feliz que gostou. Lembro da minha primeira semana aqui. Eu não conhecia ninguém."], ["Your kindness really means a lot to me. I appreciate it.", "Sua gentileza significa muito para mim. Eu valorizo isso."], ["Well, you can help me back. My garden gate is broken, and I can't fix it.", "Bem, você pode me ajudar também. O portão do meu jardim quebrou, e eu não consigo consertar."], ["Sure! It's so kind of you to trust me with it.", "Claro! É muita gentileza sua confiar isso a mim."], ["Could you come this afternoon around four?", "Você poderia vir hoje à tarde, por volta das quatro?"], ["Perfect. I'll bring my tools at four.", "Perfeito. Levo minhas ferramentas às quatro."]], ["/θ/ em thankful e thoughtful", "Em thankful e thoughtful, ponha a ponta da língua entre os dentes e solte o ar; não troque o th por t ou f.", ["thankful", "thoughtful"]], ["That's so kind ___ you.", "of", "from", "Que gentileza a sua.", "Para elogiar a atitude de alguém, usamos adjetivo + of you."], [["That's so kind of you!", "Que gentileza a sua!"], ["it was so thoughtful of you to bring it", "foi muito atencioso da sua parte trazê-lo"]], [{"t": "c", "q": "It was very thoughtful ___ you to call me.", "o": ["of", "for", "from"], "pt": "Foi muito atencioso da sua parte me ligar.", "why": "Para elogiar a atitude de alguém, usamos adjetivo + of you, e não for you nem from you."}, {"t": "l", "say": "It means a lot to me.", "o": ["It means a lot to me.", "It means a lot of me.", "It meant a lot to me."], "why": "Means a lot to me é a forma fixa no presente. Of me é erro comum, e meant mudaria para o passado."}, {"t": "b", "pt": "Isso significa muito para mim", "w": ["It", "means", "a", "lot", "to", "me"]}, {"t": "b", "pt": "Que gentileza a sua ajudar", "w": ["That's", "so", "kind", "of", "you", "to", "help"]}]];
