englishA2Plans[323]={"title": "Escolhendo o destino da viagem do grupo", "file": "", "grammar": "Discordar com educação: I see what you mean, but… e I see your point, but…", "goal": "Discorde sem ofender com I see what you mean, but… e chegue a um meio-termo.", "words": [["argument", "discussão, argumento"], ["convince", "convencer"], ["fair enough", "justo, tudo bem"], ["reasonable", "razoável"], ["agree to disagree", "concordar em discordar"], ["downside", "lado negativo"], ["meet halfway", "chegar a um meio-termo"], ["see your point", "entender seu argumento"], ["debate", "debate"]]};
englishA2Content[323]=[[["Priya wants to take the group trip to the mountains, but Kenji wants the beach.", "Priya quer fazer a viagem do grupo para as montanhas, mas Kenji quer a praia."], ["\"I see what you mean, but the beach is too crowded in July,\" Priya said.", "\"Entendo o que você quer dizer, mas a praia fica cheia demais em julho\", disse Priya."], ["Kenji answered, \"I see your point, but the mountain hotels are more expensive.\"", "Kenji respondeu: \"Entendo seu argumento, mas os hotéis da montanha são mais caros.\""], ["They had a long debate at lunch, but it didn't turn into an argument.", "Eles tiveram um longo debate no almoço, mas não virou uma discussão."], ["Priya tried to convince the others, and finally they decided to meet halfway.", "Priya tentou convencer os outros, e por fim decidiram chegar a um meio-termo."], ["They chose a lake, and everybody had to vote for it.", "Escolheram um lago, e todo mundo votou nele."]], [["Kenji, I'd like to go to the mountains in July. Hiking is so relaxing.", "Kenji, eu gostaria de ir para as montanhas em julho. Fazer trilha é tão relaxante."], ["I see what you mean, but I prefer the beach. It's cheaper.", "Entendo o que você quer dizer, mas prefiro a praia. É mais barata."], ["Cheaper? I checked last night, and the beach hotels cost ninety dollars a night.", "Mais barata? Conferi ontem à noite, e os hotéis da praia custam noventa dólares a diária."], ["Fair enough. But the mountains have a big downside: I hate hiking in the heat.", "Justo. Mas as montanhas têm um grande ponto negativo: odeio fazer trilha no calor."], ["That's reasonable. What if we start at six in the morning?", "É razoável. E se começarmos às seis da manhã?"], ["I see your point, but I can't wake up that early. Maybe we should agree to disagree.", "Entendo seu argumento, mas não consigo acordar tão cedo. Talvez devêssemos concordar em discordar."], ["Wait, let's meet halfway. A lake has swimming and a short trail. Can I convince you?", "Espere, vamos chegar a um meio-termo. Um lago tem natação e uma trilha curta. Posso te convencer?"], ["A lake? OK, you've convinced me. Let's vote at dinner.", "Um lago? Tudo bem, você me convenceu. Vamos votar no jantar."]], ["/v/ em convince e vote", "Encoste os dentes de cima no lábio de baixo e faça a voz vibrar: vote soa 'vôut', e não 'bôut'.", ["convince", "vote"]], ["I see what you mean, ___ I don't agree.", "but", "because", "Entendo o que você quer dizer, mas não concordo.", "Para discordar com educação, usamos but depois de reconhecer o ponto do outro."], [["I see what you mean, but I prefer the beach.", "Entendo o que você quer dizer, mas prefiro a praia."], ["I see your point, but I can't wake up that early.", "Entendo seu argumento, mas não consigo acordar tão cedo."]], [{"t": "c", "q": "I see what you mean, but I ___ agree.", "o": ["don't", "no", "not"], "pt": "Entendo o que você quer dizer, mas não concordo.", "why": "No presente, a negativa de agree é don't agree. Em inglês não dizemos I no agree."}, {"t": "l", "say": "I see your point, but I disagree.", "o": ["I see your point, but I disagree.", "I see your point, but I agree.", "I see your point, but I disagreed."], "why": "Disagree é discordar e agree é concordar; disagreed está no passado."}, {"t": "b", "pt": "Entendo o que você quer dizer mas discordo", "w": ["I", "see", "what", "you", "mean", "but", "I", "disagree"]}, {"t": "b", "pt": "Vamos chegar a um meio-termo e votar", "w": ["Let's", "meet", "halfway", "and", "vote"]}]];
