englishA2Plans[324]={"title": "Briga por causa da louça na república", "file": "", "grammar": "Conflitos em casa: calm down e misunderstanding", "goal": "Acalme uma discussão com Calm down, explique que foi um misunderstanding e resolva o conflito.", "words": [["misunderstanding", "mal-entendido"], ["quarrel", "discussão, briga"], ["yell", "gritar"], ["annoyed", "irritado(a)"], ["snap at", "falar de modo ríspido com"], ["storm off", "sair furioso"], ["clear the air", "limpar o clima"], ["fed up", "de saco cheio"], ["talk it over", "conversar sobre o assunto"]]};
englishA2Content[324]=[[["Noah came home tired on Monday, and the sink was full of dirty plates.", "Noah chegou cansado em casa na segunda, e a pia estava cheia de pratos sujos."], ["He was annoyed, and he started to yell at his roommate. Ben yelled back.", "Ele ficou irritado e começou a gritar com o colega de casa. Ben gritou de volta."], ["Then Ben said, \"Calm down, Noah. I didn't know it was my turn.\"", "Então Ben disse: \"Calma, Noah. Eu não sabia que era a minha vez.\""], ["Noah was fed up with the quarrel, so he went for a walk.", "Noah estava de saco cheio da briga, então saiu para caminhar."], ["When he came back, they sat down to talk it over and clear the air.", "Quando voltou, eles se sentaram para conversar sobre o assunto e limpar o clima."], ["It was only a misunderstanding: Ben thought the list on the fridge said Tuesday.", "Foi só um mal-entendido: Ben achou que a lista na geladeira dizia terça."]], [["Ben, the sink is full again! I'm so fed up with this.", "Ben, a pia está cheia de novo! Estou de saco cheio disso."], ["Don't snap at me. I thought it was your turn tonight.", "Não fale assim comigo. Achei que era a sua vez hoje."], ["It wasn't. We wrote the schedule on the fridge, remember?", "Não era. Escrevemos a escala na geladeira, lembra?"], ["Oh no, I read it wrong. It's just a misunderstanding.", "Ah, não, li errado. É só um mal-entendido."], ["You always say that, and then I wash everything alone!", "Você sempre diz isso, e depois eu lavo tudo sozinho!"], ["Calm down, please. Why do you always storm off when we have a quarrel?", "Calma, por favor. Por que você sempre sai furioso quando a gente briga?"], ["Because I don't want to yell. I just need a minute.", "Porque não quero gritar. Só preciso de um minuto."], ["OK. Let's calm down and talk it over. I'll make some tea.", "Tá bom. Vamos nos acalmar e conversar. Vou fazer um chá."], ["Thanks. And I'm sorry I yelled. Let's clear the air.", "Obrigado. E desculpe por ter gritado. Vamos limpar o clima."], ["Deal. I'll wash tonight, and you'll wash tomorrow.", "Combinado. Eu lavo hoje à noite e você lava amanhã."]], ["/j/ em yell e yelled", "Em yell comece com um 'i' bem rápido, como em 'iate'. Em yelled, o -ed final é só um 'd' leve, sem 'ede'.", ["yell", "yelled"]], ["It was only a ___ about the schedule.", "misunderstanding", "misunderstand", "Foi só um mal-entendido sobre a escala.", "Depois de a e antes de about precisamos de um substantivo: misunderstanding, e não o verbo."], [["Calm down, please.", "Calma, por favor."], ["It's just a misunderstanding.", "É só um mal-entendido."]], [{"t": "c", "q": "Please ___ down. We can talk about it.", "o": ["calm", "calmly", "calming"], "pt": "Por favor, acalme-se. Podemos conversar sobre isso.", "why": "A expressão é calm down, com o verbo na forma base depois de please; não usamos calmly nem calming."}, {"t": "l", "say": "Don't snap at me!", "o": ["Don't snap at me!", "Don't snack at me!", "Don't slap at me!"], "why": "Snap at é falar de modo ríspido; snack é lanche e slap é tapa. Os sons são parecidos, mas os sentidos mudam."}, {"t": "b", "pt": "Foi só um mal-entendido", "w": ["It", "was", "just", "a", "misunderstanding"]}, {"t": "b", "pt": "Vamos nos acalmar e conversar", "w": ["Let's", "calm", "down", "and", "talk", "it", "over"]}]];
