englishA2Plans[325]={"title": "Cuidando do avô com gripe", "file": "", "grammar": "Cuidar de alguém: look after e take care of", "goal": "Combine quem vai cuidar de um parente doente usando look after e take care of.", "words": [["look after", "cuidar de"], ["take care of", "tomar conta de"], ["elderly", "idoso(a)"], ["comfort", "conforto, consolo"], ["check on", "ver como alguém está"], ["keep company", "fazer companhia"], ["get well soon", "melhoras"], ["run errands", "fazer pequenas tarefas na rua"], ["patience", "paciência"]]};
englishA2Content[325]=[[["Elena's grandfather is elderly, and he lives alone.", "O avô da Elena é idoso e mora sozinho."], ["Last week he had the flu, so she went to look after him.", "Semana passada ele teve gripe, então ela foi cuidar dele."], ["Every morning she came to check on him and make soup.", "Toda manhã ela vinha ver como ele estava e fazer sopa."], ["\"Don't worry. I'll take care of everything,\" she told him.", "\"Não se preocupe. Eu cuido de tudo\", disse ela."], ["To cheer him up, she watched his favorite show with him.", "Para animá-lo, ela assistiu ao programa favorito dele junto com ele."], ["Her patience and a lot of tea worked: he felt better on Friday.", "A paciência dela e muito chá funcionaram: ele melhorou na sexta."]], [["How's Grandpa today? Did he eat anything?", "Como está o vovô hoje? Ele comeu alguma coisa?"], ["He had soup and toast. He's still tired, but he smiled at me.", "Ele comeu sopa e torrada. Ainda está cansado, mas sorriu para mim."], ["I want to look after him too, but I live two hours away.", "Eu também quero cuidar dele, mas moro a duas horas daqui."], ["Don't feel bad. Your calls are a big comfort to him.", "Não se sinta mal. Seus telefonemas são um grande consolo para ele."], ["Then I'll call and check on him every night. Does he need anything?", "Então vou ligar para ver como ele está toda noite. Ele precisa de alguma coisa?"], ["Yes, someone to run errands. Can you take care of that on Saturday?", "Sim, alguém para fazer umas tarefas na rua. Você pode cuidar disso no sábado?"], ["Of course. I'll keep him company, and I'll bring a card that says \"Get well soon.\"", "Claro. Vou fazer companhia a ele e levar um cartão com \"Melhoras\"."], ["He'll love it. Thanks, Aunt Rosa. See you Saturday at noon.", "Ele vai adorar. Obrigada, tia Rosa. Até sábado ao meio-dia."]], ["/tʃ/ em cheer e check", "O 'tch' de cheer e check é igual ao de 'tchau': a língua toca o céu da boca e solta o ar de uma vez.", ["cheer", "check"]], ["Can you ___ my cat while I'm away?", "look after", "look for", "Você pode cuidar do meu gato enquanto estou fora?", "Look after significa cuidar de; look for significa procurar."], [["I want to look after him too", "Eu também quero cuidar dele"], ["I'll take care of everything", "Eu cuido de tudo"]], [{"t": "c", "q": "My sister will ___ my plants this week.", "o": ["take care of", "take care", "take care to"], "pt": "Minha irmã vai cuidar das minhas plantas esta semana.", "why": "Take care of + objeto significa cuidar de alguma coisa; esquecer o of é erro comum."}, {"t": "l", "say": "Can you look after her?", "o": ["Can you look after her?", "Can you look at her?", "Can you look for her?"], "why": "Look after é cuidar, look at é olhar e look for é procurar."}, {"t": "b", "pt": "Eu cuido da minha avó", "w": ["I", "look", "after", "my", "grandmother"]}, {"t": "b", "pt": "Eu vou cuidar de tudo", "w": ["I'll", "take", "care", "of", "everything"]}]];
