englishA2ExtraWordExamples[325]={"keep company": ["I'll keep you company while you wait.", "Vou te fazer companhia enquanto você espera."]};
englishA2Plans[326]={"title": "Despedida da Priya no aeroporto", "file": "", "grammar": "Despedidas e saudade: miss e stay in touch", "goal": "Despeça-se de um amigo dizendo I'm going to miss you e combine de manter contato.", "words": [["say goodbye", "dizer adeus"], ["see you off", "ir se despedir de você"], ["stay in touch", "manter contato"], ["lose touch", "perder contato"], ["write back", "responder por escrito"], ["far away", "muito longe"], ["get together", "se reunir"], ["long-distance", "à distância"], ["count the days", "contar os dias"], ["tear up", "ficar com os olhos cheios de lágrimas"]]};
englishA2Content[326]=[[["Priya is moving to Canada for a new job, so her friends came to the airport on Saturday to see her off.", "Priya vai se mudar para o Canadá por causa de um novo emprego, então os amigos foram ao aeroporto no sábado para se despedir dela."], ["It was hard to say goodbye after ten years of friendship, and Mia started to tear up.", "Foi difícil dizer adeus depois de dez anos de amizade, e Mia começou a ficar com os olhos cheios de lágrimas."], ["\"I'm going to miss you,\" Mia said. \"Canada is so far away.\"", "\"Vou sentir sua falta\", disse Mia. \"O Canadá é tão longe.\""], ["\"Let's stay in touch,\" Priya said. \"I don't want to lose touch with you.\"", "\"Vamos manter contato\", disse Priya. \"Não quero perder contato com você.\""], ["They promised to write back to every message and to get together when she visits in December.", "Prometeram responder todas as mensagens e se reunir quando ela visitar em dezembro."], ["Then Priya hugged everyone, walked to the gate, and waved until they couldn't see her.", "Então Priya abraçou todos, caminhou até o portão e acenou até que não a viam mais."]], [["We came to see you off. Your flight leaves at six, right?", "Viemos nos despedir de você. Seu voo sai às seis, certo?"], ["Yes, at six-fifteen. I'm going to miss you so much.", "Sim, às seis e quinze. Vou sentir muita saudade de vocês."], ["We'll miss you too. Long-distance friendships are hard, but let's stay in touch.", "Também vamos sentir sua falta. Amizades à distância são difíceis, mas vamos manter contato."], ["Of course. I'll call you every Sunday, and I'll count the days until December.", "Claro. Vou ligar toda domingo e contar os dias até dezembro."], ["Good. When you visit, we'll get together at my place. Please keep in touch before that, too.", "Ótimo. Quando você vier, vamos nos reunir na minha casa. Por favor, mantenha contato até lá também."], ["I will. I'll write back to every message, I promise.", "Vou manter. Vou responder todas as mensagens, prometo."], ["Ha! Now go, or you'll be late for your flight.", "Ha! Agora vá, senão você vai se atrasar para o voo."], ["Bye, Mia! I'll text you when I land. Love you!", "Tchau, Mia! Mando mensagem quando eu pousar. Te amo!"]], ["/ɪ/ curto em miss e visit", "O /ɪ/ é um 'i' curto e solto, quase um 'é' fechado: compare sit com seat. Em miss e visit, não alongue o i como em 'mees'.", ["miss", "visit"]], ["Please keep in ___ with me.", "touch", "contact", "Por favor, mantenha contato comigo.", "A expressão fixa é keep in touch; não dizemos keep in contact."], [["I'm going to miss you so much.", "Vou sentir muita saudade de vocês."], ["let's stay in touch", "vamos manter contato"]], [{"t": "c", "q": "I'm going to ___ you when I move away.", "o": ["miss", "miss of", "missing"], "pt": "Vou sentir sua falta quando eu me mudar.", "why": "Miss you já significa sentir falta de você; não se usa of depois de miss."}, {"t": "l", "say": "Let's stay in touch.", "o": ["Let's stay in touch.", "Let's stay in town.", "Let's stay in tough."], "why": "Stay in touch é manter contato; town é cidade e tough é difícil."}, {"t": "b", "pt": "Eu vou sentir saudade de você", "w": ["I'm", "going", "to", "miss", "you"]}, {"t": "b", "pt": "Por favor mantenha contato comigo", "w": ["Please", "keep", "in", "touch", "with", "me"]}]];
