englishA2Plans[327]={"title": "Como conheci meu melhor amigo", "file": "", "grammar": "Contar uma história em ordem: when, while e after", "goal": "Conte como conheceu alguém usando when, while e after para ordenar os fatos.", "words": [["childhood", "infância"], ["grow up", "crescer"], ["mischief", "travessura"], ["accidentally", "sem querer"], ["end up", "acabar (fazendo)"], ["turn out", "acabar sendo, resultar"], ["eventually", "com o tempo"], ["afterwards", "depois, em seguida"], ["luckily", "felizmente"]]};
englishA2Content[327]=[[["In my childhood, I lived next to a boy named Leo, and we got into mischief together.", "Na minha infância, eu morava ao lado de um menino chamado Leo, e a gente aprontava junto."], ["When we were eight, we accidentally broke a neighbor's window with a ball.", "Quando tínhamos oito anos, quebramos sem querer a janela de um vizinho com uma bola."], ["While we were hiding behind a tree, the neighbor came out and laughed.", "Enquanto a gente se escondia atrás de uma árvore, o vizinho saiu e riu."], ["Luckily, he wasn't angry, and afterwards he gave us ice cream.", "Felizmente, ele não ficou bravo e depois nos deu sorvete."], ["After that day, we played together every summer.", "Depois daquele dia, brincamos juntos todo verão."], ["Today we're adults, and Leo is still my best friend.", "Hoje somos adultos, e o Leo ainda é meu melhor amigo."]], [["Kenji, where did you grow up? And how did you meet your best friend?", "Kenji, onde você cresceu? E como conheceu seu melhor amigo?"], ["In a small town near Osaka. Leo lived next door. When we were eight, we became friends.", "Numa cidade pequena perto de Osaka. O Leo morava ao lado. Quando tínhamos oito anos, ficamos amigos."], ["Really? How did it happen?", "Sério? Como foi que aconteceu?"], ["While I was riding my bike, a dog ran in front of me, and I fell. Leo helped me.", "Enquanto eu andava de bicicleta, um cachorro passou correndo na minha frente, e eu caí. O Leo me ajudou."], ["Poor you! What happened next?", "Coitado! O que aconteceu depois?"], ["After he took me home, my mom gave us cookies. Eventually, we were together every day.", "Depois que ele me levou para casa, minha mãe nos deu biscoitos. Com o tempo, ficamos juntos todos os dias."], ["And did you end up in the same school?", "E vocês acabaram na mesma escola?"], ["Yes! Life can turn out funny. Now we work in the same office.", "Sim! A vida pode ser engraçada. Hoje trabalhamos no mesmo escritório."]], ["/w/ em while e window", "Arredonde os lábios como para dizer 'u' e abra rápido: while soa 'uáil' e window soa 'uíndou'. Não comece com v nem g.", ["while", "window"]], ["I broke my arm ___ I was riding my bike.", "while", "during", "Quebrei o braço enquanto andava de bicicleta.", "While liga duas ações e vem seguido de sujeito + verbo; during vem seguido de um substantivo."], [["While I was riding my bike, a dog ran in front of me", "Enquanto eu andava de bicicleta, um cachorro passou correndo na minha frente"], ["When we were eight, we accidentally broke a neighbor's window with a ball.", "Quando tínhamos oito anos, quebramos sem querer a janela de um vizinho com uma bola."]], [{"t": "c", "q": "___ I was cooking, the phone rang.", "o": ["While", "During", "Meanwhile"], "pt": "Enquanto eu cozinhava, o telefone tocou.", "why": "While liga uma ação em andamento a outra, com sujeito e verbo depois."}, {"t": "l", "say": "When I got home, I called him.", "o": ["When I got home, I called him.", "While I got home, I called him.", "After I got home, I called him."], "why": "When marca o momento em que chegou; while pede uma ação em andamento e after muda a ordem dos fatos."}, {"t": "b", "pt": "Quando eu tinha dez anos eu quebrei o braço", "w": ["When", "I", "was", "ten", "I", "broke", "my", "arm"]}, {"t": "b", "pt": "Eu cresci numa cidade pequena", "w": ["I", "grew", "up", "in", "a", "small", "town"]}]];
