englishA2Plans[328]={"title": "Planos depois da formatura", "file": "", "grammar": "Planos para o futuro: I hope to… e I'm planning to…", "goal": "Fale dos seus planos com I hope to… (esperança) e I'm planning to… (plano).", "words": [["ambitious", "ambicioso(a)"], ["dream job", "emprego dos sonhos"], ["go abroad", "ir para o exterior"], ["come true", "virar realidade"], ["settle down", "criar raízes"], ["graduated", "formou-se"], ["independent", "independente"], ["someday", "um dia"], ["gap year", "ano sabático"]]};
englishA2Content[328]=[[["Mia graduated from college in June, and she is very ambitious.", "Mia se formou na faculdade em junho e é muito ambiciosa."], ["She hopes to find her dream job as a travel photographer.", "Ela espera encontrar o emprego dos sonhos como fotógrafa de viagem."], ["First, she's planning to take a gap year and go abroad, maybe to Spain.", "Primeiro, ela está planejando tirar um ano sabático e ir para o exterior, talvez para a Espanha."], ["She wants to be independent, so she's saving money for the trip.", "Ela quer ser independente, então está economizando dinheiro para a viagem."], ["Her parents hope to visit her in the spring.", "Os pais dela esperam visitá-la na primavera."], ["\"Someday I'll show my photos in a museum,\" she says, \"and my dream will come true.\"", "\"Um dia vou expor minhas fotos num museu\", diz ela, \"e meu sonho vai virar realidade.\""]], [["So, Mia, what are your plans after college?", "Então, Mia, quais são seus planos depois da faculdade?"], ["I hope to work for a travel magazine. What about you, Omar?", "Espero trabalhar para uma revista de viagem. E você, Omar?"], ["I'm planning to move to Chicago and open a small bakery.", "Estou planejando me mudar para Chicago e abrir uma pequena padaria."], ["A bakery? That's a big plan! Are you going to live alone?", "Uma padaria? Que grande plano! Você vai morar sozinho?"], ["Yes, I'm tired of living with my parents. I want to be independent.", "Sim, cansei de morar com meus pais. Quero ser independente."], ["Me too. But I want to take a gap year first, and someday I want to settle down.", "Eu também. Mas quero tirar um ano sabático primeiro, e um dia quero criar raízes."], ["Same here. I hope to buy a house near the beach in ten years.", "Comigo também. Espero comprar uma casa perto da praia em dez anos."], ["Great! It's a deal. Coffee at your bakery in 2030.", "Ótimo! Combinado. Café na sua padaria em 2030."]], ["/dʒ/ em graduated e job", "Faça o som do 'dj' de 'Djalma': graduated e job começam com ele. Em job não coloque 'i' no fim: não é 'jóbi'.", ["graduated", "job"]], ["I'm planning ___ a small bakery.", "to open", "opening", "Estou planejando abrir uma pequena padaria.", "Depois de planning usamos to + verbo na forma base."], [["I hope to work for a travel magazine.", "Espero trabalhar para uma revista de viagem."], ["I'm planning to move to Chicago and open a small bakery.", "Estou planejando me mudar para Chicago e abrir uma pequena padaria."]], [{"t": "c", "q": "I hope ___ Japan next year.", "o": ["to visit", "visiting", "visit"], "pt": "Espero visitar o Japão no ano que vem.", "why": "Depois de hope usamos to + verbo na forma base."}, {"t": "l", "say": "She hopes to find a job.", "o": ["She hopes to find a job.", "She hope to find a job.", "She hopes to finds a job."], "why": "Com she, o verbo hope leva -s; depois de to o verbo fica na forma base, sem -s."}, {"t": "b", "pt": "Espero encontrar o emprego dos sonhos", "w": ["I", "hope", "to", "find", "my", "dream", "job"]}, {"t": "b", "pt": "Estou planejando ir para o exterior", "w": ["I'm", "planning", "to", "go", "abroad"]}]];
