englishA2Plans[329]={"title": "Conversa de fim de curso com a professora", "file": "", "grammar": "Revisão final do A2: present perfect, used to, passado contínuo, will e going to", "goal": "Revise o A2 inteiro numa conversa de despedida de curso: passado, presente perfeito, planos e agradecimentos.", "words": [["progress", "progresso"], ["challenge", "desafio"], ["confidence", "confiança"], ["courage", "coragem"], ["come a long way", "evoluir muito"], ["get the hang of", "pegar o jeito de"], ["small talk", "conversa fiada, papo leve"], ["so far", "até agora"], ["worth it", "valer a pena"], ["set a goal", "definir uma meta"]]};
englishA2Content[329]=[[["Today Noah finished his last English class, and he felt proud of his progress.", "Hoje Noah terminou sua última aula de inglês e sentiu orgulho do seu progresso."], ["A year ago, he used to be afraid to speak, and every conversation was a challenge.", "Um ano atrás, ele tinha medo de falar, e toda conversa era um desafio."], ["Now he has made friends from six countries, and he talks with confidence.", "Agora ele fez amigos de seis países e fala com confiança."], ["It took courage, but he has come a long way, and he isn't afraid of small talk anymore.", "Exigiu coragem, mas ele evoluiu muito e não tem mais medo de conversa fiada."], ["His teacher, Ms. Lee, told him, \"If you keep going, you'll be fluent soon.\"", "A professora, Ms. Lee, disse: \"Se você continuar, logo será fluente.\""], ["\"So far, it has been worth it,\" Noah said, \"and I'm going to set a goal for next year.\"", "\"Até agora, valeu a pena\", disse Noah, \"e vou definir uma meta para o ano que vem.\""]], [["Congratulations, Noah! How do you feel on your last day?", "Parabéns, Noah! Como você se sente no último dia?"], ["A little sad, but very proud. A year ago I used to be afraid to speak.", "Um pouco triste, mas muito orgulhoso. Um ano atrás eu tinha medo de falar."], ["I remember. While the others were talking, you were looking at your notebook.", "Eu lembro. Enquanto os outros conversavam, você olhava o seu caderno."], ["Yes, and I'm sorry for being so quiet. Every class was a challenge.", "Sim, e peço desculpas por ficar tão quieto. Toda aula era um desafio."], ["It doesn't matter! You've come a long way. What was your biggest achievement?", "Não tem problema! Você evoluiu muito. Qual foi sua maior conquista?"], ["Last month I talked to a tourist for twenty minutes. I didn't use my phone once, and I even got the hang of small talk.", "No mês passado conversei com um turista por vinte minutos. Não usei o celular nenhuma vez e até peguei o jeito do papo leve."], ["That's wonderful! It took a lot of courage. You should be proud.", "Que maravilha! Exigiu muita coragem. Você deve se orgulhar."], ["That's so kind of you. I'll practice every day, because I want to speak better.", "Que gentileza sua. Vou praticar todo dia, porque quero falar melhor."], ["What are you going to do next? Have you set a goal?", "O que você vai fazer agora? Já definiu uma meta?"], ["I hope to take the B1 course in September. I'll see you there, right?", "Espero fazer o curso B1 em setembro. A gente se vê lá, certo?"]], ["/r/ inglês em progress e proud", "O r inglês não vibra: curve a língua para trás sem encostar no céu da boca. Nem o 'rr' de 'carro' nem o 'h' de 'rato'.", ["progress", "proud"]], ["A year ago I ___ be afraid to speak.", "used to", "use to", "Um ano atrás eu tinha medo de falar.", "Para hábitos e estados do passado usamos used to + verbo; use to só aparece em negativas e perguntas."], [["A year ago, he used to be afraid to speak, and every conversation was a challenge.", "Um ano atrás, ele tinha medo de falar, e toda conversa era um desafio."], ["You've come a long way.", "Você evoluiu muito."]], [{"t": "c", "q": "I've ___ a long way this year.", "o": ["come", "came", "coming"], "pt": "Eu evoluí muito este ano.", "why": "Com have/has usamos o particípio: come (come – came – come)."}, {"t": "l", "say": "I used to be afraid to speak.", "o": ["I used to be afraid to speak.", "I use to be afraid to speak.", "I was used to afraid to speak."], "why": "Para o hábito do passado usamos used to + verbo; use to e was used to mudam a forma e o sentido."}, {"t": "b", "pt": "Eu espero fazer o curso B1 em setembro", "w": ["I", "hope", "to", "take", "the", "B1", "course", "in", "September"]}, {"t": "b", "pt": "Até agora valeu a pena", "w": ["So", "far", "it's", "been", "worth", "it"]}]];
englishA2PhotoThemes[329]="notebook";
englishA2MiniStories[329]=["Um ano de inglês", "A year ago, Noah moved to Toronto, and he used to be afraid to speak English.~Um ano atrás, Noah se mudou para Toronto e tinha medo de falar inglês.|One day, while he was waiting for the bus, he ran into a classmate named Mia.~Um dia, enquanto esperava o ônibus, ele topou com uma colega chamada Mia.|They had a lot in common, so they started to hang out after class.~Eles tinham muito em comum, então começaram a passar tempo juntos depois da aula.|Noah was so busy that he forgot Mia's birthday, and he said, \"I'm sorry for forgetting.\"~Noah estava tão ocupado que esqueceu o aniversário da Mia e disse: \"Desculpe por esquecer.\"|Mia smiled and said, \"It doesn't matter. You've made a lot of progress this year.\"~Mia sorriu e disse: \"Não tem problema. Você fez muito progresso este ano.\"|When Mia had the flu, Noah looked after her and ran errands for her.~Quando Mia teve gripe, Noah cuidou dela e fez pequenas tarefas para ela.|Once they had a quarrel about a trip, but they calmed down and chose a lake.~Uma vez eles brigaram por causa de uma viagem, mas se acalmaram e escolheram um lago.|In December, Mia went home, and they promised to stay in touch.~Em dezembro, Mia voltou para casa, e eles prometeram manter contato.|Today Noah talks with confidence, and he has come a long way.~Hoje Noah fala com confiança e evoluiu muito.|He hopes to take the next course, and he's planning to travel abroad someday.~Ele espera fazer o próximo curso e planeja viajar para o exterior um dia."];
englishA2ExtraWordExamples[329]={"get the hang of": ["I'm finally getting the hang of this app.", "Finalmente estou pegando o jeito deste aplicativo."]};
